@PluginDescriptor(
	name = "Codex Gear Roadmap",
	description = "Ranks your next gear upgrades by damage gained per coin against the monster you are aiming at",
	tags = {"gear", "upgrade", "dps", "damage", "bis", "best", "loadout", "money", "codex"}
)
public class CodexGearRoadmapPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexGearRoadmapPlugin.class);
	/** Codex Plunder Pilot and Pest Control Pilot read the saved bank under this key: never rename it. */
	static final String BANK_KEY = "bank";
	/** When Gear Roadmap last saw its bank change, epoch ms, so it can tell whose bank is fresher. */
	private static final String BANK_SEEN_KEY = "bankSeenAt";
	private static final String GOAL_KEY = "goal";
	/** The upgrades picked up from the road, for the Roadmap's "Road behind" list. */
	private static final String CLAIMS_KEY = "claims";
	static final String SHORTLIST_KEY = "shortlist";
	/** Codex Ledger's config group and the key it saves its net worth history under, read and never written. */
	static final String LEDGER_GROUP = "codexledger";
	static final String LEDGER_KEY = "ledger";
	/** Codex Session Chronicle's journal and live session, read only, for where the player fights. */
	static final String CHRONICLE_GROUP = "codexsessionchronicle";
	static final String CHRONICLE_JOURNAL = "journal";
	static final String CHRONICLE_CURRENT = "current";
	private static final Skill[] SKILLS = {
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.MAGIC, Skill.PRAYER, Skill.HITPOINTS, Skill.AGILITY,
	};
	private static final Set<Integer> UNLOCK_VARBITS = new HashSet<>(Arrays.asList(
		VarbitID.PRAYER_RIGOUR_UNLOCKED, VarbitID.PRAYER_AUGURY_UNLOCKED, VarbitID.KR_KNIGHTWAVES_STATE,
		VarbitID.PRAYER_DEADEYE_UNLOCKED, VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED, VarbitID.KANDARIN_DIARY_HARD_COMPLETE,
		VarbitID.IRONMAN));
	private static final Set<Integer> TASK_VARPS = new HashSet<>(Arrays.asList(VarPlayerID.SLAYER_COUNT, VarPlayerID.SLAYER_TARGET));
	/** The slayer task id that stands for "a boss", whose name is then looked up from the boss id. */
	private static final int BOSS_TASK = 98;
	/** King's Ransom's knight training is done from this state on, which unlocks Piety and Chivalry. */
	private static final int KNIGHT_WAVES_DONE = 8;
	private static final int ANALYSE_GAP_TICKS = 3;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	private CodexGearRoadmapConfig config;

	private final UpgradePlaque plaque = new UpgradePlaque();
	private final AtomicInteger generation = new AtomicInteger();
	private final Set<String> claimed = new HashSet<>();
	/** The road behind: upgrades picked up, saved per account. */
	private Claims claims = new Claims();
	/** Targets the player shortlisted to weigh upgrades across together. */
	private Shortlist shortlist = Shortlist.empty();

	private RoadmapData data;
	private Advisor advisor;
	private Set<Integer> priceIds = Collections.emptySet();
	/** Hands each item picture's load callback over only until it arrives. */
	private final IconWatch iconWatch = new IconWatch();
	private GearRoadmapPanel panel;
	private NavigationButton navButton;

	private String profile;
	/** Worn and carried gear by id, with how many of each (ammunition is counted by the stack). */
	private Map<Integer, Long> worn = Collections.emptyMap();
	private Map<Integer, Long> inventory = Collections.emptyMap();
	/** Ammunition held in Dizana's quiver, which is in no item container: its id (0 for none) and how many. */
	private int quiverId;
	private long quiverAmount;
	private Bank bank;
	/** Quantities of the banked gear as seen this login, or null while the bank is only known from a save. */
	private Map<Integer, Long> bankCounts;
	/** When the bank was last seen to change by this plugin, epoch ms; 0 when unknown. */
	private long bankSeenAt;
	/** Codex Bank Steward's shared bank for this account, or null without it. */
	private Holdings.Shared steward;
	/** The bank planned with: this plugin's own view or Bank Steward's, whichever is fresher. */
	private Holdings holdings = Holdings.NONE;
	private long inventoryCoins;
	private Boolean ancients;
	private boolean dirty;
	/** Codex Session Chronicle's filed sessions for this account, or empty without it. */
	private List<Fights.Logged> chronicle = Collections.emptyList();
	private boolean coinsDirty;
	/** What is worn changed without changing what is owned, so only the swap advice needs redoing. */
	private boolean wornDirty;
	private int ticksSinceAnalysis;
	private final Map<Skill, Integer> realLevels = new HashMap<>();
	/** Which task the plan was made for, believed only once the varps settle after a login or hop. */
	private final TaskWatch taskWatch = new TaskWatch();
	/** Set on a login, hop or reconnect, until the game is in the world again. */
	private boolean arriving;
	/** The listed monster the player is fighting, offered as a one-click aim; built with the data. */
	private Fighting fighting;
	/** The upgrade the player is saving for, per account. */
	private Savings.Goal goal;
	/** Codex Ledger's net worth for this account, or null when it is not installed. */
	private volatile Savings.Worth worth;
	/** Whether the goal was affordable at the last look; null until then, so a login never announces it. */
	private Boolean goalAffordable;
	/** Whether the goal was announced as in reach this login, so coins dipping and returning say it once. */
	private boolean goalAnnounced;
	/** The task the player turned away from by choosing another target, by task key. */
	private String taskDismissed;
	/** Which of the task's targets the player picked, and for which task. */
	private String taskPick;
	private String taskPickKey;
	/** The current slayer task's name as the game writes it, read with the fighter. */
	private String taskName;
	/** The analysis whose report was last published, so a coin update never lands on a road about to be replaced. */
	private volatile int publishedTicket;

	/** What the latest roadmap was, so a claimed upgrade can be named; written on the executor. */
	private volatile Roadmap lastRoadmap;
	private volatile Report lastReport;
	private volatile String lastName;
	private volatile SurveyCache survey;

	/** The bank as last seen, saved per account so the roadmap knows it between sessions. */
	static final class Bank
	{
		Set<Integer> items = new TreeSet<>();
		long coins;
	}

	private static final class SurveyCache
	{
		final String key;
		final List<Roadmap.Survey> rows;

		SurveyCache(String key, List<Roadmap.Survey> rows)
		{
			this.key = key;
			this.rows = rows;
		}
	}

	@Provides
	CodexGearRoadmapConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexGearRoadmapConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		migrateConfig();
		data = RoadmapData.load(gson);
		advisor = new Advisor(data);
		fighting = new Fighting(data.targets());
		priceIds = advisor.priceIds();
		ItemIcons icons = new ItemIcons()
		{
			@Override
			public BufferedImage icon(int itemId, Runnable onLoaded)
			{
				AsyncBufferedImage image = itemManager.getImage(itemId);
				// Only until it arrives: a loaded picture would run the callback again on every paint.
				iconWatch.watch(image, onLoaded, image::onLoaded);
				return image;
			}

			@Override
			public boolean hasArrived(BufferedImage image)
			{
				return iconWatch.hasArrived(image);
			}
		};
		panel = new GearRoadmapPanel(icons, name -> clientThread.invoke(() -> aim(name)),
			option -> clientThread.invoke(() -> setGoal(option)), name -> clientThread.invoke(() -> toggleShortlist(name)));
		panel.setShare(new ShareActions()
		{
			@Override
			public void save(BufferedImage card, String fileName)
			{
				saveCard(card, fileName);
			}

			@Override
			public void copy(BufferedImage card)
			{
				copyCard(card);
			}
		});
		panel.setShowName(config.nameOnCard());
		panel.setShowWorth(config.worthOnCard());
		navButton = NavigationButton.builder()
			.tooltip("Codex Gear Roadmap")
			.icon(Sigil.icon(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(plaque);
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadBank();
				readContainer(InventoryID.WORN);
				readContainer(InventoryID.INV);
				readQuiver();
				dirty = true;
			}
		});
	}

	/** The old on-task switch becomes the slayer task setting; only an explicit "off" needs carrying over. */
	private void migrateConfig()
	{
		String old = configManager.getConfiguration(CodexGearRoadmapConfig.GROUP, CodexGearRoadmapConfig.OLD_ON_TASK);
		if (old == null)
		{
			return;
		}
		if ("false".equals(old)
			&& configManager.getConfiguration(CodexGearRoadmapConfig.GROUP, CodexGearRoadmapConfig.SLAYER_TASK) == null)
		{
			configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, CodexGearRoadmapConfig.SLAYER_TASK, SlayerTask.Mode.NEVER);
		}
		configManager.unsetConfiguration(CodexGearRoadmapConfig.GROUP, CodexGearRoadmapConfig.OLD_ON_TASK);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(plaque);
		clientToolbar.removeNavigation(navButton);
		plaque.clear();
		// A card still waiting for its pictures is never saved or copied once the plugin is off.
		CardPictures.cancel();
		generation.incrementAndGet();
		clientThread.invokeLater(this::forget);
		panel = null;
	}

	private void forget()
	{
		profile = null;
		bank = null;
		bankCounts = null;
		bankSeenAt = 0;
		steward = null;
		holdings = Holdings.NONE;
		worn = Collections.emptyMap();
		inventory = Collections.emptyMap();
		quiverId = 0;
		quiverAmount = 0;
		inventoryCoins = 0;
		ancients = null;
		lastRoadmap = null;
		lastReport = null;
		realLevels.clear();
		taskWatch.forget();
		if (fighting != null)
		{
			fighting.clear();
		}
		showFighting();
		survey = null;
		claimed.clear();
		claims = new Claims();
		shortlist = Shortlist.empty();
		goal = null;
		worth = null;
		chronicle = Collections.emptyList();
		goalAffordable = null;
		goalAnnounced = false;
		taskDismissed = null;
		taskPick = null;
		taskPickKey = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.HOPPING || state == GameState.LOGGING_IN || state == GameState.CONNECTION_LOST)
		{
			// The varps are taken afresh in the new world; the task may blink to none and back meanwhile.
			taskWatch.arrived();
			arriving = true;
		}
		if (state == GameState.LOGIN_SCREEN)
		{
			forget();
			plaque.clear();
			generation.incrementAndGet();
			publish(Report.loggedOut(), null);
		}
		else if (state == GameState.LOGGED_IN && arriving)
		{
			// Only arriving in a world needs a fresh plan: the game passes through LOGGED_IN again after
			// every loading screen (each teleport), and what changes there brings its own event.
			arriving = false;
			dirty = true;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		bank = null;
		bankCounts = null;
		bankSeenAt = 0;
		steward = null;
		holdings = Holdings.NONE;
		profile = null;
		ancients = null;
		survey = null;
		claimed.clear();
		claims = new Claims();
		shortlist = Shortlist.empty();
		goal = null;
		worth = null;
		chronicle = Collections.emptyList();
		goalAffordable = null;
		goalAnnounced = false;
		taskDismissed = null;
		taskPick = null;
		taskPickKey = null;
		loadBank();
		dirty = true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (LEDGER_GROUP.equals(event.getGroup()))
		{
			// Codex Ledger saved its book: only the savings pace moves, never the plan.
			if (LEDGER_KEY.equals(event.getKey()) && profile != null && profile.equals(event.getProfile()))
			{
				readWorth();
				coinsDirty = true;
			}
			return;
		}
		if (Holdings.STEWARD_GROUP.equals(event.getGroup()))
		{
			// Bank Steward saw the bank: what is owned may have moved, though nothing was claimed here.
			if (Holdings.STEWARD_KEY.equals(event.getKey()) && profile != null && profile.equals(event.getProfile()))
			{
				clientThread.invoke(() ->
				{
					Set<Integer> before = ownedIds();
					long coinsBefore = coins();
					readSteward();
					if (!ownedIds().equals(before))
					{
						dirty = true;
					}
					else if (coins() != coinsBefore)
					{
						coinsDirty = true;
					}
				});
			}
			return;
		}
		if (CHRONICLE_GROUP.equals(event.getGroup()))
		{
			// Session Chronicle filed a session: where the player fights may have moved.
			if (CHRONICLE_JOURNAL.equals(event.getKey()) && profile != null && profile.equals(event.getProfile()))
			{
				clientThread.invoke(() ->
				{
					readChronicle();
					dirty = true;
				});
			}
			return;
		}
		if (!CodexGearRoadmapConfig.GROUP.equals(event.getGroup()) || event.getProfile() != null)
		{
			// The plugin's own per-account saves (bank, goal) change nothing that needs a new plan.
			return;
		}
		if (!config.showPlaque())
		{
			plaque.clear();
		}
		if (CodexGearRoadmapConfig.NAME_ON_CARD.equals(event.getKey()) || CodexGearRoadmapConfig.WORTH_ON_CARD.equals(event.getKey()))
		{
			// Only the road card, drawn when asked for, uses them: nothing to plan again.
			GearRoadmapPanel target = panel;
			boolean showName = config.nameOnCard();
			boolean showWorth = config.worthOnCard();
			if (target != null)
			{
				SwingUtilities.invokeLater(() ->
				{
					target.setShowName(showName);
					target.setShowWorth(showWorth);
				});
			}
			return;
		}
		if (CodexGearRoadmapConfig.TARGET.equals(event.getKey()))
		{
			// A target typed in the settings is a choice too: one the task does not cover stops following it.
			String chosen = event.getNewValue();
			clientThread.invoke(() ->
			{
				Report report = lastReport;
				if (client.getGameState() == GameState.LOGGED_IN && report != null && !report.getTaskTargets().isEmpty()
					&& !report.getTaskTargets().contains(chosen))
				{
					taskDismissed = taskKey();
				}
				dirty = true;
			});
		}
		dirty = true;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id != InventoryID.WORN && id != InventoryID.INV && id != InventoryID.BANK)
		{
			return;
		}
		// The first sight of the bank is not a claim: everything in it was simply unknown before.
		boolean bankKnown = holdings.isKnown();
		Set<Integer> before = ownedIds();
		long coinsBefore = coins();
		Set<Integer> wornBefore = new HashSet<>(worn.keySet());
		Set<Integer> carriedBefore = new HashSet<>(inventory.keySet());
		readContainer(id);
		if (!worn.keySet().equals(wornBefore) || !inventory.keySet().equals(carriedBefore))
		{
			// Putting on or taking off something already owned only changes the swap advice.
			wornDirty = true;
		}
		Set<Integer> after = ownedIds();
		if (!after.equals(before))
		{
			dirty = true;
			if (bankKnown)
			{
				checkGoal(before, after);
				if (taskWatch.isSettled())
				{
					// Just after a login or hop the containers fill in again: gear arriving then is no claim.
					checkClaims(before, after);
				}
			}
		}
		else if (coins() != coinsBefore)
		{
			// Coins only move the "in reach" line, which does not need a new plan.
			coinsDirty = true;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// Experience drops fire this on every hit; only a new real level changes the plan.
		for (Skill skill : SKILLS)
		{
			if (skill == event.getSkill())
			{
				Integer previous = realLevels.put(skill, event.getLevel());
				if (previous == null || previous != event.getLevel())
				{
					dirty = true;
				}
				return;
			}
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (UNLOCK_VARBITS.contains(event.getVarbitId()))
		{
			dirty = true;
		}
		else if (event.getVarbitId() == -1 && (event.getVarpId() == VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO
			|| event.getVarpId() == VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT))
		{
			// Every arrow fired moves the count: only a change in what is owned re-plans.
			Set<Integer> before = ownedIds();
			readQuiver();
			if (!ownedIds().equals(before))
			{
				dirty = true;
			}
		}
		else if (event.getVarbitId() == VarbitID.SLAYER_TARGET_BOSSID
			|| event.getVarbitId() == -1 && TASK_VARPS.contains(event.getVarpId()))
		{
			// Only a new task, or the end of one, changes the plan; the count itself does not.
			taskChanged(taskWatch.seen(taskKey()));
		}
	}

	private void taskChanged(TaskWatch.Change change)
	{
		if (change == TaskWatch.Change.ENDED)
		{
			// The task is done: the next one is followed again, even if it is the same monster.
			taskDismissed = null;
			taskPick = null;
			taskPickKey = null;
		}
		if (change != TaskWatch.Change.NONE)
		{
			dirty = true;
		}
	}

	/** Notes the listed monster the player is attacking, and lets go of one fought long ago; cheap, so every tick. */
	private void watchFight()
	{
		Player me = client.getLocalPlayer();
		Actor foe = me == null ? null : me.getInteracting();
		long now = System.currentTimeMillis();
		boolean changed = foe instanceof NPC && foe.getCombatLevel() > 0 && fighting.saw(foe.getName(), now);
		changed |= fighting.expire(now);
		if (changed)
		{
			showFighting();
		}
	}

	private void showFighting()
	{
		Target t = fighting == null ? null : fighting.current();
		String name = t == null ? null : t.getName();
		GearRoadmapPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.setFighting(name));
		}
	}

	/** The task by its id (and boss id), or "" without one; its kill count is left out on purpose. */
	private String taskKey()
	{
		boolean onTask = client.getVarpValue(VarPlayerID.SLAYER_COUNT) > 0;
		return onTask ? client.getVarpValue(VarPlayerID.SLAYER_TARGET) + ":" + client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID) : "";
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// Switching to another RuneLite profile does not restart the plugin, so that profile's old setting is carried over here.
		migrateConfig();
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (profile == null)
		{
			loadBank();
		}
		taskChanged(taskWatch.tick(taskKey()));
		watchFight();
		ticksSinceAnalysis++;
		// The plan reads the slayer task straight from the varps, so it waits for them to settle after
		// a login or hop: a plan made while they blink to none would aim away from the task, and the
		// settling tick, seeing the same task as before, would never plan again.
		if (dirty && ticksSinceAnalysis >= ANALYSE_GAP_TICKS && taskWatch.isSettled())
		{
			dirty = false;
			coinsDirty = false;
			wornDirty = false;
			ticksSinceAnalysis = 0;
			analyse();
		}
		else if ((coinsDirty || wornDirty) && !dirty && publishedTicket == generation.get())
		{
			coinsDirty = false;
			wornDirty = false;
			Report report = lastReport;
			if (report != null && report.getRoadmap() != null)
			{
				Report recoined = dress(report.withRoadmap(report.getRoadmap().withCoins(report.isIronman() ? 0 : coins())));
				lastReport = recoined;
				lastRoadmap = recoined.getRoadmap();
				publish(recoined, lastName);
			}
		}
	}

	private void readContainer(int id)
	{
		ItemContainer container = client.getItemContainer(id);
		if (container == null)
		{
			return;
		}
		Map<Integer, Long> items = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0 && data.gear(item.getId()) != null)
			{
				items.merge(item.getId(), (long) item.getQuantity(), Long::sum);
			}
		}
		if (id == InventoryID.WORN)
		{
			worn = items;
		}
		else if (id == InventoryID.INV)
		{
			inventory = items;
			inventoryCoins = coinsIn(container);
		}
		else
		{
			Bank seen = new Bank();
			seen.items = new TreeSet<>(items.keySet());
			seen.coins = coinsIn(container);
			bankCounts = items;
			bankSeenAt = System.currentTimeMillis();
			if (bank == null || !bank.items.equals(seen.items) || bank.coins != seen.coins)
			{
				bank = seen;
				saveBank();
			}
			choose();
		}
	}

	/** Coins and platinum tokens, each token worth a thousand. */
	private static long coinsIn(ItemContainer container)
	{
		return container.count(ItemID.COINS) + 1000L * container.count(ItemID.PLATINUM);
	}

	/** Everything owned, worn, carried and banked; ammunition only as a stack worth bringing. */
	private Set<Integer> ownedIds()
	{
		Map<Integer, Long> total = new HashMap<>(worn);
		inventory.forEach((id, n) -> total.merge(id, n, Long::sum));
		if (quiverId > 0 && quiverAmount > 0)
		{
			total.merge(quiverId, quiverAmount, Long::sum);
		}
		// A quantity never seen stays unknown, and an unknown stack counts whatever else is held.
		holdings.getGear().forEach((id, n) -> total.merge(id, n, (a, b) -> a == Holdings.UNKNOWN || b == Holdings.UNKNOWN ? Holdings.UNKNOWN : a + b));
		Set<Integer> ids = new HashSet<>();
		total.forEach((id, n) ->
		{
			Gear g = data.gear(id);
			if (g != null && Holdings.enough(g.getSlot() == Gear.AMMO, n))
			{
				ids.add(id);
			}
		});
		return ids;
	}

	/** The ammunition in Dizana's quiver, kept in varps wherever the quiver is. */
	private void readQuiver()
	{
		quiverId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		quiverAmount = Math.max(0, client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT));
	}

	private long coins()
	{
		return inventoryCoins + holdings.getCoins();
	}

	/** Settles which bank to plan with, this plugin's own or Bank Steward's. */
	private void choose()
	{
		holdings = Holdings.choose(bank == null ? null : bank.items, bank == null ? 0 : bank.coins, bankCounts, bankSeenAt,
			steward, id -> data.gear(id) != null);
	}

	/** Reads Codex Bank Steward's shared bank for this account; never writes it. Null when it is not installed. */
	private void readSteward()
	{
		steward = Holdings.readSteward(gson, configManager.getRSProfileConfiguration(Holdings.STEWARD_GROUP, Holdings.STEWARD_KEY));
		choose();
	}

	private void loadBank()
	{
		String key = configManager.getRSProfileKey();
		if (key == null)
		{
			return;
		}
		profile = key;
		loadGoal();
		loadClaims();
		loadShortlist();
		readWorth();
		readChronicle();
		Bank saved = readBank(gson, configManager.getRSProfileConfiguration(CodexGearRoadmapConfig.GROUP, BANK_KEY));
		if (saved != null)
		{
			bank = saved;
			bankCounts = null;
			bankSeenAt = seenAt();
		}
		readSteward();
	}

	/**
	 * This plugin's saved bank, or null when there is none or it cannot be read; it waits to see the
	 * bank again then. An id that is not one, or coins that are not a count, cost only themselves.
	 */
	static Bank readBank(Gson gson, String json)
	{
		JsonObject o = Saved.object(gson, json);
		JsonElement items = o == null ? null : o.get("items");
		if (items == null || !items.isJsonArray())
		{
			return null;
		}
		Bank bank = new Bank();
		for (JsonElement e : items.getAsJsonArray())
		{
			Long id = Saved.whole(e);
			if (id != null && id > 0 && id <= Integer.MAX_VALUE)
			{
				bank.items.add(id.intValue());
			}
		}
		Long coins = Saved.whole(o.get("coins"));
		bank.coins = coins == null ? 0 : Math.max(0, Math.min(coins, Saved.MAX_WORTH));
		return bank;
	}

	/** When the saved bank was seen, or 0 for a bank saved before the time was kept. */
	private long seenAt()
	{
		String saved = configManager.getRSProfileConfiguration(CodexGearRoadmapConfig.GROUP, BANK_SEEN_KEY);
		try
		{
			return saved == null ? 0 : Long.parseLong(saved.trim());
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private void saveBank()
	{
		if (profile == null)
		{
			profile = configManager.getRSProfileKey();
		}
		if (profile != null && bank != null)
		{
			configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, profile, BANK_KEY, gson.toJson(bank));
			configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, profile, BANK_SEEN_KEY, Long.toString(bankSeenAt));
		}
	}

	/** Names the upgrades from the road the player just picked up. */
	private void checkClaims(Set<Integer> before, Set<Integer> after)
	{
		Roadmap map = lastRoadmap;
		if (map == null)
		{
			return;
		}
		List<Roadmap.Step> path = map.getPath();
		for (int i = 0; i < path.size(); i++)
		{
			Roadmap.Option option = path.get(i).getOption();
			if (claimed.contains(option.getName()) || !ownsAll(option.getPieces(), after) || ownsAll(option.getPieces(), before))
			{
				continue;
			}
			claimed.add(option.getName());
			announce(map, i, option);
		}
	}

	/** The player now owns every piece of their savings goal: say so, and the goal is done. */
	private void checkGoal(Set<Integer> before, Set<Integer> after)
	{
		if (goal == null)
		{
			return;
		}
		List<Gear> pieces = new ArrayList<>();
		for (int id : goal.getIds())
		{
			Gear g = data.gear(id);
			if (g == null)
			{
				return;
			}
			pieces.add(g);
		}
		if (!ownsAll(pieces, after) || ownsAll(pieces, before))
		{
			return;
		}
		// The same upgrade on the road is not claimed a second time, but it is still on the road
		// behind: the goal met is the biggest buy of all, and its plaque said so already.
		claimed.add(goal.getName());
		if (taskWatch.isSettled())
		{
			rememberClaim(goal.getName());
		}
		Gear icon = pieces.get(0);
		for (Gear g : pieces)
		{
			if (g.getSlot() == Gear.BODY)
			{
				icon = g;
			}
		}
		if (config.showPlaque())
		{
			plaque.show(new UpgradePlaque.View("GOAL MET", goal.getName(), "The upgrade you saved for is yours",
				"Pick your next goal on the Roadmap", Theme.GREEN, itemManager.getImage(icon.getId()), System.currentTimeMillis(),
				config.plaqueSeconds() * 1000L));
		}
		if (config.chatLine())
		{
			String line = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Gear Roadmap: ")
				.append(ChatColorType.NORMAL).append("savings goal met, ")
				.append(ChatColorType.HIGHLIGHT).append(goal.getName())
				.append(ChatColorType.NORMAL).append(" is yours.")
				.build();
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(line)
				.build());
		}
		setGoal(null);
	}

	private static boolean ownsAll(List<Gear> pieces, Set<Integer> ids)
	{
		for (Gear piece : pieces)
		{
			boolean has = false;
			for (int id : piece.getIds())
			{
				if (ids.contains(id))
				{
					has = true;
					break;
				}
			}
			if (!has)
			{
				return false;
			}
		}
		return true;
	}

	private void announce(Roadmap map, int index, Roadmap.Option option)
	{
		String target = map.getTarget().getName();
		claims.add(new Claims.Claim(option.getName(), option.getIcon().getId(), option.getGain(), target, System.currentTimeMillis()));
		saveClaims();
		String gain = Format.gain(option.getGain()) + " DPS against " + target;
		List<Roadmap.Step> path = map.getPath();
		String next = index + 1 < path.size()
			? "Next: " + path.get(index + 1).getOption().getName() + ", " + Format.coins(path.get(index + 1).getOption().getCost())
			: "That was the last stop on this road";
		if (config.showPlaque())
		{
			plaque.show(new UpgradePlaque.View("UPGRADE CLAIMED", option.getName(), gain, next, Theme.GOLD,
				itemManager.getImage(option.getIcon().getId()), System.currentTimeMillis(), config.plaqueSeconds() * 1000L));
		}
		if (config.chatLine())
		{
			String line = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Gear Roadmap: ")
				.append(ChatColorType.NORMAL).append(option.getName() + " adds ")
				.append(ChatColorType.HIGHLIGHT).append(Format.gain(option.getGain()) + " DPS")
				.append(ChatColorType.NORMAL).append(" against " + target + ".")
				.build();
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(line)
				.build());
		}
	}

	/**
	 * The player picked a target on the Targets tab. One of the slayer task's targets only moves
	 * the aim within the task; any other becomes the chosen target and stops following this task.
	 */
	private void aim(String name)
	{
		Report report = lastReport;
		String key = client.getGameState() == GameState.LOGGED_IN ? taskKey() : "";
		boolean onTaskTarget = report != null && report.getTaskTargets().contains(name);
		if (onTaskTarget && config.followTask())
		{
			taskPick = name;
			taskPickKey = key;
			taskDismissed = null;
			dirty = true;
			return;
		}
		if (!key.isEmpty() && report != null && !report.getTaskTargets().isEmpty())
		{
			taskDismissed = key;
		}
		if (name.equals(config.target()))
		{
			dirty = true;
		}
		configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, CodexGearRoadmapConfig.TARGET, name);
	}

	/** Saves for an upgrade, or clears the goal when given null. */
	private void setGoal(Roadmap.Option option)
	{
		if (option == null)
		{
			goal = null;
		}
		else
		{
			List<Integer> ids = new ArrayList<>();
			for (Gear piece : option.getPieces())
			{
				ids.add(piece.getIds()[0]);
			}
			goal = new Savings.Goal(option.getName(), ids);
		}
		goalAffordable = null;
		goalAnnounced = false;
		saveGoal();
		dirty = true;
	}

	/** Puts a stop of the latest road on the road behind, if it is one. */
	private void rememberClaim(String name)
	{
		Roadmap map = lastRoadmap;
		if (map == null)
		{
			return;
		}
		for (Roadmap.Step step : map.getPath())
		{
			Roadmap.Option option = step.getOption();
			if (option.getName().equals(name))
			{
				claims.add(new Claims.Claim(option.getName(), option.getIcon().getId(), option.getGain(), map.getTarget().getName(),
					System.currentTimeMillis()));
				saveClaims();
				return;
			}
		}
	}

	private void loadShortlist()
	{
		String saved = configManager.getRSProfileConfiguration(CodexGearRoadmapConfig.GROUP, SHORTLIST_KEY);
		shortlist = Shortlist.read(gson, saved);
	}

	/** The player right-clicked a target to put it on the shortlist, or take it off. */
	private void toggleShortlist(String name)
	{
		shortlist = shortlist.toggle(name);
		if (profile != null)
		{
			if (shortlist.isEmpty())
			{
				configManager.unsetConfiguration(CodexGearRoadmapConfig.GROUP, profile, SHORTLIST_KEY);
			}
			else
			{
				configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, profile, SHORTLIST_KEY, shortlist.write(gson));
			}
		}
		dirty = true;
	}

	private void loadClaims()
	{
		String saved = configManager.getRSProfileConfiguration(CodexGearRoadmapConfig.GROUP, CLAIMS_KEY);
		claims = Claims.read(gson, saved);
		keepAside(CLAIMS_KEY, saved, claims);
	}

	/**
	 * Sets a save aside under its key plus "Unreadable" when part of it could not be read (a broken
	 * entry, a later version's field), before the next write goes over it; one copy, never over a
	 * fuller one.
	 */
	private void keepAside(String key, String saved, Object read)
	{
		if (profile == null || !Saved.lost(gson, saved, read))
		{
			return;
		}
		String aside = key + "Unreadable";
		if (Saved.setAside(configManager.getRSProfileConfiguration(CodexGearRoadmapConfig.GROUP, aside), saved))
		{
			log.warn("Part of the saved {} could not be read; it is kept as it was as {}", key, aside);
			configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, profile, aside, saved);
		}
	}

	private void saveClaims()
	{
		if (profile != null)
		{
			configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, profile, CLAIMS_KEY, gson.toJson(claims));
		}
	}

	private void loadGoal()
	{
		goal = null;
		goalAffordable = null;
		goalAnnounced = false;
		String saved = configManager.getRSProfileConfiguration(CodexGearRoadmapConfig.GROUP, GOAL_KEY);
		goal = Savings.readGoal(gson, saved);
		keepAside(GOAL_KEY, saved, goal);
	}

	private void saveGoal()
	{
		if (profile == null)
		{
			return;
		}
		if (goal == null)
		{
			configManager.unsetConfiguration(CodexGearRoadmapConfig.GROUP, profile, GOAL_KEY);
		}
		else
		{
			configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, profile, GOAL_KEY, gson.toJson(goal));
		}
	}

	/** Reads Codex Ledger's saved net worth for this account; never writes it. Null when it is not installed. */
	private void readWorth()
	{
		// Another plugin's format may change under us; without it the goal simply has no pace.
		worth = Savings.readWorth(gson, configManager.getRSProfileConfiguration(LEDGER_GROUP, LEDGER_KEY));
	}

	/** Reads Codex Session Chronicle's journal for this account; never writes it. Empty when it is not installed. */
	private void readChronicle()
	{
		chronicle = readLogged(CHRONICLE_JOURNAL, true);
	}

	/** One of Chronicle's saved values as sessions: the journal is a list, the live session one. */
	private List<Fights.Logged> readLogged(String key, boolean list)
	{
		// Another plugin's format may change under us; without it there is simply no "where you fight".
		return Fights.read(gson, configManager.getRSProfileConfiguration(CHRONICLE_GROUP, key), list);
	}

	/** Adds the savings goal's standing to a report, and says so once the player's coins reach it. */
	private Report dress(Report report)
	{
		report = report.withSwap(swap(report.getRoadmap())).withClaims(claims.recent());
		Roadmap map = report.getRoadmap();
		if (map == null || goal == null || report.isIronman() || map.getGoal() == null)
		{
			return report.withSavings(null);
		}
		Savings.View view = Savings.of(map.getGoal(), map.isGoalOwned(), coins(), worth, System.currentTimeMillis());
		boolean affordable = view.isAffordable();
		if (Savings.inReach(goalAffordable, goalAnnounced, view))
		{
			goalAnnounced = true;
			announceGoal(view, map.getTarget().getName());
		}
		goalAffordable = affordable;
		return report.withSavings(view);
	}

	/** What is worn now against the best loadout owned for the road's target; one damage sum, so cheap enough for the client thread. */
	private Swap swap(Roadmap map)
	{
		if (map == null || map.getNow() == null)
		{
			return null;
		}
		return Swap.of(worn.keySet(), inventory.keySet(), data::gear, map.getNow().best(), advisor.planner().calc(), fighter(),
			map.getTarget());
	}

	private void announceGoal(Savings.View view, String target)
	{
		Roadmap.Option option = view.getOption();
		String gain = option.getGain() > 0 ? Format.gain(option.getGain()) + " DPS against " + target : "Saved for in Gear Roadmap";
		if (config.showPlaque())
		{
			plaque.show(new UpgradePlaque.View("GOAL IN REACH", option.getName(), gain,
				"Your coins now cover its " + Format.coins(option.getCost()), Theme.TEAL,
				itemManager.getImage(option.getIcon().getId()), System.currentTimeMillis(), config.plaqueSeconds() * 1000L));
		}
		if (config.chatLine())
		{
			String line = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Gear Roadmap: ")
				.append(ChatColorType.NORMAL).append("your coins now cover your goal, ")
				.append(ChatColorType.HIGHLIGHT).append(option.getName())
				.append(ChatColorType.NORMAL).append(" (" + Format.coins(option.getCost()) + ").")
				.build();
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(line)
				.build());
		}
	}

	private Fighter fighter()
	{
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : SKILLS)
		{
			levels.put(skill.getName(), client.getRealSkillLevel(skill));
		}
		if (ancients == null)
		{
			ancients = Quest.DESERT_TREASURE_I.getState(client) == QuestState.FINISHED;
		}
		boolean piety = client.getVarbitValue(VarbitID.KR_KNIGHTWAVES_STATE) >= KNIGHT_WAVES_DONE;
		boolean rigour = client.getVarbitValue(VarbitID.PRAYER_RIGOUR_UNLOCKED) == 1;
		boolean augury = client.getVarbitValue(VarbitID.PRAYER_AUGURY_UNLOCKED) == 1;
		boolean deadeye = client.getVarbitValue(VarbitID.PRAYER_DEADEYE_UNLOCKED) == 1;
		boolean vigour = client.getVarbitValue(VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED) == 1;
		boolean kandarin = client.getVarbitValue(VarbitID.KANDARIN_DIARY_HARD_COMPLETE) == 1;
		taskName = currentTask();
		SlayerTask task = SlayerTask.of(config.slayerTask(), taskName);
		return new Fighter(levels, config.boost(), config.prayers(), piety, rigour, augury, ancients, task)
			.withUnlocks(deadeye, vigour, kandarin);
	}

	/** The name of the player's current slayer task, as the slayer helper shows it, or null. */
	private String currentTask()
	{
		if (client.getVarpValue(VarPlayerID.SLAYER_COUNT) <= 0)
		{
			return null;
		}
		try
		{
			int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
			int row;
			if (taskId == BOSS_TASK)
			{
				List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID,
					DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
				if (rows.isEmpty())
				{
					return null;
				}
				row = (Integer) client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
			}
			else
			{
				List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
				if (rows.isEmpty())
				{
					return null;
				}
				row = rows.get(0);
			}
			return (String) client.getDBTableField(row, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read the slayer task", e);
			return null;
		}
	}

	private void analyse()
	{
		Set<Integer> ids = ownedIds();
		Set<Gear> owned = new LinkedHashSet<>();
		for (int id : ids)
		{
			Gear g = data.gear(id);
			if (g != null)
			{
				owned.add(g);
			}
		}
		Fighter fighter = fighter();
		Map<Integer, Long> prices = new HashMap<>();
		for (int id : priceIds)
		{
			long price = itemManager.getItemPrice(id);
			if (price > 0)
			{
				prices.put(id, price);
			}
		}
		// Owned pieces too, though no upgrade buys them, so outgrown gear has a price to sell at. Only
		// tradeable ones can be sold: an untradeable piece is priced by what it was made from.
		Set<Integer> sellable = new HashSet<>();
		for (Gear g : owned)
		{
			if (itemManager.getItemComposition(g.getId()).isTradeable())
			{
				sellable.add(g.getId());
			}
			if (!prices.containsKey(g.getId()))
			{
				long price = itemManager.getItemPrice(g.getId());
				if (price > 0)
				{
					prices.put(g.getId(), price);
				}
			}
		}
		String key = taskKey();
		boolean follow = config.followTask() && !key.equals(taskDismissed);
		boolean bossTask = !key.isEmpty() && client.getVarpValue(VarPlayerID.SLAYER_TARGET) == BOSS_TASK;
		Aim aimed = Aim.choose(data.targets(), config.target(), follow, taskName, bossTask,
			key.equals(taskPickKey) ? taskPick : null);
		Target target = aimed.getTarget();
		List<String> taskTargets = new ArrayList<>();
		for (Target t : aimed.getCovered())
		{
			taskTargets.add(t.getName());
		}
		boolean following = aimed.isFollowing();
		String shownTask = taskName;
		boolean ironman = client.getVarbitValue(VarbitID.IRONMAN) > 0;
		// Ironmen cannot buy, so their coins never put an upgrade in reach.
		long coins = ironman ? 0 : coins();
		boolean bankSeen = holdings.isKnown();
		boolean seasonal = client.getWorldType().contains(WorldType.SEASONAL);
		String boosts = config.boost().toString();
		String task = fighter.getTask().getTask();
		Boolean slayer = target.isSlayer() ? fighter.onTaskFor(target) : null;
		String surveyKey = new TreeSet<>(ids) + "|" + fighter.getLevels() + "|" + fighter.assumptions() + unlocks();
		Player player = client.getLocalPlayer();
		String name = player == null ? null : player.getName();
		Target aim = target;
		// Ironmen cannot buy, so they have no savings goal.
		Savings.Goal saving = ironman ? null : goal;
		List<Fights.Logged> sessions = new ArrayList<>(chronicle);
		sessions.addAll(readLogged(CHRONICLE_CURRENT, false));
		Fights.Tally tally = sessions.isEmpty() ? null : Fights.tally(sessions, data.targets(), System.currentTimeMillis());
		List<String> listedNames = shortlist.getNames();
		List<Target> listedTargets = shortlist.targets(data.targets());
		int ticket = generation.incrementAndGet();
		executor.execute(() ->
		{
			try
			{
				Roadmap map = advisor.plan(owned, fighter, aim, id -> prices.getOrDefault(id, 0L), coins, saving);
				SurveyCache cached = survey;
				if (cached == null || !cached.key.equals(surveyKey))
				{
					cached = new SurveyCache(surveyKey, advisor.survey(owned, fighter));
				}
				if (ticket == generation.get())
				{
					survey = cached;
					lastRoadmap = map;
					// Ironmen cannot buy, so there is nothing to weigh for them.
					List<Fights.Pick> fights = ironman ? Collections.emptyList()
						: advisor.fights(owned, fighter, tally, id -> prices.getOrDefault(id, 0L));
					List<Fights.Pick> listedPicks = ironman ? Collections.emptyList()
						: advisor.shortlist(owned, fighter, listedTargets, id -> prices.getOrDefault(id, 0L));
					Report planned = new Report(true, map, cached.rows, boosts, owned.size(), bankSeen)
						.withAccount(ironman, seasonal, task, slayer)
						.withTask(following, taskTargets, shownTask)
						.withExtras(tally, fights, Levels.ahead(advisor.planner().calc(), map, fighter))
						.withShortlist(listedNames, listedPicks)
						// Ironmen cannot sell, so nothing is outgrown for coins.
						.withOutgrown(ironman ? null : Outgrown.of(owned, cached.rows, g -> advisor.planner().wieldable(g, fighter),
							g -> sellable.contains(g.getId()), id -> prices.getOrDefault(id, 0L)));
					// The goal's standing is settled on the client thread, where the goal and coins live.
					clientThread.invokeLater(() ->
					{
						if (ticket != generation.get())
						{
							return;
						}
						Report report = dress(planned);
						lastReport = report;
						lastName = name;
						publishedTicket = ticket;
						publish(report, name);
					});
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Gear Roadmap planning failed", e);
			}
		});
	}

	private String unlocks()
	{
		return client.getVarbitValue(VarbitID.KR_KNIGHTWAVES_STATE) + "/" + client.getVarbitValue(VarbitID.PRAYER_RIGOUR_UNLOCKED)
			+ "/" + client.getVarbitValue(VarbitID.PRAYER_AUGURY_UNLOCKED);
	}

	private void publish(Report report, String name)
	{
		GearRoadmapPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(report, name));
		}
	}

	/** Asks where to save the road card with RuneLite's own file chooser, then writes it there; runs on the Swing thread. */
	private void saveCard(BufferedImage card, String fileName)
	{
		GearRoadmapPanel view = panel;
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save road card")
			.addExtensionFilter("PNG image", "png")
			.setDefaultExtension("png")
			.setFileName(fileName)
			.showDialog(view);
		if (chosen == null || chosen.isEmpty())
		{
			return;
		}
		Filepath target = chosen.get(0);
		executor.execute(() ->
		{
			String note;
			try (OutputStream out = target.openOutputStream())
			{
				ImageIO.write(card, "png", out);
				note = "Saved as " + target.getFileName() + ".";
			}
			catch (IOException e)
			{
				log.warn("Could not save the road card", e);
				note = "The card could not be saved: " + e.getMessage();
			}
			String shown = note;
			GearRoadmapPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(() -> p.shareNote(shown));
			}
		});
	}

	private void copyCard(BufferedImage card)
	{
		String note;
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageTransfer(ImageTransfer.opaque(card)), null);
			note = "Copied. Paste it anywhere you share pictures.";
		}
		catch (IllegalStateException e)
		{
			note = "The clipboard is busy, try again in a moment.";
		}
		GearRoadmapPanel p = panel;
		if (p != null)
		{
			p.shareNote(note);
		}
	}
}

package com.codex.gearroadmap;

import com.codex.gearroadmap.ui.Theme;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

/** Hands the road card to the system clipboard as a picture. */
final class ImageTransfer implements Transferable
{
	private final BufferedImage image;

	ImageTransfer(BufferedImage image)
	{
		this.image = image;
	}

	/**
	 * The card on a solid backing. Some clipboards (Windows among them) drop transparency and
	 * would paint its rounded corners black, so they are filled with the card's own ink.
	 */
	static BufferedImage opaque(BufferedImage card)
	{
		BufferedImage out = new BufferedImage(card.getWidth(), card.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.setColor(Theme.INK_DEEP);
		g.fillRect(0, 0, out.getWidth(), out.getHeight());
		g.drawImage(card, 0, 0, null);
		g.dispose();
		return out;
	}

	@Override
	public DataFlavor[] getTransferDataFlavors()
	{
		return new DataFlavor[]{DataFlavor.imageFlavor};
	}

	@Override
	public boolean isDataFlavorSupported(DataFlavor flavor)
	{
		return DataFlavor.imageFlavor.equals(flavor);
	}

	@Override
	public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
	{
		if (!isDataFlavorSupported(flavor))
		{
			throw new UnsupportedFlavorException(flavor);
		}
		return image;
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.CatalogueEntry;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Weighs every upgrade in the catalogue against the player's best loadout for one target,
 * then walks the road ahead: the upgrade with the most damage per coin first, then the
 * next one from there, and so on. Earned upgrades and ones the player cannot wield yet
 * are listed on their own.
 */
public final class Advisor
{
	public static final int STEPS = 8;
	public static final int AMMO_STACK = 1000;
	/** Kills of each shortlisted target an upgrade is weighed over. */
	public static final int SHORTLIST_KILLS = 100;
	private static final int SIDE_LIST = 4;
	/** How many of the cheapest do-nothing-alone pieces the road tries in pairs. */
	private static final int PAIR_POOL = 10;

	/** Grand Exchange prices: 0 when an item has none. */
	public interface Prices
	{
		long price(int itemId);
	}

	private static final String[][] BUNDLES = {
		{"Void melee set", "Pest Control", "void melee helm", "void knight top", "void knight robe", "void knight gloves"},
		{"Void ranger set", "Pest Control", "void ranger helm", "void knight top", "void knight robe", "void knight gloves"},
		{"Void mage set", "Pest Control", "void mage helm", "void knight top", "void knight robe", "void knight gloves"},
		{"Elite void ranger set", "Pest Control and the Western Provinces hard diary", "void ranger helm", "elite void top", "elite void robe", "void knight gloves"},
		{"Elite void mage set", "Pest Control and the Western Provinces hard diary", "void mage helm", "elite void top", "elite void robe", "void knight gloves"},
		{"Obsidian armour", null, "obsidian helmet", "obsidian platebody", "obsidian platelegs"},
	};

	/** Earned upgrades that are pointless once a better form of the same item is owned. */
	private static final String[][] SUPERSEDED = {
		{"salve amulet", "salve amulet(i)", "salve amulet (e)", "salve amulet(ei)"},
		{"salve amulet(i)", "salve amulet (e)", "salve amulet(ei)"},
		{"salve amulet (e)", "salve amulet(ei)"},
		{"black mask", "black mask (i)", "slayer helmet", "slayer helmet (i)"},
		{"black mask (i)", "slayer helmet (i)"},
		{"slayer helmet", "slayer helmet (i)"},
		{"fire cape", "infernal cape"},
		{"ava's accumulator", "ava's assembler", "dizana's quiver", "blessed dizana's quiver"},
		{"saradomin cape", "imbued saradomin cape"},
	};

	private final RoadmapData data;
	private final Planner planner;

	public Advisor(RoadmapData data)
	{
		this.data = data;
		this.planner = new Planner(data);
	}

	public Planner planner()
	{
		return planner;
	}

	/** The roadmap for one target. */
	public Roadmap plan(Collection<Gear> ownedGear, Fighter fighter, Target target, Prices prices, long coins)
	{
		return plan(ownedGear, fighter, target, prices, coins, null);
	}

	/** The roadmap for one target, with the player's savings goal priced and weighed against it. */
	public Roadmap plan(Collection<Gear> ownedGear, Fighter fighter, Target target, Prices prices, long coins, Savings.Goal goal)
	{
		Set<Gear> owned = new LinkedHashSet<>(ownedGear);
		Planner.Best start = planner.optimise(owned, fighter, target);
		double base = start.dps();
		List<Candidate> candidates = candidates(owned);

		List<Roadmap.Option> free = new ArrayList<>();
		List<Roadmap.Option> locked = new ArrayList<>();
		List<Roadmap.Option> bought = new ArrayList<>();
		Map<Roadmap.Option, Integer> shortBy = new HashMap<>();
		for (Candidate c : candidates)
		{
			long cost = cost(c, owned, prices);
			if (cost < 0)
			{
				continue;
			}
			Planner.Plan after = planner.withAdded(start, owned, c.pieces, fighter, target);
			double gain = after.dps() - base;
			if (gain < threshold(base))
			{
				continue;
			}
			String missing = fighter.missing(c.requirements);
			Roadmap.Option option = new Roadmap.Option(c.name, c.pieces, c.icon(), cost, gain, base, after, missing,
				c.earn, cost == 0 && c.earn == null ? imbueNote(c) : c.note, c.ammo);
			if (missing != null)
			{
				locked.add(option);
				shortBy.put(option, fighter.shortfall(c.requirements));
			}
			else if (cost == 0)
			{
				free.add(option);
			}
			else
			{
				bought.add(option);
			}
		}
		Comparator<Roadmap.Option> byGain = Comparator.comparingDouble((Roadmap.Option o) -> -o.getGain());
		free.sort(byGain);
		// One reward of the same task in one slot is enough: the dragon gloves need not stand
		// beside the barrows gloves that the same quest gives later.
		Set<String> rewards = new HashSet<>();
		free.removeIf(o -> o.getEarn() != null && !rewards.add(o.getEarn() + "/" + o.getIcon().getSlot()));
		// What a few more levels unlock comes before a dream forty levels away.
		locked.sort(Comparator.comparingDouble((Roadmap.Option o) -> -o.getGain() / (1 + shortBy.get(o) / 10.0)));

		List<Roadmap.Step> path = walk(owned, fighter, target, prices, coins, start, candidates);
		Set<String> onPath = new HashSet<>();
		for (Roadmap.Step step : path)
		{
			onPath.add(step.getOption().getName());
		}
		List<Roadmap.Option> leaps = new ArrayList<>();
		bought.sort(byGain);
		for (Roadmap.Option o : bought)
		{
			if (!onPath.contains(o.getName()) && leaps.size() < SIDE_LIST)
			{
				leaps.add(o);
			}
		}
		Roadmap map = new Roadmap(target, start, path, cut(free, SIDE_LIST + 2), cut(locked, SIDE_LIST), leaps, coins);
		return goal == null ? map : map.withGoal(goal(owned, fighter, target, prices, start, goal), owns(owned, goal));
	}

	/**
	 * A savings goal as it stands against this target: what is still to buy and the damage it
	 * adds to the loadout owned now, which may be nothing here. Null when a piece is unknown or
	 * has no price at the moment.
	 */
	Roadmap.Option goal(Set<Gear> owned, Fighter fighter, Target target, Prices prices, Planner.Best start, Savings.Goal goal)
	{
		if (goal == null || !goal.isValid())
		{
			return null;
		}
		List<Gear> pieces = new ArrayList<>();
		Map<String, Integer> req = new HashMap<>();
		String note = null;
		for (int id : goal.getIds())
		{
			Gear g = data.gear(id);
			if (g == null)
			{
				return null;
			}
			if (!pieces.contains(g))
			{
				pieces.add(g);
			}
			CatalogueEntry entry = data.entry(g);
			if (entry != null)
			{
				entry.getRequirements().forEach((k, v) -> req.merge(k, v, Math::max));
				note = pieces.size() == 1 ? entry.getNote() : null;
			}
		}
		Candidate c = new Candidate(goal.getName(), pieces, req, null, note, pieces.size() == 1 && pieces.get(0).getSlot() == Gear.AMMO);
		long cost = cost(c, owned, prices);
		if (cost < 0)
		{
			return null;
		}
		Planner.Plan after = planner.withAdded(start, owned, pieces, fighter, target);
		double gain = Math.max(0, after.dps() - start.dps());
		return new Roadmap.Option(c.name, pieces, c.icon(), cost, gain, start.dps(), gain > 0 ? after : start.best(),
			fighter.missing(req), null, note, c.ammo);
	}

	/** Whether every piece of a goal is owned already, any variant of it counting. */
	boolean owns(Set<Gear> owned, Savings.Goal goal)
	{
		if (goal == null || !goal.isValid())
		{
			return false;
		}
		for (int id : goal.getIds())
		{
			Gear g = data.gear(id);
			if (g == null || !owned.contains(g))
			{
				return false;
			}
		}
		return true;
	}

	/** Greedy road: the best damage per coin, then again from the gear that leaves. */
	private List<Roadmap.Step> walk(Set<Gear> owned, Fighter fighter, Target target, Prices prices, long coins,
		Planner.Best start, List<Candidate> candidates)
	{
		Set<Gear> have = new LinkedHashSet<>(owned);
		Planner.Best current = start;
		List<Roadmap.Step> path = new ArrayList<>();
		long spent = 0;
		Set<Candidate> used = new HashSet<>();
		for (int step = 0; step < STEPS; step++)
		{
			double base = current.dps();
			Candidate pick = null;
			Planner.Plan pickPlan = null;
			long pickCost = 0;
			double pickRatio = 0;
			List<Candidate> pickParts = Collections.emptyList();
			List<Candidate> flat = new ArrayList<>();
			Map<Candidate, Long> flatCost = new HashMap<>();
			for (Candidate c : candidates)
			{
				if (used.contains(c) || have.containsAll(c.pieces) || fighter.missing(c.requirements) != null)
				{
					continue;
				}
				long cost = cost(c, have, prices);
				if (cost <= 0)
				{
					continue;
				}
				Planner.Plan after = planner.withAdded(current, have, c.pieces, fighter, target);
				double gain = after.dps() - base;
				if (gain < threshold(base))
				{
					if (c.pieces.size() == 1 && !c.ammo && morePower(c.pieces.get(0), current.best()))
					{
						flat.add(c);
						flatCost.put(c, cost);
					}
					continue;
				}
				double ratio = gain / cost;
				if (ratio > pickRatio)
				{
					pick = c;
					pickPlan = after;
					pickCost = cost;
					pickRatio = ratio;
				}
			}
			// A piece that adds strength or accuracy short of the next max hit does nothing alone,
			// yet two of them together can cross it: try the cheapest such pieces in pairs.
			flat.sort(Comparator.comparingLong(flatCost::get));
			int pool = Math.min(flat.size(), PAIR_POOL);
			for (int i = 0; i < pool; i++)
			{
				for (int j = i + 1; j < pool; j++)
				{
					Candidate a = flat.get(i);
					Candidate b = flat.get(j);
					if (a.pieces.get(0).getSlot() == b.pieces.get(0).getSlot())
					{
						continue;
					}
					long cost = flatCost.get(a) + flatCost.get(b);
					List<Gear> both = new ArrayList<>(a.pieces);
					both.addAll(b.pieces);
					Planner.Plan after = planner.withAdded(current, have, both, fighter, target);
					double gain = after.dps() - base;
					if (gain >= threshold(base) && gain / cost > pickRatio)
					{
						pick = new Candidate(a.name + " + " + b.name, both, a.requirements, null, null, false);
						pickPlan = after;
						pickCost = cost;
						pickRatio = gain / cost;
						pickParts = Arrays.asList(a, b);
					}
				}
			}
			if (pick == null)
			{
				break;
			}
			used.add(pick);
			used.addAll(pickParts);
			have.addAll(pick.pieces);
			Planner.Best next = planner.optimise(have, fighter, target);
			// The fresh search is never worse than the quick one; keep whichever found more.
			Planner.Plan plan = next.dps() >= pickPlan.dps() ? next.best() : pickPlan;
			spent += pickCost;
			Roadmap.Option option = new Roadmap.Option(pick.name, pick.pieces, pick.icon(), pickCost, plan.dps() - base, base, plan,
				null, null, pick.note, pick.ammo);
			path.add(new Roadmap.Step(option, spent, spent <= coins));
			// Build the next step on the loadout this one showed, or its gain is counted twice.
			current = next.keeping(plan);
		}
		return path;
	}

	/** Every item id the roadmap may price, so the plugin can look them up on the client thread. */
	public Set<Integer> priceIds()
	{
		Set<Integer> ids = new HashSet<>();
		for (Candidate c : candidates(Collections.emptySet()))
		{
			for (Gear piece : c.pieces)
			{
				for (int id : piece.getIds())
				{
					ids.add(id);
				}
				CatalogueEntry entry = data.entry(piece);
				if (entry != null && entry.getBuild() != null)
				{
					for (int id : entry.getBuild())
					{
						ids.add(id);
					}
				}
			}
		}
		return ids;
	}

	/**
	 * Upgrades weighed across where the player really fights: the fighting time each would have saved
	 * over the tally's days, at the targets that took the most of it. Ranked by time saved per coin,
	 * like the road; only upgrades the player can wear now and can buy are weighed.
	 */
	public List<Fights.Pick> fights(Collection<Gear> ownedGear, Fighter fighter, Fights.Tally tally, Prices prices)
	{
		if (tally == null || tally.isEmpty())
		{
			return Collections.emptyList();
		}
		Set<Gear> owned = new LinkedHashSet<>(ownedGear);
		List<Start> starts = new ArrayList<>();
		int targets = 0;
		for (Map.Entry<Target, Integer> e : tally.getKills().entrySet())
		{
			if (targets >= Fights.TARGETS)
			{
				break;
			}
			targets++;
			Target t = e.getKey();
			int all = e.getValue();
			// Each kill is weighed as it was fought: on a task with the slayer helmet's bonus, off one without.
			int helmet = helmetKills(fighter.getTask(), tally, t, all);
			addStart(starts, owned, fighter.withTask(SlayerTask.ALWAYS), t, helmet);
			addStart(starts, owned, fighter.withTask(SlayerTask.NEVER), t, all - helmet);
		}
		return weigh(owned, fighter, starts, prices, Fights.MIN_SECONDS * tally.getDays() / Fights.DAYS);
	}

	/**
	 * Upgrades weighed across a shortlist the player chose, such as the bosses left to finish: the
	 * fighting time each would save over {@link #SHORTLIST_KILLS} kills of every listed target,
	 * ranked by time saved per coin. A target the player cannot hurt yet is left out.
	 */
	public List<Fights.Pick> shortlist(Collection<Gear> ownedGear, Fighter fighter, List<Target> targets, Prices prices)
	{
		if (targets == null || targets.isEmpty())
		{
			return Collections.emptyList();
		}
		Set<Gear> owned = new LinkedHashSet<>(ownedGear);
		List<Start> starts = new ArrayList<>();
		for (Target t : targets)
		{
			addStart(starts, owned, fighter, t, SHORTLIST_KILLS);
		}
		return weigh(owned, fighter, starts, prices, 0);
	}

	/** Every upgrade the player can wear and buy now, by the fighting time it saves over the starts per coin. */
	private List<Fights.Pick> weigh(Set<Gear> owned, Fighter fighter, List<Start> starts, Prices prices, double minSeconds)
	{
		if (starts.isEmpty())
		{
			return Collections.emptyList();
		}
		List<Fights.Pick> picks = new ArrayList<>();
		Map<Fights.Pick, Double> value = new HashMap<>();
		for (Candidate c : candidates(owned))
		{
			if (c.earn != null || fighter.missing(c.requirements) != null)
			{
				continue;
			}
			long cost = cost(c, owned, prices);
			if (cost <= 0)
			{
				continue;
			}
			double total = 0;
			Map<String, Double> where = new HashMap<>();
			for (Start start : starts)
			{
				Target t = start.target;
				Planner.Plan after = planner.withAdded(start.best, owned, c.pieces, start.fighter, t);
				if (after.dps() <= start.best.dps() + 1e-9)
				{
					continue;
				}
				double saved = Fights.seconds(start.kills, t, start.best.dps()) - Fights.seconds(start.kills, t, after.dps());
				total += saved;
				where.merge(t.getName(), saved, Double::sum);
			}
			if (total <= 0 || total < minSeconds)
			{
				continue;
			}
			List<String> names = new ArrayList<>(where.keySet());
			names.sort(Comparator.comparingDouble((String n) -> -where.get(n)));
			Fights.Pick pick = new Fights.Pick(c.name, c.icon(), cost, total, names);
			picks.add(pick);
			value.put(pick, total / cost);
		}
		picks.sort(Comparator.comparingDouble((Fights.Pick p) -> -value.get(p)));
		return cut(picks, Fights.PICKS);
	}

	/**
	 * How many of a target's kills to weigh with the slayer helmet's bonus. With the setting on
	 * always or never, all or none. With it following the task, the kills Chronicle saw made on a
	 * task that covers the target, plus, for kills from before it kept the task, those a Slayer
	 * creature (but not a boss) would most likely have been: today's task says nothing of them.
	 */
	static int helmetKills(SlayerTask setting, Fights.Tally tally, Target t, int all)
	{
		if (setting.getMode() != SlayerTask.Mode.SMART)
		{
			return setting.covers(t) ? all : 0;
		}
		if (!t.isSlayer())
		{
			return 0;
		}
		int unknown = SlayerTask.of(SlayerTask.Mode.SMART, null).covers(t) ? tally.unknown(t) : 0;
		return Math.min(all, tally.onTask(t) + unknown);
	}

	private void addStart(List<Start> starts, Set<Gear> owned, Fighter fighter, Target t, int kills)
	{
		if (kills <= 0)
		{
			return;
		}
		Planner.Best best = planner.optimise(owned, fighter, t);
		if (best.dps() > 0)
		{
			starts.add(new Start(t, fighter, best, kills));
		}
	}

	/** Where a fought target's kills start from, for one slayer helmet assumption. */
	private static final class Start
	{
		final Target target;
		final Fighter fighter;
		final Planner.Best best;
		final int kills;

		Start(Target target, Fighter fighter, Planner.Best best, int kills)
		{
			this.target = target;
			this.fighter = fighter;
			this.best = best;
			this.kills = kills;
		}
	}

	/** Every target's best loadout, for the Targets tab. */
	public List<Roadmap.Survey> survey(Collection<Gear> owned, Fighter fighter)
	{
		List<Roadmap.Survey> rows = new ArrayList<>();
		for (Target t : data.targets())
		{
			Planner.Best best = planner.optimise(owned, fighter, t);
			rows.add(new Roadmap.Survey(t, best));
		}
		return rows;
	}

	/** Whether a piece has more damage than what the plan wears in its slot, for the plan's own style. */
	static boolean morePower(Gear g, Planner.Plan plan)
	{
		Result.Kind kind = plan.getResult().getKind();
		if (kind == null || g.getSlot() == Gear.WEAPON)
		{
			return false;
		}
		Gear worn = plan.getLoadout().get(g.getSlot());
		return power(g, kind) > (worn == null ? 0 : power(worn, kind));
	}

	private static int power(Gear g, Result.Kind kind)
	{
		switch (kind)
		{
			case RANGED:
				return g.rangedStrength();
			case MAGIC:
				return g.magicDamage();
			default:
				return g.strength();
		}
	}

	private static double threshold(double base)
	{
		return Math.max(0.02, base * 0.004);
	}

	private static <T> List<T> cut(List<T> list, int size)
	{
		return list.size() <= size ? list : new ArrayList<>(list.subList(0, size));
	}

	private static String imbueNote(Candidate c)
	{
		return c.note == null ? "Made from gear you own" : c.note + ", which you own";
	}

	/** Coins to buy what is not owned yet: -1 when something has no price. */
	long cost(Candidate c, Set<Gear> owned, Prices prices)
	{
		if (c.earn != null)
		{
			return 0;
		}
		long total = 0;
		for (Gear piece : c.pieces)
		{
			if (owned.contains(piece))
			{
				continue;
			}
			CatalogueEntry entry = data.entry(piece);
			int[] build = entry == null ? null : entry.getBuild();
			if (build != null)
			{
				for (int id : build)
				{
					Gear part = data.gear(id);
					if (part != null && owned.contains(part))
					{
						continue;
					}
					long p = prices.price(id);
					if (p <= 0)
					{
						return -1;
					}
					total += p;
				}
				continue;
			}
			long cheapest = -1;
			for (int id : piece.getIds())
			{
				long p = prices.price(id);
				if (p > 0 && (cheapest < 0 || p < cheapest))
				{
					cheapest = p;
				}
			}
			if (cheapest < 0)
			{
				return -1;
			}
			total += cheapest * (piece.getSlot() == Gear.AMMO ? AMMO_STACK : 1);
		}
		return total;
	}

	List<Candidate> candidates(Set<Gear> owned)
	{
		List<Candidate> list = new ArrayList<>();
		for (CatalogueEntry entry : data.catalogue())
		{
			Gear g = entry.getGear();
			if (owned.contains(g) || g.getName().startsWith("Void ") || g.getName().startsWith("Elite void")
				|| g.key().startsWith("obsidian helmet") || superseded(g, owned))
			{
				continue;
			}
			list.add(new Candidate(g.getName(), Collections.singletonList(g), entry.getRequirements(), entry.getEarn(),
				entry.getNote(), g.getSlot() == Gear.AMMO));
		}
		for (String[] bundle : BUNDLES)
		{
			List<Gear> pieces = new ArrayList<>();
			Map<String, Integer> req = new HashMap<>();
			for (int i = 2; i < bundle.length; i++)
			{
				Gear g = data.named(bundle[i]);
				if (g == null)
				{
					pieces = null;
					break;
				}
				pieces.add(g);
				CatalogueEntry entry = data.entry(g);
				if (entry != null)
				{
					entry.getRequirements().forEach((k, v) -> req.merge(k, v, Math::max));
				}
			}
			if (pieces != null && !owned.containsAll(pieces))
			{
				list.add(new Candidate(bundle[0], pieces, req, bundle[1], null, false));
			}
		}
		return list;
	}

	private boolean superseded(Gear g, Set<Gear> owned)
	{
		for (String[] row : SUPERSEDED)
		{
			if (!row[0].equals(g.key()))
			{
				continue;
			}
			for (int i = 1; i < row.length; i++)
			{
				Gear better = data.named(row[i]);
				if (better != null && owned.contains(better))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Something the roadmap can recommend: one piece, or a set that only works whole. */
	static final class Candidate
	{
		final String name;
		final List<Gear> pieces;
		final Map<String, Integer> requirements;
		final String earn;
		final String note;
		final boolean ammo;

		Candidate(String name, List<Gear> pieces, Map<String, Integer> requirements, String earn, String note, boolean ammo)
		{
			this.name = name;
			this.pieces = pieces;
			this.requirements = requirements;
			this.earn = earn;
			this.note = note;
			this.ammo = ammo;
		}

		/** The piece whose picture stands for it: a set shows its body. */
		Gear icon()
		{
			for (Gear g : pieces)
			{
				if (g.getSlot() == Gear.BODY)
				{
					return g;
				}
			}
			return pieces.get(0);
		}
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;
import java.util.Collections;
import java.util.List;

/**
 * Which target the roadmap is for. Normally the one the player chose; while they have a
 * slayer task for a listed monster, and they let the roadmap follow it, the task's monster
 * instead, so the road answers "what should I buy for this task?". Bosses a broad task also
 * covers (Vorkath on blue dragons) are offered, not aimed at, until the player picks one.
 */
public final class Aim
{
	private final Target target;
	private final boolean following;
	private final List<Target> covered;

	private Aim(Target target, boolean following, List<Target> covered)
	{
		this.target = target;
		this.following = following;
		this.covered = covered;
	}

	/**
	 * @param targets every listed target, in the catalogue's order
	 * @param chosen the target the player chose, by name; the first target when it is unknown
	 * @param follow whether to follow the task: the setting is on and the player has not turned
	 *               away from this task by choosing a target it does not cover
	 * @param task the current slayer task's name, or null
	 * @param bossTask whether the task is a boss task, given by a boss slayer master
	 * @param pick which of the task's targets the player picked, or null for the task's own
	 */
	public static Aim choose(List<Target> targets, String chosen, boolean follow, String task, boolean bossTask, String pick)
	{
		Target base = null;
		for (Target t : targets)
		{
			if (t.getName().equals(chosen))
			{
				base = t;
				break;
			}
		}
		if (base == null && !targets.isEmpty())
		{
			base = targets.get(0);
		}
		List<Target> covered = SlayerTask.targetsFor(task, targets);
		if (!follow || covered.isEmpty())
		{
			return new Aim(base, false, covered);
		}
		for (Target t : covered)
		{
			if (t.getName().equals(pick))
			{
				return new Aim(t, true, covered);
			}
		}
		// The chosen target already on the task stays: someone aimed at Cerberus on a hellhound task meant it.
		if (covered.contains(base))
		{
			return new Aim(base, true, covered);
		}
		// A task only moves the aim to a boss when it is that boss's own task: a Bears task is
		// usually done on bears, not Callisto, so it waits for the player to pick the boss.
		Target first = covered.get(0);
		if (bossTask || !"Boss".equals(first.getGroup()) || SlayerTask.normal(first.getName()).equals(SlayerTask.normal(task)))
		{
			return new Aim(first, true, covered);
		}
		return new Aim(base, false, covered);
	}

	public Target getTarget()
	{
		return target;
	}

	/** Whether the target is the task's rather than the one the player chose. */
	public boolean isFollowing()
	{
		return following;
	}

	/** The listed targets the task covers, best first. */
	public List<Target> getCovered()
	{
		return Collections.unmodifiableList(covered);
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import java.util.Locale;
import java.util.Set;

/**
 * The game's combat formulas for one loadout against one monster: effective levels,
 * attack and defence rolls, max hits, and the special effects that change them, such
 * as the salve amulet, slayer helmet, void, crystal armour, the twisted bow and the
 * dragon and demon bane weapons. Every style the weapon offers is tried and the
 * fastest one is kept.
 */
public final class Calc
{
	private static final double TICK = 0.6;

	private static final String[][] STANDARD_SPELLS = {
		{"Fire Strike", "13", "8"}, {"Fire Bolt", "35", "12"}, {"Fire Blast", "59", "16"},
		{"Fire Wave", "75", "20"}, {"Fire Surge", "95", "24"},
	};
	private static final String[][] ANCIENT_SPELLS = {
		{"Ice Rush", "58", "16"}, {"Ice Burst", "70", "22"}, {"Ice Blitz", "82", "26"}, {"Ice Barrage", "94", "30"},
	};

	/** The staves that can autocast the Ancient Magicks, by the start of their names. */
	private static final String[] ANCIENT_STAVES = {
		"ancient staff", "ahrim's staff", "master wand", "kodai wand", "nightmare staff", "harmonised nightmare staff",
		"eldritch nightmare staff", "volatile nightmare staff", "staff of the dead", "toxic staff of the dead",
		"staff of light", "staff of balance", "zuriel's staff", "void knight mace", "blue moon spear",
	};
	/** The soulreaper axe is assumed to be kept at its full stacks. */
	static final int SOULREAPER_STACKS = 5;

	private final RoadmapData data;

	public Calc(RoadmapData data)
	{
		this.data = data;
	}

	/** The best result over every style the weapon offers. */
	public Result best(Loadout loadout, Fighter fighter, Target target)
	{
		return best(loadout, fighter, target, null);
	}

	/** The best result using only one kind of attack, or any when kind is null. */
	public Result best(Loadout loadout, Fighter fighter, Target target, Result.Kind kind)
	{
		return evaluate(loadout, fighter, target, kind, null, null);
	}

	/** One attack type and stance, such as "stab" and "Aggressive", as the equipment screen would set it. */
	public Result styled(Loadout loadout, Fighter fighter, Target target, String type, String stance)
	{
		return evaluate(loadout, fighter, target, null, type, stance);
	}

	private Result evaluate(Loadout loadout, Fighter fighter, Target target, Result.Kind kind, String onlyType, String onlyStance)
	{
		Gear weapon = loadout.weapon();
		String category = weapon == null ? "Unarmed" : weapon.getCategory();
		Totals totals = new Totals(loadout, data.ammoFor(weapon));
		Result best = Result.NONE;
		for (RoadmapData.Style style : data.styles(category))
		{
			String type = style.getType();
			String stance = style.getStance();
			if (stance == null || stance.startsWith("Defensive") || "Longrange".equals(stance) && !"magic".equals(type)
				|| onlyType != null && !(onlyType.equals(type) && onlyStance.equals(stance)))
			{
				continue;
			}
			Result.Kind styleKind = "magic".equals(type) ? Result.Kind.MAGIC : "ranged".equals(type) ? Result.Kind.RANGED : Result.Kind.MELEE;
			if (!target.allows(styleKind.name()))
			{
				continue;
			}
			Result r;
			if ("magic".equals(type))
			{
				if (kind != null && kind != Result.Kind.MAGIC)
				{
					continue;
				}
				r = "Autocast".equals(stance) ? autocast(loadout, totals, fighter, target) : powered(loadout, totals, fighter, target, stance);
			}
			else if ("ranged".equals(type))
			{
				if (kind != null && kind != Result.Kind.RANGED)
				{
					continue;
				}
				r = ranged(loadout, totals, fighter, target, stance);
			}
			else
			{
				if (kind != null && kind != Result.Kind.MELEE)
				{
					continue;
				}
				r = melee(loadout, totals, fighter, target, type, stance);
			}
			r = r.timesUptime(target.uptime(styleKind.name()));
			if (r.isBetterThan(best))
			{
				best = r;
			}
		}
		return best;
	}

	/** Summed bonuses, leaving out ammunition the weapon does not fire. */
	static final class Totals
	{
		final int[] offence = new int[5];
		int strength;
		int rangedStrength;
		int magicDamage;
		boolean ammoValid = true;
		/** Whether the weapon fires the ammunition worn, as bows and crossbows do. */
		boolean firesAmmo;

		Totals(Loadout loadout, Set<Integer> fires)
		{
			Gear ammo = loadout.get(Gear.AMMO);
			boolean countAmmo = fires != null && !fires.isEmpty();
			if (countAmmo)
			{
				ammoValid = ammo != null && firesAny(fires, ammo);
				firesAmmo = ammoValid;
			}
			for (int slot = 0; slot < Gear.SLOTS; slot++)
			{
				Gear g = loadout.get(slot);
				if (g == null)
				{
					continue;
				}
				boolean projectileIgnored = slot == Gear.AMMO && !countAmmo;
				for (int t = 0; t < 5; t++)
				{
					if (!(projectileIgnored && t == Gear.RANGED))
					{
						offence[t] += g.offence(t);
					}
				}
				strength += g.strength();
				if (!projectileIgnored)
				{
					rangedStrength += g.rangedStrength();
				}
				magicDamage += g.magicDamage();
			}
		}

		private static boolean firesAny(Set<Integer> fires, Gear ammo)
		{
			for (int id : ammo.getIds())
			{
				if (fires.contains(id))
				{
					return true;
				}
			}
			return false;
		}
	}

	private Result melee(Loadout lo, Totals tot, Fighter f, Target t, String type, String stance)
	{
		int attackType = "stab".equals(type) ? Gear.STAB : "slash".equals(type) ? Gear.SLASH : Gear.CRUSH;
		Gear weapon = lo.weapon();
		String key = weapon == null ? "" : weapon.key();
		Fighter.Prayer prayer = f.meleePrayer();
		int effAttack = f.attack() * prayer.accuracy / 100 + 8 + ("Accurate".equals(stance) ? 3 : "Controlled".equals(stance) ? 1 : 0);
		int strengthLevel = f.strength() * prayer.strength / 100;
		if (key.equals("soulreaper axe"))
		{
			// Kept at its full five stacks, each worth 6% of the strength level; it does not stack with prayers.
			strengthLevel += f.strength() * SOULREAPER_STACKS * 6 / 100;
		}
		int effStrength = strengthLevel + 8 + ("Aggressive".equals(stance) ? 3 : "Controlled".equals(stance) ? 1 : 0);
		if (voidSet(lo, "void melee helm", false))
		{
			effAttack = effAttack * 11 / 10;
			effStrength = effStrength * 11 / 10;
		}
		long baseRoll = (long) effAttack * (tot.offence[attackType] + 64);
		int baseMax = (effStrength * (tot.strength + 64) + 320) / 640;
		long roll = baseRoll;
		int max = baseMax;

		// The salve amulet and the black mask do not stack; the salve wins on undead.
		boolean undead = t.is("undead");
		boolean demon = t.is("demon");
		boolean dragon = t.is("dragon");
		boolean kalphite = t.is("kalphite");
		boolean revenant = revenantBonus(lo, t, "ursine chainmace", "viggora's chainmace");
		if (undead && lo.wearsAny("salve amulet (e)", "salve amulet(ei)"))
		{
			roll = roll * 6 / 5;
			max = max * 6 / 5;
		}
		else if (undead && lo.wearsAny("salve amulet", "salve amulet(i)"))
		{
			roll = roll * 7 / 6;
			max = max * 7 / 6;
		}
		else if (slayerBonus(lo, f, t, false))
		{
			roll = roll * 7 / 6;
			max = max * 7 / 6;
		}

		// Accuracy, in the order the game applies it.
		boolean obsidian = tzhaarWeapon(lo) && lo.wears("obsidian helmet") && lo.wears("obsidian platebody") && lo.wears("obsidian platelegs");
		if (obsidian)
		{
			roll += baseRoll / 10;
		}
		if (revenant)
		{
			roll = roll * 3 / 2;
		}
		int bane = !demon ? 0 : lo.wearsAny("arclight", "emberlight") ? 70 : lo.wearsAny("silverlight", "darklight") ? 60 : 0;
		bane = bane * t.demonbaneVulnerability() / 100;
		roll += roll * bane / 100;
		if (dragon && key.equals("dragon hunter lance"))
		{
			roll = roll * 6 / 5;
		}
		if (kalphite && key.equals("keris partisan of breaching"))
		{
			roll = roll * 133 / 100;
		}
		int inquisitor = attackType != Gear.CRUSH ? 0 : (lo.wears("inquisitor's great helm") ? 1 : 0)
			+ (lo.wears("inquisitor's hauberk") ? 2 : 0) + (lo.wears("inquisitor's plateskirt") ? 2 : 0);
		roll = roll * (200 + inquisitor) / 200;

		// Max hit, in the order the game applies it.
		if (demon && lo.wearsAny("arclight", "emberlight"))
		{
			max += max * bane / 100;
		}
		if (obsidian)
		{
			max += baseMax / 10;
		}
		if (dragon && key.equals("dragon hunter lance"))
		{
			max = max * 6 / 5;
		}
		if (kalphite && key.startsWith("keris"))
		{
			max = max * (key.equals("keris partisan of amascut") ? 115 : 133) / 100;
		}
		if (revenant)
		{
			max = max * 3 / 2;
		}
		if (demon && lo.wearsAny("silverlight", "darklight"))
		{
			max += max * bane / 100;
		}
		if (key.equals("colossal blade"))
		{
			max += Math.min(t.getSize() * 2, 10);
		}
		max = max * (200 + inquisitor) / 200;

		long defence = (long) (t.getDefence() + 9) * (t.defensive(attackType) + 64);
		boolean fang = key.startsWith("osmumten's fang");
		// The fang rolls its accuracy twice only when it stabs.
		double accuracy = fang && attackType == Gear.STAB ? fangChance(roll, defence) : hitChance(roll, defence);
		boolean berserker = tzhaarWeapon(lo) && lo.wears("berserker necklace");
		boolean shieldBreaker = lo.wearsAny("arclight", "emberlight", "silverlight", "darklight") || key.startsWith("abyssal");
		// Spears, hastas and halberds stab the Corporeal Beast in full, as does the fang.
		boolean corpbane = attackType == Gear.STAB && (fang || key.endsWith("halberd") || key.contains("hasta")
			|| key.contains("spear") && !key.equals("blue moon spear"));
		Npc npc = new Npc(t, Result.Kind.MELEE, shieldBreaker, corpbane);
		double damage;
		if (fang)
		{
			// The fang never rolls in the bottom or top 15% of its range.
			int low = max * 3 / 20;
			max -= low;
			damage = accuracy * npc.mean(low, max, 1, 1, 0);
		}
		else if (key.contains("of vitur"))
		{
			// The scythe's second and third swings hit large monsters for half and a quarter, each rolled on its own.
			damage = 0;
			for (int i = 0; i < Math.min(3, t.getSize()); i++)
			{
				damage += accuracy * npc.mean(0, max >> i, 1, 1, 0);
			}
		}
		else if (key.equals("dual macuahuitl"))
		{
			// Two half hits; the second is only thrown when the first lands.
			int first = max / 2;
			damage = accuracy * npc.mean(0, first, 1, 1, 0) + accuracy * accuracy * npc.mean(0, max - first, 1, 1, 0);
		}
		else if (berserker)
		{
			damage = accuracy * npc.mean(0, max, 6, 5, 0);
			max = max * 6 / 5;
		}
		else if (kalphite && key.startsWith("keris"))
		{
			// One hit in 51 deals triple damage.
			damage = accuracy * (npc.mean(0, max, 1, 1, 0) * 50 + npc.mean(0, max, 3, 1, 0)) / 51;
		}
		else
		{
			damage = accuracy * npc.mean(0, max, 1, 1, 0);
		}
		int ticks = speed(weapon);
		String label = capital(type) + ", " + stance.toLowerCase(Locale.ROOT);
		return new Result(Result.Kind.MELEE, damage / (ticks * TICK), max, accuracy, ticks, label, prayer.name, null);
	}

	private Result ranged(Loadout lo, Totals tot, Fighter f, Target t, String stance)
	{
		if (!tot.ammoValid)
		{
			return Result.NONE;
		}
		Gear weapon = lo.weapon();
		String key = weapon == null ? "" : weapon.key();
		Fighter.Prayer prayer = f.rangedPrayer();
		int effAttack = f.ranged() * prayer.accuracy / 100 + 8 + ("Accurate".equals(stance) ? 3 : 0);
		int effStrength = f.ranged() * prayer.strength / 100 + 8 + ("Accurate".equals(stance) ? 3 : 0);
		if (voidSet(lo, "void ranger helm", false))
		{
			effAttack = effAttack * 11 / 10;
			effStrength = voidSet(lo, "void ranger helm", true) ? effStrength * 9 / 8 : effStrength * 11 / 10;
		}
		int bonus = tot.offence[Gear.RANGED];
		int strength = tot.rangedStrength;
		if (key.startsWith("toxic blowpipe"))
		{
			// Loaded with dragon darts.
			strength += 35;
		}
		if (tot.firesAmmo && lo.wearsAny("dizana's quiver", "blessed dizana's quiver", "dizana's max cape"))
		{
			// A charged quiver adds to arrows and bolts the weapon fires.
			bonus += 10;
			strength += 1;
		}
		long roll = (long) effAttack * (bonus + 64);
		int max = (effStrength * (strength + 64) + 320) / 640;

		boolean crystal = key.startsWith("crystal bow") || key.startsWith("bow of faerdhinen");
		int pieces = !crystal ? 0 : (lo.wears("crystal helm") ? 1 : 0) + (lo.wears("crystal legs") ? 2 : 0) + (lo.wears("crystal body") ? 3 : 0);
		roll = roll * (20 + pieces) / 20;
		max = max * (40 + pieces) / 40;

		boolean undead = t.is("undead");
		boolean dragonbane = t.is("dragon") && key.equals("dragon hunter crossbow");
		boolean demonbane = t.is("demon") && key.equals("scorching bow");
		boolean revenant = revenantBonus(lo, t, "webweaver bow", "craw's bow");
		boolean salve = undead && lo.wearsAny("salve amulet(ei)", "salve amulet(i)");
		boolean mask = !salve && slayerBonus(lo, f, t, true);
		if (salve)
		{
			int num = lo.wears("salve amulet(ei)") ? 6 : 7;
			roll = roll * num / (num - 1);
		}
		else if (mask)
		{
			roll = roll * 23 / 20;
		}
		if (key.equals("twisted bow"))
		{
			int magic = Math.min(250, Math.max(t.getMagic(), t.getMagicAttack()));
			roll = twistedBow(roll, magic, true);
		}
		if (revenant)
		{
			roll = roll * 3 / 2;
		}
		if (dragonbane)
		{
			roll = roll * 13 / 10;
		}
		int bane = 30 * t.demonbaneVulnerability() / 100;
		if (demonbane)
		{
			roll += roll * bane / 100;
		}

		if (salve)
		{
			int num = lo.wears("salve amulet(ei)") ? 6 : 7;
			max = max * num / (num - 1);
		}
		else if (mask)
		{
			// The imbued slayer helmet adds to the revenant, dragon and demon bonuses rather than multiplying them.
			int numerator = 23 + (revenant ? 10 : 0) + (dragonbane ? 5 : 0) + (demonbane ? 6 : 0);
			max = max * numerator / 20;
			revenant = false;
			dragonbane = false;
			demonbane = false;
		}
		if (key.equals("twisted bow"))
		{
			int magic = Math.min(250, Math.max(t.getMagic(), t.getMagicAttack()));
			max = (int) twistedBow(max, magic, false);
		}
		if (revenant)
		{
			max = max * 3 / 2;
		}
		if (dragonbane)
		{
			max = max * 5 / 4;
		}
		if (demonbane)
		{
			max += max * bane / 100;
		}

		String category = weapon == null ? "" : weapon.getCategory();
		int defType = "Thrown".equals(category) ? Target.D_LIGHT : "Bow".equals(category) ? Target.D_STANDARD : Target.D_HEAVY;
		long defence = (long) (t.getDefence() + 9) * (t.defensive(defType) + 64);
		double accuracy = hitChance(roll, defence);
		Npc npc = new Npc(t, Result.Kind.RANGED, key.equals("scorching bow"));
		double damage = accuracy * npc.mean(0, max, 1, 1, 0);
		if (key.equals("dark bow"))
		{
			// Two arrows each attack, each rolled on its own.
			damage *= 2;
		}

		Gear ammo = lo.get(Gear.AMMO);
		if ("Crossbow".equals(category) && ammo != null)
		{
			boolean zaryte = key.equals("zaryte crossbow");
			double diary = f.isKandarinHard() ? 1.1 : 1.0;
			if (ammo.key().startsWith("diamond bolts (e)") || ammo.key().startsWith("diamond dragon bolts (e)"))
			{
				// One bolt in ten pierces armour: it always hits, for up to 15% more.
				double chance = 0.1 * diary;
				double effect = npc.mean(0, max * (zaryte ? 126 : 115) / 100, 1, 1, 0);
				damage = chance * effect + (1 - chance) * damage;
			}
			else if (ammo.key().startsWith("ruby bolts (e)") || ammo.key().startsWith("ruby dragon bolts (e)"))
			{
				// Six in a hundred take a fifth of the monster's current health, up to 100, so the
				// effect is averaged over the whole kill rather than taken at full health.
				double chance = 0.06 * diary;
				double effect = rubyAverage(npc, t.getHp(), zaryte ? 22 : 20, zaryte ? 110 : 100);
				damage = chance * effect + (1 - chance) * damage;
			}
		}
		int ticks = Math.max(1, speed(weapon) - ("Rapid".equals(stance) ? 1 : 0));
		return new Result(Result.Kind.RANGED, damage / (ticks * TICK), max, accuracy, ticks, stance, prayer.name, null);
	}

	/** The ruby bolt's damage averaged over every health the monster passes through from full to dead. */
	static double rubyAverage(Npc npc, int hp, int percent, int cap)
	{
		if (hp <= 0)
		{
			return 0;
		}
		double sum = 0;
		for (int h = 1; h <= hp; h++)
		{
			sum += npc.hit(Math.max(1, Math.min(cap, h * percent / 100)));
		}
		return sum / hp;
	}

	/** Staves with their own spell built in, such as tridents and Tumeken's shadow. */
	private Result powered(Loadout lo, Totals tot, Fighter f, Target t, String stance)
	{
		Gear weapon = lo.weapon();
		if (weapon == null)
		{
			return Result.NONE;
		}
		int level = f.magic();
		String key = weapon.key();
		int base;
		if (key.startsWith("trident of the seas"))
		{
			base = Math.max(1, level / 3 - 5);
		}
		else if (key.startsWith("trident of the swamp"))
		{
			base = Math.max(1, level / 3 - 2);
		}
		else if (key.contains("sanguinesti staff"))
		{
			base = Math.max(1, level / 3);
		}
		else if (key.equals("tumeken's shadow"))
		{
			base = Math.max(1, level / 3 + 1);
		}
		else if (key.equals("eye of ayak"))
		{
			base = Math.max(1, level / 3 - 6);
		}
		else if (key.equals("warped sceptre"))
		{
			base = Math.max(1, (8 * level + 96) / 37);
		}
		else if (key.equals("accursed sceptre"))
		{
			base = Math.max(1, level / 3 - 6);
		}
		else if (key.equals("thammaron's sceptre"))
		{
			base = Math.max(1, level / 3 - 8);
		}
		else
		{
			return Result.NONE;
		}
		return magic(lo, tot, f, t, base, "Accurate".equals(stance) ? 2 : 0, speed(weapon), null, null, false,
			"Accurate".equals(stance) ? "Accurate" : "Longrange");
	}

	/** Staves that autocast a combat spell: the strongest fire spell, or ice from the Ancient Magicks. */
	private Result autocast(Loadout lo, Totals tot, Fighter f, Target t)
	{
		Result best = Result.NONE;
		int real = f.level("Magic");
		Gear weapon = lo.weapon();
		boolean harmonised = weapon != null && weapon.key().startsWith("harmonised nightmare staff");
		String[] fire = pick(STANDARD_SPELLS, real);
		if (fire != null)
		{
			best = magic(lo, tot, f, t, Integer.parseInt(fire[2]), 0, harmonised ? 4 : 5, fire[0], "fire", false, "Autocast");
		}
		String[] ice = f.isAncients() && autocastsAncients(weapon) ? pick(ANCIENT_SPELLS, real) : null;
		if (ice != null)
		{
			// Ice spells have no element, so no weakness applies to them.
			Result r = magic(lo, tot, f, t, Integer.parseInt(ice[2]), 0, 5, ice[0], null, true, "Autocast");
			if (r.isBetterThan(best))
			{
				best = r;
			}
		}
		return best;
	}

	/** Only some staves can autocast the Ancient Magicks. */
	static boolean autocastsAncients(Gear weapon)
	{
		if (weapon == null)
		{
			return false;
		}
		String key = weapon.key();
		for (String staff : ANCIENT_STAVES)
		{
			if (key.startsWith(staff))
			{
				return true;
			}
		}
		return key.contains("ancient sceptre");
	}

	private static String[] pick(String[][] spells, int level)
	{
		String[] best = null;
		for (String[] spell : spells)
		{
			if (level >= Integer.parseInt(spell[1]))
			{
				best = spell;
			}
		}
		return best;
	}

	private Result magic(Loadout lo, Totals tot, Fighter f, Target t, int base, int stanceBonus, int ticks,
		String spell, String element, boolean ancient, String style)
	{
		Gear weapon = lo.weapon();
		String key = weapon == null ? "" : weapon.key();
		Fighter.Prayer prayer = f.magicPrayer();
		int effMagic = f.magic() * prayer.accuracy / 100 + 9 + stanceBonus;
		if (voidSet(lo, "void mage helm", false))
		{
			effMagic = effMagic * 29 / 20;
		}
		int bonus = tot.offence[Gear.MAGIC];
		int damageBonus = tot.magicDamage;
		if (key.equals("tumeken's shadow"))
		{
			bonus *= 3;
			damageBonus = Math.min(1000, damageBonus * 3);
		}
		if (ancient)
		{
			// Each piece of virtus adds 3% to Ancient Magicks.
			damageBonus += 30 * ((lo.wears("virtus mask") ? 1 : 0) + (lo.wears("virtus robe top") ? 1 : 0)
				+ (lo.wears("virtus robe bottom") ? 1 : 0));
		}
		if (voidSet(lo, "void mage helm", true))
		{
			damageBonus += 50;
		}
		long baseRoll = (long) effMagic * (bonus + 64);
		long roll = baseRoll;
		boolean undead = t.is("undead");
		boolean mask = false;
		boolean revenant = revenantBonus(lo, t, "accursed sceptre", "thammaron's sceptre");
		if (undead && lo.wears("salve amulet(ei)"))
		{
			roll = roll * 120 / 100;
			damageBonus += 200;
		}
		else if (undead && lo.wears("salve amulet(i)"))
		{
			roll = roll * 115 / 100;
			damageBonus += 150;
		}
		else if (slayerBonus(lo, f, t, true))
		{
			mask = true;
		}
		if (mask)
		{
			roll = roll * 23 / 20;
		}
		if (revenant)
		{
			roll = roll * 3 / 2;
		}
		boolean weak = element != null && element.equals(t.weakness());
		if (weak)
		{
			roll += baseRoll * t.weaknessSeverity() / 100;
		}
		damageBonus += prayer.magicDamage;
		int max = base + base * damageBonus / 1000;
		if (mask)
		{
			max = max * 23 / 20;
		}
		if (revenant)
		{
			max = max * 3 / 2;
		}
		if (weak)
		{
			max += base * t.weaknessSeverity() / 100;
		}
		if ("fire".equals(element) && lo.wears("tome of fire"))
		{
			// A charged tome of fire adds a tenth to fire spells.
			max = max * 11 / 10;
		}
		long defence = (long) (t.getMagic() + 9) * (t.defensive(Target.D_MAGIC) + 64);
		double accuracy = hitChance(roll, defence);
		Npc npc = new Npc(t, Result.Kind.MAGIC, false);
		double perHit = npc.mean(0, max, 1, 1, 0);
		if (key.contains("sanguinesti staff"))
		{
			// One landed hit in five deals 8 more.
			perHit = 0.8 * perHit + 0.2 * npc.mean(0, max, 1, 1, 8);
		}
		double damage = accuracy * perHit;
		return new Result(Result.Kind.MAGIC, damage / (ticks * TICK), max, accuracy, ticks, style, prayer.name, spell);
	}

	/** Whether a revenant weapon, kept charged, gets its half again against a Wilderness monster. */
	private static boolean revenantBonus(Loadout lo, Target t, String... weapons)
	{
		Gear weapon = lo.weapon();
		if (weapon == null || !t.isWilderness())
		{
			return false;
		}
		for (String w : weapons)
		{
			if (weapon.key().equals(w))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * What one landed hit is worth against a target: the game raises an accurate 0 to 1, then the
	 * target's own rules apply, such as Zulrah's cap on big hits, the Kraken shrugging off ranged
	 * attacks, the Tormented demon's shield and flat armour.
	 */
	static final class Npc
	{
		private final boolean zulrah;
		private final int halve;
		private final int divisor;
		private final boolean shielded;
		private final int flat;

		Npc(Target t, Result.Kind kind, boolean bane)
		{
			this(t, kind, bane, kind == Result.Kind.MAGIC);
		}

		/** Corpbane weapons (stabbing spears and halberds, the fang, and magic) hurt the Corporeal Beast in full. */
		Npc(Target t, Result.Kind kind, boolean bane, boolean corpbane)
		{
			String name = t.getName();
			zulrah = "Zulrah".equals(name);
			halve = "Corporeal Beast".equals(name) && !corpbane ? 2 : 1;
			divisor = kind == Result.Kind.RANGED && "Kraken".equals(name) ? 7 : 1;
			shielded = "Tormented Demon".equals(name) && !bane;
			flat = kind == Result.Kind.MAGIC ? 0 : t.getFlatArmour();
		}

		/** The mean of a landed hit rolled from lo to hi, each scaled by num/den and given add. */
		double mean(int lo, int hi, int num, int den, int add)
		{
			if (hi <= 0 && add <= 0)
			{
				return 0;
			}
			int top = Math.max(lo, hi);
			double sum = 0;
			for (int h = lo; h <= top; h++)
			{
				// The Corporeal Beast halves hits after the 0 is raised to 1.
				sum += hit(Math.max(1, h * num / den + add) / halve);
			}
			return sum / (top - lo + 1);
		}

		/** One landed hitsplat after the target's rules. */
		double hit(int h)
		{
			if (zulrah && h > 50)
			{
				// Zulrah turns any hit over 50 into one from 45 to 50.
				double sum = 0;
				for (int i = 45; i <= 50; i++)
				{
					sum += rest(i);
				}
				return sum / 6;
			}
			return rest(h);
		}

		private double rest(int h)
		{
			int d = h >= 1 ? Math.max(1, h / divisor) : 0;
			if (shielded)
			{
				// A shielded Tormented demon takes a fifth less from anything but demonbane and abyssal weapons.
				d = Math.max(d >= 1 ? 1 : d, d * 4 / 5);
			}
			return Math.max(0, d - flat);
		}
	}

	private static boolean slayerBonus(Loadout lo, Fighter f, Target t, boolean imbuedOnly)
	{
		if (!f.onTaskFor(t))
		{
			return false;
		}
		Gear head = lo.get(Gear.HEAD);
		if (head == null)
		{
			return false;
		}
		String key = head.key();
		boolean mask = key.contains("slayer helmet") || key.startsWith("black mask");
		return mask && (!imbuedOnly || key.contains("(i)"));
	}

	private static boolean tzhaarWeapon(Loadout lo)
	{
		Gear weapon = lo.weapon();
		if (weapon == null)
		{
			return false;
		}
		String key = weapon.key();
		return key.startsWith("toktz-xil-") || key.startsWith("tzhaar-ket-") || key.startsWith("toktz-mej-");
	}

	/** Whether a full void set with the given helm is worn; elite asks for the elite top and robe. */
	private static boolean voidSet(Loadout lo, String helm, boolean elite)
	{
		if (!lo.wears(helm) || !lo.wears("void knight gloves"))
		{
			return false;
		}
		boolean eliteSet = lo.wears("elite void top") && lo.wears("elite void robe");
		if (elite)
		{
			return eliteSet;
		}
		return eliteSet || lo.wears("void knight top") && lo.wears("void knight robe");
	}

	private static int speed(Gear weapon)
	{
		return weapon == null || weapon.getSpeed() <= 0 ? 4 : weapon.getSpeed();
	}

	static double hitChance(long attack, long defence)
	{
		if (attack > defence)
		{
			return 1 - (defence + 2.0) / (2.0 * (attack + 1));
		}
		return attack / (2.0 * (defence + 1));
	}

	/** Osmumten's fang rolls its accuracy twice and keeps the better one. */
	static double fangChance(long attack, long defence)
	{
		double a = attack;
		double d = defence;
		if (attack > defence)
		{
			return 1 - (d + 2) * (2 * d + 3) / (6 * (a + 1) * (a + 1));
		}
		return a * (4 * a + 5) / (6 * (a + 1) * (d + 1));
	}

	/** The twisted bow's scaling with the target's magic, for accuracy or damage. */
	static long twistedBow(long value, int magic, boolean accuracy)
	{
		int factor = accuracy ? 10 : 14;
		int base = accuracy ? 140 : 250;
		long t2 = (3L * magic - factor) / 100;
		long inner = 3L * magic / 10 - 10L * factor;
		long t3 = inner * inner / 100;
		long bonus = Math.max(0, Math.min(base, base + t2 - t3));
		return value * bonus / 100;
	}

	private static String capital(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.codex.gearroadmap.core;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The road behind: each upgrade from the road the player has picked up, newest first, with the
 * damage it added, where, and when. Saved per account so the panel can show how far the road has
 * come; only the latest few are kept.
 */
public final class Claims
{
	/** Claims kept; older ones fall off the end. */
	public static final int KEPT = 12;
	static final double MAX_GAIN = 100;
	/** Far enough ahead for any clock, short of a date no claim could have. */
	static final long MAX_AT = 4_102_444_800_000L;

	/** One upgrade picked up from the road. */
	public static final class Claim
	{
		private String name;
		private int icon;
		private double gain;
		private String target;
		private long at;

		/** For Gson. */
		Claim()
		{
		}

		public Claim(String name, int icon, double gain, String target, long at)
		{
			this.name = name;
			this.icon = icon;
			this.gain = gain;
			this.target = target;
			this.at = at;
		}

		public String getName()
		{
			return name;
		}

		public int getIcon()
		{
			return icon;
		}

		/** Damage per second it added against its target when it was picked up. */
		public double getGain()
		{
			return gain;
		}

		public String getTarget()
		{
			return target;
		}

		public long getAt()
		{
			return at;
		}

		boolean isValid()
		{
			// No upgrade adds a hundred damage a second; a figure past it, or a time to come, is a damaged save.
			return name != null && !name.isEmpty() && target != null && at > 0 && at < MAX_AT && gain >= 0 && gain < MAX_GAIN;
		}
	}

	private List<Claim> claims = new ArrayList<>();

	/**
	 * The saved road behind, or none when it cannot be read. A claim that cannot be read is left out
	 * on its own, so the others are kept (and saved again with the next claim).
	 */
	public static Claims read(Gson gson, String json)
	{
		JsonObject o = Saved.object(gson, json);
		Claims read = new Claims();
		for (Claim c : Saved.list(gson, o == null ? null : o.get("claims"), Claim.class))
		{
			if (c.isValid())
			{
				read.claims.add(c);
			}
		}
		read.claims.sort((a, b) -> Long.compare(b.at, a.at));
		while (read.claims.size() > KEPT)
		{
			read.claims.remove(read.claims.size() - 1);
		}
		return read;
	}

	/**
	 * Adds a claim at the front. The same upgrade claimed again (sold and bought back) moves up
	 * rather than being listed twice.
	 */
	public void add(Claim claim)
	{
		if (claim == null || !claim.isValid())
		{
			return;
		}
		List<Claim> list = list();
		list.removeIf(c -> c.name.equals(claim.name));
		list.add(0, claim);
		while (list.size() > KEPT)
		{
			list.remove(list.size() - 1);
		}
		claims = list;
	}

	/** Newest first; a copy. Claims read back broken from an old or hand-edited save are left out. */
	public List<Claim> recent()
	{
		List<Claim> out = new ArrayList<>();
		for (Claim c : list())
		{
			if (c != null && c.isValid())
			{
				out.add(c);
			}
		}
		out.sort((a, b) -> Long.compare(b.at, a.at));
		return Collections.unmodifiableList(out);
	}

	public boolean isEmpty()
	{
		return recent().isEmpty();
	}

	private List<Claim> list()
	{
		List<Claim> out = new ArrayList<>();
		if (claims != null)
		{
			for (Claim c : claims)
			{
				if (c != null && c.isValid())
				{
					out.add(c);
				}
			}
		}
		return out;
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * The player as the formulas need them: real levels, which potions and prayers to
 * assume, which offensive prayers they have unlocked and the spellbook they can use.
 */
public final class Fighter
{
	public enum Boost
	{
		NONE("No potions"),
		POTIONS("Combat potions"),
		BEST("Best boosts");

		private final String label;

		Boost(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private final Map<String, Integer> levels;
	private final Boost boost;
	private final boolean prayers;
	private final boolean piety;
	private final boolean rigour;
	private final boolean augury;
	private final boolean ancients;
	private final SlayerTask task;
	private boolean deadeye;
	private boolean vigour;
	private boolean kandarinHard;

	public Fighter(Map<String, Integer> levels, Boost boost, boolean prayers, boolean piety, boolean rigour, boolean augury,
		boolean ancients, boolean onTask)
	{
		this(levels, boost, prayers, piety, rigour, augury, ancients, onTask ? SlayerTask.ALWAYS : SlayerTask.NEVER);
	}

	public Fighter(Map<String, Integer> levels, Boost boost, boolean prayers, boolean piety, boolean rigour, boolean augury,
		boolean ancients, SlayerTask task)
	{
		this.levels = levels == null ? Collections.emptyMap() : new HashMap<>(levels);
		this.boost = boost == null ? Boost.NONE : boost;
		this.prayers = prayers;
		this.piety = piety;
		this.rigour = rigour;
		this.augury = augury;
		this.ancients = ancients;
		this.task = task == null ? SlayerTask.NEVER : task;
	}

	/**
	 * The same fighter with the prayer scrolls read from the game (Deadeye and Mystic Vigour)
	 * and whether the Kandarin hard diary is done, which makes enchanted bolts trigger more often.
	 */
	public Fighter withUnlocks(boolean deadeye, boolean vigour, boolean kandarinHard)
	{
		Fighter f = new Fighter(levels, boost, prayers, piety, rigour, augury, ancients, task);
		f.deadeye = deadeye;
		f.vigour = vigour;
		f.kandarinHard = kandarinHard;
		return f;
	}

	/** The same fighter with another slayer helmet assumption, to weigh kills made on and off a task apart. */
	public Fighter withTask(SlayerTask other)
	{
		return new Fighter(levels, boost, prayers, piety, rigour, augury, ancients, other).withUnlocks(deadeye, vigour, kandarinHard);
	}

	/** The same fighter with one skill at another level, to weigh what training it is worth. */
	public Fighter withLevel(String skill, int level)
	{
		Map<String, Integer> raised = new HashMap<>(levels);
		raised.put(skill, level);
		return new Fighter(raised, boost, prayers, piety, rigour, augury, ancients, task).withUnlocks(deadeye, vigour, kandarinHard);
	}

	/** A maxed account with every unlock, used for previews and tests. */
	public static Fighter maxed(Boost boost)
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String skill : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Hitpoints", "Agility"})
		{
			levels.put(skill, 99);
		}
		return new Fighter(levels, boost, true, true, true, true, true, false).withUnlocks(true, true, true);
	}

	public int level(String skill)
	{
		Integer level = levels.get(skill);
		return level == null ? 1 : level;
	}

	public Map<String, Integer> getLevels()
	{
		return Collections.unmodifiableMap(levels);
	}

	public Boost getBoost()
	{
		return boost;
	}

	public boolean isAncients()
	{
		return ancients;
	}

	public SlayerTask getTask()
	{
		return task;
	}

	/** Whether the black mask and slayer helmet count against this target. */
	public boolean onTaskFor(Target target)
	{
		return task.covers(target);
	}

	public boolean isKandarinHard()
	{
		return kandarinHard;
	}

	/** Everything that changes the numbers besides levels and gear, for caching. */
	public String assumptions()
	{
		return boost + "/" + prayers + piety + rigour + augury + deadeye + vigour + "/" + ancients + kandarinHard + "/" + task;
	}

	/** Whether the player meets every level an item asks for. */
	public boolean meets(Map<String, Integer> requirements)
	{
		for (Map.Entry<String, Integer> r : requirements.entrySet())
		{
			if (level(r.getKey()) < r.getValue())
			{
				return false;
			}
		}
		return true;
	}

	/** The first requirement not met, as "75 Ranged", or null. */
	public String missing(Map<String, Integer> requirements)
	{
		for (Map.Entry<String, Integer> r : requirements.entrySet())
		{
			if (level(r.getKey()) < r.getValue())
			{
				return r.getValue() + " " + r.getKey();
			}
		}
		return null;
	}

	/** How many levels in all the fighter is short of these requirements. */
	public int shortfall(Map<String, Integer> requirements)
	{
		int total = 0;
		for (Map.Entry<String, Integer> r : requirements.entrySet())
		{
			total += Math.max(0, r.getValue() - level(r.getKey()));
		}
		return total;
	}

	int attack()
	{
		return melee(level("Attack"));
	}

	int strength()
	{
		return melee(level("Strength"));
	}

	private int melee(int level)
	{
		// Super combat potion: 5 plus 15%.
		return boost == Boost.NONE ? level : level + 5 + level * 15 / 100;
	}

	int ranged()
	{
		int level = level("Ranged");
		// Ranging potion: 4 plus 10%.
		return boost == Boost.NONE ? level : level + 4 + level / 10;
	}

	int magic()
	{
		int level = level("Magic");
		switch (boost)
		{
			case POTIONS:
				// Magic potion.
				return level + 4;
			case BEST:
				// Saturated heart.
				return level + 4 + level / 10;
			default:
				return level;
		}
	}

	/** The best melee prayer as accuracy and strength percentages, with its name. */
	Prayer meleePrayer()
	{
		int prayer = level("Prayer");
		int defence = level("Defence");
		if (!prayers)
		{
			return Prayer.NONE;
		}
		if (piety && prayer >= 70 && defence >= 70)
		{
			return new Prayer("Piety", 120, 123, 0);
		}
		if (piety && prayer >= 60 && defence >= 65)
		{
			return new Prayer("Chivalry", 115, 118, 0);
		}
		int accuracy = prayer >= 34 ? 115 : prayer >= 16 ? 110 : prayer >= 7 ? 105 : 100;
		int damage = prayer >= 31 ? 115 : prayer >= 13 ? 110 : prayer >= 4 ? 105 : 100;
		if (prayer >= 34)
		{
			return new Prayer("Incredible Reflexes and Ultimate Strength", accuracy, damage, 0);
		}
		return accuracy == 100 && damage == 100 ? Prayer.NONE : new Prayer("Offensive prayers", accuracy, damage, 0);
	}

	Prayer rangedPrayer()
	{
		int prayer = level("Prayer");
		if (!prayers)
		{
			return Prayer.NONE;
		}
		if (rigour && prayer >= 74 && level("Defence") >= 70)
		{
			return new Prayer("Rigour", 120, 123, 0);
		}
		if (deadeye && prayer >= 62)
		{
			return new Prayer("Deadeye", 118, 118, 0);
		}
		if (prayer >= 44)
		{
			return new Prayer("Eagle Eye", 115, 115, 0);
		}
		if (prayer >= 26)
		{
			return new Prayer("Hawk Eye", 110, 110, 0);
		}
		return prayer >= 8 ? new Prayer("Sharp Eye", 105, 105, 0) : Prayer.NONE;
	}

	Prayer magicPrayer()
	{
		int prayer = level("Prayer");
		if (!prayers)
		{
			return Prayer.NONE;
		}
		if (augury && prayer >= 77 && level("Defence") >= 70)
		{
			return new Prayer("Augury", 125, 100, 40);
		}
		if (vigour && prayer >= 63)
		{
			return new Prayer("Mystic Vigour", 118, 100, 30);
		}
		if (prayer >= 45)
		{
			return new Prayer("Mystic Might", 115, 100, 20);
		}
		if (prayer >= 27)
		{
			return new Prayer("Mystic Lore", 110, 100, 10);
		}
		return prayer >= 9 ? new Prayer("Mystic Will", 105, 100, 0) : Prayer.NONE;
	}

	/** An offensive prayer: accuracy and strength as percentages, and magic damage in tenths of a percent. */
	static final class Prayer
	{
		static final Prayer NONE = new Prayer(null, 100, 100, 0);

		final String name;
		final int accuracy;
		final int strength;
		final int magicDamage;

		Prayer(String name, int accuracy, int strength, int magicDamage)
		{
			this.name = name;
			this.accuracy = accuracy;
			this.strength = strength;
			this.magicDamage = magicDamage;
		}
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;
import java.util.Collection;
import java.util.HashMap;
import java.util.Map;

/**
 * The listed target the player is fighting right now, if any, so the roadmap can offer to aim at
 * it in one click. It never moves the aim by itself: someone fighting Vorkath may well be planning
 * for Zulrah. A fight is remembered for a few minutes after the last blow, through a bank trip.
 */
public final class Fighting
{
	/** How long a fight is offered after the player last attacked it. */
	public static final long FRESH_MS = 5 * 60_000L;
	/** Monsters the game names apart from the target that stands for them. */
	private static final String[][] ALIASES = {
		{"dusk", "grotesque guardians"},
		{"dawn", "dawn (grotesque guardians)"},
	};

	private final Map<String, Target> byKey = new HashMap<>();
	private Target target;
	private long lastAt;

	public Fighting(Collection<Target> targets)
	{
		for (Target t : targets)
		{
			byKey.put(Fights.key(t.getName()), t);
		}
		for (String[] alias : ALIASES)
		{
			Target t = byKey.get(alias[1]);
			if (t != null)
			{
				byKey.put(alias[0], t);
			}
		}
	}

	/** The listed target a monster of this name stands for, or null. */
	public Target match(String npcName)
	{
		return npcName == null ? null : byKey.get(Fights.key(npcName.replace(' ', ' ')));
	}

	/**
	 * The player is attacking a monster of this name.
	 *
	 * @return true when the target being fought changed
	 */
	public boolean saw(String npcName, long now)
	{
		Target t = match(npcName);
		if (t == null)
		{
			return false;
		}
		lastAt = now;
		if (t == target)
		{
			return false;
		}
		target = t;
		return true;
	}

	/**
	 * Lets go of a fight not seen for a while.
	 *
	 * @return true when it was let go
	 */
	public boolean expire(long now)
	{
		if (target != null && now - lastAt > FRESH_MS)
		{
			target = null;
			return true;
		}
		return false;
	}

	/** The listed target being fought, or null. */
	public Target current()
	{
		return target;
	}

	public void clear()
	{
		target = null;
		lastAt = 0;
	}
}

package com.codex.gearroadmap.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Where the player really fights, from the sessions Codex Session Chronicle files in its journal,
 * and which upgrades would save them the most fighting time there. Chronicle's journal is read,
 * never written; without it there is nothing here and the rest of the plugin is unchanged.
 */
public final class Fights
{
	/** Days of sessions counted. */
	public static final int DAYS = 30;
	/**
	 * More kills than one session could hold (one every game tick for a week); a line claiming more is
	 * a damaged save and counts this many. A long day's grind of tens of thousands is real.
	 */
	public static final int MAX_KILLS = 1_000_000;
	private static final int ON = 0;
	private static final int OFF = 1;
	/** Fought targets weighed at most, the ones that took the most fighting time first. */
	static final int TARGETS = 6;
	/** Upgrades offered at most. */
	static final int PICKS = 5;
	/** Fighting time an upgrade must save over a full window to be offered at all; less over a shorter one. */
	static final double MIN_SECONDS = 10 * 60;

	private Fights()
	{
	}

	/**
	 * One session in Chronicle's journal as it saves it (group "codexsessionchronicle", key "journal",
	 * a list of these; key "current" holds one): when it began and its kill lines by key.
	 */
	public static final class Logged
	{
		long startedAt;
		Map<String, Line> kills;

		Logged()
		{
		}

		Logged(long startedAt, Map<String, Line> kills)
		{
			this.startedAt = startedAt;
			this.kills = kills;
		}
	}

	/**
	 * Chronicle's saved journal (a list) or live session (one), as sessions; empty when it cannot be
	 * read. A session that cannot be read is left out on its own, and so is a kill line within one.
	 */
	public static List<Logged> read(Gson gson, String json, boolean list)
	{
		if (json == null || json.trim().isEmpty())
		{
			return Collections.emptyList();
		}
		try
		{
			// The quick way, whenever it all reads whole; Chronicle's journal is read on every replan.
			List<Logged> whole = list ? gson.fromJson(json, LOGGED_LIST) : Collections.singletonList(gson.fromJson(json, Logged.class));
			List<Logged> out = new ArrayList<>();
			for (Logged s : whole)
			{
				if (s != null && s.kills != null)
				{
					s.kills.values().removeIf(line -> line == null);
					out.add(s);
				}
			}
			return out;
		}
		catch (RuntimeException e)
		{
			// Something in it is broken (or it is not a journal at all): read it session by session below.
		}
		JsonElement root = Saved.tree(gson, json);
		List<JsonElement> sessions = new ArrayList<>();
		if (list && root != null && root.isJsonArray())
		{
			root.getAsJsonArray().forEach(sessions::add);
		}
		else if (!list && root != null && root.isJsonObject())
		{
			sessions.add(root);
		}
		List<Logged> out = new ArrayList<>();
		for (JsonElement e : sessions)
		{
			if (!e.isJsonObject())
			{
				continue;
			}
			JsonObject o = e.getAsJsonObject();
			Long startedAt = Saved.whole(o.get("startedAt"));
			JsonElement kills = o.get("kills");
			if (startedAt == null || kills == null || !kills.isJsonObject())
			{
				continue;
			}
			Map<String, Line> lines = new HashMap<>();
			for (Map.Entry<String, JsonElement> k : kills.getAsJsonObject().entrySet())
			{
				Line line = Saved.as(gson, k.getValue(), Line.class);
				if (line != null)
				{
					lines.put(k.getKey(), line);
				}
			}
			out.add(new Logged(startedAt, lines));
		}
		return out;
	}

	private static final java.lang.reflect.Type LOGGED_LIST = new com.google.gson.reflect.TypeToken<List<Logged>>()
	{
	}.getType();

	/** One of Chronicle's kill lines, counted the way Chronicle counts it. */
	public static final class Line
	{
		String name;
		int looted;
		int firstKc;
		int lastKc;
		Map<String, int[]> counters;
		/** True for loot from something opened rather than killed; null in older saves. */
		Boolean event;
		/**
		 * Kills looted while a slayer task was assigned, by the task's name, and under "" those looted
		 * with no task; null in sessions Chronicle saved before it kept them.
		 */
		Map<String, Integer> tasks;

		Line()
		{
		}

		Line(String name, int looted)
		{
			this.name = name;
			this.looted = looted;
		}

		int count()
		{
			long counted = 0;
			if (counters != null)
			{
				for (int[] range : counters.values())
				{
					if (range != null && range.length == 2 && range[1] >= range[0])
					{
						counted += (long) range[1] - range[0] + 1;
					}
				}
			}
			else if (firstKc > 0 && lastKc >= firstKc)
			{
				counted = (long) lastKc - firstKc + 1;
			}
			return (int) Math.min(MAX_KILLS, Math.max(Math.max(0, looted), counted));
		}

		boolean isKill()
		{
			return firstKc > 0 || counters != null && !counters.isEmpty() || !Boolean.TRUE.equals(event);
		}
	}

	/** Kills of each target over the last {@link #DAYS} days, most fighting first. */
	public static final class Tally
	{
		private final Map<Target, Integer> kills;
		private final Map<Target, int[]> split;
		private final int sessions;
		private final int days;

		Tally(Map<Target, Integer> kills, int sessions)
		{
			this(kills, Collections.emptyMap(), sessions, DAYS);
		}

		Tally(Map<Target, Integer> kills, Map<Target, int[]> split, int sessions, int days)
		{
			this.kills = kills;
			this.split = split;
			this.sessions = sessions;
			this.days = days;
		}

		/** Kills of a target made on a slayer task that covers it. */
		public int onTask(Target t)
		{
			int[] s = split.get(t);
			return s == null ? 0 : s[ON];
		}

		/** Kills of a target made with no task for it, as Chronicle saw. */
		public int offTask(Target t)
		{
			int[] s = split.get(t);
			return s == null ? 0 : s[OFF];
		}

		/** Kills of a target from before Chronicle kept the slayer task, or counted without loot. */
		public int unknown(Target t)
		{
			Integer all = kills.get(t);
			return all == null ? 0 : Math.max(0, all - onTask(t) - offTask(t));
		}

		/** Days the kills were counted over: fewer than {@link #DAYS} while the journal is younger than that. */
		public int getDays()
		{
			return days;
		}

		public Map<Target, Integer> getKills()
		{
			return kills;
		}

		/** Sessions in the window that had a kill of a target on the list. */
		public int getSessions()
		{
			return sessions;
		}

		public boolean isEmpty()
		{
			return kills.isEmpty();
		}

		/** A short key that changes when the tally does, for caching. */
		public String key()
		{
			StringBuilder b = new StringBuilder();
			kills.forEach((t, n) -> b.append(t.getName()).append('=').append(n).append(';'));
			return b.toString();
		}
	}

	/** An upgrade weighed across where the player fights. */
	public static final class Pick
	{
		private final String name;
		private final Gear icon;
		private final long cost;
		private final double seconds;
		private final List<String> where;

		Pick(String name, Gear icon, long cost, double seconds, List<String> where)
		{
			this.name = name;
			this.icon = icon;
			this.cost = cost;
			this.seconds = seconds;
			this.where = where;
		}

		public String getName()
		{
			return name;
		}

		public Gear getIcon()
		{
			return icon;
		}

		public long getCost()
		{
			return cost;
		}

		/** Fighting time it would have saved over the tally's days, in seconds. */
		public double getSeconds()
		{
			return seconds;
		}

		/** The fought targets it saves the most time at, most first. */
		public List<String> getWhere()
		{
			return where;
		}
	}

	/**
	 * Counts the kills of every target on the list in sessions begun in the last {@link #DAYS} days.
	 * Loot from something opened rather than killed is left out, as Chronicle leaves it out. The first
	 * of two sessions begun at the same moment is kept, so pass the journal before the live session.
	 */
	public static Tally tally(Collection<Logged> sessions, Collection<Target> targets, long now)
	{
		Map<String, Target> byKey = new HashMap<>();
		for (Target t : targets)
		{
			byKey.put(key(t.getName()), t);
		}
		long from = now - DAYS * 86_400_000L;
		Map<Target, Integer> kills = new HashMap<>();
		Map<Target, int[]> split = new HashMap<>();
		int counted = 0;
		long earliest = now;
		// A session Chronicle has just filed can still be its live one for a moment: count it once.
		Set<Long> seen = new HashSet<>();
		for (Logged s : sessions)
		{
			if (s == null || s.kills == null || s.startedAt < from || s.startedAt > now || !seen.add(s.startedAt))
			{
				continue;
			}
			boolean any = false;
			for (Map.Entry<String, Line> e : s.kills.entrySet())
			{
				Line line = e.getValue();
				if (line == null || !line.isKill())
				{
					continue;
				}
				// Chronicle's key is the folded name (Dusk files under "grotesque guardians"); the line's own
				// name is only the first one the game gave it.
				Target t = e.getKey() == null ? null : byKey.get(key(e.getKey()));
				if (t == null && line.name != null)
				{
					t = byKey.get(key(line.name));
				}
				int n = line.count();
				if (t != null && n > 0)
				{
					// Held at the ceiling, so a damaged journal of thousands of sessions never wraps below zero.
					kills.merge(t, n, (a, b) -> (int) Math.min(Integer.MAX_VALUE, (long) a + b));
					any = true;
					if (line.tasks != null)
					{
						int[] s2 = split.computeIfAbsent(t, k -> new int[2]);
						int known = 0;
						for (Map.Entry<String, Integer> task : line.tasks.entrySet())
						{
							int k = task.getValue() == null ? 0 : Math.max(0, Math.min(task.getValue(), n - known));
							known += k;
							boolean covered = task.getKey() != null && !task.getKey().isEmpty()
								&& SlayerTask.taskCovers(task.getKey(), t.getName());
							s2[covered ? ON : OFF] += k;
						}
					}
				}
			}
			counted += any ? 1 : 0;
			earliest = any ? Math.min(earliest, s.startedAt) : earliest;
		}
		List<Map.Entry<Target, Integer>> list = new ArrayList<>(kills.entrySet());
		// Most fighting first: kills times hitpoints stands in for the time each took.
		list.sort((a, b) -> Long.compare((long) b.getValue() * b.getKey().getHp(), (long) a.getValue() * a.getKey().getHp()));
		Map<Target, Integer> sorted = new LinkedHashMap<>();
		for (Map.Entry<Target, Integer> e : list)
		{
			sorted.put(e.getKey(), e.getValue());
		}
		// A journal begun three days ago tells of three days, not a month.
		int days = (int) Math.max(1, Math.min(DAYS, (now - earliest + 86_399_999L) / 86_400_000L));
		return new Tally(Collections.unmodifiableMap(sorted), split, counted, days);
	}

	/** Names as Chronicle files them and targets as the list names them, folded alike. */
	static String key(String name)
	{
		String key = name.toLowerCase(Locale.ROOT).trim();
		if (key.startsWith("the "))
		{
			key = key.substring(4);
		}
		return key;
	}

	/** Seconds of fighting the kills take at this damage per second. */
	static double seconds(int kills, Target t, double dps)
	{
		return dps <= 0 ? Double.POSITIVE_INFINITY : kills * t.getHp() / dps;
	}
}

package com.codex.gearroadmap.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.IntPredicate;

/**
 * The bank Gear Roadmap plans with. Gear Roadmap keeps its own view of the bank (the gear it knows
 * and the coins, with no quantities once saved), and Codex Bank Steward, when installed, publishes
 * the whole bank with every quantity under {@code codexbanksteward/bankV1}:
 * {@code {"version":1,"savedAt":1760000000000,"items":{"995":1234567,"26950":1},"truncated":false}}.
 * Bank Steward's is read, never written, and is used when it is at least as fresh as Gear Roadmap's
 * own view, or tells the same story with quantities added; without it nothing changes.
 */
public final class Holdings
{
	public static final String STEWARD_GROUP = "codexbanksteward";
	public static final String STEWARD_KEY = "bankV1";
	/** Ammunition held below this is a few strays, not a stack worth bringing: it is not counted as owned. */
	public static final long AMMO_TRIP = 100;
	/** A quantity that was never seen; the item counts as owned whatever it is. */
	public static final long UNKNOWN = -1;

	static final int COINS = 995;
	static final int PLATINUM = 13204;
	/** Readers take no more kinds of item than Bank Steward ever writes. */
	private static final int MAX_ITEMS = 2000;

	/** Where the bank in use came from. */
	public enum Source
	{
		/** Nothing yet: the bank has not been seen by either plugin. */
		NONE,
		/** Gear Roadmap's own view. */
		OWN,
		/** Codex Bank Steward's shared bank. */
		BANK_STEWARD
	}

	/** Bank Steward's shared bank, as read. */
	public static final class Shared
	{
		private final Map<Integer, Long> items;
		private final long savedAt;

		Shared(Map<Integer, Long> items, long savedAt)
		{
			this.items = Collections.unmodifiableMap(items);
			this.savedAt = savedAt;
		}

		public Map<Integer, Long> getItems()
		{
			return items;
		}

		public long getSavedAt()
		{
			return savedAt;
		}
	}

	private final Source source;
	private final Map<Integer, Long> gear;
	private final long coins;

	private Holdings(Source source, Map<Integer, Long> gear, long coins)
	{
		this.source = source;
		this.gear = Collections.unmodifiableMap(gear);
		this.coins = coins;
	}

	/** How far ahead of this clock another plugin's clock may be. */
	static final long CLOCK_SLACK_MS = 3_600_000L;

	public static final Holdings NONE = new Holdings(Source.NONE, Collections.emptyMap(), 0);

	public Source getSource()
	{
		return source;
	}

	/** Banked gear by item id, with its quantity or {@link #UNKNOWN}. */
	public Map<Integer, Long> getGear()
	{
		return gear;
	}

	/** Banked coins, platinum tokens counted at a thousand. */
	public long getCoins()
	{
		return coins;
	}

	public boolean isKnown()
	{
		return source != Source.NONE;
	}

	/**
	 * Reads Bank Steward's shared bank; null when there is none or it cannot be read. Anything
	 * odd in it (a bad id, a negative count) is skipped rather than trusted.
	 */
	public static Shared readSteward(Gson gson, String json)
	{
		return readSteward(gson, json, System.currentTimeMillis());
	}

	/**
	 * As {@link #readSteward(Gson, String)}, at a given time: a copy dated after it (a damaged save, or
	 * a clock far off) is taken as undated, so it never passes for fresher than the bank seen just now.
	 */
	public static Shared readSteward(Gson gson, String json, long now)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			if (root == null || !root.isJsonObject())
			{
				return null;
			}
			JsonObject o = root.getAsJsonObject();
			JsonElement list = o.get("items");
			if (list == null || !list.isJsonObject())
			{
				return null;
			}
			Map<Integer, Long> items = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : list.getAsJsonObject().entrySet())
			{
				Integer id = parseInt(e.getKey());
				Long qty = number(e.getValue());
				if (id != null && id > 0 && qty != null && qty > 0 && items.size() < MAX_ITEMS)
				{
					// No stack holds more than this, whatever the copy claims.
					items.put(id, Math.min(qty, Integer.MAX_VALUE));
				}
			}
			Long savedAt = number(o.get("savedAt"));
			return new Shared(items, savedAt == null || savedAt < 0 || savedAt > now + CLOCK_SLACK_MS ? 0 : savedAt);
		}
		catch (JsonParseException | IllegalStateException | UnsupportedOperationException e)
		{
			return null;
		}
	}

	/**
	 * The bank to plan with.
	 *
	 * @param own Gear Roadmap's own banked gear ids, or null when it has never seen the bank
	 * @param ownCoins the coins in Gear Roadmap's own view
	 * @param ownCounts quantities Gear Roadmap saw itself this login, or null when its view was read back from a save
	 * @param ownSeenAt when Gear Roadmap last saw its bank change, epoch ms, or 0 when it does not know
	 * @param steward Bank Steward's shared bank, or null
	 * @param isGear whether Gear Roadmap knows an item id as gear
	 */
	public static Holdings choose(Set<Integer> own, long ownCoins, Map<Integer, Long> ownCounts, long ownSeenAt,
		Shared steward, IntPredicate isGear)
	{
		Holdings mine = own == null ? null : mine(own, ownCoins, ownCounts);
		Holdings shared = steward == null ? null : shared(steward, isGear);
		if (shared == null)
		{
			return mine == null ? NONE : mine;
		}
		if (mine == null)
		{
			return shared;
		}
		// Seen this login, Gear Roadmap's own view is as fresh as a bank can be and has its counts.
		if (ownCounts != null && ownSeenAt >= steward.getSavedAt())
		{
			return mine;
		}
		// The same gear in both: Bank Steward's adds the quantities, whichever saw it last.
		if (mine.gear.keySet().equals(shared.gear.keySet()))
		{
			return shared;
		}
		return steward.getSavedAt() >= ownSeenAt ? shared : mine;
	}

	private static Holdings mine(Set<Integer> own, long coins, Map<Integer, Long> counts)
	{
		Map<Integer, Long> gear = new HashMap<>();
		for (int id : own)
		{
			Long n = counts == null ? null : counts.get(id);
			gear.put(id, n == null || n <= 0 ? UNKNOWN : n);
		}
		return new Holdings(Source.OWN, gear, coins);
	}

	private static Holdings shared(Shared steward, IntPredicate isGear)
	{
		Map<Integer, Long> gear = new HashMap<>();
		long coins = 0;
		for (Map.Entry<Integer, Long> e : steward.getItems().entrySet())
		{
			int id = e.getKey();
			if (id == COINS)
			{
				coins += e.getValue();
			}
			else if (id == PLATINUM)
			{
				coins += 1000L * e.getValue();
			}
			else if (isGear.test(id))
			{
				gear.put(id, e.getValue());
			}
		}
		return new Holdings(Source.BANK_STEWARD, gear, coins);
	}

	/**
	 * Whether a stack counts as owned: anything at all, except ammunition, which needs at least
	 * {@link #AMMO_TRIP} across the bank, the inventory and the quiver. An unknown quantity counts.
	 */
	public static boolean enough(boolean ammo, long quantity)
	{
		return quantity == UNKNOWN || (ammo ? quantity >= AMMO_TRIP : quantity > 0);
	}

	private static Integer parseInt(String s)
	{
		try
		{
			return Integer.valueOf(s.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static Long number(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		try
		{
			double d = e.getAsDouble();
			if (Double.isNaN(d) || Double.isInfinite(d) || d != Math.floor(d))
			{
				return null;
			}
			return e.getAsLong();
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Which levels are worth training for the fight the roadmap is aimed at: for each skill that
 * powers the best loadout, the nearest level that raises the damage it does, how much, and what
 * that is worth in coins at the price the road's first step charges for damage.
 */
public final class Levels
{
	/** Levels ahead looked at for each skill. */
	static final int AHEAD = 10;
	/** A gain smaller than this share of the damage is not worth naming. */
	static final double MIN_SHARE = 0.005;

	private Levels()
	{
	}

	/** One skill's next level that pays. */
	public static final class Step
	{
		private final String skill;
		private final int from;
		private final int to;
		private final double gain;
		private final double share;
		private final int maxHit;
		private final boolean newMaxHit;
		private final long worth;
		private final String prayer;

		Step(String skill, int from, int to, double gain, double share, int maxHit, boolean newMaxHit, long worth)
		{
			this(skill, from, to, gain, share, maxHit, newMaxHit, worth, null);
		}

		Step(String skill, int from, int to, double gain, double share, int maxHit, boolean newMaxHit, long worth, String prayer)
		{
			this.prayer = prayer;
			this.skill = skill;
			this.from = from;
			this.to = to;
			this.gain = gain;
			this.share = share;
			this.maxHit = maxHit;
			this.newMaxHit = newMaxHit;
			this.worth = worth;
		}

		public String getSkill()
		{
			return skill;
		}

		public int getFrom()
		{
			return from;
		}

		/** The level that pays. */
		public int getTo()
		{
			return to;
		}

		/** Damage per second it adds. */
		public double getGain()
		{
			return gain;
		}

		/** The gain as a share of the damage now. */
		public double getShare()
		{
			return share;
		}

		public int getMaxHit()
		{
			return maxHit;
		}

		/** Whether it is the max hit going up, rather than accuracy. */
		public boolean isNewMaxHit()
		{
			return newMaxHit;
		}

		/** The stronger prayer the level unlocks, such as Piety at 70 Defence, or null. */
		public String getPrayer()
		{
			return prayer;
		}

		/** What the same damage would cost in gear at the road's average price for it, or 0 with no road. */
		public long getWorth()
		{
			return worth;
		}
	}

	/**
	 * The skills that power an attack of this kind, and Prayer and Defence, whose levels unlock the
	 * stronger prayers (Piety and Rigour at 70 Defence, Augury at 77 Prayer).
	 */
	static String[] skills(Result.Kind kind)
	{
		switch (kind)
		{
			case RANGED:
				return new String[]{"Ranged", "Prayer", "Defence"};
			case MAGIC:
				return new String[]{"Magic", "Prayer", "Defence"};
			default:
				return new String[]{"Strength", "Attack", "Prayer", "Defence"};
		}
	}

	/**
	 * For each skill behind the best loadout's attack, the nearest level within {@link #AHEAD} that
	 * adds at least {@link #MIN_SHARE} of the damage, worn in the same gear. Best value first.
	 */
	public static List<Step> ahead(Calc calc, Roadmap map, Fighter fighter)
	{
		Planner.Plan now = map.getNow().best();
		Result r = now.getResult();
		if (r.getKind() == null || r.getDps() <= 0)
		{
			return Collections.emptyList();
		}
		Target target = map.getTarget();
		double perDps = 0;
		if (!map.getPath().isEmpty())
		{
			// The road's average price for damage, from here to its end.
			Roadmap.Step last = map.getPath().get(map.getPath().size() - 1);
			double gained = last.getOption().getAfter().dps() - now.dps();
			perDps = gained > 0 ? last.getSpent() / gained : 0;
		}
		List<Step> steps = new ArrayList<>();
		for (String skill : skills(r.getKind()))
		{
			int from = fighter.level(skill);
			for (int level = from + 1; level <= Math.min(99, from + AHEAD); level++)
			{
				Result next = calc.best(now.getLoadout(), fighter.withLevel(skill, level), target, r.getKind());
				double gain = next.getDps() - r.getDps();
				if (gain >= r.getDps() * MIN_SHARE)
				{
					String prayer = next.getPrayer() != null && !next.getPrayer().equals(r.getPrayer()) ? next.getPrayer() : null;
					steps.add(new Step(skill, from, level, gain, gain / r.getDps(), next.getMaxHit(), next.getMaxHit() > r.getMaxHit(),
						Math.round(gain * perDps), prayer));
					break;
				}
			}
		}
		// The most damage for the fewest levels first.
		steps.sort((a, b) -> Double.compare(b.getGain() / (b.getTo() - b.getFrom()), a.getGain() / (a.getTo() - a.getFrom())));
		return steps;
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Gear;
import java.util.Arrays;

/** Eleven equipment slots. Changes return a new loadout, so loadouts can be shared freely. */
public final class Loadout
{
	private static final Loadout EMPTY = new Loadout(new Gear[Gear.SLOTS]);

	private final Gear[] slots;

	private Loadout(Gear[] slots)
	{
		this.slots = slots;
	}

	public static Loadout empty()
	{
		return EMPTY;
	}

	public static Loadout of(Gear... gear)
	{
		Loadout loadout = EMPTY;
		for (Gear g : gear)
		{
			if (g != null)
			{
				loadout = loadout.with(g);
			}
		}
		return loadout;
	}

	public Gear get(int slot)
	{
		return slots[slot];
	}

	public Gear weapon()
	{
		return slots[Gear.WEAPON];
	}

	/** Wears a piece in its own slot; a two-handed weapon takes the shield off, and a shield takes a two-hander off. */
	public Loadout with(Gear gear)
	{
		Gear[] next = slots.clone();
		next[gear.getSlot()] = gear;
		if (gear.getSlot() == Gear.WEAPON && gear.isTwoHanded())
		{
			next[Gear.SHIELD] = null;
		}
		if (gear.getSlot() == Gear.SHIELD && next[Gear.WEAPON] != null && next[Gear.WEAPON].isTwoHanded())
		{
			next[Gear.WEAPON] = null;
		}
		return new Loadout(next);
	}

	public Loadout without(int slot)
	{
		Gear[] next = slots.clone();
		next[slot] = null;
		return new Loadout(next);
	}

	public boolean wears(String key)
	{
		for (Gear g : slots)
		{
			if (g != null && g.key().equals(key))
			{
				return true;
			}
		}
		return false;
	}

	public boolean wearsAny(String... keys)
	{
		for (String key : keys)
		{
			if (wears(key))
			{
				return true;
			}
		}
		return false;
	}

	public boolean contains(Gear gear)
	{
		return gear != null && slots[gear.getSlot()] == gear;
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof Loadout && Arrays.equals(slots, ((Loadout) o).slots);
	}

	@Override
	public int hashCode()
	{
		return Arrays.hashCode(slots);
	}

	@Override
	public String toString()
	{
		return Arrays.toString(slots);
	}
}

