		"zamorakian", "dorgeshuun", "rune thrownaxe", "seercull", "excalibur", "barrelchest",
	};

	/** Pickaxes, woodcutting and felling axes and harpoons, by their lower-case names; battleaxes are weapons. */
	private static final Pattern TOOL = Pattern.compile("pickaxe|harpoon|(^|\\s)(felling )?axe(\\s|$)");

	/** One piece that has been outgrown. */
	public static final class Piece
	{
		private final Gear gear;
		private final long price;

		Piece(Gear gear, long price)
		{
			this.gear = gear;
			this.price = price;
		}

		public Gear getGear()
		{
			return gear;
		}

		/** What one sells for on the Grand Exchange before tax. */
		public long getPrice()
		{
			return price;
		}
	}

	private final List<Piece> pieces;
	private final long worth;

	private Outgrown(List<Piece> pieces, long worth)
	{
		this.pieces = Collections.unmodifiableList(pieces);
		this.worth = worth;
	}

	/**
	 * @param owned every piece of combat gear owned
	 * @param survey each target's best loadouts for every kind of attack
	 * @param wieldable whether the player can use a piece now
	 * @param sellable whether a piece can go on the Grand Exchange at all: RuneLite prices an untradeable piece
	 *     (a dragon defender (t), an imbued slayer helmet) by what it was made from, so a price is no proof
	 */
	public static Outgrown of(Collection<Gear> owned, List<Roadmap.Survey> survey, Predicate<Gear> wieldable,
		Predicate<Gear> sellable, Advisor.Prices prices)
	{
		Set<String> used = new HashSet<>();
		for (Roadmap.Survey row : survey)
		{
			Planner.Best best = row.getBest();
			if (best == null)
			{
				continue;
			}
			for (Result.Kind kind : Result.Kind.values())
			{
				wear(used, best.get(kind));
			}
			wear(used, best.best());
		}
		List<Piece> pieces = new ArrayList<>();
		long worth = 0;
		if (used.isEmpty())
		{
			// No survey yet, or one that found nothing to fight with: nothing can be called outgrown.
			return new Outgrown(pieces, 0);
		}
		for (Gear g : owned)
		{
			if (g.getSlot() == Gear.AMMO || used.contains(g.key()) || kept(g) || !wieldable.test(g) || !sellable.test(g))
			{
				continue;
			}
			long price = prices.price(g.getId());
			if (price < MIN_PRICE)
			{
				continue;
			}
			pieces.add(new Piece(g, price));
			worth += price;
		}
		pieces.sort((a, b) -> Long.compare(b.price, a.price));
		return new Outgrown(pieces, worth);
	}

	private static void wear(Set<String> used, Planner.Plan plan)
	{
		if (plan == null || plan.getResult() == null || plan.dps() <= 0)
		{
			return;
		}
		for (int slot = 0; slot < Gear.SLOTS; slot++)
		{
			Gear g = plan.getLoadout().get(slot);
			if (g != null)
			{
				used.add(g.key());
			}
		}
	}

	/** Gear kept for what it does rather than its damage. */
	static boolean kept(Gear g)
	{
		String name = g.key();
		if (TOOL.matcher(name).find() && !name.startsWith("soulreaper"))
		{
			// Skilling tools carry attack bonuses but are kept for the skill.
			return true;
		}
		if (name.contains("slayer helmet") || name.contains("battlestaff") || name.startsWith("mystic ") && name.contains(" staff")
			|| name.startsWith("staff of air") || name.startsWith("staff of water") || name.startsWith("staff of earth")
			|| name.startsWith("staff of fire"))
		{
			// Every colour of slayer helmet, and staves that stand in for elemental runes.
			return true;
		}
		for (String k : KEPT)
		{
			if (name.startsWith(k))
			{
				return true;
			}
		}
		// No attack or strength at all: armour worn for its defence.
		for (int t = 0; t <= Gear.RANGED; t++)
		{
			if (g.offence(t) > 0)
			{
				return false;
			}
		}
		return g.strength() <= 0 && g.rangedStrength() <= 0 && g.magicDamage() <= 0;
	}

	/** Outgrown pieces, the most valuable first. */
	public List<Piece> getPieces()
	{
		return pieces;
	}

	/** What they all sell for before tax. */
	public long getWorth()
	{
		return worth;
	}

	public boolean isEmpty()
	{
		return pieces.isEmpty();
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.CatalogueEntry;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Finds the best loadout a player can put together from what they own, for each kind of
 * attack, by trying their strongest weapons and then improving one slot at a time until
 * no single swap helps. The same search answers "what if I also owned this?" for every
 * upgrade the roadmap weighs.
 */
public final class Planner
{
	/** Slots in the order they are improved; the weapon is chosen first and held. */
	private static final int[] ORDER = {Gear.AMMO, Gear.BODY, Gear.LEGS, Gear.HEAD, Gear.SHIELD, Gear.NECK, Gear.CAPE,
		Gear.HANDS, Gear.FEET, Gear.RING};
	private static final int WEAPONS_TRIED = 5;
	private static final String[][] SETS = {
		{"void melee helm", "void knight top", "void knight robe", "void knight gloves"},
		{"void ranger helm", "void knight top", "void knight robe", "void knight gloves"},
		{"void mage helm", "void knight top", "void knight robe", "void knight gloves"},
		{"void ranger helm", "elite void top", "elite void robe", "void knight gloves"},
		{"void mage helm", "elite void top", "elite void robe", "void knight gloves"},
		{"obsidian helmet", "obsidian platebody", "obsidian platelegs"},
	};

	/** One loadout and what it does. */
	public static final class Plan
	{
		private final Loadout loadout;
		private final Result result;

		Plan(Loadout loadout, Result result)
		{
			this.loadout = loadout;
			this.result = result;
		}

		public Loadout getLoadout()
		{
			return loadout;
		}

		public Result getResult()
		{
			return result;
		}

		public double dps()
		{
			return result.getDps();
		}
	}

	/** The best plan for each kind of attack, and the best of them. */
	public static final class Best
	{
		private final Map<Result.Kind, Plan> plans;
		private final Plan best;

		Best(Map<Result.Kind, Plan> plans)
		{
			this.plans = plans;
			Plan top = null;
			for (Plan p : plans.values())
			{
				if (top == null || p.dps() > top.dps() + 1e-9)
				{
					top = p;
				}
			}
			this.best = top == null ? new Plan(Loadout.empty(), Result.NONE) : top;
		}

		public Plan get(Result.Kind kind)
		{
			return plans.get(kind);
		}

		public Plan best()
		{
			return best;
		}

		public double dps()
		{
			return best.dps();
		}

		/**
		 * These plans with one swapped in where it beats the plan of its kind. The road keeps a quick
		 * search's find when the fresh search falls short of it, so the next step builds on that.
		 */
		Best keeping(Plan plan)
		{
			Result.Kind kind = plan.getResult().getKind();
			Plan held = kind == null ? null : plans.get(kind);
			if (held == null || plan.dps() <= held.dps() + 1e-9)
			{
				return this;
			}
			Map<Result.Kind, Plan> merged = new EnumMap<>(plans);
			merged.put(kind, plan);
			return new Best(merged);
		}
	}

	private final RoadmapData data;
	private final Calc calc;

	public Planner(RoadmapData data)
	{
		this.data = data;
		this.calc = new Calc(data);
	}

	public Calc calc()
	{
		return calc;
	}

	/** The best loadouts from the gear owned. */
	public Best optimise(Collection<Gear> owned, Fighter fighter, Target target)
	{
		Map<Result.Kind, Plan> plans = new EnumMap<>(Result.Kind.class);
		for (Result.Kind kind : Result.Kind.values())
		{
			plans.put(kind, target.allows(kind.name()) ? optimise(owned, fighter, target, kind) : new Plan(Loadout.empty(), Result.NONE));
		}
		return new Best(plans);
	}

	private Plan optimise(Collection<Gear> owned, Fighter fighter, Target target, Result.Kind kind)
	{
		List<List<Gear>> bySlot = bySlot(owned, fighter, kind);
		List<Plan> weapons = new ArrayList<>();
		for (Gear weapon : bySlot.get(Gear.WEAPON))
		{
			Loadout start = withAmmo(Loadout.of(weapon), bySlot, fighter, target, kind);
			weapons.add(new Plan(start, calc.best(start, fighter, target, kind)));
		}
		if (kind == Result.Kind.MELEE)
		{
			weapons.add(new Plan(Loadout.empty(), calc.best(Loadout.empty(), fighter, target, kind)));
		}
		weapons.sort(Comparator.comparingDouble((Plan p) -> -p.dps()));

		Plan best = new Plan(Loadout.empty(), Result.NONE);
		int tried = 0;
		for (Plan start : weapons)
		{
			if (start.dps() <= 0 && kind != Result.Kind.MELEE || tried++ >= WEAPONS_TRIED)
			{
				break;
			}
			Plan p = ascend(start.getLoadout(), bySlot, fighter, target, kind, -1, 3);
			if (p.dps() > best.dps() + 1e-9)
			{
				best = p;
			}
			for (String[] set : SETS)
			{
				Loadout seeded = seed(start.getLoadout(), set, bySlot);
				if (seeded != null)
				{
					Plan s = ascend(seeded, bySlot, fighter, target, kind, -1, 3);
					if (s.dps() > best.dps() + 1e-9)
					{
						best = s;
					}
				}
			}
		}
		return best;
	}

	/**
	 * The best overall plan if the player also owned these pieces, starting from the plans
	 * they already have. Faster than a fresh search, and the same answer in practice.
	 */
	public Plan withAdded(Best current, Collection<Gear> owned, List<Gear> added, Fighter fighter, Target target)
	{
		Set<Gear> all = new LinkedHashSet<>(owned);
		all.addAll(added);
		Plan best = current.best();
		for (Result.Kind kind : Result.Kind.values())
		{
			if (!fits(added, kind) || !target.allows(kind.name()))
			{
				continue;
			}
			List<List<Gear>> bySlot = bySlot(all, fighter, kind);
			Plan from = current.get(kind);
			Loadout start = from == null || from.dps() <= 0 ? Loadout.empty() : from.getLoadout();
			int locked = -1;
			for (Gear g : added)
			{
				if (g.getSlot() == Gear.SHIELD && start.weapon() != null && start.weapon().isTwoHanded())
				{
					start = oneHanded(start, g, bySlot, fighter, target, kind);
				}
				start = start.with(g);
				locked = added.size() == 1 ? g.getSlot() : -1;
			}
			if (start.weapon() == null && kind != Result.Kind.MELEE)
			{
				continue;
			}
			if (start.weapon() != null && containsWeapon(added))
			{
				start = withAmmo(start, bySlot, fighter, target, kind);
			}
			Plan p = ascend(start, bySlot, fighter, target, kind, locked, 2);
			if (p.dps() > best.dps() + 1e-9)
			{
				best = p;
			}
		}
		return best;
	}

	/** Swaps a two-handed weapon for the best one-handed one, so a shield can be tried. */
	private Loadout oneHanded(Loadout lo, Gear shield, List<List<Gear>> bySlot, Fighter fighter, Target target, Result.Kind kind)
	{
		Loadout best = lo.without(Gear.WEAPON);
		Result bestResult = calc.best(best.with(shield), fighter, target, kind);
		for (Gear weapon : bySlot.get(Gear.WEAPON))
		{
			if (weapon.isTwoHanded())
			{
				continue;
			}
			Loadout next = withAmmo(lo.with(weapon), bySlot, fighter, target, kind);
			Result r = calc.best(next.with(shield), fighter, target, kind);
			if (r.isBetterThan(bestResult))
			{
				best = next;
				bestResult = r;
			}
		}
		return best;
	}

	private static boolean containsWeapon(List<Gear> gear)
	{
		for (Gear g : gear)
		{
			if (g.getSlot() == Gear.WEAPON)
			{
				return true;
			}
		}
		return false;
	}

	/** Whether any of the pieces can matter to this kind of attack. */
	private boolean fits(List<Gear> added, Result.Kind kind)
	{
		for (Gear g : added)
		{
			if (relevant(g, kind))
			{
				return true;
			}
		}
		return false;
	}

	private Plan ascend(Loadout loadout, List<List<Gear>> bySlot, Fighter fighter, Target target, Result.Kind kind,
		int lockedSlot, int passes)
	{
		Loadout lo = loadout;
		Result current = calc.best(lo, fighter, target, kind);
		for (int pass = 0; pass < passes; pass++)
		{
			boolean changed = false;
			for (int slot : ORDER)
			{
				if (slot == lockedSlot || slot == Gear.SHIELD && lo.weapon() != null && lo.weapon().isTwoHanded())
				{
					continue;
				}
				Loadout bestLo = lo;
				Result bestResult = current;
				if (lo.get(slot) != null)
				{
					Loadout bare = lo.without(slot);
					Result r = calc.best(bare, fighter, target, kind);
					if (r.isBetterThan(bestResult))
					{
						bestLo = bare;
						bestResult = r;
					}
				}
				for (Gear g : bySlot.get(slot))
				{
					if (lo.get(slot) == g)
					{
						continue;
					}
					Loadout next = lo.with(g);
					Result r = calc.best(next, fighter, target, kind);
					if (r.isBetterThan(bestResult))
					{
						bestLo = next;
						bestResult = r;
					}
				}
				if (bestLo != lo)
				{
					lo = bestLo;
					current = bestResult;
					changed = true;
				}
			}
			if (!changed)
			{
				break;
			}
		}
		return new Plan(lo, current);
	}

	/** Loads the best ammunition the player owns for a weapon that needs it. */
	private Loadout withAmmo(Loadout lo, List<List<Gear>> bySlot, Fighter fighter, Target target, Result.Kind kind)
	{
		Set<Integer> fires = data.ammoFor(lo.weapon());
		if (fires == null || fires.isEmpty())
		{
			return lo;
		}
		Loadout best = lo;
		Result bestResult = calc.best(lo, fighter, target, kind);
		for (Gear ammo : bySlot.get(Gear.AMMO))
		{
			Loadout next = lo.with(ammo);
			Result r = calc.best(next, fighter, target, kind);
			if (r.isBetterThan(bestResult))
			{
				best = next;
				bestResult = r;
			}
		}
		return best;
	}

	private Loadout seed(Loadout start, String[] set, List<List<Gear>> bySlot)
	{
		Loadout lo = start;
		for (String key : set)
		{
			Gear piece = null;
			for (List<Gear> slot : bySlot)
			{
				for (Gear g : slot)
				{
					if (g.key().equals(key))
					{
						piece = g;
					}
				}
			}
			if (piece == null)
			{
				return null;
			}
			lo = lo.with(piece);
		}
		return lo;
	}

	/** The owned pieces worth trying in each slot for one kind of attack, keeping only what the player can wield. */
	private List<List<Gear>> bySlot(Collection<Gear> owned, Fighter fighter, Result.Kind kind)
	{
		List<List<Gear>> slots = new ArrayList<>();
		for (int i = 0; i < Gear.SLOTS; i++)
		{
			slots.add(new ArrayList<>());
		}
		Set<Gear> seen = new HashSet<>();
		for (Gear g : owned)
		{
			if (g == null || !seen.add(g) || !wieldable(g, fighter))
			{
				continue;
			}
			if (g.getSlot() == Gear.WEAPON ? usesKind(g, kind) : relevant(g, kind))
			{
				slots.get(g.getSlot()).add(g);
			}
		}
		return slots;
	}

	public boolean wieldable(Gear gear, Fighter fighter)
	{
		CatalogueEntry entry = data.entry(gear);
		return entry == null || fighter.meets(entry.getRequirements());
	}

	/** Whether a weapon offers an attack of this kind. */
	public boolean usesKind(Gear weapon, Result.Kind kind)
	{
		for (RoadmapData.Style style : data.styles(weapon.getCategory()))
		{
			String type = style.getType();
			Result.Kind k = "magic".equals(type) ? Result.Kind.MAGIC : "ranged".equals(type) ? Result.Kind.RANGED : Result.Kind.MELEE;
			if (k == kind)
			{
				return true;
			}
		}
		return false;
	}

	/** Whether a piece can raise damage for this kind of attack. */
	boolean relevant(Gear g, Result.Kind kind)
	{
		if (g.getSlot() == Gear.WEAPON)
		{
			return usesKind(g, kind);
		}
		String key = g.key();
		if (key.startsWith("salve amulet") || key.contains("slayer helmet") || key.startsWith("black mask")
			|| key.startsWith("void ") || key.startsWith("elite void") || key.startsWith("obsidian") || key.startsWith("crystal "))
		{
			return true;
		}
		switch (kind)
		{
			case MELEE:
				return g.offence(Gear.STAB) > 0 || g.offence(Gear.SLASH) > 0 || g.offence(Gear.CRUSH) > 0 || g.strength() > 0;
			case RANGED:
				return g.offence(Gear.RANGED) > 0 || g.rangedStrength() > 0;
			default:
				return g.offence(Gear.MAGIC) > 0 || g.magicDamage() > 0;
		}
	}
}

package com.codex.gearroadmap.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** One snapshot for the panel: the roadmap for the focused target and the survey of every target. */
public final class Report
{
	private final boolean loggedIn;
	private final Roadmap roadmap;
	private final List<Roadmap.Survey> survey;
	private final String boosts;
	private final int owned;
	private final boolean bankSeen;
	private boolean ironman;
	private boolean seasonal;
	private String task;
	private Boolean slayer;
	private Savings.View savings;
	private boolean following;
	private String taskName;
	private List<String> taskTargets = Collections.emptyList();
	private Fights.Tally tally;
	private List<Fights.Pick> fights = Collections.emptyList();
	private List<Levels.Step> levels = Collections.emptyList();
	private Swap swap;
	private Outgrown outgrown;
	private List<Claims.Claim> claims = Collections.emptyList();
	private List<String> shortlist = Collections.emptyList();
	private List<Fights.Pick> shortlistPicks = Collections.emptyList();

	public Report(boolean loggedIn, Roadmap roadmap, List<Roadmap.Survey> survey, String boosts, int owned, boolean bankSeen)
	{
		this.loggedIn = loggedIn;
		this.roadmap = roadmap;
		this.survey = survey == null ? Collections.emptyList() : survey;
		this.boosts = boosts;
		this.owned = owned;
		this.bankSeen = bankSeen;
	}

	/** A copy that knows the account: ironmen cannot buy, and seasonal worlds have their own economy. */
	public Report withAccount(boolean ironman, boolean seasonal, String task)
	{
		return withAccount(ironman, seasonal, task, null);
	}

	/** As above, with whether the slayer helmet counts against the aimed target, or null when it is no slayer monster. */
	public Report withAccount(boolean ironman, boolean seasonal, String task, Boolean slayer)
	{
		Report r = copy(roadmap);
		r.ironman = ironman;
		r.seasonal = seasonal;
		r.task = task;
		r.slayer = slayer;
		return r;
	}

	/** A copy with another roadmap, such as the same road with the player's coins updated. */
	public Report withRoadmap(Roadmap roadmap)
	{
		return copy(roadmap);
	}

	/**
	 * A copy that knows which targets the slayer task covers, and whether the roadmap is aimed
	 * at one of them because it follows the task rather than the chosen target.
	 */
	public Report withTask(boolean following, List<String> taskTargets, String taskName)
	{
		Report r = copy(roadmap);
		r.following = following;
		r.taskName = taskName;
		r.taskTargets = taskTargets == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(taskTargets));
		return r;
	}

	/**
	 * A copy that knows where the player fights (from Codex Session Chronicle), the upgrades that save
	 * the most time there, and the levels worth training for the aimed target.
	 */
	public Report withExtras(Fights.Tally tally, List<Fights.Pick> fights, List<Levels.Step> levels)
	{
		Report r = copy(roadmap);
		r.tally = tally;
		r.fights = fights == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(fights));
		r.levels = levels == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(levels));
		return r;
	}

	/** Kills by target over the last 30 days from Codex Session Chronicle, or null when it is not installed. */
	public Fights.Tally getTally()
	{
		return tally;
	}

	/** Upgrades weighed across where the player fights, best value first. */
	public List<Fights.Pick> getFights()
	{
		return fights;
	}

	/**
	 * A copy that knows the targets the player shortlisted, such as the bosses left to finish, and
	 * the upgrades that save the most fighting time across all of them.
	 */
	public Report withShortlist(List<String> names, List<Fights.Pick> picks)
	{
		Report r = copy(roadmap);
		r.shortlist = names == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(names));
		r.shortlistPicks = picks == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(picks));
		return r;
	}

	/** The shortlisted targets' names, in the order they were added. */
	public List<String> getShortlist()
	{
		return shortlist;
	}

	/** Upgrades weighed across the shortlist, best value first. */
	public List<Fights.Pick> getShortlistPicks()
	{
		return shortlistPicks;
	}

	/** The next level worth training in each skill behind the best loadout, best value first. */
	public List<Levels.Step> getLevels()
	{
		return levels;
	}

	/** A copy that knows what is worn now against the best owned, or null before the gear has been read. */
	public Report withSwap(Swap swap)
	{
		Report r = copy(roadmap);
		r.swap = swap;
		r.outgrown = outgrown;
		return r;
	}

	/** A copy that knows the owned gear no best loadout wears, or null for an ironman. */
	public Report withOutgrown(Outgrown outgrown)
	{
		Report r = copy(roadmap);
		r.outgrown = outgrown;
		return r;
	}

	/** Owned gear no best loadout wears against any target, or null. */
	public Outgrown getOutgrown()
	{
		return outgrown;
	}

	/** What is worn now against the best loadout owned for the aimed target, or null. */
	public Swap getSwap()
	{
		return swap;
	}

	/** A copy with the upgrades picked up from the road, newest first. */
	public Report withClaims(List<Claims.Claim> claims)
	{
		Report r = copy(roadmap);
		r.claims = claims == null ? Collections.emptyList() : claims;
		return r;
	}

	/** A copy with the savings goal's standing, or none. */
	public Report withSavings(Savings.View savings)
	{
		Report r = copy(roadmap);
		r.savings = savings;
		return r;
	}

	private Report copy(Roadmap roadmap)
	{
		Report r = new Report(loggedIn, roadmap, survey, boosts, owned, bankSeen);
		r.ironman = ironman;
		r.seasonal = seasonal;
		r.task = task;
		r.slayer = slayer;
		r.savings = savings;
		r.following = following;
		r.taskName = taskName;
		r.taskTargets = taskTargets;
		r.tally = tally;
		r.fights = fights;
		r.levels = levels;
		r.swap = swap;
		r.outgrown = outgrown;
		r.claims = claims;
		r.shortlist = shortlist;
		r.shortlistPicks = shortlistPicks;
		return r;
	}

	public static Report loggedOut()
	{
		return new Report(false, null, null, null, 0, false);
	}

	public boolean isLoggedIn()
	{
		return loggedIn;
	}

	/** Null until the first plan is ready. */
	public Roadmap getRoadmap()
	{
		return roadmap;
	}

	public List<Roadmap.Survey> getSurvey()
	{
		return survey;
	}

	/** The potions assumed, as the config names them. */
	public String getBoosts()
	{
		return boosts;
	}

	/** How many pieces of combat gear the player owns. */
	public int getOwned()
	{
		return owned;
	}

	/** Ironmen cannot buy from the Grand Exchange, so prices stand for how hard an item is to get. */
	public boolean isIronman()
	{
		return ironman;
	}

	public boolean isSeasonal()
	{
		return seasonal;
	}

	/** Whether the slayer helmet counts against the aimed target; null when it is not a slayer monster. */
	public Boolean getSlayer()
	{
		return slayer;
	}

	/** The current slayer task's name, lower case, or null. */
	public String getTask()
	{
		return task;
	}

	/** The savings goal's standing, or null without a goal. */
	public Savings.View getSavings()
	{
		return savings;
	}

	/** The upgrades picked up from the road, newest first; empty before the first. */
	public List<Claims.Claim> getClaims()
	{
		return claims;
	}

	/** Whether the roadmap is aimed at the slayer task's monster rather than the chosen target. */
	public boolean isFollowingTask()
	{
		return following;
	}

	/** The current slayer task's name as the game writes it, or null. */
	public String getTaskName()
	{
		return taskName;
	}

	/** The targets the current slayer task covers, best first; empty without a task or when none are listed. */
	public List<String> getTaskTargets()
	{
		return taskTargets;
	}

	/** Whether the bank has been read, so the owned list is complete. */
	public boolean isBankSeen()
	{
		return bankSeen;
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;

/** What one loadout does to one target with its best attack style. */
public final class Result
{
	public enum Kind
	{
		MELEE("Melee"),
		RANGED("Ranged"),
		MAGIC("Magic");

		private final String label;

		Kind(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	static final Result NONE = new Result(null, 0, 0, 0, 0, null, null, null);

	private final Kind kind;
	private final double dps;
	private final int maxHit;
	private final double accuracy;
	private final int ticks;
	private final String style;
	private final String prayer;
	private final String spell;

	Result(Kind kind, double dps, int maxHit, double accuracy, int ticks, String style, String prayer, String spell)
	{
		this.kind = kind;
		this.dps = dps;
		this.maxHit = maxHit;
		this.accuracy = accuracy;
		this.ticks = ticks;
		this.style = style;
		this.prayer = prayer;
		this.spell = spell;
	}

	public Kind getKind()
	{
		return kind;
	}

	/** Expected damage per second. */
	public double getDps()
	{
		return dps;
	}

	public int getMaxHit()
	{
		return maxHit;
	}

	/** Chance each attack hits. */
	public double getAccuracy()
	{
		return accuracy;
	}

	/** Game ticks between attacks. */
	public int getTicks()
	{
		return ticks;
	}

	/** The attack style chosen, such as "Slash, aggressive" or "Rapid". */
	public String getStyle()
	{
		return style;
	}

	public String getPrayer()
	{
		return prayer;
	}

	public String getSpell()
	{
		return spell;
	}

	/** Seconds to kill the target at this rate, ignoring overkill and downtime. */
	public double secondsToKill(Target target)
	{
		return dps <= 0 ? Double.POSITIVE_INFINITY : target.getHp() / dps;
	}

	/** The same attack landing only this share of the fight, as when a phase keeps the player off the target. */
	Result timesUptime(int percent)
	{
		if (percent >= 100 || kind == null)
		{
			return this;
		}
		return new Result(kind, dps * percent / 100.0, maxHit, accuracy, ticks, style, prayer, spell);
	}

	public boolean isBetterThan(Result other)
	{
		return other == null || dps > other.dps + 1e-9;
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Everything the panel shows for one target: the loadouts owned now and the upgrades ahead. */
public final class Roadmap
{
	/** One upgrade weighed against the loadout it would join. */
	public static final class Option
	{
		private final String name;
		private final List<Gear> pieces;
		private final Gear icon;
		private final long cost;
		private final double gain;
		private final double before;
		private final Planner.Plan after;
		private final String missing;
		private final String earn;
		private final String note;
		private final boolean ammo;

		Option(String name, List<Gear> pieces, Gear icon, long cost, double gain, double before, Planner.Plan after,
			String missing, String earn, String note, boolean ammo)
		{
			this.name = name;
			this.pieces = pieces;
			this.icon = icon;
			this.cost = cost;
			this.gain = gain;
			this.before = before;
			this.after = after;
			this.missing = missing;
			this.earn = earn;
			this.note = note;
			this.ammo = ammo;
		}

		public String getName()
		{
			return name;
		}

		public List<Gear> getPieces()
		{
			return pieces;
		}

		public Gear getIcon()
		{
			return icon;
		}

		/** Coins to buy it; 0 when it is earned or made from gear already owned. */
		public long getCost()
		{
			return cost;
		}

		/** Damage per second it adds. */
		public double getGain()
		{
			return gain;
		}

		/** The gain as a share of the damage before it. */
		public double getGainShare()
		{
			return before <= 0 ? 0 : gain / before;
		}

		public Planner.Plan getAfter()
		{
			return after;
		}

		/** The level still missing to wield it, such as "80 Ranged", or null. */
		public String getMissing()
		{
			return missing;
		}

		public String getEarn()
		{
			return earn;
		}

		public String getNote()
		{
			return note;
		}

		/** Ammunition is priced per thousand. */
		public boolean isAmmo()
		{
			return ammo;
		}
	}

	/** One step of the road, with what the road has cost up to and including it. */
	public static final class Step
	{
		private final Option option;
		private final long spent;
		private final boolean affordable;

		Step(Option option, long spent, boolean affordable)
		{
			this.option = option;
			this.spent = spent;
			this.affordable = affordable;
		}

		public Option getOption()
		{
			return option;
		}

		public long getSpent()
		{
			return spent;
		}

		/** Whether the player's coins already cover the road up to here. */
		public boolean isAffordable()
		{
			return affordable;
		}
	}

	/** One target in the Targets list: the best the player can do there now. */
	public static final class Survey
	{
		private final Target target;
		private final Planner.Plan plan;
		private final Planner.Best best;

		Survey(Target target, Planner.Best best)
		{
			this.target = target;
			this.plan = best.best();
			this.best = best;
		}

		/** The best plan for each kind of attack, not only the best of them. */
		public Planner.Best getBest()
		{
			return best;
		}

		public Target getTarget()
		{
			return target;
		}

		public Planner.Plan getPlan()
		{
			return plan;
		}
	}

	private final Target target;
	private final Planner.Best now;
	private final List<Step> path;
	private final List<Option> free;
	private final List<Option> locked;
	private final List<Option> leaps;
	private final long coins;
	private Option goal;
	private boolean goalOwned;

	Roadmap(Target target, Planner.Best now, List<Step> path, List<Option> free, List<Option> locked, List<Option> leaps, long coins)
	{
		this.target = target;
		this.now = now;
		this.path = path;
		this.free = free;
		this.locked = locked;
		this.leaps = leaps;
		this.coins = coins;
	}

	public Target getTarget()
	{
		return target;
	}

	/** The same road, with what the player's coins now cover. */
	public Roadmap withCoins(long coins)
	{
		List<Step> steps = new ArrayList<>();
		for (Step s : path)
		{
			steps.add(new Step(s.option, s.spent, s.spent <= coins));
		}
		List<Option> bought = new ArrayList<>(leaps);
		return new Roadmap(target, now, steps, free, locked, bought, coins).withGoal(goal, goalOwned);
	}

	/** The same road with the player's savings goal, as weighed against this target. */
	Roadmap withGoal(Option goal, boolean owned)
	{
		this.goal = goal;
		this.goalOwned = owned;
		return this;
	}

	/** The savings goal priced against this target, or null without one (or while it has no price). */
	public Option getGoal()
	{
		return goal;
	}

	/** Whether every piece of the savings goal is owned already. */
	public boolean isGoalOwned()
	{
		return goalOwned;
	}

	public Planner.Best getNow()
	{
		return now;
	}

	public List<Step> getPath()
	{
		return Collections.unmodifiableList(path);
	}

	public List<Option> getFree()
	{
		return free;
	}

	public List<Option> getLocked()
	{
		return locked;
	}

	public List<Option> getLeaps()
	{
		return leaps;
	}

	public long getCoins()
	{
		return coins;
	}

	/** Damage per second at the end of the road. */
	public double finalDps()
	{
		return path.isEmpty() ? now.dps() : path.get(path.size() - 1).getOption().getAfter().dps();
	}
}

package com.codex.gearroadmap.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Reading back what was saved in the profile, this plugin's own or another Codex plugin's, when any
 * of it may be missing, cut short, of the wrong type or written by a later version. Nothing here
 * throws: what cannot be read is left out, and only that.
 */
public final class Saved
{
	/** More than any account is worth or any stack holds; a figure past it is damage. */
	public static final long MAX_WORTH = 10_000_000_000_000L;

	private Saved()
	{
	}

	/** The saved text as a JSON object, or null when it is blank, not JSON or not an object. */
	public static JsonObject object(Gson gson, String json)
	{
		JsonElement root = tree(gson, json);
		return root != null && root.isJsonObject() ? root.getAsJsonObject() : null;
	}

	/** The saved text as JSON, or null when it is blank or not JSON. */
	static JsonElement tree(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, JsonElement.class);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** One saved object as a class, or null when it cannot be read as one. */
	public static <T> T as(Gson gson, JsonElement e, Class<T> type)
	{
		if (e == null || !e.isJsonObject())
		{
			return null;
		}
		try
		{
			return gson.fromJson(e, type);
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	/** A saved list of objects read one by one, so a broken entry costs only itself; empty without one. */
	public static <T> List<T> list(Gson gson, JsonElement e, Class<T> type)
	{
		if (e == null || !e.isJsonArray())
		{
			return Collections.emptyList();
		}
		List<T> out = new ArrayList<>();
		for (JsonElement entry : e.getAsJsonArray())
		{
			T read = as(gson, entry, type);
			if (read != null)
			{
				out.add(read);
			}
		}
		return out;
	}

	/** The saved text as a list of objects read one by one; empty when it is not a list. */
	public static <T> List<T> list(Gson gson, String json, Class<T> type)
	{
		return list(gson, tree(gson, json), type);
	}

	/** The entries of a saved list that read as this class on their own, or null when it is not a list. */
	static JsonArray readable(Gson gson, JsonElement e, Class<?> type)
	{
		if (e == null || !e.isJsonArray())
		{
			return null;
		}
		JsonArray kept = new JsonArray();
		for (JsonElement entry : e.getAsJsonArray())
		{
			if (as(gson, entry, type) != null)
			{
				kept.add(entry);
			}
		}
		return kept;
	}

	/** The longest damaged save set aside; one past it is only logged, so the profile never doubles in size for it. */
	public static final int MAX_ASIDE = 1_000_000;

	/**
	 * True when {@code json} was saved and {@code read}, what was read from it, written out again lacks
	 * part of it: a broken entry left out, or a later version's field passed over in silence. Such a
	 * save would be lost at the next write, so it is set aside first. Only the shape is compared, not
	 * the figures, which reading may bring back to sense.
	 */
	public static boolean lost(Gson gson, String json, Object read)
	{
		JsonElement saved = tree(gson, json);
		if (json == null || json.trim().isEmpty())
		{
			return false;
		}
		JsonElement reread;
		try
		{
			reread = read == null ? null : gson.toJsonTree(read);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			reread = null;
		}
		return saved == null || !covers(saved, reread);
	}

	/** True when every field and list entry in {@code saved} is still there in {@code reread}; a field saved as null was nothing to lose. */
	static boolean covers(JsonElement saved, JsonElement reread)
	{
		if (saved == null || saved.isJsonNull())
		{
			return true;
		}
		if (reread == null || reread.isJsonNull())
		{
			return false;
		}
		if (saved.isJsonObject())
		{
			if (!reread.isJsonObject())
			{
				return false;
			}
			JsonObject now = reread.getAsJsonObject();
			for (java.util.Map.Entry<String, JsonElement> field : saved.getAsJsonObject().entrySet())
			{
				if (!covers(field.getValue(), now.get(field.getKey())))
				{
					return false;
				}
			}
			return true;
		}
		if (saved.isJsonArray())
		{
			if (!reread.isJsonArray() || reread.getAsJsonArray().size() < saved.getAsJsonArray().size())
			{
				return false;
			}
			JsonArray then = saved.getAsJsonArray();
			JsonArray now = reread.getAsJsonArray();
			for (int i = 0; i < then.size(); i++)
			{
				if (!covers(then.get(i), now.get(i)))
				{
					return false;
				}
			}
			return true;
		}
		return true;
	}

	/**
	 * Whether a save that could not be read whole should be set aside in place of the copy already
	 * there, which is kept to just one: yes when there is none, and otherwise only for a save at least
	 * as long, so a later stub never replaces a fuller copy.
	 */
	public static boolean setAside(String kept, String damaged)
	{
		if (damaged == null || damaged.trim().isEmpty() || damaged.length() > MAX_ASIDE)
		{
			return false;
		}
		return kept == null || kept.isEmpty() || !kept.equals(damaged) && damaged.length() >= kept.length();
	}

	/** A whole number, or null for anything else (text, a fraction, too big to be a long). */
	public static Long whole(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		try
		{
			return new java.math.BigDecimal(e.getAsString()).longValueExact();
		}
		catch (ArithmeticException | NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.codex.gearroadmap.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A savings goal: one upgrade the player is putting coins aside for, how far their coins
 * already go, and, when Codex Ledger keeps their net worth, how long the rest should take
 * at the pace their wealth has grown over the last week.
 */
public final class Savings
{
	/** How far back the pace looks. */
	public static final long WINDOW_MS = 7L * 24 * 3_600_000L;
	/** A pace from less history than this would mostly be noise. */
	public static final long MIN_SPAN_MS = 24 * 3_600_000L;
	private static final long DAY_MS = 24 * 3_600_000L;
	/** Past this many days an estimate says nothing useful. */
	private static final int MAX_DAYS = 999;

	/** The saved goal: the upgrade's name and one item id per piece, so it can be found again on any road. */
	public static final class Goal
	{
		private String name;
		private List<Integer> ids;

		public Goal()
		{
		}

		public Goal(String name, List<Integer> ids)
		{
			this.name = name;
			this.ids = new ArrayList<>(ids);
		}

		public String getName()
		{
			return name == null ? "" : name;
		}

		public List<Integer> getIds()
		{
			return ids == null ? Collections.emptyList() : Collections.unmodifiableList(ids);
		}

		/** A goal read back from the profile is only usable with a name and at least one piece. */
		public boolean isValid()
		{
			return name != null && !name.isEmpty() && ids != null && !ids.isEmpty();
		}
	}

	/**
	 * The saved savings goal, or null when there is none or it cannot be used: it needs a name and at
	 * least one piece. A piece that is not an item id is left out on its own.
	 */
	public static Goal readGoal(Gson gson, String json)
	{
		JsonObject o = Saved.object(gson, json);
		if (o == null)
		{
			return null;
		}
		JsonElement name = o.get("name");
		JsonElement list = o.get("ids");
		if (name == null || !name.isJsonPrimitive() || !name.getAsJsonPrimitive().isString() || list == null || !list.isJsonArray())
		{
			return null;
		}
		List<Integer> ids = new ArrayList<>();
		for (JsonElement e : list.getAsJsonArray())
		{
			Long id = Saved.whole(e);
			if (id != null && id > 0 && id <= Integer.MAX_VALUE)
			{
				ids.add(id.intValue());
			}
		}
		Goal goal = new Goal(name.getAsString().trim(), ids);
		return goal.isValid() ? goal : null;
	}

	/**
	 * Codex Ledger's saved net worth, or null when it is not installed, has not begun or cannot be
	 * read. Only "total" and "history" are read, so damage anywhere else in the ledger is no matter;
	 * a point of history that cannot be read, or holds a worth no account has, is left out.
	 */
	public static Worth readWorth(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			// The quick way, which skips the rest of the ledger unread; used whenever the two fields read whole.
			Worth whole = gson.fromJson(json, Worth.class);
			if (whole == null || whole.total <= 0 || whole.total > Saved.MAX_WORTH)
			{
				return null;
			}
			List<Point> history = new ArrayList<>();
			for (Point p : whole.getHistory())
			{
				if (p != null && p.t > 0 && p.v >= 0 && p.v <= Saved.MAX_WORTH)
				{
					history.add(p);
				}
			}
			history.sort((a, b) -> Long.compare(a.t, b.t));
			return new Worth(whole.total, history);
		}
		catch (RuntimeException e)
		{
			// Something in them is broken: read them point by point below.
		}
		JsonObject o = Saved.object(gson, json);
		Long total = o == null ? null : Saved.whole(o.get("total"));
		if (total == null || total <= 0 || total > Saved.MAX_WORTH)
		{
			return null;
		}
		List<Point> history = new ArrayList<>();
		JsonElement list = o.get("history");
		if (list != null && list.isJsonArray())
		{
			for (JsonElement e : list.getAsJsonArray())
			{
				if (!e.isJsonObject())
				{
					continue;
				}
				Long t = Saved.whole(e.getAsJsonObject().get("t"));
				Long v = Saved.whole(e.getAsJsonObject().get("v"));
				if (t != null && v != null && t > 0 && v >= 0 && v <= Saved.MAX_WORTH)
				{
					history.add(new Point(t, v));
				}
			}
		}
		history.sort((a, b) -> Long.compare(a.t, b.t));
		return new Worth(total, history);
	}

	/** Net worth over time, as Codex Ledger saves it; only the fields Gear Roadmap reads. */
	public static final class Worth
	{
		private long total;
		private List<Point> history;

		public Worth()
		{
		}

		public Worth(long total, List<Point> history)
		{
			this.total = total;
			this.history = history;
		}

		public long getTotal()
		{
			return total;
		}

		public List<Point> getHistory()
		{
			return history == null ? Collections.emptyList() : history;
		}
	}

	/** One reading of net worth: when, and how much. Named as Codex Ledger names them. */
	public static final class Point
	{
		private long t;
		private long v;

		public Point()
		{
		}

		public Point(long time, long value)
		{
			this.t = time;
			this.v = value;
		}

		public long getTime()
		{
			return t;
		}

		public long getValue()
		{
			return v;
		}
	}

	/** What the panel shows for a goal. */
	public static final class View
	{
		private final Roadmap.Option option;
		private final boolean owned;
		private final long coins;
		private final long worth;
		private final boolean ledger;
		private final Long perDay;

		View(Roadmap.Option option, boolean owned, long coins, long worth, boolean ledger, Long perDay)
		{
			this.option = option;
			this.owned = owned;
			this.coins = coins;
			this.worth = worth;
			this.ledger = ledger;
			this.perDay = perDay;
		}

		/** The upgrade as it stands against the aimed target now; its gain may be nothing here. */
		public Roadmap.Option getOption()
		{
			return option;
		}

		/** The player already owns every piece: the goal is met. */
		public boolean isOwned()
		{
			return owned;
		}

		public long getCost()
		{
			return option.getCost();
		}

		public long getCoins()
		{
			return coins;
		}

		public long getRemaining()
		{
			return Math.max(0, getCost() - coins);
		}

		/** Share of the price the player's coins already cover, 0 to 1. */
		public double getProgress()
		{
			if (owned || getCost() <= 0)
			{
				return 1;
			}
			return Math.max(0, Math.min(1, coins / (double) getCost()));
		}

		public boolean isAffordable()
		{
			return owned || coins >= getCost();
		}

		/** Whether Codex Ledger's net worth was readable at all. */
		public boolean hasLedger()
		{
			return ledger;
		}

		/** Net worth as Codex Ledger last saved it, 0 without it. */
		public long getWorth()
		{
			return worth;
		}

		/** Net worth gained per day over the last week, or null when there is too little history to say. */
		public Long getPerDay()
		{
			return perDay;
		}

		/** Whole days until the rest is saved at that pace, or -1 when it cannot be told (no pace, or not growing). */
		public int getDays()
		{
			if (isAffordable())
			{
				return 0;
			}
			if (perDay == null || perDay <= 0)
			{
				return -1;
			}
			long days = (getRemaining() + perDay - 1) / perDay;
			return days > MAX_DAYS ? -1 : (int) days;
		}
	}

	private Savings()
	{
	}

	/**
	 * The goal's standing.
	 *
	 * @param option the goal priced and weighed against the aimed target
	 * @param owned whether every piece is already owned
	 * @param coins coins and platinum the player holds
	 * @param worth Codex Ledger's saved net worth, or null when it is not installed or has not started
	 * @param now the time now, to read the last week of history
	 */
	public static View of(Roadmap.Option option, boolean owned, long coins, Worth worth, long now)
	{
		if (option == null)
		{
			return null;
		}
		return new View(option, owned, Math.max(0, coins), worth == null ? 0 : worth.getTotal(), worth != null, pace(worth, now));
	}

	/**
	 * Whether to say a goal is now in reach: only when the coins have just come to cover it,
	 * never on the first look after login, and once per goal per login, so coins dipping into a
	 * Grand Exchange offer and back, or a price wobbling across the line, do not say it again.
	 *
	 * @param wasAffordable whether the goal was affordable at the last look, or null before the first
	 * @param announced whether it was announced already since the goal was set or the player logged in
	 */
	public static boolean inReach(Boolean wasAffordable, boolean announced, View view)
	{
		return view != null && !announced && Boolean.FALSE.equals(wasAffordable) && view.isAffordable() && !view.isOwned();
	}

	/**
	 * Net worth gained per day across the last week: from the first reading inside the window
	 * to the latest, so one lucky drop counts for what it was rather than for every day after.
	 * Null with less than a day of history to go on.
	 */
	public static Long paceOf(Worth worth, long now)
	{
		return pace(worth, now);
	}

	static Long pace(Worth worth, long now)
	{
		if (worth == null)
		{
			return null;
		}
		List<Point> points = worth.getHistory();
		Point first = null;
		Point last = null;
		for (Point p : points)
		{
			if (p == null || p.getTime() > now || now - p.getTime() > WINDOW_MS)
			{
				continue;
			}
			if (first == null || p.getTime() < first.getTime())
			{
				first = p;
			}
			if (last == null || p.getTime() > last.getTime())
			{
				last = p;
			}
		}
		if (first == null || last.getTime() - first.getTime() < MIN_SPAN_MS)
		{
			return null;
		}
		double days = (last.getTime() - first.getTime()) / (double) DAY_MS;
		return Math.round((last.getValue() - first.getValue()) / days);
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;

/**
 * Targets the player shortlisted to plan for together, such as the bosses left to finish on the
 * collection log or the ones a slayer grind will pass through. Upgrades are then weighed across all
 * of them at once. Saved per account as a list of target names, in the order they were added.
 */
public final class Shortlist
{
	/** Targets kept on the shortlist at most; adding one more drops the oldest. */
	public static final int KEPT = 12;

	private final List<String> names;

	private Shortlist(List<String> names)
	{
		this.names = names;
	}

	public static Shortlist empty()
	{
		return new Shortlist(Collections.emptyList());
	}

	/** Reads a saved shortlist; anything unreadable is left out, and a broken save reads as empty. */
	public static Shortlist read(Gson gson, String saved)
	{
		if (saved == null || saved.isEmpty())
		{
			return empty();
		}
		List<String> names = new ArrayList<>();
		try
		{
			JsonElement root = gson.fromJson(saved, JsonElement.class);
			if (root == null || !root.isJsonArray())
			{
				return empty();
			}
			JsonArray array = root.getAsJsonArray();
			for (JsonElement e : array)
			{
				if (e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isString())
				{
					String name = e.getAsString().trim();
					if (!name.isEmpty() && name.length() <= 80 && !names.contains(name))
					{
						names.add(name);
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			return empty();
		}
		while (names.size() > KEPT)
		{
			names.remove(0);
		}
		return new Shortlist(Collections.unmodifiableList(names));
	}

	public String write(Gson gson)
	{
		return gson.toJson(names);
	}

	public boolean contains(String name)
	{
		return names.contains(name);
	}

	public boolean isEmpty()
	{
		return names.isEmpty();
	}

	public List<String> getNames()
	{
		return names;
	}

	/** A copy with the target added, or taken off when it is already listed. */
	public Shortlist toggle(String name)
	{
		List<String> next = new ArrayList<>(names);
		if (!next.remove(name))
		{
			next.add(name);
			while (next.size() > KEPT)
			{
				next.remove(0);
			}
		}
		return new Shortlist(Collections.unmodifiableList(next));
	}

	/** The listed targets that are still on the list of targets, in shortlist order. */
	public List<Target> targets(Collection<Target> all)
	{
		List<Target> found = new ArrayList<>();
		for (String name : names)
		{
			for (Target t : all)
			{
				if (t.getName().equals(name))
				{
					found.add(t);
					break;
				}
			}
		}
		return found;
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Whether the black mask and slayer helmet count against a target. Slayer creatures are
 * nearly always killed on task, bosses and training spots seldom are, so by default the
 * bonus counts for Slayer creatures and for anything the player's current task covers.
 */
public final class SlayerTask
{
	public enum Mode
	{
		SMART("Slayer monsters and your task"),
		ALWAYS("Always"),
		NEVER("Never");

		private final String label;

		Mode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	public static final SlayerTask ALWAYS = new SlayerTask(Mode.ALWAYS, null);
	public static final SlayerTask NEVER = new SlayerTask(Mode.NEVER, null);

	/** Tasks that also cover a boss or monster besides its own name, as the Slayer helper lists them. */
	private static final Map<String, Set<String>> COVERED_BY = new HashMap<>();

	static
	{
		cover("vorkath", "blue dragons", "zombies");
		cover("kree'arra", "aviansies");
		cover("k'ril tsutsaroth", "greater demons");
		cover("cerberus", "hellhounds");
		cover("abyssal sire", "abyssal demons");
		cover("alchemical hydra", "hydras");
		cover("kraken", "cave kraken", "cave kraken boss");
		cover("thermonuclear smoke devil", "smoke devils");
		cover("grotesque guardians", "gargoyles");
		cover("dawn (grotesque guardians)", "gargoyles");
		cover("sarachnis", "spiders");
		cover("kalphite queen", "kalphites");
		cover("dagannoth rex", "dagannoth", "dagannoth kings");
		cover("dagannoth prime", "dagannoth", "dagannoth kings");
		cover("dagannoth supreme", "dagannoth", "dagannoth kings");
		cover("tztok-jad", "tzhaar");
		cover("tormented demon", "greater demons");
		cover("araxxor", "araxytes", "spiders");
		cover("amoxliatl", "lesser nagua");
		cover("skotizo", "black demons", "greater demons");
		cover("callisto", "bears");
		cover("artio", "bears");
		cover("venenatis", "spiders");
		cover("spindel", "spiders");
		cover("vet'ion", "skeletons");
		cover("scorpia", "scorpions");
		cover("demonic gorilla", "black demons", "monkeys");
		cover("greater nechryael", "nechryael");
		cover("lizardman shaman", "lizardmen");
		cover("rune dragon", "metal dragons");
		cover("adamant dragon", "metal dragons");
		cover("brutal black dragon", "black dragons");
		cover("kalphite soldier", "kalphites");
		cover("ammonite crab", "crabs");
		cover("sand crab", "crabs");
		cover("rock crab", "crabs");
		cover("basilisk knight", "basilisks");
	}

	private final Mode mode;
	private final String task;

	private SlayerTask(Mode mode, String task)
	{
		this.mode = mode;
		this.task = task == null || task.isEmpty() ? null : normal(task);
	}

	/** The assumption for a mode, with the player's current task name (or null when they have none). */
	public static SlayerTask of(Mode mode, String currentTask)
	{
		if (mode == Mode.ALWAYS)
		{
			return ALWAYS;
		}
		if (mode == Mode.NEVER)
		{
			return NEVER;
		}
		return new SlayerTask(Mode.SMART, currentTask);
	}

	public Mode getMode()
	{
		return mode;
	}

	/** The current task, lower case, or null. */
	public String getTask()
	{
		return task;
	}

	/** Whether the slayer helmet's bonus counts against this target. */
	public boolean covers(Target target)
	{
		if (target == null || !target.isSlayer() || mode == Mode.NEVER)
		{
			return false;
		}
		if (mode == Mode.ALWAYS || "Slayer".equals(target.getGroup()))
		{
			return true;
		}
		return task != null && taskCovers(task, target.getName());
	}

	/** Whether a task, by its name in the game, covers a monster by its name. */
	static boolean taskCovers(String task, String monster)
	{
		String t = normal(task);
		String m = normal(monster);
		if (t.equals(m))
		{
			return true;
		}
		return COVERED_BY.getOrDefault(m, Collections.emptySet()).contains(t);
	}

	/**
	 * The targets a task covers, best first: the monster it is named for, then other Slayer
	 * creatures, then training spots, then bosses, each in the catalogue's own order. A Smoke
	 * devils task aims at smoke devils before the Thermonuclear smoke devil.
	 */
	public static List<Target> targetsFor(String task, List<Target> targets)
	{
		List<Target> covered = new ArrayList<>();
		if (task == null || task.isEmpty() || targets == null)
		{
			return covered;
		}
		String named = normal(task);
		for (Target t : targets)
		{
			if (t.isSlayer() && taskCovers(task, t.getName()))
			{
				covered.add(t);
			}
		}
		covered.sort(Comparator.comparingInt(t -> normal(t.getName()).equals(named) ? 0
			: "Slayer".equals(t.getGroup()) ? 1 : "Training".equals(t.getGroup()) ? 2 : 3));
		return covered;
	}

	/** Lower case, without "The" or a plural "s", so "The Abyssal Sire" and "Hill Giants" match their monsters. */
	static String normal(String name)
	{
		String s = name.toLowerCase(Locale.ROOT).trim();
		if (s.startsWith("the "))
		{
			s = s.substring(4);
		}
		if (s.endsWith("s") && !s.endsWith("ss"))
		{
			s = s.substring(0, s.length() - 1);
		}
		return s;
	}

	private static void cover(String monster, String... tasks)
	{
		Set<String> set = COVERED_BY.computeIfAbsent(normal(monster), k -> new HashSet<>());
		for (String task : tasks)
		{
			set.add(normal(task));
		}
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof SlayerTask && ((SlayerTask) o).mode == mode
			&& (task == null ? ((SlayerTask) o).task == null : task.equals(((SlayerTask) o).task));
	}

	@Override
	public int hashCode()
	{
		return mode.hashCode() * 31 + (task == null ? 0 : task.hashCode());
	}

	@Override
	public String toString()
	{
		return mode + (task == null ? "" : ":" + task);
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.function.IntFunction;

/**
 * What the player is wearing against the best loadout they own for the aimed target: the pieces to
 * put on, where each one is (carried or in the bank), and the damage the change adds. Only pieces to
 * put on are listed; a slot the best loadout leaves empty is not a reason to take anything off.
 */
public final class Swap
{
	/** Below this, wearing something else is not worth a line. */
	static final double MIN_GAIN = 0.005;

	/** Where a piece to put on is kept. */
	public enum Where
	{
		INVENTORY,
		BANK
	}

	/** One piece to put on. */
	public static final class Change
	{
		private final Gear wear;
		private final Gear off;
		private final Where where;

		Change(Gear wear, Gear off, Where where)
		{
			this.wear = wear;
			this.off = off;
			this.where = where;
		}

		public Gear getWear()
		{
			return wear;
		}

		/** What it replaces, or null for an empty slot (or one holding something the roadmap does not know). */
		public Gear getOff()
		{
			return off;
		}

		public Where getWhere()
		{
			return where;
		}
	}

	private final List<Change> changes;
	private final double wornDps;
	private final double bestDps;
	private final Result.Kind wornKind;

	private Swap(List<Change> changes, double wornDps, double bestDps, Result.Kind wornKind)
	{
		this.changes = Collections.unmodifiableList(changes);
		this.wornDps = wornDps;
		this.bestDps = bestDps;
		this.wornKind = wornKind;
	}

	/**
	 * @param worn the gear worn now, by item id, as the game shows it; ids the roadmap does not know are ignored
	 * @param carried item ids in the inventory, to tell a piece at hand from one in the bank
	 * @param byId the roadmap's piece for an item id, or null
	 * @param best the best loadout owned for the target, or null when nothing can attack it
	 */
	public static Swap of(Set<Integer> worn, Set<Integer> carried, IntFunction<Gear> byId, Planner.Plan best,
		Calc calc, Fighter fighter, Target target)
	{
		Loadout now = Loadout.empty();
		for (int id : worn)
		{
			Gear g = byId.apply(id);
			if (g != null)
			{
				now = now.with(g);
			}
		}
		Result wornResult = calc.best(now, fighter, target);
		double wornDps = wornResult == null ? 0 : wornResult.getDps();
		Result.Kind wornKind = wornResult == null || wornDps <= 0 ? null : wornResult.getKind();
		if (best == null || best.getResult() == null || best.dps() <= 0)
		{
			return new Swap(new ArrayList<>(), wornDps, 0, wornKind);
		}
		List<Change> changes = new ArrayList<>();
		if (best.dps() - wornDps >= MIN_GAIN)
		{
			Loadout lo = best.getLoadout();
			for (int slot : ORDER)
			{
				Gear want = lo.get(slot);
				Gear have = now.get(slot);
				if (want == null || have != null && have.key().equals(want.key()))
				{
					continue;
				}
				changes.add(new Change(want, have, carries(carried, want) ? Where.INVENTORY : Where.BANK));
			}
		}
		return new Swap(changes, wornDps, best.dps(), wornKind);
	}

	/** Weapon first, as the change that matters most, then the body down. */
	private static final int[] ORDER = {Gear.WEAPON, Gear.SHIELD, Gear.AMMO, Gear.HEAD, Gear.BODY, Gear.LEGS, Gear.NECK, Gear.CAPE,
		Gear.HANDS, Gear.FEET, Gear.RING};

	private static boolean carries(Set<Integer> carried, Gear g)
	{
		for (int id : g.getIds())
		{
			if (carried.contains(id))
			{
				return true;
			}
		}
		return false;
	}

	/** The pieces to put on, weapon first; empty when what is worn is already the best owned. */
	public List<Change> getChanges()
	{
		return changes;
	}

	/** Damage a second in what is worn now. */
	public double getWornDps()
	{
		return wornDps;
	}

	/** Damage a second in the best loadout owned. */
	public double getBestDps()
	{
		return bestDps;
	}

	/** How what is worn now attacks, or null when it cannot hurt the target. */
	public Result.Kind getWornKind()
	{
		return wornKind;
	}

	/** The damage a second the changes add. */
	public double gain()
	{
		return Math.max(0, bestDps - wornDps);
	}

	public boolean isBest()
	{
		return changes.isEmpty() && bestDps > 0;
	}
}

package com.codex.gearroadmap.core;

/**
 * Follows the slayer task by its key (task id and boss id, or "" without one) through logins and
 * world hops. Arriving in a world makes the client take its varps afresh, so for a few ticks the
 * task can read as none and then come back. Taking that blink at its word would end the task, and
 * with it the player's choice to look elsewhere or at one of its bosses; so a change is only
 * believed once the varps have had a few ticks to settle.
 */
public final class TaskWatch
{
	/** Ticks after arriving in a world before the task's varps are believed. */
	public static final int SETTLE_TICKS = 5;

	/** What a reading of the task means for the plan. */
	public enum Change
	{
		/** Nothing to do. */
		NONE,
		/** A task began, or is a different one: plan again. */
		CHANGED,
		/** The task was done or dropped: plan again, and follow the next one afresh. */
		ENDED
	}

	/** The task as last believed, or null before the first settled reading. */
	private String key;
	private int settle = SETTLE_TICKS;

	/** The player arrived in a world: a login, a world hop or the connection coming back. */
	public void arrived()
	{
		settle = SETTLE_TICKS;
	}

	/** Logged out: the next login's task is read afresh. */
	public void forget()
	{
		key = null;
		settle = SETTLE_TICKS;
	}

	/** Whether the varps have settled since arriving, so what changes now is the player's doing. */
	public boolean isSettled()
	{
		return settle == 0;
	}

	/** A task varp moved, reading the task as it now stands. */
	public Change seen(String now)
	{
		return settle > 0 ? Change.NONE : compare(now);
	}

	/** A game tick passed while logged in; the settling tick reads the task once. */
	public Change tick(String now)
	{
		if (settle == 0 || --settle > 0)
		{
			return Change.NONE;
		}
		return compare(now);
	}

	/** The task as last believed, "" without one, or null before it is known. */
	public String getKey()
	{
		return key;
	}

	private Change compare(String now)
	{
		if (now.equals(key))
		{
			return Change.NONE;
		}
		String was = key;
		key = now;
		return now.isEmpty() && was != null && !was.isEmpty() ? Change.ENDED : Change.CHANGED;
	}
}

package com.codex.gearroadmap.data;

import java.util.Collections;
import java.util.Map;

/**
 * An item the roadmap may recommend: what it takes to wield, and how it is had,
 * either bought (the item itself or the tradeable parts it is made from) or earned.
 */
public final class CatalogueEntry
{
	private String name;
	private Map<String, Integer> req;
	private int[] build;
	private String earn;
	private String note;

	private transient Gear gear;

	public CatalogueEntry()
	{
	}

	public CatalogueEntry(Gear gear, Map<String, Integer> requirements, int[] build, String earn, String note)
	{
		this.name = gear.getName();
		this.gear = gear;
		this.req = requirements;
		this.build = build;
		this.earn = earn;
		this.note = note;
	}

	public String getName()
	{
		return name;
	}

	public Gear getGear()
	{
		return gear;
	}

	void setGear(Gear gear)
	{
		this.gear = gear;
	}

	/** Skill name to the level needed to wield it. */
	public Map<String, Integer> getRequirements()
	{
		return req == null ? Collections.emptyMap() : req;
	}

	/** Tradeable parts bought to make it, or null when the item itself is bought. */
	public int[] getBuild()
	{
		return build;
	}

	/** Where it is earned, for items that cannot be bought. */
	public String getEarn()
	{
		return earn;
	}

	public boolean isEarned()
	{
		return earn != null;
	}

	public String getNote()
	{
		return note;
	}
}

package com.codex.gearroadmap.data;

import java.util.Locale;

/**
 * One piece of equipment as the combat formulas see it: its slot, attack bonuses,
 * strength bonuses and, for weapons, its category and attack speed. The several ids
 * of one item (charged and uncharged, ornament kits, locked copies) share one Gear.
 */
public final class Gear
{
	public static final int HEAD = 0;
	public static final int CAPE = 1;
	public static final int NECK = 2;
	public static final int AMMO = 3;
	public static final int WEAPON = 4;
	public static final int BODY = 5;
	public static final int SHIELD = 6;
	public static final int LEGS = 7;
	public static final int HANDS = 8;
	public static final int FEET = 9;
	public static final int RING = 10;
	public static final int SLOTS = 11;

	public static final int STAB = 0;
	public static final int SLASH = 1;
	public static final int CRUSH = 2;
	public static final int MAGIC = 3;
	public static final int RANGED = 4;

	public static final String[] SLOT_NAMES = {"Head", "Cape", "Neck", "Ammo", "Weapon", "Body", "Shield", "Legs", "Hands", "Feet", "Ring"};

	// Field names follow the bundled JSON.
	private int id;
	private int[] ids;
	private String name;
	private int slot;
	private int[] o;
	private int[] p;
	private String cat;
	private int spd;
	private boolean two;
	private Integer am;

	private transient String key;

	public Gear()
	{
	}

	public Gear(int id, String name, int slot, int[] offence, int[] power, String category, int speed, boolean twoHanded)
	{
		this.id = id;
		this.name = name;
		this.slot = slot;
		this.o = offence;
		this.p = power;
		this.cat = category;
		this.spd = speed;
		this.two = twoHanded;
	}

	public int getId()
	{
		return id;
	}

	/** Every item id that counts as this piece. */
	public int[] getIds()
	{
		return ids == null || ids.length == 0 ? new int[]{id} : ids;
	}

	public String getName()
	{
		return name;
	}

	/** The lower-case name the special effects are keyed on. */
	public String key()
	{
		if (key == null)
		{
			key = name.toLowerCase(Locale.ROOT);
		}
		return key;
	}

	public int getSlot()
	{
		return slot;
	}

	/** Stab, slash, crush, magic and ranged attack bonuses. */
	public int offence(int type)
	{
		return o == null ? 0 : o[type];
	}

	public int strength()
	{
		return p == null ? 0 : p[0];
	}

	public int rangedStrength()
	{
		return p == null ? 0 : p[1];
	}

	/** Magic damage in tenths of a percent, as the equipment screen counts it times ten. */
	public int magicDamage()
	{
		return p == null ? 0 : p[2];
	}

	public String getCategory()
	{
		return cat == null ? "" : cat;
	}

	public int getSpeed()
	{
		return spd;
	}

	/** Index of the ammunition list this weapon fires, or -1 when it is not on that table. */
	public int ammoList()
	{
		return am == null ? -1 : am;
	}

	public boolean isTwoHanded()
	{
		return two;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.codex.gearroadmap.data;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * The bundled tables: every combat-relevant piece of equipment, the catalogue of
 * upgrades worth recommending, the attack styles of each weapon category and the
 * monsters a roadmap can aim at.
 */
public final class RoadmapData
{
	private static final String RESOURCE = "/com/codex/gearroadmap/gear-roadmap.json";

	/** What a weapon category offers: an attack type ("stab", "ranged", "magic"...) and a stance. */
	public static final class Style
	{
		private final String type;
		private final String stance;

		public Style(String type, String stance)
		{
			this.type = type;
			this.stance = stance;
		}

		public String getType()
		{
			return type;
		}

		public String getStance()
		{
			return stance;
		}
	}

	private static final class Raw
	{
		Map<String, List<List<String>>> styles;
		List<List<Integer>> ammo;
		List<Gear> gear;
		List<CatalogueEntry> catalogue;
		List<Target> targets;
	}

	private final Map<Integer, Gear> byId = new HashMap<>();
	private final Map<String, Gear> byName = new HashMap<>();
	private final Map<String, List<Style>> styles = new HashMap<>();
	private final Map<String, CatalogueEntry> catalogue = new LinkedHashMap<>();
	private final List<Target> targets;
	private final List<Gear> gear;
	private final List<Set<Integer>> ammo = new ArrayList<>();

	private RoadmapData(Raw raw)
	{
		gear = raw.gear == null ? Collections.emptyList() : raw.gear;
		for (Gear g : gear)
		{
			byName.put(g.key(), g);
			for (int id : g.getIds())
			{
				byId.putIfAbsent(id, g);
			}
		}
		if (raw.styles != null)
		{
			for (Map.Entry<String, List<List<String>>> e : raw.styles.entrySet())
			{
				List<Style> list = new ArrayList<>();
				for (List<String> pair : e.getValue())
				{
					if (pair.size() >= 2)
					{
						list.add(new Style(pair.get(0), pair.get(1)));
					}
				}
				styles.put(e.getKey(), list);
			}
		}
		if (raw.catalogue != null)
		{
			for (CatalogueEntry entry : raw.catalogue)
			{
				Gear g = byName.get(entry.getName().toLowerCase(Locale.ROOT));
				if (g != null)
				{
					entry.setGear(g);
					catalogue.put(g.key(), entry);
				}
			}
		}
		if (raw.ammo != null)
		{
			for (List<Integer> list : raw.ammo)
			{
				ammo.add(list == null ? Collections.emptySet() : new HashSet<>(list));
			}
		}
		targets = raw.targets == null ? Collections.emptyList() : raw.targets;
	}

	public static RoadmapData load(Gson gson) throws IOException
	{
		try (InputStream in = RoadmapData.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing " + RESOURCE);
			}
			return read(gson, new InputStreamReader(in, StandardCharsets.UTF_8));
		}
	}

	public static RoadmapData read(Gson gson, Reader reader) throws IOException
	{
		try
		{
			Raw raw = gson.fromJson(reader, Raw.class);
			if (raw == null)
			{
				throw new IOException("Empty gear data");
			}
			return new RoadmapData(raw);
		}
		catch (JsonParseException e)
		{
			throw new IOException(e);
		}
	}

	/** The piece an item id counts as, or null when it is not combat gear. */
	public Gear gear(int itemId)
	{
		return byId.get(itemId);
	}

	/**
	 * The ammunition ids a weapon fires: null when the weapon is not a ranged weapon that
	 * cares, empty when it fires no ammunition (a blowpipe or crystal bow).
	 */
	public Set<Integer> ammoFor(Gear weapon)
	{
		int list = weapon == null ? -1 : weapon.ammoList();
		return list < 0 || list >= ammo.size() ? null : ammo.get(list);
	}

	public Gear named(String name)
	{
		return name == null ? null : byName.get(name.toLowerCase(Locale.ROOT));
	}

	public List<Gear> allGear()
	{
		return gear;
	}

	public List<Style> styles(String category)
	{
		List<Style> list = styles.get(category);
		return list == null ? styles.getOrDefault("Unarmed", Collections.emptyList()) : list;
	}

	public CatalogueEntry entry(Gear gear)
	{
		return gear == null ? null : catalogue.get(gear.key());
	}

	public List<CatalogueEntry> catalogue()
	{
		return new ArrayList<>(catalogue.values());
	}

	public List<Target> targets()
	{
		return targets;
	}

	public Target target(String name)
	{
		for (Target t : targets)
		{
			if (t.getName().equalsIgnoreCase(name))
			{
				return t;
			}
		}
		return null;
	}
}

package com.codex.gearroadmap.data;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** A monster the player can aim their gear at, with the stats that defend against each attack. */
public final class Target
{
	public static final int D_STAB = 0;
	public static final int D_SLASH = 1;
	public static final int D_CRUSH = 2;
	public static final int D_MAGIC = 3;
	public static final int D_LIGHT = 4;
	public static final int D_STANDARD = 5;
	public static final int D_HEAVY = 6;

	private int id;
	private String name;
	private String group;
	private int hp;
	private int def;
	private int mag;
	private int mb;
	private int[] d;
	private int size;
	private List<String> attr;
	private boolean slayer;
	private List<Object> weak;
	private List<String> only;
	private boolean wild;
	private int fa;
	private Map<String, Integer> up;

	public Target()
	{
	}

	public Target(String name, String group, int hp, int def, int magic, int[] defensive, int size, List<String> attributes, boolean slayer)
	{
		this.name = name;
		this.group = group;
		this.hp = hp;
		this.def = def;
		this.mag = magic;
		this.d = defensive;
		this.size = size;
		this.attr = attributes;
		this.slayer = slayer;
	}

	public int getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	/** Boss, Slayer or Training. */
	public String getGroup()
	{
		return group;
	}

	public int getHp()
	{
		return hp;
	}

	public int getDefence()
	{
		return def;
	}

	public int getMagic()
	{
		return mag;
	}

	public int getMagicAttack()
	{
		return mb;
	}

	public int defensive(int type)
	{
		return d == null ? 0 : d[type];
	}

	public int getSize()
	{
		return Math.max(1, size);
	}

	public boolean is(String attribute)
	{
		return attr != null && attr.contains(attribute);
	}

	public List<String> getAttributes()
	{
		return attr == null ? Collections.emptyList() : attr;
	}

	public boolean isSlayer()
	{
		return slayer;
	}

	/** Whether it is fought in the Wilderness, where revenant weapons are stronger. */
	public boolean isWilderness()
	{
		return wild;
	}

	/** Armour taken off every melee and ranged hit that lands, or added when below zero. */
	public int getFlatArmour()
	{
		return fa;
	}

	/** Percent of a demonbane weapon's bonus this demon takes: Duke Sucellus resists, Yama is weak to it. */
	public int demonbaneVulnerability()
	{
		if ("Duke Sucellus".equals(name))
		{
			return 70;
		}
		return "Yama".equals(name) ? 120 : 100;
	}

	/** Bosses, Slayer creatures or training spots. */
	public boolean isBoss()
	{
		return "Boss".equals(group);
	}

	/** The element this monster takes extra magic damage from, or null. */
	public String weakness()
	{
		return weak == null || weak.size() < 2 || weak.get(0) == null ? null : weak.get(0).toString().toLowerCase(Locale.ROOT);
	}

	/** Percent of extra accuracy and damage the weak element gets. */
	public int weaknessSeverity()
	{
		if (weak == null || weak.size() < 2 || !(weak.get(1) instanceof Number))
		{
			return 0;
		}
		return ((Number) weak.get(1)).intValue();
	}

	@Override
	public String toString()
	{
		return name;
	}

	/**
	 * Percent of the fight this kind of attack can keep hitting, against what the damage formulas assume.
	 * Vorkath's acid phase and fire bombs keep a melee player walking and off him, while ranged and magic
	 * attack through them, so his melee damage counts at 80%. Every other target is 100.
	 */
	public int uptime(String kind)
	{
		Integer pct = up == null ? null : up.get(kind.toLowerCase(Locale.ROOT));
		return pct == null ? 100 : Math.max(1, Math.min(100, pct));
	}

	/** Whether the target can be hurt with this kind of attack: melee, ranged or magic. */
	public boolean allows(String kind)
	{
		return only == null || only.contains(kind.toLowerCase(Locale.ROOT));
	}
}

package com.codex.gearroadmap.overlay;

import com.codex.gearroadmap.ui.Sigil;
import com.codex.gearroadmap.ui.Theme;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A gilt plaque that rises in the game view when the player gets an upgrade from their
 * road: the item, the damage it adds against the aimed target and what comes next. It
 * draws a view the plugin prepares, so rendering never touches game state.
 */
public class UpgradePlaque extends Overlay
{
	private static final int WIDTH = 228;
	private static final int PAD = 9;
	private static final int ICON = 40;
	private static final long FADE_MS = 450;

	/** What the plaque shows. */
	public static final class View
	{
		final String heading;
		final String name;
		final String gain;
		final String next;
		final Color color;
		final BufferedImage icon;
		final long shownAt;
		final long durationMs;

		public View(String heading, String name, String gain, String next, Color color, BufferedImage icon,
			long shownAt, long durationMs)
		{
			this.heading = heading;
			this.name = name;
			this.gain = gain;
			this.next = next;
			this.color = color;
			this.icon = icon;
			this.shownAt = shownAt;
			this.durationMs = durationMs;
		}
	}

	private volatile View view;

	public UpgradePlaque()
	{
		setPosition(OverlayPosition.TOP_CENTER);
	}

	public void show(View view)
	{
		this.view = view;
	}

	public void clear()
	{
		view = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		View v = view;
		if (v == null)
		{
			return null;
		}
		long age = System.currentTimeMillis() - v.shownAt;
		if (age > v.durationMs)
		{
			view = null;
			return null;
		}
		float alpha = (float) Math.min(1, Math.min(age / (double) FADE_MS, (v.durationMs - age) / (double) FADE_MS));
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0, alpha)));
		Theme.smooth(g);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int lines = 2 + (v.gain == null ? 0 : 1) + (v.next == null ? 0 : 1);
		int textHeight = small.getHeight() + bold.getHeight() + (lines - 2) * (small.getHeight() + 1);
		int height = PAD * 2 + Math.max(ICON, textHeight);
		Color tint = v.color;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, WIDTH - 1, height - 1, 12, 12);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 238), 0, height, Theme.alpha(Theme.INK_DEEP, 238)));
		g.fill(shape);
		double beat = 0.5 + 0.5 * Math.sin(age / 220.0);
		g.setStroke(new BasicStroke(3f));
		g.setColor(Theme.alpha(tint, (int) (40 + beat * 70)));
		g.draw(shape);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(tint, 200));
		g.draw(shape);

		// The item sits in a lit well.
		int wellX = PAD;
		int wellY = (height - ICON) / 2;
		g.setPaint(new RadialGradientPaint(wellX + ICON / 2f, wellY + ICON / 2f, ICON / 2f,
			new float[]{0f, 1f}, new Color[]{Theme.alpha(tint, 110), Theme.alpha(Theme.INK_DEEP, 220)}));
		g.fill(new Ellipse2D.Float(wellX, wellY, ICON, ICON));
		g.setColor(Theme.alpha(tint, 170));
		g.draw(new Ellipse2D.Float(wellX, wellY, ICON, ICON));
		if (v.icon != null)
		{
			g.drawImage(v.icon, wellX + (ICON - v.icon.getWidth()) / 2, wellY + (ICON - v.icon.getHeight()) / 2, null);
		}
		else
		{
			Sigil.paint(g, wellX + 8, wellY + 8, ICON - 16);
		}

		int x = PAD + ICON + 9;
		int width = WIDTH - x - PAD;
		int y = PAD + Math.max(0, (Math.max(ICON, textHeight) - textHeight) / 2);
		g.setFont(Theme.small());
		shadow(g, v.heading, x, y + small.getAscent(), tint);
		y += small.getHeight();
		g.setFont(Theme.title());
		shadow(g, clip(v.name, bold, width), x, y + bold.getAscent(), Theme.GOLD_BRIGHT);
		y += bold.getHeight();
		g.setFont(Theme.small());
		if (v.gain != null)
		{
			shadow(g, clip(v.gain, small, width), x, y + small.getAscent(), Theme.TEAL);
			y += small.getHeight() + 1;
		}
		if (v.next != null)
		{
			shadow(g, clip(v.next, small, width), x, y + small.getAscent(), Theme.TEXT_MUTED);
		}
		g.setComposite(old);
		return new Dimension(WIDTH, height);
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String clip(String text, FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String ellipsis = "...";
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + ellipsis) > width)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.Consumer;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;
	private Consumer<Point> onMenu;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
				else if (SwingUtilities.isRightMouseButton(e) && onMenu != null)
				{
					onMenu.accept(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this));
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	/** What a right-click opens, given where on the card it was; call after {@link #onClick}. */
	public Card onMenu(Consumer<Point> action)
	{
		onMenu = action;
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.gearroadmap.ui;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.SwingUtilities;
import javax.swing.Timer;

/**
 * Item pictures for one card, held until the card is drawn with all of them in.
 *
 * <p>A card is drawn once, when its button is pressed, so a picture still loading would be saved as
 * an empty well. The card is drawn a first time to learn which pictures it needs; if any has not
 * arrived, it is drawn again as soon as the last one does (or after a short wait, so a picture that
 * never comes cannot hold the card back). The second drawing is handed the very same pictures, so
 * one evicted from RuneLite's small picture cache in between cannot come back blank.
 */
public final class CardPictures implements ItemIcons
{
	/** The longest a card waits for its pictures before it is drawn with what has come. */
	static final int WAIT_MS = 2_500;

	private final ItemIcons source;
	private final Map<Integer, BufferedImage> taken = new HashMap<>();
	private final Set<Integer> waiting = new HashSet<>();
	private final Set<Integer> arrived = new HashSet<>();
	private Runnable whenAllArrived;

	CardPictures(ItemIcons source)
	{
		this.source = source;
	}

	@Override
	public BufferedImage icon(int itemId, Runnable ignored)
	{
		synchronized (this)
		{
			if (taken.containsKey(itemId))
			{
				return taken.get(itemId);
			}
		}
		BufferedImage image = source.icon(itemId, () -> arrived(itemId));
		synchronized (this)
		{
			taken.put(itemId, image);
			if (image != null && !source.hasArrived(image) && !arrived.contains(itemId))
			{
				waiting.add(itemId);
			}
		}
		return image;
	}

	@Override
	public boolean hasArrived(BufferedImage image)
	{
		return source.hasArrived(image);
	}

	private void arrived(int itemId)
	{
		Runnable done = null;
		synchronized (this)
		{
			arrived.add(itemId);
			if (waiting.remove(itemId) && waiting.isEmpty())
			{
				done = whenAllArrived;
			}
		}
		if (done != null)
		{
			done.run();
		}
	}

	/** True when no picture the card asked for is still on its way. */
	synchronized boolean allArrived()
	{
		return waiting.isEmpty();
	}

	/** Runs once the last picture still on its way arrives; at once if none is. */
	void whenAllArrived(Runnable run)
	{
		boolean now;
		synchronized (this)
		{
			whenAllArrived = run;
			now = waiting.isEmpty();
		}
		if (now)
		{
			run.run();
		}
	}

	/**
	 * Draws a card with all its pictures in and hands it over on the Swing thread, as Save and Copy need.
	 *
	 * @param icons where pictures come from, or null to draw without them
	 * @param render draws the card with the pictures given
	 * @param deliver takes the finished card
	 */
	public static void draw(ItemIcons icons, Function<ItemIcons, BufferedImage> render, Consumer<BufferedImage> deliver)
	{
		// A second press while the first card still waits for its pictures is let go, so one press
		// never becomes two save dialogs.
		if (!BUSY.compareAndSet(false, true))
		{
			return;
		}
		int generation = GENERATION.get();
		Timer[] wait = new Timer[1];
		draw(icons, pictures -> GENERATION.get() == generation ? render.apply(pictures) : null, card ->
		{
			// A card still waiting when the plugin stopped is dropped, not saved by a plugin that is gone.
			if (GENERATION.get() == generation)
			{
				deliver.accept(card);
			}
		}, SwingUtilities::invokeLater, run ->
		{
			Timer timer = new Timer(WAIT_MS, e -> run.run());
			timer.setRepeats(false);
			wait[0] = timer;
			waitTimer = timer;
			timer.start();
		}, () ->
		{
			// The wait is over either way; a card drawn early lets go of its timer.
			if (wait[0] != null)
			{
				wait[0].stop();
			}
			if (waitTimer == wait[0])
			{
				waitTimer = null;
			}
			if (GENERATION.get() == generation)
			{
				BUSY.set(false);
			}
		});
	}

	/**
	 * Lets go of a card still waiting for its pictures, for the plugin's shutdown: it is never handed
	 * over, and the next card (after a restart) is not held back by it.
	 */
	public static void cancel()
	{
		GENERATION.incrementAndGet();
		BUSY.set(false);
		Runnable stop = () ->
		{
			if (waitTimer != null)
			{
				waitTimer.stop();
				waitTimer = null;
			}
		};
		// Plugins stop on the Swing thread; there it is done before any new card can begin.
		if (SwingUtilities.isEventDispatchThread())
		{
			stop.run();
		}
		else
		{
			SwingUtilities.invokeLater(stop);
		}
	}

	/** True while a card waits for its pictures. */
	private static final AtomicBoolean BUSY = new AtomicBoolean();
	/** Moved on by {@link #cancel}, so a card begun before it is dropped. */
	private static final AtomicInteger GENERATION = new AtomicInteger();
	/** The wait of the card waiting now; used on the Swing thread only. */
	private static Timer waitTimer;

	/**
	 * As {@link #draw(ItemIcons, Function, Consumer)}, with how to get back on the Swing thread and how
	 * to wait, for tests.
	 *
	 * @param after runs once the card has been handed over, or failed to draw
	 */
	static void draw(ItemIcons icons, Function<ItemIcons, BufferedImage> render, Consumer<BufferedImage> deliver,
		Consumer<Runnable> onSwing, Consumer<Runnable> afterWait, Runnable after)
	{
		boolean waiting = false;
		try
		{
			if (icons == null)
			{
				deliver.accept(render.apply(null));
				return;
			}
			CardPictures pictures = new CardPictures(icons);
			BufferedImage first = render.apply(pictures);
			if (pictures.allArrived())
			{
				deliver.accept(first);
				return;
			}
			AtomicBoolean done = new AtomicBoolean();
			Runnable finish = () -> onSwing.accept(() ->
			{
				if (done.compareAndSet(false, true))
				{
					try
					{
						deliver.accept(render.apply(pictures));
					}
					finally
					{
						after.run();
					}
				}
			});
			pictures.whenAllArrived(finish);
			afterWait.accept(finish);
			waiting = true;
		}
		finally
		{
			if (!waiting)
			{
				after.run();
			}
		}
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Report;
import com.codex.gearroadmap.core.Result;
import com.codex.gearroadmap.core.Roadmap;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.geom.Path2D;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/**
 * The crest at the top of the panel: the dial, the player and their target, and three
 * ledgers for the kill time now, how much faster the road ends, and the coins to spend.
 */
public class Crest extends JPanel
{
	private final DpsDial dial = new DpsDial(74);
	private final JLabel title = Ui.label("Gear Roadmap", Theme.title(), Theme.GOLD_BRIGHT);
	private final JLabel target = Ui.label("Log in to plan", Theme.small(), Theme.TEXT_MUTED);
	private final Ledger kill = new Ledger("Kill time");
	private final Ledger road = new Ledger("Road ahead");
	private final Ledger coins = new Ledger("Coins");
	private Color glow = Theme.GOLD_DIM;

	public Crest()
	{
		super(new BorderLayout(10, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(12, 10, 12, 10));

		JPanel dialHolder = new JPanel(new BorderLayout());
		dialHolder.setOpaque(false);
		dialHolder.add(dial, BorderLayout.NORTH);
		add(dialHolder, BorderLayout.WEST);

		JPanel right = new JPanel();
		right.setOpaque(false);
		right.setLayout(new BoxLayout(right, BoxLayout.Y_AXIS));
		title.setAlignmentX(LEFT_ALIGNMENT);
		target.setAlignmentX(LEFT_ALIGNMENT);
		right.add(title);
		right.add(target);
		JPanel ledgers = new JPanel(new GridLayout(3, 1, 0, 2));
		ledgers.setOpaque(false);
		ledgers.setBorder(new EmptyBorder(4, 0, 0, 0));
		ledgers.add(kill);
		ledgers.add(road);
		ledgers.add(coins);
		ledgers.setAlignmentX(LEFT_ALIGNMENT);
		right.add(ledgers);
		add(right, BorderLayout.CENTER);
		dial.set("-", 0, 0, Theme.GOLD, false);
	}

	public void update(Report report, String playerName)
	{
		Roadmap map = report.getRoadmap();
		if (!report.isLoggedIn() || map == null)
		{
			title.setText(playerName == null ? "Gear Roadmap" : playerName);
			target.setText(report.isLoggedIn() ? "Reading your gear..." : "Log in to plan");
			target.setForeground(Theme.TEXT_MUTED);
			dial.set("-", 0, 0, Theme.GOLD, true);
			kill.set("-", Theme.TEXT);
			road.set("-", Theme.TEXT);
			coins.set("-", Theme.TEXT);
			glow = Theme.GOLD_DIM;
			repaint();
			return;
		}
		Result now = map.getNow().best().getResult();
		Color color = Theme.kind(now.getKind());
		title.setText(playerName == null ? "Gear Roadmap" : playerName);
		target.setText("vs " + map.getTarget().getName() + (now.getKind() == null ? "" : "  ·  " + now.getKind()));
		target.setForeground(Theme.mix(Theme.TEXT_MUTED, color, 0.55));
		double end = map.finalDps();
		double affordable = now.getDps();
		for (Roadmap.Step step : map.getPath())
		{
			if (step.isAffordable())
			{
				affordable = step.getOption().getAfter().dps();
			}
		}
		dial.set(Format.dps(now.getDps()), end <= 0 ? 0 : now.getDps() / end, end <= 0 ? 0 : affordable / end, color, true);
		kill.set(Format.time(now.secondsToKill(map.getTarget())), Theme.TEXT);
		road.set(map.getPath().isEmpty() ? "Complete" : Format.share(end / Math.max(0.01, now.getDps()) - 1), Theme.TEAL);
		if (report.isIronman())
		{
			coins.label("Road cost");
			coins.set(map.getPath().isEmpty() ? "-" : Format.coins(map.getPath().get(map.getPath().size() - 1).getSpent()), Theme.GOLD);
		}
		else
		{
			coins.label("Coins");
			coins.set(Format.coins(map.getCoins()).replace("Free", "0"), Theme.GOLD);
		}
		glow = Theme.mix(Theme.GOLD_DIM, color, 0.4);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, glow, 0.2), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// Gilt rule along the bottom with a small diamond at its centre.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
		super.paintComponent(graphics);
	}

	/** One labelled value. */
	private static final class Ledger extends JPanel
	{
		private final JLabel value = Ui.label("-", Theme.small(), Theme.TEXT);
		private final JLabel name;

		Ledger(String label)
		{
			super(new BorderLayout());
			setOpaque(false);
			name = Ui.label(label, Theme.small(), Theme.TEXT_MUTED);
			add(name, BorderLayout.WEST);
			add(value, BorderLayout.EAST);
			setPreferredSize(new Dimension(10, 15));
		}

		void label(String text)
		{
			name.setText(text);
		}

		void set(String text, Color color)
		{
			value.setText(text);
			value.setForeground(color);
		}
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import javax.swing.JComponent;

/**
 * The crest's dial: today's damage per second in the middle, and an arc showing how far
 * along the road that is, from nothing to the damage at the road's end. A faint second
 * arc marks what the player's coins already reach.
 */
public class DpsDial extends JComponent
{
	private final int diameter;
	private final Animator now = new Animator(this);
	private final Animator reach = new Animator(this);
	private String value = "-";
	private Color color = Theme.GOLD;

	public DpsDial(int diameter)
	{
		this.diameter = diameter;
		Dimension d = new Dimension(diameter, diameter);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
	}

	/**
	 * @param share today's damage as a share of the road's end
	 * @param affordable the damage the player's coins reach, as the same share
	 */
	public void set(String value, double share, double affordable, Color color, boolean animate)
	{
		this.value = value;
		this.color = color;
		now.set(clamp(share), animate);
		reach.set(clamp(Math.max(share, affordable)), animate);
	}

	private static double clamp(double v)
	{
		return Double.isNaN(v) ? 0 : Math.max(0, Math.min(1, v));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		float thickness = 6f;
		float inset = thickness / 2 + 2;
		float size = diameter - inset * 2;

		g.setPaint(new RadialGradientPaint(diameter / 2f, diameter / 2f, size / 2f, new float[]{0f, 1f},
			new Color[]{Theme.alpha(color, 46), Theme.alpha(Theme.INK_DEEP, 0)}));
		g.fill(new Ellipse2D.Float(inset, inset, size, size));

		// A 270 degree track open at the bottom, like a gauge.
		float start = 225;
		float sweep = -270;
		g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.STROKE, 210));
		g.draw(new Arc2D.Float(inset, inset, size, size, start, sweep, Arc2D.OPEN));
		double reached = reach.get();
		if (reached > now.get() + 0.005)
		{
			g.setColor(Theme.alpha(Theme.GOLD, 70));
			g.draw(new Arc2D.Float(inset, inset, size, size, start, (float) (sweep * reached), Arc2D.OPEN));
		}
		double value = now.get();
		if (value > 0)
		{
			int segments = Math.max(1, (int) Math.ceil(value * 60));
			double step = sweep * value / segments;
			for (int i = 0; i < segments; i++)
			{
				double t = (i + 1) / (double) segments * value;
				g.setColor(Theme.mix(Theme.GOLD_DIM, color, Math.min(1, t * 1.3)));
				g.draw(new Arc2D.Double(inset, inset, size, size, start + i * step, step - (i < segments - 1 ? 0.6 : 0), Arc2D.OPEN));
			}
		}
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 90));
		g.draw(new Ellipse2D.Float(0.5f, 0.5f, diameter - 1, diameter - 1));

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int y = diameter / 2 + bold.getAscent() / 2 - 4;
		ProgressRing.drawShadowed(g, this.value, (diameter - bold.stringWidth(this.value)) / 2, y, Theme.TEXT);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		ProgressRing.drawShadowed(g, "DPS", (diameter - small.stringWidth("DPS")) / 2, y + small.getAscent() + 1, Theme.TEXT_MUTED);
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import java.util.Locale;

/** Coins, damage and times in the short forms the panel uses. */
public final class Format
{
	private Format()
	{
	}

	/**
	 * "850", "8,240", "60k", "1.4M", "12.0M", "1.60B"; "Free" for nothing at all. One rule across the
	 * Codex plugins: thousands whole, millions with one decimal and billions with two, zero or not,
	 * so prices side by side read alike ("9.9M" beside "12.0M", never "12M").
	 */
	public static String coins(long gp)
	{
		if (gp <= 0)
		{
			return "Free";
		}
		if (gp < 10_000)
		{
			return String.format(Locale.ENGLISH, "%,d", gp);
		}
		// A figure that rounds up to a thousand of one unit is written in the next ("1.0M", not "1000k").
		if (gp < 999_500)
		{
			return Math.round(gp / 1_000.0) + "k";
		}
		if (gp < 999_950_000)
		{
			return fixed(gp / 1_000_000.0, 1) + "M";
		}
		return fixed(gp / 1_000_000_000.0, 2) + "B";
	}

	private static String fixed(double value, int places)
	{
		return String.format(Locale.ENGLISH, "%." + places + "f", value);
	}

	/** Damage per second to two places. */
	public static String dps(double dps)
	{
		return String.format(Locale.ENGLISH, "%.2f", Math.max(0, dps));
	}

	/** "+0.42", for a gain. */
	public static String gain(double dps)
	{
		return "+" + dps(dps);
	}

	/** "+14%", with "<1%" for the smallest gains. */
	public static String share(double share)
	{
		if (share <= 0)
		{
			return "+0%";
		}
		if (share < 0.01)
		{
			return "+<1%";
		}
		return "+" + Math.round(share * 100) + "%";
	}

	/** Whole percent. */
	public static String percent(double share)
	{
		return Math.round(Math.max(0, Math.min(1, share)) * 100) + "%";
	}

	/** "48s", "1m 32s", "12m"; "-" when it cannot be done. */
	public static String time(double seconds)
	{
		if (Double.isNaN(seconds) || Double.isInfinite(seconds) || seconds <= 0)
		{
			return "-";
		}
		long s = Math.round(seconds);
		if (s < 60)
		{
			return s + "s";
		}
		long m = s / 60;
		long r = s % 60;
		if (m >= 10 || r == 0)
		{
			return m + "m";
		}
		return m + "m " + r + "s";
	}

	/** "1h 18m", "34m": a longer stretch of time, to the minute. */
	public static String span(double seconds)
	{
		long m = Math.round(Math.max(0, seconds) / 60);
		return m >= 60 ? m / 60 + "h " + m % 60 + "m" : m + "m";
	}

	/** "+0.8%", "+12%": a share to one place below ten percent. */
	public static String fine(double share)
	{
		double pct = Math.max(0, share) * 100;
		return pct < 10 ? "+" + String.format(java.util.Locale.ENGLISH, "%.1f", pct) + "%" : "+" + Math.round(pct) + "%";
	}

	/** A slayer task's name with a capital first letter, as the game lists it: "Abyssal demons". */
	public static String task(String task)
	{
		if (task == null || task.isEmpty())
		{
			return "";
		}
		return Character.toUpperCase(task.charAt(0)) + task.substring(1);
	}

	/** What each point of DPS costs on this upgrade: "85k per DPS". */
	public static String value(long cost, double gain)
	{
		if (cost <= 0 || gain <= 0)
		{
			return "";
		}
		return coins(Math.round(cost / gain)) + " per DPS";
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Loadout;
import com.codex.gearroadmap.data.Gear;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.swing.JComponent;

/**
 * The loadout laid out like the game's worn equipment screen. Pieces new to the player
 * glow teal; empty slots show a faint engraving of what belongs there.
 */
public class GearGrid extends JComponent
{
	private static final int TILE_W = 38;
	private static final int TILE_H = 34;
	private static final int GAP = 6;
	/** Column and row of each slot, in the order of Gear's slot numbers. */
	private static final int[][] CELLS = {
		{1, 0}, {0, 1}, {1, 1}, {2, 1}, {0, 2}, {1, 2}, {2, 2}, {1, 3}, {0, 4}, {1, 4}, {2, 4},
	};
	private static final String[] ENGRAVING = {"Hd", "Cp", "Nk", "Am", "Wp", "Bd", "Sh", "Lg", "Gl", "Bt", "Rg"};

	private final Loadout loadout;
	private final Set<Gear> fresh;
	private final Color accent;
	private final Map<Integer, BufferedImage> images = new HashMap<>();
	private int hover = -1;

	public GearGrid(Loadout loadout, Set<Gear> fresh, Color accent, ItemIcons icons)
	{
		this.loadout = loadout;
		this.fresh = fresh == null ? Collections.emptySet() : fresh;
		this.accent = accent;
		setPreferredSize(new Dimension(10, 5 * TILE_H + 4 * GAP + 4));
		setOpaque(false);
		for (int slot = 0; slot < Gear.SLOTS; slot++)
		{
			Gear g = loadout.get(slot);
			if (g != null && icons != null)
			{
				images.put(slot, icons.icon(g.getId(), this::repaint));
			}
		}
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int slot = slotAt(e.getX(), e.getY());
				if (slot != hover)
				{
					hover = slot;
					Gear g = slot < 0 ? null : loadout.get(slot);
					setToolTipText(slot < 0 ? null : g == null ? Gear.SLOT_NAMES[slot] + ": empty" : g.getName());
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	private int left()
	{
		return (getWidth() - (3 * TILE_W + 2 * GAP)) / 2;
	}

	private int slotAt(int x, int y)
	{
		for (int slot = 0; slot < Gear.SLOTS; slot++)
		{
			int tx = left() + CELLS[slot][0] * (TILE_W + GAP);
			int ty = 2 + CELLS[slot][1] * (TILE_H + GAP);
			if (x >= tx && x < tx + TILE_W && y >= ty && y < ty + TILE_H)
			{
				return slot;
			}
		}
		return -1;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int left = left();

		// Faint gilt threads joining the slots, like the game's equipment frame.
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 70));
		int cx = left + TILE_W + GAP + TILE_W / 2;
		g.drawLine(cx, 2 + TILE_H, cx, 2 + 4 * (TILE_H + GAP));
		int midY = 2 + 2 * (TILE_H + GAP) + TILE_H / 2;
		g.drawLine(left + TILE_W, midY, left + 2 * (TILE_W + GAP), midY);
		int capeY = 2 + (TILE_H + GAP) + TILE_H / 2;
		g.drawLine(left + TILE_W, capeY, left + 2 * (TILE_W + GAP), capeY);

		for (int slot = 0; slot < Gear.SLOTS; slot++)
		{
			int tx = left + CELLS[slot][0] * (TILE_W + GAP);
			int ty = 2 + CELLS[slot][1] * (TILE_H + GAP);
			drawTile(g, slot, tx, ty);
		}
		g.dispose();
	}

	private void drawTile(Graphics2D g, int slot, int x, int y)
	{
		Gear gear = loadout.get(slot);
		boolean isFresh = gear != null && fresh.contains(gear);
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, TILE_W - 1, TILE_H - 1, 8, 8);
		Color top = gear == null ? Theme.INK_DEEP : Theme.mix(Theme.CARD_TOP, isFresh ? Theme.TEAL : accent, 0.16);
		g.setPaint(new GradientPaint(x, y, top, x, y + TILE_H, gear == null ? Theme.INK_DEEP : Theme.CARD));
		g.fill(shape);
		Color rim = isFresh ? Theme.TEAL : gear == null ? Theme.STROKE_SOFT : Theme.alpha(Theme.GOLD, 150);
		if (hover == slot)
		{
			rim = Theme.GOLD_BRIGHT;
		}
		g.setStroke(new BasicStroke(isFresh ? 1.4f : 1f));
		g.setColor(rim);
		g.draw(shape);
		if (gear == null)
		{
			g.setFont(Theme.small());
			FontMetrics fm = g.getFontMetrics();
			String text = ENGRAVING[slot];
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(text, x + (TILE_W - fm.stringWidth(text)) / 2, y + (TILE_H + fm.getAscent()) / 2 - 1);
			return;
		}
		BufferedImage image = images.get(slot);
		if (image != null)
		{
			Composite old = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1f));
			g.drawImage(image, x + (TILE_W - image.getWidth()) / 2, y + (TILE_H - image.getHeight()) / 2, null);
			g.setComposite(old);
		}
		g.setColor(Theme.alpha(Color.WHITE, 16));
		g.drawLine(x + 5, y + 1, x + TILE_W - 5, y + 1);
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Report;
import com.codex.gearroadmap.core.Roadmap;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.awt.Graphics;
import java.util.function.Consumer;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Gear Roadmap side panel: the crest, then three pages. Roadmap is the road of
 * upgrades for the aimed target, Loadout is the gear that road starts from, and Targets
 * compares the player against every target and lets them aim at another.
 */
public class GearRoadmapPanel extends PluginPanel
{
	private static final String[] TABS = {"roadmap", "loadout", "targets"};

	private final ItemIcons icons;
	private final Consumer<String> onAim;
	private final Consumer<Roadmap.Option> onGoal;
	private final Consumer<String> onShortlist;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Roadmap", "Loadout", "Targets");
	private final Segmented kinds = new Segmented(false, LoadoutView.KINDS);
	private final Segmented filters = new Segmented(false, TargetsView.FILTERS);
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane roadmap = scroller();
	private final JScrollPane loadout = scroller();
	private final JScrollPane targets = scroller();
	private final JPanel kindHolder = new JPanel(new BorderLayout());

	private Report report = Report.loggedOut();
	private String playerName;
	/** Whether the road card carries the character's name, from the settings. */
	private boolean showName = true;
	private boolean showWorth;
	private String search = "";
	private Roadmap.Option preview;
	/** The listed monster being fought, and the one the player hid the offer for. */
	private String fighting;
	private String hiddenFight;
	private ShareActions share;
	/** A line under the road card's buttons, such as where it was saved. */
	private String shareNote;
	/** Set when a report arrived while the panel was closed; it is drawn once the panel opens. */
	private boolean stale;

	/**
	 * @param onAim called with a target's name when the player picks it
	 * @param onGoal called with an upgrade to save for, or null to clear the goal
	 * @param onShortlist called with a target's name to put it on the shortlist, or take it off
	 */
	public GearRoadmapPanel(ItemIcons icons, Consumer<String> onAim, Consumer<Roadmap.Option> onGoal, Consumer<String> onShortlist)
	{
		super(false);
		this.icons = icons;
		this.onAim = onAim;
		this.onGoal = onGoal;
		this.onShortlist = onShortlist;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		JPanel loadoutHolder = new JPanel(new BorderLayout());
		loadoutHolder.setOpaque(false);
		kindHolder.setOpaque(false);
		kindHolder.setBorder(new EmptyBorder(6, 8, 0, 8));
		kindHolder.add(kinds, BorderLayout.CENTER);
		loadoutHolder.add(kindHolder, BorderLayout.NORTH);
		loadoutHolder.add(loadout, BorderLayout.CENTER);

		JPanel targetHolder = new JPanel(new BorderLayout());
		targetHolder.setOpaque(false);
		JPanel tools = new JPanel(new BorderLayout(0, 5));
		tools.setOpaque(false);
		tools.setBorder(new EmptyBorder(6, 8, 0, 8));
		tools.add(new SearchField("Find a target", text ->
		{
			search = text;
			rebuildTargets();
		}), BorderLayout.NORTH);
		tools.add(filters, BorderLayout.SOUTH);
		targetHolder.add(tools, BorderLayout.NORTH);
		targetHolder.add(targets, BorderLayout.CENTER);

		content.setOpaque(false);
		content.add(roadmap, TABS[0]);
		content.add(loadoutHolder, TABS[1]);
		content.add(targetHolder, TABS[2]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(tab ->
		{
			if (tab == 1 && preview != null)
			{
				preview = null;
				rebuildLoadout();
			}
			cards.show(content, TABS[tab]);
		});
		kinds.onChange(i -> rebuildLoadout());
		filters.onChange(i -> rebuildTargets());
		rebuild();
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/** Called on the Swing thread with each new report. */
	public void update(Report report, String playerName)
	{
		if (!java.util.Objects.equals(aimed(this.report), aimed(report)))
		{
			// A note on a card saved for another target no longer applies.
			shareNote = null;
		}
		this.report = report;
		this.playerName = playerName;
		preview = null;
		if (!isShowing())
		{
			// Nothing is built while the panel is closed; it catches up when it opens.
			stale = true;
			return;
		}
		rebuild();
	}

	@Override
	public void onActivate()
	{
		if (stale)
		{
			rebuild();
		}
	}

	private static String aimed(Report report)
	{
		return report == null || report.getRoadmap() == null ? null : report.getRoadmap().getTarget().getName();
	}

	/** Whether the road card shows the player's coins and how far they go; used when the card is next drawn. */
	public void setShowWorth(boolean showWorth)
	{
		this.showWorth = showWorth;
	}

	/** Whether the road card carries the character's name; used when the card is next drawn. */
	public void setShowName(boolean showName)
	{
		this.showName = showName;
	}

	/** What the road card's buttons do. */
	public void setShare(ShareActions share)
	{
		this.share = share;
	}

	/** A line under the road card's buttons; the Roadmap tab is built again to show it. */
	public void shareNote(String note)
	{
		shareNote = note;
		rebuildRoadmap();
	}

	/** Called on the Swing thread with the listed monster the player is fighting, or null. */
	public void setFighting(String fighting)
	{
		if (java.util.Objects.equals(this.fighting, fighting))
		{
			return;
		}
		this.fighting = fighting;
		if (!isShowing())
		{
			stale = true;
			return;
		}
		rebuildRoadmap();
	}

	/** Opens one tab, for previews and tests. */
	public void showTab(int tab)
	{
		tabs.setSelected(tab, false);
		cards.show(content, TABS[tab]);
	}

	/** Shows the loadout an upgrade would build. */
	public void preview(Roadmap.Option option)
	{
		preview = option;
		rebuildLoadout();
		tabs.setSelected(1, false);
		cards.show(content, TABS[1]);
		SwingUtilities.invokeLater(() -> loadout.getVerticalScrollBar().setValue(0));
	}

	public void selectKind(int kind)
	{
		kinds.setSelected(kind, false);
		rebuildLoadout();
	}

	public void selectFilter(int filter)
	{
		filters.setSelected(filter, false);
		rebuildTargets();
	}

	private void rebuild()
	{
		stale = false;
		crest.update(report, playerName);
		rebuildRoadmap();
		rebuildLoadout();
		rebuildTargets();
	}

	private void rebuildRoadmap()
	{
		String fight = fighting == null || fighting.equals(hiddenFight) ? null : fighting;
		StackPanel view = RoadmapView.build(report, icons, () -> showTab(2), this::preview, () -> onGoal.accept(null),
			RoadmapView.fightCard(report, fight, () -> onAim.accept(fight), () ->
			{
				hiddenFight = fight;
				rebuildRoadmap();
			}));
		if (share != null && RoadCard.canDraw(report))
		{
			RoadmapView.shareCard(view, shareNote, this::saveCard, this::copyCard);
		}
		replace(roadmap, view);
	}

	/**
	 * The road card is drawn only when asked for, never as the road changes, and handed over once
	 * the pictures of its loadout and stops are in, so no stop is saved as an empty ring.
	 */
	private void drawCard(java.util.function.Consumer<BufferedImage> deliver)
	{
		Report drawn = report;
		String name = showName ? playerName : null;
		boolean worth = showWorth;
		long now = System.currentTimeMillis();
		CardPictures.draw(icons, pictures -> RoadCard.render(drawn, name, pictures, now, null, worth), deliver);
	}

	private void saveCard()
	{
		if (RoadCard.canDraw(report))
		{
			String file = "Road to " + report.getRoadmap().getTarget().getName().replaceAll("[\\\\/:*?\"<>|]", "") + ".png";
			drawCard(card -> share.save(card, file));
		}
	}

	private void copyCard()
	{
		if (RoadCard.canDraw(report))
		{
			drawCard(share::copy);
		}
	}

	private void rebuildLoadout()
	{
		kindHolder.setVisible(preview == null);
		replace(loadout, LoadoutView.build(report, kinds.getSelected(), preview, icons, () ->
		{
			preview = null;
			rebuildLoadout();
			showTab(0);
		}, option ->
		{
			onGoal.accept(option);
			preview = null;
			rebuildLoadout();
			showTab(0);
		}));
	}

	private void rebuildTargets()
	{
		String focused = report.getRoadmap() == null ? null : report.getRoadmap().getTarget().getName();
		replace(targets, TargetsView.build(report, filters.getSelected(), search, focused, name ->
		{
			showTab(0);
			onAim.accept(name);
		}, onShortlist, icons));
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Roadmap;
import com.codex.gearroadmap.core.Savings;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/**
 * The savings goal on the Roadmap tab: the upgrade, a bar of how far the player's coins go,
 * and when the rest should be saved at the pace Codex Ledger has seen their wealth grow.
 */
final class GoalCard
{
	private GoalCard()
	{
	}

	static Card build(Savings.View view, String target, ItemIcons icons, Runnable onClear)
	{
		Roadmap.Option o = view.getOption();
		boolean done = view.isAffordable();
		Card card = new Card(new BorderLayout(0, 5));
		card.setBorder(new EmptyBorder(7, 9, 8, 9));
		card.accent(done ? Theme.TEAL : Theme.GOLD);

		JPanel top = new JPanel(new BorderLayout(7, 0));
		top.setOpaque(false);
		JPanel badge = new JPanel(new BorderLayout());
		badge.setOpaque(false);
		badge.add(new IconBadge(o.getIcon().getId(), icons, true), BorderLayout.NORTH);
		top.add(badge, BorderLayout.WEST);
		// The button shares the caption's line, so the upgrade's name gets the card's full width.
		JPanel names = new JPanel(new BorderLayout(0, 1));
		names.setOpaque(false);
		JPanel caption = new JPanel(new BorderLayout(6, 0));
		caption.setOpaque(false);
		caption.add(Ui.label(view.isOwned() ? "SAVED FOR" : "SAVING FOR", Theme.small(), done ? Theme.TEAL : Theme.GOLD), BorderLayout.WEST);
		caption.add(new CodexButton("Clear", false, onClear), BorderLayout.EAST);
		names.add(caption, BorderLayout.NORTH);
		JLabel name = Ui.label(o.getName(), Theme.body(), Theme.TEXT);
		name.setToolTipText(o.getName());
		name.setMinimumSize(new Dimension(10, 10));
		name.setPreferredSize(new Dimension(10, name.getPreferredSize().height));
		names.add(name, BorderLayout.CENTER);
		top.add(names, BorderLayout.CENTER);
		card.add(top, BorderLayout.NORTH);

		JPanel body = new JPanel();
		body.setOpaque(false);
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		ProgressBar bar = new ProgressBar(6);
		bar.setProgress(view.getProgress(), done, false);
		bar.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		body.add(bar);

		JPanel numbers = new JPanel(new BorderLayout(4, 0));
		numbers.setOpaque(false);
		numbers.setBorder(new EmptyBorder(3, 0, 0, 0));
		String held = view.isOwned() ? "Owned" : Format.coins(Math.min(view.getCoins(), view.getCost())) + " of " + Format.coins(view.getCost());
		numbers.add(Ui.label(held, Theme.small(), done ? Theme.TEAL : Theme.TEXT), BorderLayout.WEST);
		numbers.add(Ui.label(Format.percent(view.getProgress()), Theme.small(), Theme.progressColor(view.getProgress())), BorderLayout.EAST);
		numbers.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		body.add(numbers);

		JLabel pace = Ui.wrapped(paceLine(view), Theme.small(), done ? Theme.TEAL : Theme.TEXT_MUTED, 180);
		if (view.getPerDay() != null)
		{
			pace.setToolTipText("From Codex Ledger: your net worth grew " + Format.coins(Math.max(0, view.getPerDay()))
				+ " a day on average over the last week");
		}
		pace.setBorder(new EmptyBorder(3, 0, 0, 0));
		pace.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		body.add(pace);

		String[] gain = gainLine(o, target);
		Color gainColor = gain[1] != null ? Theme.EMBER : o.getGain() <= 0 ? Theme.TEXT_FAINT : Theme.kind(o.getAfter().getResult().getKind());
		JLabel gainLabel = Ui.label(gain[0], Theme.small(), gainColor);
		gainLabel.setBorder(new EmptyBorder(3, 0, 0, 0));
		gainLabel.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		body.add(gainLabel);
		card.add(body, BorderLayout.CENTER);

		card.setToolTipText("<html><b>" + Ui.escape(o.getName()) + "</b><br>" + Format.coins(view.getCost())
			+ (o.isAmmo() ? " per 1,000" : "") + " at today's Grand Exchange price</html>");
		return card;
	}

	/** When the rest should be saved, in one plain sentence. */
	static String paceLine(Savings.View view)
	{
		if (view.isOwned())
		{
			return "You own it now. Clear this to pick your next goal.";
		}
		if (view.isAffordable())
		{
			return "Your coins cover it. Buy it whenever you like.";
		}
		String rest = Format.coins(view.getRemaining()) + " to go";
		if (!view.hasLedger())
		{
			return rest + ". Codex Ledger can tell you when.";
		}
		String worth = view.getWorth() >= view.getCost() ? " Your " + Format.coins(view.getWorth()) + " net worth covers it." : "";
		Long perDay = view.getPerDay();
		if (perDay == null)
		{
			return rest + ". Codex Ledger needs a day of history to tell when." + worth;
		}
		if (perDay <= 0)
		{
			return rest + ". Your net worth has not grown this week." + worth;
		}
		int days = view.getDays();
		String when = days < 0 ? "years away" : days <= 1 ? "about a day" : "about " + days + " days";
		return rest + ", " + when + " at +" + Format.coins(perDay) + " a day." + worth;
	}

	/** What the goal does against the aimed target; the second value is set when it is out of reach by level. */
	static String[] gainLine(Roadmap.Option o, String target)
	{
		if (o.getMissing() != null)
		{
			return new String[]{"Needs " + o.getMissing() + " to wield", o.getMissing()};
		}
		if (o.getGain() <= 0)
		{
			return new String[]{"Adds nothing against " + target, null};
		}
		return new String[]{Format.gain(o.getGain()) + " DPS against " + target + "  " + Format.share(o.getGainShare()), null};
	}
}

package com.codex.gearroadmap.ui;

import java.awt.AlphaComposite;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/** An item picture sitting in a small dark well, used at the start of list rows. */
public class IconBadge extends JComponent
{
	private final boolean owned;
	private BufferedImage image;

	public IconBadge(int itemId, ItemIcons icons, boolean owned)
	{
		this.owned = owned;
		Dimension d = new Dimension(28, 26);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
		if (icons != null && itemId > 0)
		{
			image = icons.icon(itemId, this::repaint);
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.fill(new Ellipse2D.Float(1, 1, w - 2, h - 2));
		g.setColor(Theme.alpha(owned ? Theme.GOLD : Theme.STROKE, owned ? 120 : 200));
		g.draw(new Ellipse2D.Float(1, 1, w - 2, h - 2));
		if (image != null)
		{
			int iw = Math.min(image.getWidth(), 36);
			int ih = Math.min(image.getHeight(), 32);
			double scale = Math.min((w - 2) / (double) iw, (h - 2) / (double) ih);
			int dw = (int) Math.round(iw * scale);
			int dh = (int) Math.round(ih * scale);
			if (!owned)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.45f));
			}
			g.drawImage(image, (w - dw) / 2, (h - dh) / 2, dw, dh, null);
		}
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import java.util.Collections;
import java.util.Set;
import java.util.WeakHashMap;
import java.util.function.Consumer;

/**
 * Hands a picture's "loaded" callback over only until the picture has arrived.
 *
 * <p>RuneLite runs a callback given after an item picture has loaded straight away (later, on the
 * client thread). A component that asks for its picture while painting and repaints when told it
 * loaded would then repaint forever. Once a picture is known to have arrived, no more callbacks
 * are passed on for it.
 */
public final class IconWatch
{
	private final Set<Object> arrived = Collections.synchronizedSet(Collections.newSetFromMap(new WeakHashMap<Object, Boolean>()));

	/**
	 * @param image the picture, compared by identity
	 * @param onLoaded run when it arrives; may be null
	 * @param register passes a callback to the picture, the way AsyncBufferedImage.onLoaded does
	 */
	public void watch(Object image, Runnable onLoaded, Consumer<Runnable> register)
	{
		if (image == null || arrived.contains(image))
		{
			return;
		}
		register.accept(() ->
		{
			arrived.add(image);
			if (onLoaded != null)
			{
				onLoaded.run();
			}
		});
	}

	/** True once the picture has said it arrived. */
	public boolean hasArrived(Object image)
	{
		return image != null && arrived.contains(image);
	}

	/** For tests: how many arrived pictures are remembered. */
	int size()
	{
		synchronized (arrived)
		{
			return arrived.size();
		}
	}
}

package com.codex.gearroadmap.ui;

import java.awt.image.BufferedImage;

/** Where the panel gets item pictures; the plugin answers from RuneLite's item manager. */
public interface ItemIcons
{
	/**
	 * @param onLoaded run once if the picture arrives later than this call
	 * @return the picture, possibly still blank, or null
	 */
	BufferedImage icon(int itemId, Runnable onLoaded);

	/**
	 * True when a picture this gave out is known to have arrived; a card waits for one that has not.
	 * Pictures that are never late (previews, tests) have always arrived.
	 */
	default boolean hasArrived(BufferedImage image)
	{
		return true;
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Loadout;
import com.codex.gearroadmap.core.Planner;
import com.codex.gearroadmap.core.Levels;
