import com.codex.gearroadmap.core.Roadmap;
import com.codex.gearroadmap.core.Savings;
import com.codex.gearroadmap.core.Swap;
import com.codex.gearroadmap.data.Gear;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The Loadout tab: the best setup the player owns for each kind of attack, or the one an upgrade builds. */
final class LoadoutView
{
	static final String[] KINDS = {"Best", "Melee", "Ranged", "Magic"};

	private LoadoutView()
	{
	}

	static StackPanel build(Report report, int kindIndex, Roadmap.Option preview, ItemIcons icons, Runnable clearPreview,
		Consumer<Roadmap.Option> saveFor)
	{
		StackPanel stack = new StackPanel(6, 8);
		Roadmap map = report.getRoadmap();
		if (!report.isLoggedIn() || map == null)
		{
			stack.add(report.isLoggedIn() ? Rows.note("Reading your gear...", 190)
				: Rows.empty("No gear to read yet", "Log in to see your best melee, ranged and magic loadouts from what you own."));
			return stack;
		}
		Planner.Plan plan;
		Set<Gear> fresh = new HashSet<>();
		if (preview != null)
		{
			plan = preview.getAfter();
			fresh.addAll(preview.getPieces());
			Card banner = new Card(new BorderLayout(8, 0));
			banner.accent(Theme.TEAL);
			banner.setBorder(new EmptyBorder(6, 10, 6, 10));
			JPanel text = new JPanel(new BorderLayout());
			text.setOpaque(false);
			JLabel with = Ui.label("With " + preview.getName(), Theme.body(), Theme.TEXT);
			with.setToolTipText(preview.getName());
			with.setMinimumSize(new Dimension(10, 10));
			with.setPreferredSize(new Dimension(10, with.getPreferredSize().height));
			text.add(with, BorderLayout.NORTH);
			text.add(Ui.label("New pieces glow teal", Theme.small(), Theme.TEAL), BorderLayout.SOUTH);
			banner.add(text, BorderLayout.CENTER);
			JPanel trail = new JPanel(new BorderLayout());
			trail.setOpaque(false);
			trail.add(new CodexButton("Back", false, clearPreview), BorderLayout.NORTH);
			banner.add(trail, BorderLayout.EAST);
			stack.add(banner);
			// Anything bought can be saved for; ironmen cannot buy, and earned upgrades cost nothing.
			if (!report.isIronman() && preview.getCost() > 0)
			{
				Savings.View savings = report.getSavings();
				boolean already = savings != null && savings.getOption().getName().equals(preview.getName());
				JPanel save = new JPanel(new BorderLayout(8, 0));
				save.setOpaque(false);
				save.setBorder(new EmptyBorder(0, 2, 0, 0));
				String line = already ? "This is your savings goal." : savings != null
					? "Replaces " + savings.getOption().getName() + " as your goal." : "Track your coins toward it on the Roadmap.";
				save.add(Ui.wrapped(line, Theme.small(), already ? Theme.GOLD : Theme.TEXT_MUTED, 110), BorderLayout.CENTER);
				if (!already)
				{
					JPanel holder = new JPanel(new BorderLayout());
					holder.setOpaque(false);
					holder.add(new CodexButton("Save for it", true, () -> saveFor.accept(preview)), BorderLayout.NORTH);
					save.add(holder, BorderLayout.EAST);
				}
				stack.add(save);
			}
		}
		else if (kindIndex == 0)
		{
			plan = map.getNow().best();
		}
		else
		{
			plan = map.getNow().get(Result.Kind.values()[kindIndex - 1]);
		}
		Result r = plan == null ? null : plan.getResult();
		if (r == null || r.getKind() == null || r.getDps() <= 0)
		{
			Result.Kind wanted = kindIndex == 0 ? null : Result.Kind.values()[kindIndex - 1];
			String name = map.getTarget().getName();
			stack.add(Rows.note(wanted != null && !map.getTarget().allows(wanted.name())
				? name + " can't be hurt with " + wanted.toString().toLowerCase(Locale.ROOT) + "."
				: "You own nothing that can attack " + name + " this way.", 190));
			return stack;
		}
		Color tint = Theme.kind(r.getKind());
		stack.add(new SectionHeader(r.getKind() + " vs " + map.getTarget().getName()));
		Card frame = new Card(new BorderLayout());
		frame.setBorder(new EmptyBorder(8, 6, 8, 6));
		frame.add(new GearGrid(plan.getLoadout(), fresh, tint, icons), BorderLayout.CENTER);
		stack.add(frame);

		JPanel tiles = new JPanel(new GridLayout(2, 2, 5, 5));
		tiles.setOpaque(false);
		double before = map.getNow().dps();
		tiles.add(new StatTile(Format.dps(r.getDps()), "DPS", preview != null ? Format.gain(r.getDps() - before) + " vs now" : null, tint));
		tiles.add(new StatTile(String.valueOf(r.getMaxHit()), "Max hit", "every " + r.getTicks() + " ticks", Theme.GOLD));
		tiles.add(new StatTile(Format.percent(r.getAccuracy()), "Accuracy", null, Theme.TEAL));
		tiles.add(new StatTile(Format.time(r.secondsToKill(map.getTarget())), "Kill time", map.getTarget().getHp() + " hitpoints",
			Theme.EMBER));
		stack.add(tiles);

		stack.add(Rows.check(Mark.Kind.NOTE, styleLine(r), r.getPrayer() == null ? "No prayer" : r.getPrayer(), null));
		stack.add(Rows.check(Mark.Kind.NOTE, report.getBoosts() == null ? "No boosts" : report.getBoosts(),
			pieces(plan.getLoadout()) + " pieces worn", null));
		int uptime = map.getTarget().uptime(r.getKind().name());
		if (uptime < 100)
		{
			stack.add(Rows.check(Mark.Kind.NOTE, r.getKind() + " counted at " + uptime + "%",
				map.getTarget().getName() + "'s phases keep you off", null));
		}
		Boolean slayer = report.getSlayer();
		if (slayer != null)
		{
			stack.add(Rows.check(slayer ? Mark.Kind.GOOD : Mark.Kind.NOTE, slayer ? "On task" : "Off task",
				slayer ? "Slayer helmet bonus counts" : "No slayer helmet bonus", null));
		}
		if (preview == null && kindIndex == 0)
		{
			wearing(stack, report.getSwap(), map.getTarget().getName(), icons);
		}
		if (preview == null && kindIndex == 0 && !report.getLevels().isEmpty())
		{
			// Training is an upgrade too: the next level in each skill that adds damage, in the same gear.
			stack.add(new SectionHeader("Levels that pay", "same gear"));
			boolean priced = false;
			for (Levels.Step step : report.getLevels())
			{
				// Short enough for the sidebar beside the price; a long prayer name ("Incredible Reflexes and ...") is left to the tooltip.
				String prayer = step.getPrayer() == null ? null : step.getPrayer().length() <= 13 ? step.getPrayer() : "Prayer";
				String what = (prayer != null ? prayer : step.isNewMaxHit() ? "Max hit " + step.getMaxHit() : "Accuracy")
					+ ", " + Format.fine(step.getShare()) + " DPS";
				boolean worth = step.getWorth() > 0 && !report.isIronman();
				priced |= worth;
				Card row = Rows.line(new Mark(Mark.Kind.GOOD, 14), step.getSkill() + " " + step.getTo(), what,
					worth ? Ui.label(Format.coins(step.getWorth()), Theme.small(), Theme.GOLD) : null, null);
				row.setToolTipText("<html>" + step.getSkill() + " " + step.getFrom() + " to " + step.getTo() + " adds "
					+ Format.gain(step.getGain()) + " DPS against " + Ui.escape(map.getTarget().getName()) + " in this loadout"
					+ (step.getPrayer() != null ? ", as it unlocks " + step.getPrayer() : step.isNewMaxHit() ? "" : ", as more hits land") + "."
					+ (worth ? "<br>The road ahead pays about that much for the same damage." : "") + "</html>");
				stack.add(row);
			}
			if (priced)
			{
				stack.add(Rows.note("Beside each, what the road ahead would charge in gear for the same damage.", 190));
			}
		}
		if (preview == null)
		{
			stack.add(Rows.note("Built from the " + report.getOwned() + " pieces of combat gear you own. Click any upgrade on the Roadmap to see the loadout it makes.", 190));
		}
		return stack;
	}

	/** What is worn now against this loadout: the pieces to put on, or a word that it is already worn. */
	static void wearing(StackPanel stack, Swap swap, String target, ItemIcons icons)
	{
		if (swap == null || swap.getBestDps() <= 0)
		{
			return;
		}
		if (swap.isBest())
		{
			stack.add(Rows.check(Mark.Kind.GOOD, "You're wearing it", "Your best for " + target, null));
			return;
		}
		if (swap.getChanges().isEmpty())
		{
			return;
		}
		stack.add(new SectionHeader("Put on", Format.gain(swap.gain()) + " DPS"));
		for (Swap.Change c : swap.getChanges())
		{
			Gear off = c.getOff();
			String where = c.getWhere() == Swap.Where.INVENTORY ? "In your inventory" : "In your bank";
			Card row = Rows.line(new IconBadge(c.getWear().getId(), icons, true), c.getWear().getName(),
				off == null ? where : where + ", for " + off.getName(), null, null);
			row.setToolTipText("<html>" + Ui.escape(c.getWear().getName()) + " in your " + Gear.SLOT_NAMES[c.getWear().getSlot()].toLowerCase(Locale.ROOT)
				+ " slot" + (off == null ? "" : " instead of " + Ui.escape(off.getName())) + "</html>");
			stack.add(row);
		}
		String now = swap.getWornKind() == null ? "What you're wearing can't hurt " + target + "."
			: "You're wearing " + Format.dps(swap.getWornDps()) + " DPS of " + swap.getWornKind().toString().toLowerCase(Locale.ROOT) + " against " + target + ".";
		stack.add(Rows.note(now + " The loadout above does " + Format.dps(swap.getBestDps()) + ".", 190));
	}

	private static String styleLine(Result r)
	{
		if (r.getSpell() != null)
		{
			return r.getSpell() + ", " + r.getStyle().toLowerCase(Locale.ROOT);
		}
		return r.getStyle();
	}

	private static int pieces(Loadout lo)
	{
		int n = 0;
		for (int i = 0; i < Gear.SLOTS; i++)
		{
			if (lo.get(i) != null)
			{
				n++;
			}
		}
		return n;
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A drawn verdict: a sealed check, a warning, a cross, a quiet note, or an empty dashed ring. */
public class Mark extends JComponent
{
	public enum Kind
	{
		GOOD,
		NOTE,
		WARN,
		BAD,
		NONE
	}

	private final Kind kind;
	private final int size;

	public Mark(Kind kind, int size)
	{
		this.kind = kind;
		this.size = size;
		Dimension d = new Dimension(size, size);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
	}

	public static Color color(Kind kind)
	{
		switch (kind)
		{
			case GOOD:
				return Theme.GREEN;
			case WARN:
				return Theme.EMBER;
			case BAD:
				return Theme.BLOOD;
			case NOTE:
				return Theme.GOLD;
			default:
				return Theme.TEXT_FAINT;
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, kind, 0, 0, size);
		g.dispose();
	}

	/** Draws a mark anywhere, so the overlay can use the same shapes as the panel. */
	public static void paint(Graphics2D g, Kind kind, float x, float y, int size)
	{
		float s = size - 2;
		float o = 1;
		Color c = color(kind);
		Ellipse2D circle = new Ellipse2D.Float(x + o, y + o, s, s);
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		switch (kind)
		{
			case GOOD:
			{
				g.setColor(Theme.alpha(c, 60));
				g.fill(circle);
				g.setColor(c);
				g.draw(circle);
				Path2D check = new Path2D.Float();
				check.moveTo(x + o + s * 0.28, y + o + s * 0.52);
				check.lineTo(x + o + s * 0.44, y + o + s * 0.68);
				check.lineTo(x + o + s * 0.74, y + o + s * 0.34);
				g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.draw(check);
				break;
			}
			case WARN:
			{
				Path2D tri = new Path2D.Float();
				tri.moveTo(x + o + s / 2, y + o + s * 0.04);
				tri.lineTo(x + o + s, y + o + s * 0.94);
				tri.lineTo(x + o, y + o + s * 0.94);
				tri.closePath();
				g.setColor(Theme.alpha(c, 60));
				g.fill(tri);
				g.setColor(c);
				g.draw(tri);
				g.setStroke(new BasicStroke(1.7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawLine(Math.round(x + o + s / 2), Math.round(y + o + s * 0.36f), Math.round(x + o + s / 2), Math.round(y + o + s * 0.6f));
				g.fill(new Ellipse2D.Float(x + o + s / 2 - 1.1f, y + o + s * 0.72f, 2.2f, 2.2f));
				break;
			}
			case BAD:
			{
				g.setColor(Theme.alpha(c, 70));
				g.fill(circle);
				g.setColor(c);
				g.draw(circle);
				float a = s * 0.32f;
				float m = s / 2 + o;
				g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawLine(Math.round(x + m - a), Math.round(y + m - a), Math.round(x + m + a), Math.round(y + m + a));
				g.drawLine(Math.round(x + m + a), Math.round(y + m - a), Math.round(x + m - a), Math.round(y + m + a));
				break;
			}
			case NOTE:
			{
				g.setColor(Theme.alpha(c, 40));
				g.fill(circle);
				g.setColor(Theme.alpha(c, 170));
				g.draw(circle);
				float dot = s * 0.34f;
				g.setColor(c);
				g.fill(new Ellipse2D.Float(x + o + (s - dot) / 2, y + o + (s - dot) / 2, dot, dot));
				break;
			}
			default:
			{
				g.setColor(c);
				g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1, new float[]{2f, 2f}, 0));
				g.draw(circle);
			}
		}
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tag, such as "Opens 12 more" or "Master". */
public class Pill extends JComponent
{
	private final String text;
	private final Color color;

	public Pill(String text, Color color)
	{
		this.text = text;
		this.color = color;
		setFont(Theme.small());
		setOpaque(false);
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 12, fm.getHeight() + 3);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, h, h);
		g.setColor(Theme.alpha(color, 34));
		g.fill(shape);
		g.setColor(Theme.alpha(color, 120));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(color);
		g.drawString(text, (w - fm.stringWidth(text)) / 2, (h + fm.getAscent()) / 2 - 1);
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A slim rounded bar that fills with the same ember-to-teal ramp as the rings. */
public class ProgressBar extends JComponent
{
	private final Animator animator = new Animator(this);
	private boolean complete;

	public ProgressBar(int height)
	{
		setPreferredSize(new Dimension(10, height));
		setMinimumSize(new Dimension(10, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		setOpaque(false);
	}

	public void setProgress(double progress, boolean complete, boolean animate)
	{
		this.complete = complete;
		animator.set(Math.max(0, Math.min(1, progress)), animate);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float arc = h;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(0, 0, w, h, arc, arc));
		double value = animator.get();
		if (value > 0)
		{
			float fill = (float) Math.max(h, w * value);
			if (complete)
			{
				g.setColor(Theme.GREEN);
			}
			else
			{
				g.setPaint(new GradientPaint(0, 0, Theme.progressColor(0), w, 0, Theme.progressColor(1)));
			}
			g.fill(new RoundRectangle2D.Float(0, 0, fill, h, arc, arc));
			g.setColor(Theme.alpha(java.awt.Color.WHITE, 40));
			g.drawLine(Math.round(arc / 2), 0, Math.round(fill - arc / 2), 0);
		}
		g.setColor(Theme.alpha(Theme.STROKE, 160));
		g.draw(new RoundRectangle2D.Float(0, 0, w - 1, h - 1, arc, arc));
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import javax.swing.JComponent;

/** A gilded progress ring with the percentage set in the game's bold font. */
public class ProgressRing extends JComponent
{
	private final int diameter;
	private final float thickness;
	private final Animator animator = new Animator(this);
	private String caption;
	private boolean complete;

	public ProgressRing(int diameter, float thickness)
	{
		this.diameter = diameter;
		this.thickness = thickness;
		Dimension size = new Dimension(diameter, diameter);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		setOpaque(false);
	}

	public void setProgress(double progress, boolean complete, boolean animate)
	{
		this.complete = complete;
		animator.set(Math.max(0, Math.min(1, progress)), animate);
	}

	/** A small line under the percentage, for rings large enough to hold it. */
	public void setCaption(String caption)
	{
		this.caption = caption;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		double value = animator.get();
		float inset = thickness / 2f + 1;
		float size = diameter - inset * 2;

		// Inner well: a faint radial glow tinted by progress.
		Color glow = complete ? Theme.GREEN : Theme.progressColor(value);
		float r = size / 2f;
		g.setPaint(new RadialGradientPaint(diameter / 2f, diameter / 2f, r,
			new float[]{0f, 1f}, new Color[]{Theme.alpha(glow, 40), Theme.alpha(Theme.INK_DEEP, 0)}));
		g.fill(new Ellipse2D.Float(inset, inset, size, size));

		g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.STROKE, 200));
		g.draw(new Arc2D.Float(inset, inset, size, size, 0, 360, Arc2D.OPEN));

		if (value > 0)
		{
			g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			// Draw the arc in short segments so its colour can travel from ember to teal.
			int segments = Math.max(1, (int) Math.ceil(value * 72));
			double sweep = value * 360 / segments;
			for (int i = 0; i < segments; i++)
			{
				double t = (i + 1) / (double) segments * value;
				g.setColor(complete ? Theme.GREEN : Theme.progressColor(t));
				g.draw(new Arc2D.Double(inset, inset, size, size, 90 - i * sweep, -sweep - (i < segments - 1 ? 0.6 : 0), Arc2D.OPEN));
			}
		}

		// Fine gold rim outside the track.
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 90));
		g.draw(new Ellipse2D.Float(0.5f, 0.5f, diameter - 1, diameter - 1));

		g.setFont(diameter >= 48 ? Theme.title() : Theme.small());
		String text = Math.round(value * 100) + "%";
		FontMetrics fm = g.getFontMetrics();
		if (complete)
		{
			drawCheck(g, diameter / 2f, diameter / 2f - (caption != null && diameter >= 60 ? 5 : 0), diameter * 0.16f);
			text = null;
		}
		int textY = diameter / 2 + fm.getAscent() / 2 - 2;
		if (caption != null && diameter >= 60)
		{
			textY -= 5;
		}
		if (text != null)
		{
			drawShadowed(g, text, (diameter - fm.stringWidth(text)) / 2, textY, Theme.TEXT);
		}

		if (caption != null && diameter >= 60)
		{
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			drawShadowed(g, caption, (diameter - small.stringWidth(caption)) / 2, textY + small.getAscent() + 1, Theme.TEXT_MUTED);
		}
		g.dispose();
	}

	/** A drawn check mark, since the game fonts have no glyph for one. */
	static void drawCheck(Graphics2D g, float cx, float cy, float r)
	{
		java.awt.geom.Path2D check = new java.awt.geom.Path2D.Float();
		check.moveTo(cx - r, cy);
		check.lineTo(cx - r * 0.3f, cy + r * 0.7f);
		check.lineTo(cx + r, cy - r * 0.65f);
		g.setStroke(new BasicStroke(Math.max(1.6f, r * 0.32f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.GREEN);
		g.draw(check);
	}

	static void drawShadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Fights;
import com.codex.gearroadmap.core.Loadout;
import com.codex.gearroadmap.core.Report;
import com.codex.gearroadmap.core.Result;
import com.codex.gearroadmap.core.Roadmap;
import com.codex.gearroadmap.core.Savings;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.Target;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Locale;
import java.util.Random;

/**
 * The road as a picture to share: the player's loadout today, the damage it does and what the
 * road ahead would make of it, each stop with its item and price on a winding gilt road, the
 * savings goal and how long it should take with Codex Ledger, and the buy that would save the
 * most time where Codex Session Chronicle says the player fights. Drawn at twice the panel's
 * scale on the suite's gilt page so the game's pixel fonts stay crisp.
 */
public final class RoadCard
{
	static final int WIDTH = 360;
	static final int SCALE = 2;
	/** Stops drawn; four to a row. */
	static final int STOPS = 8;
	private static final int PER_ROW = 4;
	private static final int PAD = 20;
	private static final int STOP_H = 90;
	private static final String[] ENGRAVING = {"Hd", "Cp", "Nk", "Am", "Wp", "Bd", "Sh", "Lg", "Gl", "Bt", "Rg"};
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("d MMMM yyyy", Locale.ENGLISH);

	private RoadCard()
	{
	}

	/** True when there is a road to draw: logged in with a plan made. */
	public static boolean canDraw(Report report)
	{
		return report != null && report.isLoggedIn() && report.getRoadmap() != null;
	}

	/** "Gilded Owl's road to Vorkath", or "My road to Vorkath" without the name. */
	public static String title(String player, Target target)
	{
		String who = player == null || player.isEmpty() ? "My road" : player + "'s road";
		return who + " to " + target.getName();
	}

	/** What the whole road does: "+40% DPS for 156M", "Best in slot here" when nothing is left to buy. */
	public static String verdict(Roadmap map, boolean ironman)
	{
		if (map.getPath().isEmpty())
		{
			return "Best in slot for this fight";
		}
		long total = map.getPath().get(map.getPath().size() - 1).getSpent();
		double now = map.getNow().dps();
		long share = now <= 0 ? 0 : Math.round((map.finalDps() / now - 1) * 100);
		return "+" + share + "% damage " + (ironman ? "for gear worth " : "for ") + Format.coins(total);
	}

	/** Renders the card with the coins on it; pictures still loading are left out and onLoaded runs when one arrives. */
	public static BufferedImage render(Report report, String player, ItemIcons icons, long now, Runnable onLoaded)
	{
		return render(report, player, icons, now, onLoaded, true);
	}

	/**
	 * @param worth whether the card may show what the player has: the coins at its foot and how far
	 *     they go toward the savings goal. Off, a card can be shared without telling anyone your wealth.
	 */
	public static BufferedImage render(Report report, String player, ItemIcons icons, long now, Runnable onLoaded, boolean worth)
	{
		BufferedImage scratch = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = scratch.createGraphics();
		int height = content(sg, report, player, icons, now, onLoaded, worth);
		sg.dispose();

		BufferedImage image = new BufferedImage(WIDTH * SCALE, height * SCALE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.scale(SCALE, SCALE);
		Theme.smooth(g);
		frame(g, height);
		content(g, report, player, icons, now, onLoaded, worth);
		g.dispose();
		return image;
	}

	private static void frame(Graphics2D g, int h)
	{
		int w = WIDTH;
		RoundRectangle2D page = new RoundRectangle2D.Float(0, 0, w, h, 18, 18);
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.CARD_TOP, 0.5), 0, h, Theme.INK_DEEP));
		g.fill(page);
		g.setClip(page);
		g.setPaint(new RadialGradientPaint(w / 2f, 40, w * 0.8f, new float[]{0f, 1f},
			new Color[]{Theme.alpha(Theme.GOLD, 46), Theme.alpha(Theme.GOLD, 0)}));
		g.fillRect(0, 0, w, h);
		// The same faint grain every time, so the page reads as vellum.
		Random grain = new Random(11);
		for (int i = 0; i < w * h / 26; i++)
		{
			g.setColor(Theme.alpha(grain.nextBoolean() ? Theme.GOLD_BRIGHT : Color.BLACK, 6 + grain.nextInt(8)));
			g.fillRect(grain.nextInt(w), grain.nextInt(h), 1, 1);
		}
		g.setClip(null);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 190));
		g.draw(new RoundRectangle2D.Float(4.5f, 4.5f, w - 9, h - 9, 14, 14));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 120));
		g.draw(new RoundRectangle2D.Float(8.5f, 8.5f, w - 17, h - 17, 10, 10));
		float[][] corners = {{14, 14}, {w - 14, 14}, {14, h - 14}, {w - 14, h - 14}};
		for (float[] c : corners)
		{
			diamond(g, c[0], c[1], 3.5f, Theme.GOLD);
		}
	}

	private static int content(Graphics2D g, Report report, String player, ItemIcons icons, long now, Runnable onLoaded, boolean worth)
	{
		Theme.smooth(g);
		Roadmap map = report.getRoadmap();
		Target target = map.getTarget();
		int x = PAD;
		int cw = WIDTH - PAD * 2;
		int y = PAD + 4;

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		Sigil.paint(g, x, y - 2, 13);
		g.setColor(Theme.GOLD);
		g.drawString("GEAR ROADMAP", x + 18, y + small.getAscent() - 1);
		String date = DATE.format(Instant.ofEpochMilli(now).atZone(ZoneId.systemDefault()));
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(date, x + cw - small.stringWidth(date), y + small.getAscent() - 1);
		y += small.getHeight() + 8;

		// The title as large as fits: the name and the target are what a friend reads first.
		// A long name and target take two lines at the middle size rather than shrink to body text.
		String title = title(player, target);
		Font large = Theme.title().deriveFont(Theme.title().getSize2D() * 2f);
		String[] lines = {title};
		if (g.getFontMetrics(large).stringWidth(title) > cw)
		{
			large = Theme.title().deriveFont(Theme.title().getSize2D() * 1.5f);
			int to = title.lastIndexOf(" to ");
			if (g.getFontMetrics(large).stringWidth(title) > cw && to > 0)
			{
				lines = new String[]{title.substring(0, to), title.substring(to + 1)};
			}
		}
		g.setFont(large);
		FontMetrics lm = g.getFontMetrics();
		for (String line : lines)
		{
			ProgressRing.drawShadowed(g, clip(line, lm, cw), x, y + lm.getAscent() - 4, Theme.GOLD_BRIGHT);
			y += lm.getAscent() - 2;
		}
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		ProgressRing.drawShadowed(g, clip(verdict(map, report.isIronman()), bold, cw), x, y + bold.getAscent(), Theme.TEXT);
		y += bold.getHeight();
		Result nowResult = map.getNow().best().getResult();
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_MUTED);
		String style = nowResult.getStyle() == null ? "" : ", " + nowResult.getStyle().toLowerCase(Locale.ROOT);
		String boosts = report.getBoosts() == null ? "" : ", " + report.getBoosts().toLowerCase(Locale.ROOT);
		g.drawString(clip(kindName(nowResult.getKind()) + style + boosts, small, cw), x, y + small.getAscent());
		y += small.getHeight() + 8;
		rule(g, x, y, cw);
		y += 12;

		y = dpsBand(g, map, target, x, y, cw) + 12;

		header(g, "Today's loadout", Format.dps(nowResult.getDps()) + " DPS", x, y, cw);
		y += 24;
		y = loadout(g, map.getNow().best().getLoadout(), icons, onLoaded, x, y, cw) + 12;

		List<Roadmap.Step> path = map.getPath();
		if (!path.isEmpty())
		{
			int shown = Math.min(STOPS, path.size());
			String trailing = path.size() > shown ? shown + " of " + path.size() + " stops" : path.size() + (path.size() == 1 ? " stop" : " stops");
			header(g, "The road ahead", trailing, x, y, cw);
			y += 24;
			y = road(g, path.subList(0, shown), icons, onLoaded, x, y, cw) + 8;
		}

		Savings.View savings = report.getSavings();
		if (savings != null)
		{
			y = savings(g, savings, worth, x, y, cw) + 12;
		}

		List<Fights.Pick> fights = report.getFights();
		Fights.Tally tally = report.getTally();
		if (fights != null && !fights.isEmpty() && tally != null && !tally.isEmpty())
		{
			Fights.Pick pick = fights.get(0);
			int days = Math.max(1, tally.getDays());
			header(g, "Where I fight", "last " + days + (days == 1 ? " day" : " days"), x, y, cw);
			y += 24;
			BufferedImage icon = icons == null || pick.getIcon() == null ? null : icons.icon(pick.getIcon().getId(), onLoaded);
			int tx = x;
			if (icon != null)
			{
				g.drawImage(icon, x, y - 4, null);
				tx = x + icon.getWidth() + 8;
			}
			g.setFont(Theme.body());
			FontMetrics fm = g.getFontMetrics();
			ProgressRing.drawShadowed(g, clip(pick.getName() + " would have saved " + Format.span(pick.getSeconds()), fm, x + cw - tx), tx,
				y + fm.getAscent() - 2, Theme.TEXT);
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_MUTED);
			List<String> at = pick.getWhere();
			String where = at.size() <= 1 ? String.join("", at)
				: String.join(", ", at.subList(0, at.size() - 1)) + " and " + at.get(at.size() - 1);
			g.drawString(clip(where.isEmpty() ? "over the fights I log most" : "at " + where + ", the fights I log most", small, x + cw - tx), tx,
				y + fm.getAscent() + small.getAscent());
			y += 34;
		}

		y += 2;
		rule(g, x, y, cw);
		y += 8;
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString("Codex Gear Roadmap for RuneLite", x, y + small.getAscent());
		String coins = foot(report, worth);
		g.drawString(coins, x + cw - small.stringWidth(coins), y + small.getAscent());
		y += small.getHeight();
		return y + PAD;
	}

	/** The card's foot: "441.8M in coins", "Ironman", or nothing when worth is kept off the card. */
	static String foot(Report report, boolean worth)
	{
		long coins = report.getRoadmap().getCoins();
		return report.isIronman() ? "Ironman" : !worth ? "" : coins <= 0 ? "No coins yet" : Format.coins(coins) + " in coins";
	}

	/** Damage now and at the road's end, the kill time each way and the max hit. */
	private static int dpsBand(Graphics2D g, Roadmap map, Target target, int x, int y, int cw)
	{
		Result now = map.getNow().best().getResult();
		List<Roadmap.Step> path = map.getPath();
		Result end = path.isEmpty() ? now : path.get(path.size() - 1).getOption().getAfter().getResult();
		int h = 62;
		RoundRectangle2D box = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, cw - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(box);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(box);

		int half = cw / 2;
		column(g, "NOW", Format.dps(now.getDps()), killLine(now, target), Theme.TEXT, x + 12, y);
		if (path.isEmpty())
		{
			// Nothing left to buy: the right half says so rather than repeat the same figures.
			g.setFont(Theme.body());
			FontMetrics fm = g.getFontMetrics();
			ProgressRing.drawShadowed(g, "Nothing left", x + half + 18, y + 26, Theme.GOLD_BRIGHT);
			ProgressRing.drawShadowed(g, "to buy here", x + half + 18, y + 26 + fm.getHeight(), Theme.GOLD_BRIGHT);
			return y + h;
		}
		String endLabel = end.getKind() != now.getKind() ? "ROAD'S END, " + kindName(end.getKind()).toUpperCase(Locale.ROOT) : "ROAD'S END";
		column(g, endLabel, Format.dps(end.getDps()), killLine(end, target), Theme.GOLD_BRIGHT, x + half + 18, y);
		// An arrow between the two, gilt.
		float ax = x + half - 2;
		float ay = y + 30;
		g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.GOLD);
		g.draw(new java.awt.geom.Line2D.Float(ax - 12, ay, ax + 8, ay));
		Path2D head = new Path2D.Float();
		head.moveTo(ax + 3, ay - 5);
		head.lineTo(ax + 9, ay);
		head.lineTo(ax + 3, ay + 5);
		g.draw(head);
		return y + h;
	}

	private static String killLine(Result r, Target target)
	{
		double seconds = r.secondsToKill(target);
		String kill = Double.isInfinite(seconds) || Double.isNaN(seconds) ? "no kill" : Format.time(seconds) + " a kill";
		return kill + ", max hit " + r.getMaxHit();
	}

	private static void column(Graphics2D g, String label, String dps, String detail, Color color, int x, int y)
	{
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label, x, y + 8 + small.getAscent());
		Font big = Theme.title().deriveFont(Theme.title().getSize2D() * 1.5f);
		g.setFont(big);
		FontMetrics bm = g.getFontMetrics();
		int base = y + 10 + small.getHeight() + bm.getAscent() - 6;
		ProgressRing.drawShadowed(g, dps, x, base, color);
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(" DPS", x + bm.stringWidth(dps), base);
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(clip(detail, small, 140), x, base + small.getHeight());
	}

	/** The eleven worn slots in a row, as the equipment screen keeps them. */
	private static int loadout(Graphics2D g, Loadout loadout, ItemIcons icons, Runnable onLoaded, int x, int y, int cw)
	{
		int gap = 3;
		int tile = (cw - gap * (Gear.SLOTS - 1)) / Gear.SLOTS;
		int th = tile + 4;
		for (int slot = 0; slot < Gear.SLOTS; slot++)
		{
			int tx = x + slot * (tile + gap);
			RoundRectangle2D cell = new RoundRectangle2D.Float(tx + 0.5f, y + 0.5f, tile - 1, th - 1, 6, 6);
			g.setColor(Theme.INK_DEEP);
			g.fill(cell);
			Gear piece = loadout.get(slot);
			g.setColor(piece == null ? Theme.STROKE_SOFT : Theme.alpha(Theme.GOLD_DIM, 160));
			g.draw(cell);
			if (piece == null)
			{
				// An empty slot is engraved with its name, as the equipment screen leaves its outline.
				g.setFont(Theme.small());
				FontMetrics fm = g.getFontMetrics();
				String mark = ENGRAVING[slot];
				g.setColor(Theme.alpha(Theme.TEXT_FAINT, 150));
				g.drawString(mark, tx + (tile - fm.stringWidth(mark)) / 2, y + th / 2 + fm.getAscent() / 2 - 1);
			}
			BufferedImage icon = piece == null || icons == null ? null : icons.icon(piece.getId(), onLoaded);
			if (icon != null)
			{
				fit(g, icon, tx + 1, y + 2, tile - 2, th - 4, 1f);
			}
		}
		return y + th;
	}

	/** The stops, four to a row on a serpentine road; the stretch the coins cover glows gold. */
	private static int road(Graphics2D g, List<Roadmap.Step> stops, ItemIcons icons, Runnable onLoaded, int x, int y, int cw)
	{
		int gap = 8;
		int colW = (cw - gap * (PER_ROW - 1)) / PER_ROW;
		int rows = (stops.size() + PER_ROW - 1) / PER_ROW;
		float[] cx = new float[stops.size()];
		float[] cy = new float[stops.size()];
		for (int i = 0; i < stops.size(); i++)
		{
			int row = i / PER_ROW;
			int col = row % 2 == 0 ? i % PER_ROW : PER_ROW - 1 - i % PER_ROW;
			cx[i] = x + col * (colW + gap) + colW / 2f;
			cy[i] = y + row * (STOP_H + 6) + 20;
		}
		// The road first, behind the stops: solid gold as far as the coins go, dashed beyond.
		for (int i = 1; i < stops.size(); i++)
		{
			Path2D leg = new Path2D.Float();
			leg.moveTo(cx[i - 1], cy[i - 1]);
			if (cy[i] != cy[i - 1])
			{
				// The turn at a row's end bends round the outside like a road on a hill, clear of the names.
				float side = cx[i] > x + cw / 2f ? x + cw + 16 : x - 16;
				leg.curveTo(side, cy[i - 1], side, cy[i], cx[i], cy[i]);
			}
			else
			{
				leg.lineTo(cx[i], cy[i]);
			}
			boolean lit = stops.get(i).isAffordable();
			g.setStroke(new BasicStroke(4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(Theme.alpha(Theme.INK_DEEP, 220));
			g.draw(leg);
			g.setStroke(lit ? new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND)
				: new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, new float[]{4f, 4f}, 0));
			g.setColor(lit ? Theme.GOLD : Theme.alpha(Theme.GOLD_DIM, 170));
			g.draw(leg);
		}
		for (int i = 0; i < stops.size(); i++)
		{
			stop(g, stops.get(i), i + 1, icons, onLoaded, cx[i], cy[i], colW);
		}
		return y + rows * (STOP_H + 6) - 6;
	}

	/** One stop: its item in a ring with the step number, then its name, price and the damage it adds. */
	private static void stop(Graphics2D g, Roadmap.Step step, int number, ItemIcons icons, Runnable onLoaded, float cx, float cy, int colW)
	{
		boolean lit = step.isAffordable();
		Roadmap.Option o = step.getOption();
		float r = 15;
		if (lit)
		{
			g.setColor(Theme.alpha(Theme.GOLD, 40));
			g.fill(new Ellipse2D.Float(cx - r - 4, cy - r - 4, (r + 4) * 2, (r + 4) * 2));
		}
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(cx - r, cy - r, r * 2, r * 2));
		g.setStroke(new BasicStroke(1.4f));
		g.setColor(lit ? Theme.GOLD : Theme.STROKE);
		g.draw(new Ellipse2D.Float(cx - r, cy - r, r * 2, r * 2));
		BufferedImage icon = icons == null ? null : icons.icon(o.getIcon().getId(), onLoaded);
		if (icon != null)
		{
			fit(g, icon, Math.round(cx - r + 3), Math.round(cy - r + 3), Math.round(r * 2 - 6), Math.round(r * 2 - 6), lit ? 1f : 0.65f);
		}
		// A pair's second piece sits in a small well on the other shoulder.
		Gear partner = partner(o);
		if (partner != null)
		{
			float px = cx - r + 3;
			float py = cy + r - 5;
			g.setColor(Theme.INK_DEEP);
			g.fill(new Ellipse2D.Float(px - 8, py - 8, 16, 16));
			g.setColor(lit ? Theme.GOLD : Theme.TEXT_FAINT);
			g.draw(new Ellipse2D.Float(px - 8, py - 8, 16, 16));
			BufferedImage second = icons == null ? null : icons.icon(partner.getId(), onLoaded);
			if (second != null)
			{
				fit(g, second, Math.round(px - 6), Math.round(py - 6), 12, 12, lit ? 1f : 0.65f);
			}
		}
		// The number on the ring's shoulder.
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String label = String.valueOf(number);
		float bx = cx + r - 3;
		float by = cy - r + 2;
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(bx - 6, by - 6, 12, 12));
		g.setColor(lit ? Theme.GOLD : Theme.TEXT_FAINT);
		g.draw(new Ellipse2D.Float(bx - 6, by - 6, 12, 12));
		ProgressRing.drawShadowed(g, label, Math.round(bx - small.stringWidth(label) / 2f), Math.round(by + small.getAscent() / 2f - 1),
			lit ? Theme.GOLD_BRIGHT : Theme.TEXT_MUTED);

		int left = Math.round(cx - colW / 2f);
		int ty = Math.round(cy + r + 4);
		g.setFont(Theme.small());
		// The name may take two lines, so "Dragon hunter lance" is read whole under its ring.
		// A one-line name sits on the second line, just over its price, so prices across a row stay level.
		List<String> name = nameLines(o.getName(), small, colW);
		int line = 2 - name.size();
		for (String text : name)
		{
			centred(g, text, left, colW, ty + small.getAscent() + small.getHeight() * line++, lit ? Theme.TEXT : Theme.TEXT_MUTED);
		}
		line = 2;
		String price = priceLine(o, small, colW);
		centred(g, price, left, colW, ty + small.getAscent() + small.getHeight() * line, lit ? Theme.TEAL : Theme.GOLD);
		centred(g, Format.gain(o.getGain()) + " DPS", left, colW, ty + small.getAscent() + small.getHeight() * (line + 1),
			Theme.mix(Theme.kind(o.getAfter().getResult().getKind()), Theme.TEXT_FAINT, lit ? 0 : 0.35));
	}

	/**
	 * A stop's name in at most two lines. A pair bought together ("A + B") is named by its first
	 * piece, whole; the second is drawn on the ring's shoulder and the price says it buys both,
	 * so the stop never reads like an upgrade level ("Obsidian platelegs +1").
	 */
	static List<String> nameLines(String name, FontMetrics fm, int width)
	{
		int plus = name.indexOf(" + ");
		return lines(plus < 0 ? name : name.substring(0, plus), fm, width, 2);
	}

	/** The stop's price, "9.9M", or "9.9M for both" for a pair when that fits under its ring. */
	static String priceLine(Roadmap.Option o, FontMetrics fm, int width)
	{
		String price = o.getCost() > 0 ? Format.coins(o.getCost()) : "free";
		String both = price + " for both";
		return o.getName().contains(" + ") && fm.stringWidth(both) <= width ? both : price;
	}

	/** The second piece of a pair bought together, or null for a single upgrade. */
	static Gear partner(Roadmap.Option o)
	{
		int plus = o.getName().indexOf(" + ");
		if (plus < 0)
		{
			return null;
		}
		String second = o.getName().substring(plus + 3);
		for (Gear g : o.getPieces())
		{
			if (g.getName().equals(second))
			{
				return g;
			}
		}
		return null;
	}

	private static String kindName(Result.Kind kind)
	{
		return kind == null ? "Melee" : kind.toString().substring(0, 1) + kind.toString().substring(1).toLowerCase(Locale.ROOT);
	}

	/** The savings goal as a ribbon: how far the coins go and, with Ledger, roughly how many days are left. */
	private static int savings(Graphics2D g, Savings.View v, boolean worth, int x, int y, int cw)
	{
		boolean done = v.isOwned() || v.isAffordable();
		// Without worth on the card, how far the coins go (a share, a bar, what is left) stays off it.
		String pace = done ? "" : v.getDays() > 0 ? "about " + v.getDays() + (v.getDays() == 1 ? " day" : " days") + " at my pace"
			: worth ? Format.coins(v.getRemaining()) + " to go" : "";
		boolean bar = worth || v.isOwned();
		int h = pace.isEmpty() ? (bar ? 34 : 26) : bar ? 48 : 34;
		RoundRectangle2D box = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, cw - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(box);
		g.setColor(Theme.alpha(done ? Theme.TEAL : Theme.GOLD, 140));
		g.draw(box);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String tag = v.isOwned() ? "SAVED FOR" : "SAVING FOR";
		g.setColor(done ? Theme.TEAL : Theme.GOLD);
		g.drawString(tag, x + 9, y + 7 + small.getAscent());
		String pct = v.isOwned() ? "yours" : !worth ? (v.isAffordable() ? "in reach" : "") : Math.round(v.getProgress() * 100) + "%";
		g.setColor(done ? Theme.TEAL : Theme.GOLD_BRIGHT);
		g.drawString(pct, x + cw - 9 - small.stringWidth(pct), y + 7 + small.getAscent());
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		int tx = x + 9 + small.stringWidth(tag) + 8;
		ProgressRing.drawShadowed(g, clip(v.getOption().getName(), fm, x + cw - 9 - small.stringWidth(pct) - 8 - tx), tx,
			y + 7 + small.getAscent(), Theme.TEXT);
		int by = bar ? y + 24 : y + 14;
		if (bar)
		{
			g.setColor(Theme.INK_DEEP);
			g.fill(new RoundRectangle2D.Float(x + 9, by, cw - 18, 4, 4, 4));
			g.setPaint(new GradientPaint(x + 9, 0, Theme.GOLD_DIM, x + cw - 9, 0, done ? Theme.TEAL : Theme.GOLD_BRIGHT));
			g.fill(new RoundRectangle2D.Float(x + 9, by, (float) Math.max(4, (cw - 18) * Math.min(1, v.isOwned() ? 1 : v.getProgress())), 4, 4, 4));
		}
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_MUTED);
		if (!pace.isEmpty())
		{
			g.drawString(pace, x + cw - 9 - small.stringWidth(pace), by + 6 + small.getAscent());
		}
		return y + h;
	}

	private static void fit(Graphics2D g, BufferedImage icon, int x, int y, int w, int h, float alpha)
	{
		double scale = Math.min(1, Math.min(w / (double) Math.max(1, icon.getWidth()), h / (double) Math.max(1, icon.getHeight())));
		int dw = (int) Math.round(icon.getWidth() * scale);
		int dh = (int) Math.round(icon.getHeight() * scale);
		java.awt.Composite was = g.getComposite();
		if (alpha < 1)
		{
			g.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, alpha));
		}
		g.drawImage(icon, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh, null);
		g.setComposite(was);
	}

	private static void centred(Graphics2D g, String text, int left, int width, int baseline, Color color)
	{
		ProgressRing.drawShadowed(g, text, left + (width - g.getFontMetrics().stringWidth(text)) / 2, baseline, color);
	}

	private static void header(Graphics2D g, String text, String trailing, int x, int y, int w)
	{
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int mid = y + 10;
		diamond(g, x + 3, mid, 3, Theme.GOLD);
		String label = text.toUpperCase(Locale.ROOT);
		g.setColor(Theme.GOLD);
		g.drawString(label, x + 12, mid + fm.getAscent() / 2 - 1);
		int lineFrom = x + 12 + fm.stringWidth(label) + 6;
		int lineTo = x + w - (trailing == null ? 0 : fm.stringWidth(trailing) + 6);
		if (lineTo > lineFrom)
		{
			g.setPaint(new GradientPaint(lineFrom, 0, Theme.alpha(Theme.GOLD_DIM, 160), lineTo, 0, Theme.alpha(Theme.GOLD_DIM, 0)));
			g.fillRect(lineFrom, mid, lineTo - lineFrom, 1);
		}
		if (trailing != null)
		{
			g.setColor(Theme.TEXT_MUTED);
			g.drawString(trailing, x + w - fm.stringWidth(trailing), mid + fm.getAscent() / 2 - 1);
		}
	}

	private static void rule(Graphics2D g, int x, int y, int w)
	{
		g.setStroke(new BasicStroke(1f));
		g.setPaint(new GradientPaint(x, 0, Theme.alpha(Theme.GOLD, 0), x + w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(x, y, x + w, y);
		diamond(g, x + w / 2f, y, 3, Theme.GOLD);
	}

	private static void diamond(Graphics2D g, float cx, float cy, float r, Color color)
	{
		Path2D d = new Path2D.Float();
		d.moveTo(cx, cy - r);
		d.lineTo(cx + r, cy);
		d.lineTo(cx, cy + r);
		d.lineTo(cx - r, cy);
		d.closePath();
		g.setColor(color);
		g.fill(d);
	}

	/** Text broken at spaces into at most a number of lines of that width, the last cut with an ellipsis if it runs on. */
	static List<String> lines(String text, FontMetrics fm, int width, int max)
	{
		List<String> out = new java.util.ArrayList<>();
		String rest = text == null ? "" : text.trim();
		while (!rest.isEmpty() && out.size() < max - 1 && fm.stringWidth(rest) > width)
		{
			int cut = -1;
			for (int i = rest.indexOf(' '); i > 0; i = rest.indexOf(' ', i + 1))
			{
				if (fm.stringWidth(rest.substring(0, i)) > width)
				{
					break;
				}
				cut = i;
			}
			if (cut < 0)
			{
				break;
			}
			out.add(rest.substring(0, cut));
			rest = rest.substring(cut + 1);
		}
		if (!rest.isEmpty())
		{
			out.add(clip(rest, fm, width));
		}
		return out;
	}

	static String clip(String text, FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Roadmap;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;

/**
 * The road itself: damage per second climbing against coins spent. Each upgrade is a
 * waypoint carrying its item; the stretch the player's coins already cover is lit gold,
 * the rest waits in the dusk. Coins run on a square-root scale so cheap early steps are
 * not crushed against the left edge by one expensive leap at the end.
 */
public class RoadChart extends JComponent
{
	private static final int HEIGHT = 160;
	private static final int PAD_LEFT = 8;
	private static final int PAD_RIGHT = 12;
	private static final int PAD_TOP = 32;
	private static final int PAD_BOTTOM = 22;
	private static final int NODE = 20;

	private final Roadmap map;
	private final List<BufferedImage> icons = new ArrayList<>();
	private int hover = -1;

	public RoadChart(Roadmap map, ItemIcons icons)
	{
		this.map = map;
		setPreferredSize(new Dimension(10, HEIGHT));
		setOpaque(false);
		for (Roadmap.Step step : map.getPath())
		{
			this.icons.add(icons == null ? null : icons.icon(step.getOption().getIcon().getId(), this::repaint));
		}
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = nodeAt(e.getX(), e.getY());
				if (index != hover)
				{
					hover = index;
					setToolTipText(index < 0 ? null : tooltip(map.getPath().get(index)));
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	private static String tooltip(Roadmap.Step step)
	{
		Roadmap.Option o = step.getOption();
		return "<html><b>" + Ui.escape(o.getName()) + "</b><br>" + Format.gain(o.getGain()) + " DPS for " + Format.coins(o.getCost())
			+ "<br>" + Format.coins(step.getSpent()) + " spent by here</html>";
	}

	/**
	 * Where a coin total sits across the chart. A quarter of the distance follows the square root
	 * of the coins and the rest the step count, so dear steps late on still get room apart.
	 */
	private double x(long spent, double total, int w)
	{
		List<Roadmap.Step> path = map.getPath();
		int n = path.size();
		double t = 0;
		if (total > 0 && n > 0)
		{
			long before = 0;
			for (int k = 0; k < n; k++)
			{
				long after = path.get(k).getSpent();
				if (spent <= after || k == n - 1)
				{
					double a = blend(before, k, total, n);
					double b = blend(after, k + 1, total, n);
					double span = Math.sqrt(after / total) - Math.sqrt(before / total);
					double part = span <= 0 ? 1 : (Math.sqrt(Math.min(spent, after) / total) - Math.sqrt(before / total)) / span;
					t = a + (b - a) * Math.max(0, Math.min(1, part));
					break;
				}
				before = after;
			}
		}
		return PAD_LEFT + NODE / 2.0 + t * (w - PAD_LEFT - PAD_RIGHT - NODE);
	}

	private static double blend(long spent, int step, double total, int steps)
	{
		return 0.25 * Math.sqrt(spent / total) + 0.75 * step / steps;
	}

	private double y(double dps, double low, double high, int h)
	{
		double t = high <= low ? 0 : (dps - low) / (high - low);
		return h - PAD_BOTTOM - NODE / 2.0 - t * (h - PAD_TOP - PAD_BOTTOM - NODE);
	}

	private int nodeAt(int mx, int my)
	{
		List<Roadmap.Step> path = map.getPath();
		double total = path.isEmpty() ? 0 : path.get(path.size() - 1).getSpent();
		double low = map.getNow().dps();
		double high = map.finalDps();
		for (int i = 0; i < path.size(); i++)
		{
			double nx = x(path.get(i).getSpent(), total, getWidth());
			double ny = y(path.get(i).getOption().getAfter().dps(), low, high, getHeight());
			if (Math.abs(mx - nx) <= NODE / 2.0 + 1 && Math.abs(my - ny) <= NODE / 2.0 + 1)
			{
				return i;
			}
		}
		return -1;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D frame = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.INK_DEEP));
		g.fill(frame);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(frame);

		List<Roadmap.Step> path = map.getPath();
		double now = map.getNow().dps();
		double end = map.finalDps();
		long total = path.isEmpty() ? 0 : path.get(path.size() - 1).getSpent();
		g.setClip(frame);

		// Faint contour lines, like a surveyor's map.
		g.setStroke(new BasicStroke(1f));
		for (int i = 1; i < 4; i++)
		{
			int gy = PAD_TOP + NODE / 2 + i * (h - PAD_TOP - PAD_BOTTOM - NODE) / 4;
			g.setColor(Theme.alpha(Theme.STROKE, 70));
			g.drawLine(PAD_LEFT, gy, w - PAD_RIGHT, gy);
		}

		int n = path.size();
		double[] xs = new double[n + 1];
		double[] ys = new double[n + 1];
		xs[0] = x(0, total, w);
		ys[0] = y(now, now, end, h);
		for (int i = 0; i < n; i++)
		{
			xs[i + 1] = x(path.get(i).getSpent(), total, w);
			ys[i + 1] = y(path.get(i).getOption().getAfter().dps(), now, end, h);
		}

		// Where the player's coins run out.
		double reach = map.getCoins() >= total ? xs[n] : x(map.getCoins(), total, w);
		if (n > 0)
		{
			Path2D area = smooth(xs, ys);
			area.lineTo(xs[n], h - PAD_BOTTOM + 4);
			area.lineTo(xs[0], h - PAD_BOTTOM + 4);
			area.closePath();
			g.setPaint(new GradientPaint(0, PAD_TOP, Theme.alpha(Theme.GOLD, 46), 0, h - PAD_BOTTOM, Theme.alpha(Theme.GOLD, 0)));
			g.fill(area);

			Path2D line = smooth(xs, ys);
			g.setStroke(new BasicStroke(5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(Theme.alpha(Theme.INK_DEEP, 220));
			g.draw(line);
			g.setStroke(new BasicStroke(2.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, new float[]{5f, 4f}, 0));
			g.setColor(Theme.alpha(Theme.GOLD_DIM, 170));
			g.draw(line);
			// The covered stretch is drawn solid over the dashed road.
			Graphics2D lit = (Graphics2D) g.create();
			lit.clipRect(0, 0, (int) Math.ceil(reach), h);
			lit.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			lit.setPaint(new GradientPaint((float) xs[0], 0, Theme.GOLD, (float) Math.max(xs[0] + 1, reach), 0, Theme.GOLD_BRIGHT));
			lit.draw(line);
			lit.dispose();

			if (map.getCoins() > 0 && map.getCoins() < total)
			{
				g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 1f, new float[]{2f, 3f}, 0));
				g.setColor(Theme.alpha(Theme.TEAL, 170));
				g.drawLine((int) reach, PAD_TOP - 6, (int) reach, h - PAD_BOTTOM + 2);
				g.setFont(Theme.small());
				FontMetrics fm = g.getFontMetrics();
				String label = "Your coins";
				int lx = (int) Math.min(w - PAD_RIGHT - fm.stringWidth(label), Math.max(PAD_LEFT, reach - fm.stringWidth(label) / 2.0));
				ProgressRing.drawShadowed(g, label, lx, h - 6, Theme.TEAL);
			}
		}

		// The start: where the player stands today.
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Double(xs[0] - 5, ys[0] - 5, 10, 10));
		g.setColor(Theme.GOLD);
		g.setStroke(new BasicStroke(1.6f));
		g.draw(new Ellipse2D.Double(xs[0] - 4, ys[0] - 4, 8, 8));

		for (int i = 0; i < n; i++)
		{
			drawNode(g, xs[i + 1], ys[i + 1], i, path.get(i).isAffordable());
		}
		// Step numbers go on after every node, so a crowded stretch late on never hides one under its neighbour.
		for (int i = 0; i < n; i++)
		{
			drawBadge(g, xs[i + 1], ys[i + 1], i, path.get(i).isAffordable());
		}

		g.setClip(null);
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		boolean coinsLabel = map.getCoins() > 0 && map.getCoins() < total;
		if (!coinsLabel || reach > PAD_LEFT + 90)
		{
			ProgressRing.drawShadowed(g, Format.dps(now) + " now", PAD_LEFT + 2, h - 6, Theme.TEXT_MUTED);
		}
		String title = "THE ROAD AHEAD";
		int room = w - PAD_RIGHT - (PAD_LEFT + 2 + fm.stringWidth(title) + 8);
		String top = n == 0 ? "Nothing left to buy" : top(Format.dps(end), Format.coins(total), fm, room);
		ProgressRing.drawShadowed(g, top, w - PAD_RIGHT - fm.stringWidth(top), 15, n == 0 ? Theme.TEXT_MUTED : Theme.GOLD_BRIGHT);
		ProgressRing.drawShadowed(g, title, PAD_LEFT + 2, 15, Theme.GOLD);
		g.dispose();
	}

	/**
	 * The figures beside the chart's title, "6.93 DPS  ·  156.3M", closed up and then without the
	 * cost (which the list below adds up) when the room beside the title is short, so they never run
	 * into it.
	 */
	static String top(String dps, String cost, FontMetrics fm, int room)
	{
		String[] tries = {dps + " DPS  ·  " + cost, dps + " DPS · " + cost, dps + " DPS"};
		for (String t : tries)
		{
			if (fm.stringWidth(t) <= room)
			{
				return t;
			}
		}
		return tries[tries.length - 1];
	}

	private void drawNode(Graphics2D g, double cx, double cy, int index, boolean affordable)
	{
		float r = NODE / 2f;
		boolean lit = hover == index;
		Color rim = affordable ? Theme.GOLD : Theme.STROKE;
		g.setColor(Theme.alpha(Theme.INK_DEEP, 235));
		g.fill(new Ellipse2D.Double(cx - r, cy - r, NODE, NODE));
		if (affordable || lit)
		{
			g.setColor(Theme.alpha(lit ? Theme.GOLD_BRIGHT : Theme.GOLD, lit ? 70 : 38));
			g.fill(new Ellipse2D.Double(cx - r - 3, cy - r - 3, NODE + 6, NODE + 6));
		}
		g.setStroke(new BasicStroke(1.4f));
		g.setColor(lit ? Theme.GOLD_BRIGHT : rim);
		g.draw(new Ellipse2D.Double(cx - r, cy - r, NODE, NODE));
		BufferedImage image = icons.get(index);
		if (image != null)
		{
			double scale = Math.min((NODE - 4) / (double) Math.max(1, image.getWidth()), (NODE - 4) / (double) Math.max(1, image.getHeight()));
			int dw = (int) Math.round(image.getWidth() * scale);
			int dh = (int) Math.round(image.getHeight() * scale);
			Composite old = g.getComposite();
			if (!affordable && !lit)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.6f));
			}
			g.drawImage(image, (int) Math.round(cx - dw / 2.0), (int) Math.round(cy - dh / 2.0), dw, dh, null);
			g.setComposite(old);
		}
	}

	/** The step number on the node's shoulder. */
	private void drawBadge(Graphics2D g, double cx, double cy, int index, boolean affordable)
	{
		float r = NODE / 2f;
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		String label = String.valueOf(index + 1);
		float bx = (float) (cx + r - 4);
		float by = (float) (cy - r - 3);
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(bx - 5, by - 5, 10, 10));
		g.setColor(affordable ? Theme.GOLD : Theme.TEXT_FAINT);
		g.draw(new Ellipse2D.Float(bx - 5, by - 5, 10, 10));
		ProgressRing.drawShadowed(g, label, Math.round(bx - fm.stringWidth(label) / 2f), Math.round(by + fm.getAscent() / 2f - 1),
			affordable ? Theme.GOLD_BRIGHT : Theme.TEXT_MUTED);
	}

	/** A gently curving road through the waypoints. */
	private static Path2D smooth(double[] xs, double[] ys)
	{
		Path2D path = new Path2D.Double();
		path.moveTo(xs[0], ys[0]);
		for (int i = 1; i < xs.length; i++)
		{
			double mid = (xs[i - 1] + xs[i]) / 2;
			path.curveTo(mid, ys[i - 1], mid, ys[i], xs[i], ys[i]);
		}
		return path;
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Claims;
import com.codex.gearroadmap.core.Outgrown;
import com.codex.gearroadmap.core.Report;
import com.codex.gearroadmap.core.Result;
import com.codex.gearroadmap.core.Roadmap;
import com.codex.gearroadmap.core.Savings;
import com.codex.gearroadmap.data.Gear;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;
import javax.swing.Box;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The Roadmap tab: the target, the road chart, the steps in order, then free, locked and big upgrades. */
final class RoadmapView
{
	private RoadmapView()
	{
	}

	static StackPanel build(Report report, ItemIcons icons, Runnable openTargets, Consumer<Roadmap.Option> preview, Runnable clearGoal)
	{
		return build(report, icons, openTargets, preview, clearGoal, null);
	}

	/**
	 * @param fight the offer to aim at the monster being fought, put under the target card; null for none
	 */
	static StackPanel build(Report report, ItemIcons icons, Runnable openTargets, Consumer<Roadmap.Option> preview, Runnable clearGoal,
		JComponent fight)
	{
		StackPanel stack = new StackPanel(5, 8);
		Roadmap map = report.getRoadmap();
		if (!report.isLoggedIn())
		{
			stack.add(Rows.empty("Your road starts at login", "Log in and Gear Roadmap reads the gear you own and your levels, "
				+ "then lays out the upgrades that speed up your kills the most for every coin."));
			return stack;
		}
		if (map == null)
		{
			stack.add(Rows.note("Reading your gear...", 190));
			return stack;
		}
		stack.add(targetCard(report, openTargets));
		if (fight != null)
		{
			stack.add(fight);
		}
		if (!report.isBankSeen())
		{
			stack.add(Rows.reason(com.codex.gearroadmap.ui.Mark.Kind.NOTE,
				"Open your bank once so the roadmap knows all the gear you own, not just what you carry."));
		}
		Savings.View savings = report.getSavings();
		if (savings != null)
		{
			stack.add(GoalCard.build(savings, map.getTarget().getName(), icons, clearGoal));
		}
		stack.add(new RoadChart(map, icons));

		Result.Kind kind = map.getNow().best().getResult().getKind();
		if (map.getPath().isEmpty())
		{
			stack.add(Rows.note("Nothing on the Grand Exchange would make you faster here. You have the best gear for this target.", 190));
		}
		else
		{
			stack.add(new SectionHeader("Next upgrades", "most DPS per coin"));
			int rank = 0;
			for (Roadmap.Step step : map.getPath())
			{
				Roadmap.Option o = step.getOption();
				rank++;
				stack.add(goal(UpgradeRow.build(o, UpgradeRow.Mode.STEP, rank, step.isAffordable(), kind, icons, map.getTarget(),
					() -> preview.accept(o)), o, savings));
				kind = o.getAfter().getResult().getKind();
			}
		}
		Result.Kind now = map.getNow().best().getResult().getKind();
		if (!map.getFree().isEmpty())
		{
			stack.add(new SectionHeader("Free upgrades", "earned, not bought"));
			for (Roadmap.Option o : map.getFree())
			{
				stack.add(UpgradeRow.build(o, UpgradeRow.Mode.FREE, 0, true, now, icons, map.getTarget(), () -> preview.accept(o)));
			}
		}
		if (!map.getLeaps().isEmpty())
		{
			stack.add(new SectionHeader("Big leaps", "most DPS"));
			for (Roadmap.Option o : map.getLeaps())
			{
				stack.add(goal(UpgradeRow.build(o, UpgradeRow.Mode.LEAP, 0, o.getCost() <= map.getCoins(), now, icons, map.getTarget(),
					() -> preview.accept(o)), o, savings));
			}
		}
		if (!map.getLocked().isEmpty())
		{
			stack.add(new SectionHeader("Unlock by training"));
			for (Roadmap.Option o : map.getLocked())
			{
				stack.add(goal(UpgradeRow.build(o, UpgradeRow.Mode.LOCKED, 0, false, now, icons, map.getTarget(),
					() -> preview.accept(o)), o, savings));
			}
		}
		outgrown(stack, report.getOutgrown(), map, icons);
		roadBehind(stack, report.getClaims(), icons);
		stack.add(Rows.note(footnote(report), 190));
		return stack;
	}

	/** The road as a picture to share: two buttons above the tab's footnote, and a line once one is used. */
	static void shareCard(StackPanel stack, String note, Runnable save, Runnable copy)
	{
		// The footnote on what the numbers assume stays the last thing on the tab.
		int at = Math.max(0, stack.getComponentCount() - 1);
		stack.add(new SectionHeader("Share your road"), at++);
		Card card = new Card(new BorderLayout(0, 6));
		card.setBorder(new EmptyBorder(8, 10, 8, 10));
		card.add(Ui.wrapped("Your loadout, the road ahead and your goal on a gilt card, ready to post.", Theme.small(), Theme.TEXT_MUTED, 176),
			BorderLayout.NORTH);
		JPanel buttons = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.LEFT, 0, 0));
		buttons.setOpaque(false);
		buttons.add(new CodexButton("Save card", true, save));
		buttons.add(javax.swing.Box.createHorizontalStrut(6));
		buttons.add(new CodexButton("Copy", false, copy));
		card.add(buttons, BorderLayout.CENTER);
		if (note != null)
		{
			card.add(Ui.wrapped(note, Theme.small(), Theme.TEAL, 176), BorderLayout.SOUTH);
		}
		stack.add(card, at);
	}

	/** Claims listed on the tab; the save keeps a few more. */
	static final int BEHIND = 5;
	private static final java.time.format.DateTimeFormatter DAY = java.time.format.DateTimeFormatter.ofPattern("d MMM", java.util.Locale.ENGLISH);

	/** The road behind: the upgrades picked up from the road, newest first, with what each added and when. */
	static void roadBehind(StackPanel stack, List<Claims.Claim> claims, ItemIcons icons)
	{
		if (claims == null || claims.isEmpty())
		{
			return;
		}
		stack.add(new SectionHeader("Road behind", claims.size() + " claimed"));
		for (int i = 0; i < claims.size() && i < BEHIND; i++)
		{
			Claims.Claim c = claims.get(i);
			Card row = Rows.line(new IconBadge(c.getIcon(), icons, true), firstPiece(c.getName()), behindDetail(c),
				Ui.label(claimDay(c.getAt()), Theme.small(), Theme.TEXT_MUTED), i == 0 ? Theme.GOLD : null, 118);
			row.setToolTipText("<html>" + Ui.escape(c.getName()) + "<br>Picked up " + Ui.escape(claimDay(c.getAt()))
				+ ", adding " + Format.gain(c.getGain()) + " DPS against " + Ui.escape(c.getTarget()) + " at the time.</html>");
			stack.add(row);
		}
	}

	/** "+0.81 DPS at Vorkath", or "Pair, +0.23 DPS at Vorkath" for two pieces bought together. */
	static String behindDetail(Claims.Claim c)
	{
		return (c.getName().contains(" + ") ? "Pair, " : "") + Format.gain(c.getGain()) + " DPS at " + c.getTarget();
	}

	/** A pair bought together ("A + B") is listed by its first piece; the tooltip names both. */
	static String firstPiece(String name)
	{
		int plus = name.indexOf(" + ");
		return plus < 0 ? name : name.substring(0, plus);
	}

	private static String claimDay(long at)
	{
		return DAY.format(java.time.Instant.ofEpochMilli(at).atZone(java.time.ZoneId.systemDefault()));
	}

	/** Owned gear no best loadout wears, and what selling it puts toward the road. */
	static void outgrown(StackPanel stack, Outgrown outgrown, Roadmap map, ItemIcons icons)
	{
		if (outgrown == null || outgrown.isEmpty())
		{
			return;
		}
		stack.add(new SectionHeader("Outgrown", Format.coins(outgrown.getWorth())));
		int shown = 0;
		for (Outgrown.Piece p : outgrown.getPieces())
		{
			if (shown++ == Outgrown.SHOWN)
			{
				break;
			}
			Card row = Rows.line(new IconBadge(p.getGear().getId(), icons, true), p.getGear().getName(),
				Gear.SLOT_NAMES[p.getGear().getSlot()], Ui.label(Format.coins(p.getPrice()), Theme.small(), Theme.GOLD), null);
			row.setToolTipText("<html>" + Ui.escape(p.getGear().getName()) + " is in none of your best loadouts,<br>for any kind of attack against any target.</html>");
			stack.add(row);
		}
		int more = outgrown.getPieces().size() - Outgrown.SHOWN;
		StringBuilder text = new StringBuilder("None of your best loadouts, for any style against any target, wear ")
			.append(outgrown.getPieces().size() == 1 ? "this" : "these")
			.append(more > 0 ? " or " + more + " more" : "").append(".");
		if (!map.getPath().isEmpty())
		{
			Roadmap.Option next = map.getPath().get(0).getOption();
			long cost = next.getCost();
			long share = cost <= 0 ? 0 : outgrown.getWorth() * 100 / cost;
			if (share >= 1)
			{
				text.append(outgrown.getWorth() >= cost ? " Selling them would pay for " + next.getName() + "."
					: " Selling them would pay " + share + "% of " + next.getName() + ".");
			}
		}
		text.append(" Gear kept for its effect (dragonfire shields, slayer and tank gear), skilling tools and untradeables are never listed.");
		stack.add(Rows.note(text.toString(), 190));
	}

	/** The upgrade the player is saving for wears a gilt rim wherever it appears. */
	private static Card goal(Card row, Roadmap.Option o, Savings.View savings)
	{
		if (savings != null && savings.getOption().getName().equals(o.getName()))
		{
			row.highlighted(true);
			row.setToolTipText(row.getToolTipText().replace("</html>", "<br>Your savings goal</html>"));
		}
		return row;
	}

	/** What the numbers assume, in a sentence or three. */
	static String footnote(Report report)
	{
		StringBuilder text = new StringBuilder();
		if (report.isIronman())
		{
			text.append("As an ironman you cannot buy, so Grand Exchange prices here stand for how hard each item is to get. ");
		}
		else if (report.isSeasonal())
		{
			text.append("Prices are from the main game's Grand Exchange, not this world's. ");
		}
		else
		{
			text.append("Prices are live Grand Exchange prices. ");
		}
		text.append("Ammunition is priced per 1,000. Assumes ")
			.append(report.getBoosts() == null ? "no boosts" : report.getBoosts().toLowerCase(Locale.ROOT))
			.append(" and your best unlocked prayers.");
		Boolean slayer = report.getSlayer();
		if (report.getSavings() == null && !report.isIronman() && report.getRoadmap() != null && !report.getRoadmap().getPath().isEmpty())
		{
			text.append(" Click an upgrade and press Save for it to make it your savings goal.");
		}
		if (slayer != null)
		{
			String name = report.getRoadmap() == null ? "this target" : report.getRoadmap().getTarget().getName();
			text.append(slayer ? " Counts the slayer helmet bonus against " + name + "."
				: " No slayer helmet bonus against " + name + " without a task for it.");
		}
		return text.toString();
	}

	/**
	 * The monster the player is fighting, when it is a listed target the road is not aimed at: what
	 * their best gear does there, and a button to aim the road at it.
	 *
	 * @return the card, or null when there is nothing to offer
	 */
	static Card fightCard(Report report, String fighting, Runnable aim, Runnable hide)
	{
		Roadmap map = report.getRoadmap();
		if (fighting == null || map == null || !report.isLoggedIn() || report.getSurvey() == null || fighting.equals(map.getTarget().getName()))
		{
			return null;
		}
		String here = null;
		for (Roadmap.Survey row : report.getSurvey())
		{
			if (row.getTarget().getName().equals(fighting))
			{
				Result r = row.getBest().best().getResult();
				here = r.getKind() == null ? "Nothing you own can hurt it" : "Your best here: " + Format.dps(r.getDps()) + " DPS, " + r.getKind().toString().toLowerCase(Locale.ROOT);
				break;
			}
		}
		Card card = new Card(new BorderLayout(0, 4));
		card.setBorder(new EmptyBorder(6, 10, 7, 10));
		card.accent(Theme.TEAL);
		JLabel title = Ui.label("Fighting " + fighting, Theme.body(), Theme.TEXT);
		title.setMinimumSize(new Dimension(10, 10));
		title.setPreferredSize(new Dimension(10, title.getPreferredSize().height));
		card.add(title, BorderLayout.NORTH);
		if (here != null)
		{
			card.add(Ui.label(here, Theme.small(), Theme.TEXT_MUTED), BorderLayout.CENTER);
		}
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		buttons.setOpaque(false);
		buttons.add(new CodexButton("Aim the road here", true, aim));
		buttons.add(Box.createHorizontalStrut(6));
		buttons.add(new CodexButton("Hide", false, hide));
		card.add(buttons, BorderLayout.SOUTH);
		card.setToolTipText("<html>You are fighting " + Ui.escape(fighting) + ", but the road is aimed at " + Ui.escape(map.getTarget().getName())
			+ ".<br>The road never moves on its own: aim it here if this is the fight you want gear for.</html>");
		return card;
	}

	private static Card targetCard(Report report, Runnable openTargets)
	{
		Roadmap map = report.getRoadmap();
		Result r = map.getNow().best().getResult();
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(7, 10, 7, 10));
		card.accent(Theme.kind(r.getKind()));
		// The name shares its line with the button; the fight's numbers get the full width below.
		JPanel top = new JPanel(new BorderLayout(6, 0));
		top.setOpaque(false);
		JLabel name = Ui.label(map.getTarget().getName(), Theme.title(), Theme.GOLD_BRIGHT);
		name.setMinimumSize(new Dimension(10, 10));
		name.setPreferredSize(new Dimension(10, name.getPreferredSize().height));
		top.add(name, BorderLayout.CENTER);
		top.add(new CodexButton("Change", false, openTargets), BorderLayout.EAST);
		card.add(top, BorderLayout.NORTH);
		String line = r.getKind() == null ? "No way to hurt it yet"
			: r.getKind() + "  ·  max hit " + r.getMaxHit() + "  ·  " + Format.percent(r.getAccuracy()) + " acc";
		JLabel sub = Ui.label(line, Theme.small(), Theme.TEXT_MUTED);
		sub.setBorder(new EmptyBorder(3, 0, 0, 0));
		sub.setToolTipText(r.getKind() == null ? null : "Your best setup hits up to " + r.getMaxHit() + " and lands "
			+ Format.percent(r.getAccuracy()) + " of its attacks");
		JPanel lines = new JPanel(new BorderLayout());
		lines.setOpaque(false);
		lines.add(sub, BorderLayout.NORTH);
		if (report.isFollowingTask())
		{
			JLabel task = Ui.label(report.getTaskName() == null ? "On your slayer task" : "On task: " + Format.task(report.getTaskName()),
				Theme.small(), Theme.TEAL);
			task.setBorder(new EmptyBorder(2, 0, 0, 0));
			task.setToolTipText("The roadmap follows your slayer task. Pick a target the task does not cover to aim elsewhere until your next task");
			lines.add(task, BorderLayout.SOUTH);
		}
		card.add(lines, BorderLayout.SOUTH);
		return card;
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Compact card lines: a verdict mark, a name, a quiet second line and an optional value. */
public final class Rows
{
	private Rows()
	{
	}

	public static Card check(Mark.Kind kind, String title, String detail, String value)
	{
		return line(new Mark(kind, 14), title, detail, value == null ? null : Ui.label(value, Theme.small(), Mark.color(kind)),
			kind == Mark.Kind.BAD ? Theme.BLOOD : null);
	}

	/** A verdict with a sentence that may run to two lines. */
	public static Card reason(Mark.Kind kind, String text)
	{
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (kind == Mark.Kind.BAD)
		{
			card.accent(Theme.BLOOD);
		}
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.setBorder(new EmptyBorder(1, 0, 0, 0));
		holder.add(new Mark(kind, 14), BorderLayout.NORTH);
		card.add(holder, BorderLayout.WEST);
		card.add(Ui.wrapped(text, Theme.body(), Theme.TEXT, 160), BorderLayout.CENTER);
		return card;
	}

	public static Card line(JComponent lead, String title, String detail, JComponent trailing, Color accent)
	{
		return line(lead, title, detail, trailing, accent, 0);
	}

	/** @param wrap above 0, the width the detail wraps at instead of being cut short */
	public static Card line(JComponent lead, String title, String detail, JComponent trailing, Color accent, int wrap)
	{
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (accent != null)
		{
			card.accent(accent);
		}
		if (lead != null)
		{
			JPanel holder = new JPanel(new BorderLayout());
			holder.setOpaque(false);
			holder.setBorder(new EmptyBorder(1, 0, 0, 0));
			holder.add(lead, BorderLayout.NORTH);
			card.add(holder, BorderLayout.WEST);
		}
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		JLabel name = Ui.label(title, Theme.body(), Theme.TEXT);
		name.setToolTipText(title);
		text.add(name);
		if (detail != null && !detail.isEmpty())
		{
			JLabel sub = wrap > 0 ? Ui.wrapped(detail, Theme.small(), Theme.TEXT_MUTED, wrap) : Ui.label(detail, Theme.small(), Theme.TEXT_MUTED);
			sub.setToolTipText(detail);
			text.add(sub);
		}
		// Long names clip with an ellipsis rather than push the value off the card.
		text.setMinimumSize(new Dimension(10, 10));
		text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
		card.add(text, BorderLayout.CENTER);
		if (trailing != null)
		{
			JPanel holder = new JPanel(new BorderLayout());
			holder.setOpaque(false);
			holder.add(trailing, BorderLayout.NORTH);
			card.add(holder, BorderLayout.EAST);
		}
		return card;
	}

	/** An empty state as a card: what is missing in gold, and what to do about it beneath. */
	public static Card empty(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 3));
		card.setBorder(new EmptyBorder(8, 10, 9, 10));
		card.add(Ui.label(title, Theme.body(), Theme.GOLD_BRIGHT), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, 176), BorderLayout.CENTER);
		return card;
	}

	/** A quiet line of text for empty states. */
	public static JComponent note(String text, int width)
	{
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.setBorder(new EmptyBorder(2, 4, 2, 4));
		holder.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_FAINT, width), BorderLayout.CENTER);
		return holder;
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.util.function.Consumer;
import javax.swing.JTextField;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/** An inked search line with a small lens, matching the rest of the panel. */
class SearchField extends JTextField
{
	private final String hint;

	SearchField(String hint, Consumer<String> onChange)
	{
		this.hint = hint;
		setOpaque(false);
		setFont(Theme.body());
		setForeground(Theme.TEXT);
		setCaretColor(Theme.GOLD_BRIGHT);
		setSelectionColor(Theme.alpha(Theme.GOLD, 90));
		setBorder(new EmptyBorder(4, 24, 4, 8));
		setPreferredSize(new Dimension(10, 26));
		getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				onChange.accept(getText());
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				onChange.accept(getText());
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				onChange.accept(getText());
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(shape);
		g.setColor(isFocusOwner() ? Theme.alpha(Theme.GOLD, 150) : Theme.STROKE_SOFT);
		g.draw(shape);
		g.setStroke(new BasicStroke(1.4f));
		g.setColor(Theme.GOLD_DIM);
		g.draw(new Ellipse2D.Float(8, h / 2f - 5, 8, 8));
		g.drawLine(15, h / 2 + 2, 18, h / 2 + 5);
		if (getText().isEmpty() && !isFocusOwner())
		{
			g.setFont(getFont());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(hint, 24, (h + g.getFontMetrics().getAscent()) / 2 - 2);
		}
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.util.Locale;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase(Locale.ROOT);
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int h = getHeight();
		int mid = h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(4, mid - 4);
		diamond.lineTo(8, mid);
		diamond.lineTo(4, mid + 4);
		diamond.lineTo(0, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		int textX = 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = getWidth();
		if (trailing != null)
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = getWidth() - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, getWidth() - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			ProgressRing.drawShadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

