/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(Theme.RADIUS, 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(Locale.ROOT), 8, 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		ProgressRing.drawShadowed(g, value, 8, 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null)
		{
			g.setFont(Theme.small());
			String clipped = note;
			while (clipped.length() > 1 && small.stringWidth(clipped) > w - 16)
			{
				clipped = clipped.substring(0, clipped.length() - 2) + "…";
			}
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(clipped, 8, h - 6);
		}
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Advisor;
import com.codex.gearroadmap.core.Fights;
import com.codex.gearroadmap.core.Report;
import com.codex.gearroadmap.core.Result;
import com.codex.gearroadmap.core.Roadmap;
import com.codex.gearroadmap.data.Target;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.border.EmptyBorder;

/**
 * The Targets tab: every target with the best the player can do there now; clicking one aims the
 * roadmap at it, and right-clicking one puts it on the shortlist the upgrades are weighed across.
 */
final class TargetsView
{
	static final String[] FILTERS = {"All", "Bosses", "Slayer", "Training"};

	private TargetsView()
	{
	}

	static StackPanel build(Report report, int filter, String search, String focused, Consumer<String> onPick,
		Consumer<String> onShortlist, ItemIcons icons)
	{
		TargetRows rows = new TargetRows(report, focused, onPick, onShortlist);
		StackPanel stack = new StackPanel(4, 8);
		if (!report.isLoggedIn())
		{
			stack.add(Rows.empty("Over 70 targets wait", "Log in to see your damage and kill time against every boss, slayer monster and training spot."));
			return stack;
		}
		if (report.getSurvey().isEmpty())
		{
			stack.add(Rows.note("Weighing your gear against every target...", 190));
			return stack;
		}
		String needle = search == null ? "" : search.trim().toLowerCase(Locale.ROOT);
		boolean listed = needle.isEmpty() && filter == 0 && shortlist(stack, report, icons, rows);
		boolean fought = needle.isEmpty() && filter == 0 && fights(stack, report, icons);
		List<String> task = report.getTaskTargets();
		if (!task.isEmpty() && needle.isEmpty() && filter == 0)
		{
			// The task's monsters first, so aiming at what the task covers is one click away.
			stack.add(new SectionHeader("Slayer task", report.getTaskName() == null ? null : Format.task(report.getTaskName())));
			for (String name : task)
			{
				for (Roadmap.Survey row : report.getSurvey())
				{
					if (row.getTarget().getName().equals(name))
					{
						stack.add(rows.row(row));
					}
				}
			}
			stack.add(new SectionHeader("All targets"));
		}
		else if (fought || listed)
		{
			stack.add(new SectionHeader("All targets"));
		}
		int shown = 0;
		for (Roadmap.Survey row : report.getSurvey())
		{
			Target t = row.getTarget();
			if (!matches(t, filter) || !needle.isEmpty() && !t.getName().toLowerCase(Locale.ROOT).contains(needle))
			{
				continue;
			}
			stack.add(rows.row(row));
			shown++;
		}
		if (shown == 0)
		{
			stack.add(Rows.note("No targets match.", 190));
		}
		return stack;
	}

	/**
	 * The targets the player shortlisted, such as the bosses left to finish, and the upgrades that
	 * save the most fighting time across all of them. Shown only once something is shortlisted.
	 */
	static boolean shortlist(StackPanel stack, Report report, ItemIcons icons, TargetRows rows)
	{
		List<String> names = report.getShortlist();
		if (names.isEmpty())
		{
			return false;
		}
		stack.add(new SectionHeader("Your shortlist", names.size() == 1 ? "1 target" : names.size() + " targets"));
		JComponent note = Rows.note("Upgrades weighed over " + Advisor.SHORTLIST_KILLS + " kills of each. Most time saved for the coins first.", 190);
		note.setToolTipText("<html>Right-click any target to add it to the shortlist or take it off.<br>"
			+ "Useful for the bosses left on your collection log, or the stops on a long grind.</html>");
		stack.add(note);
		for (String name : names)
		{
			for (Roadmap.Survey row : report.getSurvey())
			{
				if (row.getTarget().getName().equals(name))
				{
					stack.add(rows.row(row));
				}
			}
		}
		List<Fights.Pick> picks = report.getShortlistPicks();
		if (picks.isEmpty())
		{
			stack.add(Rows.note(report.isIronman() ? "Ironmen are shown the roadmap for each target instead."
				: "Nothing you could buy now would save much time across these.", 190));
			return true;
		}
		String span = Advisor.SHORTLIST_KILLS + " kills of each";
		for (Fights.Pick p : picks)
		{
			stack.add(pick(p, icons, span));
		}
		return true;
	}

	/** Where the player really fights, from Session Chronicle, and the upgrades that save the most time there. */
	static boolean fights(StackPanel stack, Report report, ItemIcons icons)
	{
		Fights.Tally tally = report.getTally();
		if (tally == null || tally.isEmpty())
		{
			return false;
		}
		String span = tally.getDays() == 1 ? "the last day" : "the last " + tally.getDays() + " days";
		stack.add(new SectionHeader("Where you fight", span.substring(4)));
		StringBuilder line = new StringBuilder("Kills from Session Chronicle: ");
		int shown = 0;
		for (Map.Entry<Target, Integer> e : tally.getKills().entrySet())
		{
			if (shown == 3)
			{
				line.append(", and more");
				break;
			}
			line.append(shown == 0 ? "" : ", ").append(e.getKey().getName()).append(' ')
				.append(String.format(Locale.ENGLISH, "%,d", e.getValue()));
			shown++;
		}
		JComponent note = Rows.note(line.append(". Most time saved for the coins first.").toString(), 190);
		note.setToolTipText("<html>Each kill is weighed as it was fought: on a slayer task that covered it with the<br>"
			+ "slayer helmet's bonus, off one without. Kills logged before Chronicle kept the task<br>"
			+ "count Slayer creatures as on task and bosses as off.</html>");
		stack.add(note);
		List<Fights.Pick> picks = report.getFights();
		if (picks.isEmpty())
		{
			stack.add(Rows.note(report.isIronman() ? "Ironmen are shown the roadmap for each target instead."
				: "Nothing you could buy now would have saved you much time there.", 190));
			return true;
		}
		for (Fights.Pick p : picks)
		{
			stack.add(pick(p, icons, span));
		}
		return true;
	}

	/** One upgrade weighed across several targets, with the time it saves over the span named. */
	private static Card pick(Fights.Pick p, ItemIcons icons, String span)
	{
		JLabel cost = Ui.label(Format.coins(p.getCost()), Theme.small(), Theme.GOLD);
		Card row = Rows.line(new IconBadge(p.getIcon().getId(), icons, true), p.getName(),
			"Saves " + Format.span(p.getSeconds()) + " of fighting", cost, null);
		StringBuilder tip = new StringBuilder("<html><b>").append(Ui.escape(p.getName())).append("</b><br>About ")
			.append(Format.span(p.getSeconds())).append(" less fighting over ").append(span).append(", mostly at ");
		List<String> where = p.getWhere();
		for (int i = 0; i < where.size() && i < 3; i++)
		{
			tip.append(i == 0 ? "" : i == where.size() - 1 || i == 2 ? " and " : ", ").append(Ui.escape(where.get(i)));
		}
		row.setToolTipText(tip.append(".</html>").toString());
		return row;
	}

	private static boolean matches(Target t, int filter)
	{
		switch (filter)
		{
			case 1:
				return "Boss".equals(t.getGroup());
			case 2:
				return "Slayer".equals(t.getGroup());
			case 3:
				return "Training".equals(t.getGroup());
			default:
				return true;
		}
	}

	/** Builds target rows: a click aims the roadmap, a right-click puts the target on the shortlist or takes it off. */
	static final class TargetRows
	{
		private final Report report;
		private final String focused;
		private final Consumer<String> onPick;
		private final Consumer<String> onShortlist;

		TargetRows(Report report, String focused, Consumer<String> onPick, Consumer<String> onShortlist)
		{
			this.report = report;
			this.focused = focused;
			this.onPick = onPick;
			this.onShortlist = onShortlist;
		}

		Card row(Roadmap.Survey row)
		{
			Target t = row.getTarget();
			boolean aimed = t.getName().equals(focused);
			boolean listed = report.getShortlist().contains(t.getName());
			Result r = row.getPlan().getResult();
			Card card = new Card(new BorderLayout(8, 0));
			card.setBorder(new EmptyBorder(5, 10, 5, 10));
			card.accent(Theme.kind(r.getKind()));
			card.highlighted(aimed);

			JPanel text = new JPanel();
			text.setOpaque(false);
			text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
			text.add(Ui.label(t.getName(), Theme.body(), aimed ? Theme.GOLD_BRIGHT : Theme.TEXT));
			String line = r.getKind() == null ? "Out of reach" : Format.dps(r.getDps()) + " DPS  ·  " + r.getKind();
			text.add(Ui.label(line, Theme.small(), r.getKind() == null ? Theme.TEXT_FAINT : Theme.mix(Theme.TEXT_MUTED, Theme.kind(r.getKind()), 0.5)));
			text.setMinimumSize(new Dimension(10, 10));
			text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
			card.add(text, BorderLayout.CENTER);

			JPanel trail = new JPanel();
			trail.setOpaque(false);
			trail.setLayout(new BoxLayout(trail, BoxLayout.Y_AXIS));
			JLabel time = Ui.label(Format.time(r.secondsToKill(t)), Theme.body(), Theme.TEXT);
			time.setAlignmentX(JComponent.RIGHT_ALIGNMENT);
			trail.add(time);
			String captionText = aimed ? "aimed" : listed ? "shortlisted" : "per kill";
			JLabel caption = Ui.label(captionText, Theme.small(), aimed || listed ? Theme.GOLD : Theme.TEXT_FAINT);
			caption.setAlignmentX(JComponent.RIGHT_ALIGNMENT);
			trail.add(caption);
			card.add(trail, BorderLayout.EAST);
			card.setToolTipText("<html><b>" + Ui.escape(t.getName()) + "</b><br>" + t.getHp() + " hitpoints, " + t.getDefence()
				+ " Defence<br>Click to aim your roadmap here<br>Right-click to " + (listed ? "take it off" : "add it to")
				+ " your shortlist</html>");
			card.onClick(() -> onPick.accept(t.getName()));
			card.onMenu(at ->
			{
				JPopupMenu menu = new JPopupMenu();
				JMenuItem item = new JMenuItem(listed ? "Remove from shortlist" : "Add to shortlist");
				item.addActionListener(e -> onShortlist.accept(t.getName()));
				menu.add(item);
				menu.show(card, at.x, at.y);
			});
			return card;
		}
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Result;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * Gear Roadmap gives each kind of attack its own colour: ember for melee, green for
 * ranged and violet for magic.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** The colour of a kind of attack. */
	public static Color kind(Result.Kind kind)
	{
		if (kind == null)
		{
			return TEXT_MUTED;
		}
		switch (kind)
		{
			case MELEE:
				return EMBER;
			case RANGED:
				return GREEN;
			default:
				return VIOLET;
		}
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Result;
import com.codex.gearroadmap.core.Roadmap;
import com.codex.gearroadmap.data.Target;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.util.Locale;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** One upgrade as a card: its picture, the damage it adds, what it costs and how to get it. */
final class UpgradeRow
{
	enum Mode
	{
		STEP,
		FREE,
		LOCKED,
		LEAP
	}

	/** The width the words of a row have beside its picture in the side panel. */
	private static final int TEXT_W = 150;

	private UpgradeRow()
	{
	}

	static Card build(Roadmap.Option o, Mode mode, int rank, boolean affordable, Result.Kind before, ItemIcons icons, Target target,
		Runnable onClick)
	{
		Card card = new Card(new BorderLayout(7, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		Result.Kind kind = o.getAfter().getResult().getKind();
		Color tint = Theme.kind(kind);
		if (mode == Mode.STEP && rank == 1 || mode == Mode.FREE)
		{
			card.accent(mode == Mode.FREE ? Theme.TEAL : Theme.GOLD);
		}

		JPanel lead = new JPanel(new BorderLayout(4, 0));
		lead.setOpaque(false);
		if (mode == Mode.STEP)
		{
			JPanel medal = new JPanel(new BorderLayout());
			medal.setOpaque(false);
			medal.setBorder(new EmptyBorder(4, 0, 0, 0));
			medal.add(new Medal(rank, affordable), BorderLayout.NORTH);
			lead.add(medal, BorderLayout.WEST);
		}
		JPanel badge = new JPanel(new BorderLayout());
		badge.setOpaque(false);
		badge.add(new IconBadge(o.getIcon().getId(), icons, mode != Mode.LOCKED), BorderLayout.NORTH);
		lead.add(badge, BorderLayout.CENTER);
		card.add(lead, BorderLayout.WEST);

		Color priceColor = affordable ? Theme.TEAL : Theme.GOLD;
		boolean priced = mode == Mode.STEP || mode == Mode.LEAP || mode == Mode.LOCKED && o.getCost() > 0;
		JPanel text = new JPanel();
		text.setOpaque(false);
		// What the words beside the picture have at the panel's width; a step's medal takes some of it.
		int room = mode == Mode.STEP ? TEXT_W - 22 : TEXT_W;
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));

		// The name gets the whole first line and the price sits under it beside the damage, so even
		// "Dragon hunter lance" or "Inquisitor's plateskirt" is read whole at the panel's width.
		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setOpaque(false);
		// A pair bought together ("A + B") names the first on top and the second beneath it.
		int plus = o.getName().indexOf(" + ");
		String title = plus < 0 ? o.getName() : o.getName().substring(0, plus);
		JLabel name = Ui.label(title, Theme.body(), mode == Mode.LOCKED ? Theme.TEXT_MUTED : Theme.TEXT);
		name.setMinimumSize(new Dimension(10, 10));
		name.setPreferredSize(new Dimension(10, name.getPreferredSize().height));
		name.setToolTipText(o.getName());
		top.add(name, BorderLayout.CENTER);
		top.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		text.add(top);
		if (plus >= 0)
		{
			// Wrapped rather than cut, so "+ Inquisitor's great hammer" is read whole.
			JLabel second = Ui.wrapped("+ " + o.getName().substring(plus + 3), Theme.body(), name.getForeground(), room);
			second.setToolTipText("Neither does anything alone: together they reach the next max hit");
			second.setAlignmentX(JComponent.LEFT_ALIGNMENT);
			text.add(second);
		}

		Color gainColor = mode == Mode.LOCKED ? Theme.mix(tint, Theme.TEXT_FAINT, 0.4) : tint;
		JPanel middle = new JPanel(new BorderLayout(4, 0));
		middle.setOpaque(false);
		middle.add(Ui.label(Format.gain(o.getGain()) + " DPS  " + Format.share(o.getGainShare()), Theme.small(), gainColor), BorderLayout.WEST);
		if (priced)
		{
			middle.add(Ui.label(Format.coins(o.getCost()), Theme.body(), priceColor), BorderLayout.EAST);
		}
		middle.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		text.add(middle);

		String detail;
		Color detailColor = Theme.TEXT_MUTED;
		switch (mode)
		{
			case FREE:
				detail = o.getEarn() != null ? o.getEarn() : o.getNote();
				detailColor = Theme.TEAL;
				break;
			case LOCKED:
				detail = "Needs " + o.getMissing();
				detailColor = Theme.EMBER;
				break;
			default:
				detail = o.isAmmo() ? "Price per 1,000" : Format.value(o.getCost(), o.getGain());
				if (kind != null && before != null && kind != before)
				{
					detail = "To " + kind.toString().toLowerCase(Locale.ROOT) + (detail.isEmpty() ? "" : " · " + detail);
					detailColor = Theme.mix(Theme.TEXT_MUTED, tint, 0.6);
				}
		}
		if (detail != null && !detail.isEmpty())
		{
			// How a free upgrade is earned, or what a locked one needs, can run long
			// ("Dragon Slayer II and Vorkath's head"): it wraps instead of being cut.
			boolean wrap = mode == Mode.FREE || mode == Mode.LOCKED;
			JLabel sub = wrap ? Ui.wrapped(detail, Theme.small(), detailColor, room) : Ui.label(detail, Theme.small(), detailColor);
			sub.setToolTipText(detail);
			sub.setAlignmentX(JComponent.LEFT_ALIGNMENT);
			text.add(sub);
		}
		text.setMinimumSize(new Dimension(10, 10));
		text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
		card.add(text, BorderLayout.CENTER);

		StringBuilder tip = new StringBuilder("<html><b>").append(Ui.escape(o.getName())).append("</b>");
		if (priced)
		{
			tip.append("<br>").append(Format.coins(o.getCost())).append(o.isAmmo() ? " per 1,000" : "")
				.append(mode == Mode.STEP ? affordable ? ", your coins cover the road to here" : ", past what your coins cover" : "");
		}
		if (o.getNote() != null)
		{
			tip.append("<br>").append(Ui.escape(o.getNote()));
		}
		Result after = o.getAfter().getResult();
		tip.append("<br>").append(Format.dps(after.getDps())).append(" DPS after, max hit ").append(after.getMaxHit());
		if (after.getStyle() != null)
		{
			tip.append(", ").append(Ui.escape(after.getStyle().toLowerCase(Locale.ROOT)));
		}
		double was = o.getGain() > 0 && o.getAfter().dps() > o.getGain() ? target.getHp() / (o.getAfter().dps() - o.getGain()) : 0;
		double now = after.secondsToKill(target);
		if (was > 0 && !Double.isInfinite(now) && was - now >= 0.5)
		{
			tip.append("<br>Kill time ").append(Format.time(was)).append(" to ").append(Format.time(now))
				.append(", ").append(Math.round((1 - now / was) * 100)).append("% faster");
		}
		if (onClick != null)
		{
			tip.append("<br><i>Click to see the loadout</i>");
		}
		card.setToolTipText(tip.append("</html>").toString());
		if (onClick != null)
		{
			card.onClick(onClick);
		}
		return card;
	}

	/** A small gilt medallion with the step number; dim once the road passes the player's coins. */
	private static final class Medal extends JComponent
	{
		private final int rank;
		private final boolean lit;

		Medal(int rank, boolean lit)
		{
			this.rank = rank;
			this.lit = lit;
			Dimension d = new Dimension(18, 18);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			g.setColor(lit ? Theme.alpha(Theme.GOLD, 60) : Theme.INK_DEEP);
			g.fill(new Ellipse2D.Float(1, 1, 16, 16));
			g.setColor(lit ? Theme.GOLD : Theme.STROKE);
			g.draw(new Ellipse2D.Float(1, 1, 16, 16));
			g.setFont(Theme.small());
			FontMetrics fm = g.getFontMetrics();
			String text = String.valueOf(rank);
			ProgressRing.drawShadowed(g, text, 9 - fm.stringWidth(text) / 2, 9 + fm.getAscent() / 2 - 1,
				lit ? Theme.GOLD_BRIGHT : Theme.TEXT_MUTED);
			g.dispose();
		}
	}
}

package com.codex.gearroadmap;

import com.codex.gearroadmap.core.Claims;
import com.codex.gearroadmap.core.Fights;
import com.codex.gearroadmap.core.Holdings;
import com.codex.gearroadmap.core.Saved;
import com.codex.gearroadmap.core.Savings;
import com.codex.gearroadmap.data.RoadmapData;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Every value Gear Roadmap reads back from the profile, its own (bank, road behind, savings goal)
 * and other Codex plugins' (Codex Ledger's worth, Session Chronicle's journal and live session, Bank
 * Steward's bank), must survive whatever is found there: empty, cut short, the wrong type, numbers
 * too big or below zero, a later version's fields, or garbage. None of it may throw, and a broken
 * entry must cost only itself, never the good ones beside it.
 */
public class DamagedSavesTest
{
	private static final Gson GSON = new GsonBuilder().create();
	private static final JsonParser PARSER = new JsonParser();
	private static final long NOW = 1_790_000_000_000L;
	private static final long DAY = 86_400_000L;
	/** Values of every wrong kind, put in place of a good one. */
	private static final String[] BAD = {
		"null", "\"\"", "\"garbage\"", "true", "0", "-1", "-9223372036854775808", "9223372036854775807",
		"1e30", "1.5", "[]", "[null]", "[\"x\"]", "{}", "{\"x\":1}", "[{}]",
	};
	/** Whole saves that are not what they should be at all. */
	private static final String[] WHOLE = {
		null, "", " ", "null", "{", "}", "[", "[]", "[{}]", "42", "\"text\"", "true", "garbage{{", "\u0000",
	};
	private static RoadmapData data;

	@BeforeClass
	public static void load() throws IOException
	{
		data = RoadmapData.load(GSON);
	}

	@Test
	public void theSavedBank()
	{
		String good = "{\"items\":[4151,9050,13072],\"coins\":1234567}";
		for (String save : cut(good))
		{
			bank(save);
		}
		for (String key : new String[]{"items", "coins"})
		{
			for (String bad : BAD)
			{
				JsonObject o = PARSER.parse(good).getAsJsonObject();
				o.add(key, PARSER.parse(bad));
				CodexGearRoadmapPlugin.Bank read = bank(o.toString());
				if (key.equals("coins"))
				{
					// Coins gone wrong cost the coins, never the gear.
					assertNotNull(bad, read);
					assertEquals(bad, 3, read.items.size());
				}
				if (read != null)
				{
					assertTrue(bad, read.coins >= 0);
				}
			}
		}
		// One id that is not one costs only itself.
		CodexGearRoadmapPlugin.Bank read = bank("{\"items\":[4151,null,\"x\",-5,0,1e30,9050],\"coins\":-40}");
		assertNotNull(read);
		assertEquals(2, read.items.size());
		assertEquals(0, read.coins);
		assertNotNull(bank("{\"items\":[4151],\"coins\":1,\"version\":3,\"tabs\":[[1]]}"));
	}

	@Test
	public void theRoadBehind()
	{
		Claims good = new Claims();
		good.add(new Claims.Claim("Abyssal whip", 4151, 1.2, "Vorkath", NOW - 3 * DAY));
		good.add(new Claims.Claim("Fire cape", 6570, 0.4, "Vorkath", NOW - 2 * DAY));
		good.add(new Claims.Claim("Ghrazi rapier", 22324, 0.8, "Zulrah", NOW - DAY));
		String whole = GSON.toJson(good);
		for (String save : cut(whole))
		{
			claims(save);
		}
		for (String bad : BAD)
		{
			JsonObject o = PARSER.parse(whole).getAsJsonObject();
			o.getAsJsonArray("claims").set(1, PARSER.parse(bad));
			assertEquals(bad, 2, claims(o.toString()).recent().size());
			for (String field : new String[]{"name", "icon", "gain", "target", "at"})
			{
				o = PARSER.parse(whole).getAsJsonObject();
				o.getAsJsonArray("claims").get(0).getAsJsonObject().add(field, PARSER.parse(bad));
				assertTrue(field + " = " + bad, claims(o.toString()).recent().size() >= 2);
			}
		}
		// A claim dated past any clock, or adding more damage than any upgrade can, is damage: it is left
		// out rather than heading the road behind for ever. A later version's fields are ignored.
		JsonObject o = PARSER.parse(whole).getAsJsonObject();
		o.addProperty("version", 4);
		o.getAsJsonArray("claims").get(0).getAsJsonObject().addProperty("at", Long.MAX_VALUE);
		o.getAsJsonArray("claims").get(0).getAsJsonObject().addProperty("gain", 1e300);
		Claims read = claims(o.toString());
		assertEquals(2, read.recent().size());
		assertEquals("Fire cape", read.recent().get(0).getName());
	}

