	{
		Set<Gear> owned = new LinkedHashSet<>();
		for (String name : MID_GAME)
		{
			Gear g = data.named(name);
			if (g == null)
			{
				throw new IllegalStateException("No gear named " + name);
			}
			owned.add(g);
		}
		return owned;
	}

