package com.codex.gearroadmap;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * Other Codex plugins read what Gear Roadmap saves, and Gear Roadmap reads Codex Ledger: these
 * pin the group, keys and JSON shape so a change here cannot quietly break them.
 */
public class SavedFormatsTest
{
	/** The shape Codex Plunder Pilot and Pest Control Pilot read the bank in: only the item ids. */
	private static final class ReaderBank
	{
		List<Integer> items;
	}

	@Test
	public void bankIsSavedWhereAndHowOtherPluginsReadIt()
	{
		assertEquals("codexgearroadmap", CodexGearRoadmapConfig.GROUP);
		assertEquals("bank", CodexGearRoadmapPlugin.BANK_KEY);

		CodexGearRoadmapPlugin.Bank bank = new CodexGearRoadmapPlugin.Bank();
		bank.items.addAll(Arrays.asList(9050, 4151, 13072));
		bank.coins = 1_234_567;
		Gson gson = new Gson();
		String json = gson.toJson(bank);
		assertEquals("{\"items\":[4151,9050,13072],\"coins\":1234567}", json);
		assertEquals(Arrays.asList(4151, 9050, 13072), gson.fromJson(json, ReaderBank.class).items);
	}

	@Test
	public void ledgerIsReadFromItsOwnGroupAndKey()
	{
		assertEquals("codexledger", CodexGearRoadmapPlugin.LEDGER_GROUP);
		assertEquals("ledger", CodexGearRoadmapPlugin.LEDGER_KEY);
	}
}

package com.codex.gearroadmap;

import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Settings keep the keys their values are saved under. */
public class SavedSettingsTest
{
	/** Every key the released plugin (main) saves settings under. */
	private static final String[] ON_MAIN = {"boost", "chatLine", "plaqueSeconds", "prayers", "showPlaque", "slayerTask", "target"};
	/** Keys added since, which players will have saved by the time this ships. */
	private static final String[] ADDED = {"followTask", "nameOnCard", "worthOnCard"};

	@Test
	public void savedSettingsKeepTheirKeys()
	{
		// A setting's key is where its value is saved: renaming one quietly resets it for every player who
		// changed it. A display name may change freely; a key may not.
		Set<String> keys = new HashSet<>();
		for (Method m : CodexGearRoadmapConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				keys.add(item.keyName());
			}
		}
		for (String key : ON_MAIN)
		{
			assertTrue(key, keys.contains(key));
		}
		for (String key : ADDED)
		{
			assertTrue(key, keys.contains(key));
		}
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.Fixtures;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

public class AdvisorTest
{
	private static RoadmapData data;
	private static Advisor advisor;

	@BeforeClass
	public static void load() throws IOException
	{
		data = RoadmapData.load(new Gson());
		advisor = new Advisor(data);
	}

	@Test
	public void everyCatalogueItemResolves()
	{
		assertEquals(200, data.catalogue().size());
		assertTrue(data.targets().size() > 60);
	}

	@Test
	public void roadmapClimbs()
	{
		Set<Gear> owned = Fixtures.midGame(data);
		Fighter fighter = Fixtures.midGameFighter();
		Target vorkath = data.target("Vorkath");
		Roadmap map = advisor.plan(owned, fighter, vorkath, Fixtures.prices(data), 42_000_000);
		System.out.println("Now " + map.getNow().best().getResult().getKind() + " " + map.getNow().dps() + " "
			+ map.getNow().best().getLoadout());
		double previous = map.getNow().dps();
		long spent = 0;
		for (Roadmap.Step step : map.getPath())
		{
			Roadmap.Option o = step.getOption();
			System.out.printf("  %-28s %,13d  +%.3f  -> %.3f  %s%n", o.getName(), o.getCost(), o.getGain(), o.getAfter().dps(),
				o.getAfter().getResult().getKind());
			assertTrue(o.getAfter().dps() > previous);
			assertTrue(step.getSpent() > spent);
			previous = o.getAfter().dps();
			spent = step.getSpent();
		}
		for (Roadmap.Option o : map.getFree())
		{
			System.out.printf("  free %-23s +%.3f %s%n", o.getName(), o.getGain(), o.getEarn());
			assertEquals(0, o.getCost());
		}
		for (Roadmap.Option o : map.getLocked())
		{
			System.out.printf("  locked %-21s +%.3f %s%n", o.getName(), o.getGain(), o.getMissing());
			assertFalse(o.getMissing().isEmpty());
		}
		for (Roadmap.Option o : map.getLeaps())
		{
			System.out.printf("  leap %-23s %,13d +%.3f%n", o.getName(), o.getCost(), o.getGain());
		}
		assertFalse(map.getPath().isEmpty());
	}

	@Test
	public void piecesThatOnlyHelpTogetherAreBoughtAsAPair()
	{
		// With a rapier at Vorkath neither a +3 strength helm nor +1 strength legs moves the max hit
		// alone, but together they do, and that pair is far better value than a 25M fang.
		Set<Gear> owned = Fixtures.midGame(data);
		owned.add(data.named("Ghrazi rapier"));
		Roadmap map = advisor.plan(owned, Fixtures.midGameFighter(), data.target("Vorkath"), Fixtures.prices(data), 0);
		Roadmap.Option first = map.getPath().get(0).getOption();
		assertEquals(2, first.getPieces().size());
		assertTrue(first.getName(), first.getName().contains(" + "));
		assertTrue(first.getGain() > 0.1);
	}

	@Test
	public void aNewAccountGetsAStarterRoad()
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String skill : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Agility"})
		{
			levels.put(skill, 30);
		}
		levels.put("Hitpoints", 30);
		Fighter fresh = new Fighter(levels, Fighter.Boost.NONE, true, true, false, false, false, false);
		Roadmap map = advisor.plan(new HashSet<>(), fresh, data.target("Hill Giant"), Fixtures.prices(data), 0);
		assertFalse(map.getPath().isEmpty());
		assertTrue(map.getPath().get(0).getOption().getCost() < 10_000);
		boolean dragonGloves = false;
		boolean barrowsGloves = false;
		for (Roadmap.Option o : map.getFree())
		{
			dragonGloves |= o.getName().equals("Dragon gloves");
			barrowsGloves |= o.getName().equals("Barrows gloves");
		}
		assertTrue(barrowsGloves);
		assertFalse("one Recipe for Disaster reward is enough", dragonGloves);
		Map<String, Integer> fang = Collections.singletonMap("Attack", 82);
		assertEquals(52, fresh.shortfall(fang));
	}

	@Test
	public void newCoinsMoveOnlyTheReach()
	{
		Roadmap map = advisor.plan(Fixtures.midGame(data), Fixtures.midGameFighter(), data.target("Vorkath"),
			Fixtures.prices(data), 0);
		assertFalse(map.getPath().get(0).isAffordable());
		long second = map.getPath().get(1).getSpent();
		Roadmap richer = map.withCoins(second);
		assertEquals(map.getPath().size(), richer.getPath().size());
		assertTrue(richer.getPath().get(0).isAffordable());
		assertTrue(richer.getPath().get(1).isAffordable());
		assertFalse(richer.getPath().get(2).isAffordable());
		assertEquals(map.getLeaps(), richer.getLeaps());
		assertEquals(second, richer.getCoins());
	}

	@Test
	public void ownedUpgradesAreNotSuggested()
	{
		Set<Gear> owned = Fixtures.midGame(data);
		Roadmap map = advisor.plan(owned, Fixtures.midGameFighter(), data.target("General Graardor"), Fixtures.prices(data), 0);
		for (Roadmap.Step step : map.getPath())
		{
			for (Gear g : step.getOption().getPieces())
			{
				assertFalse(g.getName(), owned.contains(g));
			}
			assertFalse(step.isAffordable());
		}
		assertNull(map.getPath().isEmpty() ? "empty" : null);
	}

	@Test
	public void vorkathRoadDoesNotSwapToMeleeForACheapSword()
	{
		// Vorkath's acid phase and fire bombs keep a melee player walking while a ranger keeps shooting.
		// Before melee counted at 80% there, a 60k dragon sword with the salve (e) out-damaged the
		// blowpipe on paper, and the whole road turned into melee gear.
		Target vorkath = data.target("Vorkath");
		assertEquals(80, vorkath.uptime("Melee"));
		assertEquals(100, vorkath.uptime("Ranged"));
		assertEquals(100, data.target("General Graardor").uptime("Melee"));
		Roadmap map = advisor.plan(Fixtures.midGame(data), Fixtures.midGameFighter(), vorkath, Fixtures.prices(data), 0);
		double previous = map.getNow().dps();
		for (Roadmap.Step step : map.getPath())
		{
			Roadmap.Option o = step.getOption();
			assertFalse(o.getName().contains("Dragon sword"));
			// Each step builds on the loadout the step before showed, so no gain is counted twice.
			assertEquals(o.getName(), previous + o.getGain(), o.getAfter().dps(), 1e-9);
			assertTrue(o.getName(), o.getGain() > 0);
			previous = o.getAfter().dps();
		}

		// The melee figure itself is the formula's damage times the uptime.
		Set<Gear> owned = Fixtures.midGame(data);
		owned.add(data.named("Dragon sword"));
		Planner planner = new Planner(data);
		double atVorkath = planner.optimise(owned, Fixtures.midGameFighter(), vorkath).get(Result.Kind.MELEE).dps();
		Target twin = new Target("Twin", "Boss", vorkath.getHp(), vorkath.getDefence(), vorkath.getMagic(),
			new int[]{26, 108, 108, 240, 26, 26, 26}, 7, vorkath.getAttributes(), true);
		double full = planner.optimise(owned, Fixtures.midGameFighter(), twin).get(Result.Kind.MELEE).dps();
		assertEquals(full * 0.8, atVorkath, 1e-9);
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

public class AimTest
{
	private static List<Target> targets;

	@BeforeClass
	public static void load() throws IOException
	{
		targets = RoadmapData.load(new Gson()).targets();
	}

	private static String names(Aim aim)
	{
		StringBuilder b = new StringBuilder();
		for (Target t : aim.getCovered())
		{
			b.append(b.length() == 0 ? "" : ", ").append(t.getName());
		}
		return b.toString();
	}

	@Test
	public void followsTheTaskToItsOwnMonsterFirst()
	{
		Aim aim = Aim.choose(targets, "Vorkath", true, "Abyssal demons", false, null);
		assertEquals("Abyssal demon", aim.getTarget().getName());
		assertTrue(aim.isFollowing());
		assertEquals("Abyssal demon, Abyssal Sire", names(aim));

		Aim smoke = Aim.choose(targets, "Vorkath", true, "Smoke devils", false, null);
		assertEquals("Smoke devil", smoke.getTarget().getName());
	}

	@Test
	public void staysOnTheChosenTargetWithoutATaskOrWhenNotFollowing()
	{
		assertEquals("Zulrah", Aim.choose(targets, "Zulrah", true, null, false, null).getTarget().getName());
		Aim off = Aim.choose(targets, "Zulrah", false, "Abyssal demons", false, null);
		assertEquals("Zulrah", off.getTarget().getName());
		assertFalse(off.isFollowing());
		// The task's targets are still offered on the Targets tab.
		assertEquals(2, off.getCovered().size());
		// A task with nothing listed for it leaves the aim alone.
		Aim bandits = Aim.choose(targets, "Zulrah", true, "Bandits", false, null);
		assertEquals("Zulrah", bandits.getTarget().getName());
		assertFalse(bandits.isFollowing());
	}

	@Test
	public void aChosenTargetOnTheTaskIsKept()
	{
		Aim aim = Aim.choose(targets, "Cerberus", true, "Hellhounds", false, null);
		assertEquals("Cerberus", aim.getTarget().getName());
		assertTrue(aim.isFollowing());
	}

	@Test
	public void aPickWithinTheTaskWins()
	{
		Aim aim = Aim.choose(targets, "Vorkath", true, "Abyssal demons", false, "Abyssal Sire");
		assertEquals("Abyssal Sire", aim.getTarget().getName());
		// A stale pick from another task is ignored.
		assertEquals("Abyssal demon", Aim.choose(targets, "Vorkath", true, "Abyssal demons", false, "Cerberus").getTarget().getName());
	}

	@Test
	public void bossesOfABroadTaskAreOfferedNotAimedAt()
	{
		Aim bears = Aim.choose(targets, "Zulrah", true, "Bears", false, null);
		assertEquals("Zulrah", bears.getTarget().getName());
		assertFalse(bears.isFollowing());
		assertEquals("Callisto, Artio", names(bears));
		Aim blue = Aim.choose(targets, "Zulrah", true, "Blue dragons", false, null);
		assertEquals("Zulrah", blue.getTarget().getName());
		// A boss's own task does aim at it, and so does one from a boss slayer master.
		assertEquals("Vorkath", Aim.choose(targets, "Zulrah", true, "Vorkath", true, null).getTarget().getName());
		assertEquals("Abyssal Sire", Aim.choose(targets, "Zulrah", true, "The Abyssal Sire", false, null).getTarget().getName());
		assertEquals("Dagannoth Rex", Aim.choose(targets, "Zulrah", true, "Dagannoth Kings", true, null).getTarget().getName());
	}

	@Test
	public void unknownChosenTargetFallsBackToTheFirst()
	{
		assertEquals(targets.get(0), Aim.choose(targets, "Nobody", true, null, false, null).getTarget());
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Max hits checked against in-game cases recorded for the OSRS Wiki's DPS calculator:
 * the same gear, levels and prayers must give the same max hit here.
 */
public class CalcTest
{
	private static final int[] TORVA_MELEE = {26382, 21285, 19553, 26384, 22322, 26386, 22981, 13239, 11773};
	private static final int[] VOID_MELEE = {11665, 21285, 19553, 13072, 22322, 13073, 8842, 13239, 11773};
	private static final int[] ANCESTRAL = {21018, 21780, 12002, 21021, 21024, 19544, 13235, 28313};

	private static RoadmapData data;
	private static Calc calc;

	@BeforeClass
	public static void load() throws IOException
	{
		data = RoadmapData.load(new Gson());
		calc = new Calc(data);
	}

	private static Target target(int id)
	{
		for (Target t : data.targets())
		{
			if (t.getId() == id)
			{
				return t;
			}
		}
		throw new AssertionError("No target " + id);
	}

	private static Loadout wear(int[] base, int... swaps)
	{
		Loadout lo = Loadout.empty();
		for (int id : base)
		{
			lo = lo.with(gear(id));
		}
		for (int id : swaps)
		{
			lo = lo.with(gear(id));
		}
		return lo;
	}

