import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * The Grotesque Guardians are two fights in one: Dusk takes only melee, while Dawn can also be
 * shot. A player reported that the roadmap never offered the granite hammer, which does about as
 * well as far dearer weapons there, and never looked at ranged for Dawn.
 */
public class GuardiansTest
{
	private static RoadmapData data;

	@BeforeClass
	public static void load() throws IOException
	{
		data = RoadmapData.load(new Gson());
	}

	@Test
	public void theGraniteHammerIsOnTheShoppingList()
	{
		boolean listed = false;
		for (CatalogueEntry e : data.catalogue())
		{
			listed |= "Granite hammer".equals(e.getName());
		}
		assertTrue(listed);
	}

	@Test
	public void dawnCanBeShotButDuskCannot()
	{
		Target dusk = data.target("Grotesque Guardians");
		Target dawn = data.target("Dawn (Grotesque Guardians)");
		assertTrue(dusk.allows("MELEE"));
		assertFalse(dusk.allows("RANGED"));
		assertTrue(dawn.allows("MELEE"));
		assertTrue(dawn.allows("RANGED"));
		assertFalse(dawn.allows("MAGIC"));
	}

	@Test
	public void aBowDoesDamageToDawn()
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String skill : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer"})
		{
			levels.put(skill, 90);
		}
		Fighter f = new Fighter(levels, Fighter.Boost.POTIONS, true, true, true, true, true, true);
		Gear bow = data.gear(27610);
		Loadout venator = Loadout.empty().with(bow).with(data.gear(11212));
		Calc calc = new Calc(data);
		assertTrue(calc.best(venator, f, data.target("Dawn (Grotesque Guardians)")).getDps() > 0);
		assertFalse(calc.best(venator, f, data.target("Grotesque Guardians")).getDps() > 0);
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.RoadmapData;
import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Which bank Gear Roadmap plans with. {@code bank-steward-bankV1.json} is a byte-for-byte copy of
 * the fixture Codex Bank Steward's own BankSnapshotTest proves its writer produces.
 */
public class HoldingsTest
{
	private static final Gson GSON = new Gson();
	private static final int WHIP = 4151;
	private static final int VOID_TOP = 8839;
	private static final int DRAGON_ARROW = 11212;
	private static RoadmapData data;

	@BeforeClass
	public static void load() throws Exception
	{
		data = RoadmapData.load(GSON);
	}

	private static String fixture(String name) throws Exception
	{
		try (InputStream in = HoldingsTest.class.getResourceAsStream(name))
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buf = new byte[4096];
			for (int n; (n = in.read(buf)) > 0; )
			{
				out.write(buf, 0, n);
			}
			return new String(out.toByteArray(), StandardCharsets.UTF_8).trim();
		}
	}

	private static Holdings.Shared steward(long savedAt, Object... idQty)
	{
		Map<Integer, Long> items = new HashMap<>();
		for (int i = 0; i < idQty.length; i += 2)
		{
			items.put((Integer) idQty[i], ((Number) idQty[i + 1]).longValue());
		}
		return new Holdings.Shared(items, savedAt);
	}

	private static Set<Integer> ids(Integer... ids)
	{
		return new TreeSet<>(Arrays.asList(ids));
	}

	@Test
	public void readsBankStewardsRealSnapshot() throws Exception
	{
		// CodexBankStewardConfig.GROUP and BankSnapshot.KEY.
		assertEquals("codexbanksteward", Holdings.STEWARD_GROUP);
		assertEquals("bankV1", Holdings.STEWARD_KEY);
		Holdings.Shared shared = Holdings.readSteward(GSON, fixture("bank-steward-bankV1.json"));
		assertEquals(1_760_000_000_000L, shared.getSavedAt());
		assertEquals(Long.valueOf(240), shared.getItems().get(385));
		assertEquals(Long.valueOf(1_234_567), shared.getItems().get(995));

		Holdings h = Holdings.choose(null, 0, null, 0, shared, id -> data.gear(id) != null);
		assertSame(Holdings.Source.BANK_STEWARD, h.getSource());
		assertTrue(h.isKnown());
		// Only gear is kept, with its count; the sharks, potions and the sceptre are not gear.
		assertEquals(Collections.singletonMap(VOID_TOP, 1L), h.getGear());
		assertEquals(1_234_567, h.getCoins());
	}

	@Test
	public void anUnreadableOrMissingSnapshotIsNoBank()
	{
		assertNull(Holdings.readSteward(GSON, null));
		assertNull(Holdings.readSteward(GSON, ""));
		assertNull(Holdings.readSteward(GSON, "not json {"));
		assertNull(Holdings.readSteward(GSON, "{\"items\":[4151]}"));
		assertNull(Holdings.readSteward(GSON, "[1,2]"));
		// Bad entries are skipped, the rest kept.
		Holdings.Shared odd = Holdings.readSteward(GSON, "{\"items\":{\"4151\":1,\"x\":2,\"995\":-5,\"11212\":1.5,\"8839\":\"a\"}}");
		assertEquals(Collections.singletonMap(WHIP, 1L), odd.getItems());
		assertEquals(0, odd.getSavedAt());
		assertSame(Holdings.NONE, Holdings.choose(null, 0, null, 0, null, id -> true));
		assertFalse(Holdings.NONE.isKnown());
	}

	@Test
	public void platinumTokensCountAsCoins()
	{
		Holdings h = Holdings.choose(null, 0, null, 0, steward(5, 995, 500, 13204, 3), id -> false);
		assertEquals(3_500, h.getCoins());
	}

	@Test
	public void withoutBankStewardTheOwnViewIsUsed()
	{
		Holdings h = Holdings.choose(ids(WHIP), 1_000, null, 0, null, id -> true);
		assertSame(Holdings.Source.OWN, h.getSource());
		assertEquals(Collections.singletonMap(WHIP, Holdings.UNKNOWN), h.getGear());
		assertEquals(1_000, h.getCoins());
	}

	@Test
	public void theFresherBankWins()
	{
		// Gear Roadmap last saw the bank at 100 and Bank Steward at 200, after the whip was sold.
		Holdings h = Holdings.choose(ids(WHIP, VOID_TOP), 1_000, null, 100, steward(200, VOID_TOP, 1, 995, 9_000), id -> id != 995);
		assertSame(Holdings.Source.BANK_STEWARD, h.getSource());
		assertEquals(Collections.singletonMap(VOID_TOP, 1L), h.getGear());
		assertEquals(9_000, h.getCoins());

		// The other way round, Gear Roadmap's newer view stands.
		h = Holdings.choose(ids(WHIP, VOID_TOP), 1_000, null, 300, steward(200, VOID_TOP, 1), id -> true);
		assertSame(Holdings.Source.OWN, h.getSource());
		assertEquals(1_000, h.getCoins());

		// A bank saved before Gear Roadmap kept the time defers to Bank Steward.
		h = Holdings.choose(ids(WHIP), 1_000, null, 0, steward(200, VOID_TOP, 1), id -> true);
		assertSame(Holdings.Source.BANK_STEWARD, h.getSource());
	}

	@Test
	public void theSameGearTakesBankStewardsCountsWhoeverSawItLast()
	{
		Holdings h = Holdings.choose(ids(DRAGON_ARROW), 0, null, 300, steward(200, DRAGON_ARROW, 37), id -> true);
		assertSame(Holdings.Source.BANK_STEWARD, h.getSource());
		assertEquals(Long.valueOf(37), h.getGear().get(DRAGON_ARROW));
	}

	@Test
	public void aBankSeenThisLoginKeepsItsOwnCounts()
	{
		Map<Integer, Long> counts = Collections.singletonMap(DRAGON_ARROW, 2_000L);
		Holdings h = Holdings.choose(ids(DRAGON_ARROW), 0, counts, 300, steward(200, DRAGON_ARROW, 37), id -> true);
		assertSame(Holdings.Source.OWN, h.getSource());
		assertEquals(Long.valueOf(2_000), h.getGear().get(DRAGON_ARROW));
	}

	@Test
	public void ammunitionNeedsAStackWorthBringing()
	{
		assertFalse(Holdings.enough(true, 37));
		assertTrue(Holdings.enough(true, Holdings.AMMO_TRIP));
		assertTrue("a count never seen still counts", Holdings.enough(true, Holdings.UNKNOWN));
		assertTrue(Holdings.enough(false, 1));
		assertFalse(Holdings.enough(false, 0));
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.Fixtures;
import com.codex.gearroadmap.data.RoadmapData;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

public class LevelsTest
{
	private static RoadmapData data;
	private static Advisor advisor;

	@BeforeClass
	public static void load() throws IOException
	{
		data = RoadmapData.load(new Gson());
		advisor = new Advisor(data);
	}

	@Test
	public void theNearestLevelThatAddsDamageIsNamedWithItsWorth()
	{
		Fighter fighter = Fixtures.midGameFighter();
		Roadmap map = advisor.plan(Fixtures.midGame(data), fighter, data.target("General Graardor"), Fixtures.prices(data), 0);
		List<Levels.Step> steps = Levels.ahead(advisor.planner().calc(), map, fighter);
		assertFalse(steps.isEmpty());
		Roadmap.Step last = map.getPath().get(map.getPath().size() - 1);
		double perDps = last.getSpent() / (last.getOption().getAfter().dps() - map.getNow().dps());
		for (Levels.Step s : steps)
		{
			System.out.printf("  %s %d -> %d  +%.3f (%.1f%%) max %d %s worth %,d%n", s.getSkill(), s.getFrom(), s.getTo(), s.getGain(),
				s.getShare() * 100, s.getMaxHit(), s.isNewMaxHit(), s.getWorth());
			assertTrue(s.getTo() > s.getFrom() && s.getTo() <= s.getFrom() + Levels.AHEAD);
			assertTrue(s.getShare() >= Levels.MIN_SHARE);
			assertEquals(s.getGain() * perDps, s.getWorth(), 1);
			// Nothing short of that level adds as much.
			Fighter shy = fighter.withLevel(s.getSkill(), s.getTo() - 1);
			double short1 = advisor.planner().calc().best(map.getNow().best().getLoadout(), shy, map.getTarget(),
				map.getNow().best().getResult().getKind()).getDps();
			assertTrue(short1 - map.getNow().dps() < map.getNow().dps() * Levels.MIN_SHARE);
		}
	}

	@Test
	public void aDefenceLevelThatUnlocksPietyIsNamed()
	{
		// 68 Defence and 74 Prayer pray Chivalry; two Defence levels open Piety, worth far more than
		// two levels of Strength. Looking only at Attack and Strength missed it.
		Map<String, Integer> levels = new HashMap<>(Fixtures.midGameFighter().getLevels());
		levels.put("Defence", 68);
		Fighter fighter = new Fighter(levels, Fighter.Boost.POTIONS, true, true, false, false, false, false);
		Roadmap map = advisor.plan(Fixtures.midGame(data), fighter, data.target("General Graardor"), Fixtures.prices(data), 0);
		assertEquals("Chivalry", map.getNow().best().getResult().getPrayer());
		Levels.Step defence = null;
		for (Levels.Step s : Levels.ahead(advisor.planner().calc(), map, fighter))
		{
			defence = "Defence".equals(s.getSkill()) ? s : defence;
		}
		assertNotNull(defence);
		assertEquals(70, defence.getTo());
		assertEquals("Piety", defence.getPrayer());
		assertTrue(defence.getShare() > 0.03);
		assertEquals("the best value per level comes first", "Defence",
			Levels.ahead(advisor.planner().calc(), map, fighter).get(0).getSkill());
	}

	@Test
	public void maxedSkillsHaveNothingAhead()
	{
		Fighter maxed = Fighter.maxed(Fighter.Boost.POTIONS);
		Roadmap map = advisor.plan(Fixtures.midGame(data), maxed, data.target("General Graardor"), Fixtures.prices(data), 0);
		assertTrue(Levels.ahead(advisor.planner().calc(), map, maxed).isEmpty());
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.Fixtures;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

public class OutgrownTest
{
	private static RoadmapData data;
	private static Advisor advisor;

	@BeforeClass
	public static void load() throws IOException
	{
		data = RoadmapData.load(new Gson());
		advisor = new Advisor(data);
	}

	private static Set<String> names(Outgrown o)
	{
		return o.getPieces().stream().map(p -> p.getGear().getName()).collect(Collectors.toSet());
	}

	@Test
	public void gearNoBestLoadoutWearsIsOutgrown()
	{
		Fighter fighter = Fixtures.midGameFighter();
		Set<Gear> owned = new LinkedHashSet<>(Fixtures.midGame(data));
		// A rune scimitar beside a whip and a dragon scimitar helps against nothing.
		owned.add(data.named("Rune scimitar"));
		List<Roadmap.Survey> survey = advisor.survey(owned, fighter);
		Outgrown o = Outgrown.of(owned, survey, g -> advisor.planner().wieldable(g, fighter), g -> true, id -> 60_000L);
		System.out.println("  outgrown: " + names(o));
		assertTrue(names(o).contains("Rune scimitar"));
		// The whip is worn somewhere, so it is not.
		assertFalse(names(o).contains("Abyssal whip"));
		// Kept for its effect, never listed even where nothing wears it.
		assertFalse(names(o).contains("Salve amulet (e)"));
		assertEquals(o.getPieces().size() * 60_000L, o.getWorth());
	}

	@Test
	public void gearToGrowIntoCheapGearAndNoSurveyAreNeverOutgrown()
	{
		Fighter fighter = Fixtures.midGameFighter();
		Set<Gear> owned = new LinkedHashSet<>(Fixtures.midGame(data));
		owned.add(data.named("Rune scimitar"));
		List<Roadmap.Survey> survey = advisor.survey(owned, fighter);
		assertTrue("too cheap to bother with", Outgrown.of(owned, survey, g -> true, g -> true, id -> 20_000L).isEmpty());
		assertTrue("not yet wieldable", Outgrown.of(owned, survey, g -> false, g -> true, id -> 60_000L).isEmpty());
		assertTrue("nothing surveyed", Outgrown.of(owned, Collections.emptyList(), g -> true, g -> true, id -> 60_000L).isEmpty());
	}

	@Test
	public void dragonfireTankAndSpecialAttackGearAreKept()
	{
		assertTrue(Outgrown.kept(data.named("Dragonfire shield")));
		assertTrue(Outgrown.kept(data.named("Justiciar faceguard")));
		assertTrue(Outgrown.kept(data.named("Granite maul")));
		assertTrue(Outgrown.kept(data.named("Dragon claws")));
		assertFalse(Outgrown.kept(data.named("Rune scimitar")));
	}

	@Test
	public void skillingToolsAndUtilityStavesAreKept()
	{
		// Tools with attack bonuses are still tools: a dragon pickaxe is never "outgrown" combat gear.
		for (String name : new String[]{"Dragon pickaxe", "Dragon axe", "Dragon harpoon", "3rd Age pickaxe", "Infernal axe",
			"Dragon felling axe", "Toxic staff of the dead", "Staff of light", "Mystic smoke staff", "Smoke battlestaff",
			"Staff of fire", "Twisted slayer helmet (i)", "Hydra slayer helmet (i)"})
		{
			assertTrue(name, Outgrown.kept(data.named(name)));
		}
		// A weapon named for its axe is still a weapon.
		assertFalse(Outgrown.kept(data.named("Soulreaper axe")));
		assertFalse(Outgrown.kept(data.named("Rune battleaxe")));
	}

	@Test
	public void gearThatCannotBeSoldIsNeverOutgrown()
	{
		Fighter fighter = Fixtures.midGameFighter();
		Set<Gear> owned = new LinkedHashSet<>(Fixtures.midGame(data));
		owned.add(data.named("Rune scimitar"));
		List<Roadmap.Survey> survey = advisor.survey(owned, fighter);
		// RuneLite prices an untradeable piece by what it was made from, so a price alone is no proof it sells.
		Outgrown o = Outgrown.of(owned, survey, g -> advisor.planner().wieldable(g, fighter), g -> false, id -> 60_000L);
		assertTrue(o.isEmpty());
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.Fixtures;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

public class SavingsTest
{
	private static final long DAY = 24 * 3_600_000L;
	private static final long NOW = 1_800_000_000_000L;
	private static RoadmapData data;
	private static Advisor advisor;

	@BeforeClass
	public static void load() throws IOException
	{
		data = RoadmapData.load(new Gson());
		advisor = new Advisor(data);
	}

	private static Savings.Goal goal(String... names)
	{
		List<Integer> ids = new ArrayList<>();
		for (String name : names)
		{
			ids.add(data.named(name).getIds()[0]);
		}
		return new Savings.Goal(String.join(" + ", names), ids);
	}

	private static Roadmap plan(Set<Gear> owned, Savings.Goal goal)
	{
		Target vorkath = data.target("Vorkath");
		return advisor.plan(owned, Fixtures.midGameFighter(), vorkath, Fixtures.prices(data), 10_000_000, goal);
	}

	@Test
	public void goalIsPricedAndWeighedFromTheLoadoutOwnedNow()
	{
		Roadmap map = plan(Fixtures.midGame(data), goal("Dragon hunter crossbow"));
		Roadmap.Option o = map.getGoal();
		assertNotNull(o);
		assertEquals(60_000_000, o.getCost());
		assertTrue("a dragon hunter crossbow beats a blowpipe at Vorkath", o.getGain() > 0);
		assertFalse(map.isGoalOwned());
		// The goal survives a change of coins, which rebuilds the road.
		assertEquals(60_000_000, map.withCoins(1).getGoal().getCost());
	}

	@Test
	public void ownedGoalIsMetAndCostsNothing()
	{
		Set<Gear> owned = Fixtures.midGame(data);
		owned.add(data.named("Dragon hunter crossbow"));
		Roadmap map = plan(owned, goal("Dragon hunter crossbow"));
		assertTrue(map.isGoalOwned());
		assertEquals(0, map.getGoal().getCost());
		assertTrue(Savings.of(map.getGoal(), true, 0, null, NOW).isAffordable());
	}

	@Test
	public void pairGoalCountsOnlyWhatIsStillToBuy()
	{
		Set<Gear> owned = Fixtures.midGame(data);
		owned.add(data.named("Masori body"));
		Roadmap map = plan(owned, goal("Masori body", "Masori chaps"));
		assertEquals(16_000_000, map.getGoal().getCost());
		assertFalse(map.isGoalOwned());
	}

	@Test
	public void unknownOrUnpricedGoalIsLeftOut()
	{
		assertNull(plan(Fixtures.midGame(data), new Savings.Goal("Mystery", Collections.singletonList(-5))).getGoal());
		assertNull(plan(Fixtures.midGame(data), null).getGoal());
		Savings.Goal unpriced = new Savings.Goal("Rune pouch", Collections.singletonList(data.named("Twisted bow").getIds()[0]));
		Target vorkath = data.target("Vorkath");
		Roadmap map = advisor.plan(Fixtures.midGame(data), Fixtures.midGameFighter(), vorkath, id -> 0L, 0, unpriced);
		assertNull("no price, no goal card, rather than a goal that reads as free", map.getGoal());
	}

	@Test
	public void goalFromAnotherStyleAddsNothingHereButStaysPriced()
	{
		// A savings goal stays put when the player aims elsewhere: a mystic fire staff does nothing for
		// a Vorkath loadout built on a blowpipe, so the gain may be nothing, yet the price still counts.
		Target vorkath = data.target("Vorkath");
		Roadmap map = advisor.plan(Fixtures.midGame(data), Fixtures.midGameFighter(), vorkath, Fixtures.prices(data), 0,
			goal("Mystic fire staff"));
		assertEquals(30_000, map.getGoal().getCost());
		assertTrue(map.getGoal().getGain() >= 0);
	}

	@Test
	public void progressAndRemaining()
	{
		Roadmap.Option o = plan(Fixtures.midGame(data), goal("Dragon hunter crossbow")).getGoal();
		Savings.View v = Savings.of(o, false, 15_000_000, null, NOW);
		assertEquals(0.25, v.getProgress(), 1e-9);
		assertEquals(45_000_000, v.getRemaining());
		assertFalse(v.isAffordable());
		assertFalse(v.hasLedger());
		assertEquals(-1, v.getDays());
		Savings.View rich = Savings.of(o, false, 90_000_000, null, NOW);
		assertEquals(1, rich.getProgress(), 1e-9);
		assertEquals(0, rich.getRemaining());
		assertEquals(0, rich.getDays());
	}

	@Test
	public void paceIsTheLastWeeksGrowthPerDay()
	{
		List<Savings.Point> history = Arrays.asList(
			new Savings.Point(NOW - 30 * DAY, 10_000_000),
			// The first reading inside the week starts the pace; older ones are left out.
			new Savings.Point(NOW - 6 * DAY, 40_000_000),
			new Savings.Point(NOW - 3 * DAY, 45_000_000),
			new Savings.Point(NOW, 52_000_000));
		Savings.Worth worth = new Savings.Worth(52_000_000, history);
		assertEquals(Long.valueOf(2_000_000), Savings.pace(worth, NOW));
		Roadmap.Option o = plan(Fixtures.midGame(data), goal("Dragon hunter crossbow")).getGoal();
		Savings.View v = Savings.of(o, false, 14_000_000, worth, NOW);
		assertEquals(46_000_000, v.getRemaining());
		assertEquals(23, v.getDays());
		assertTrue(v.hasLedger());
		assertEquals(52_000_000, v.getWorth());
	}

	@Test
	public void paceNeedsADayOfHistoryAndRoundsDaysUp()
	{
		Savings.Worth young = new Savings.Worth(5, Arrays.asList(new Savings.Point(NOW - 3_600_000L, 1), new Savings.Point(NOW, 5)));
		assertNull(Savings.pace(young, NOW));
		assertNull(Savings.pace(new Savings.Worth(5, null), NOW));
		assertNull(Savings.pace(null, NOW));
		// Readings from the future (a clock change) are ignored rather than trusted.
		Savings.Worth odd = new Savings.Worth(5, Arrays.asList(new Savings.Point(NOW - 2 * DAY, 0), new Savings.Point(NOW + DAY, 999)));
		assertNull(Savings.pace(odd, NOW));

		Roadmap.Option o = plan(Fixtures.midGame(data), goal("Dragon hunter crossbow")).getGoal();
		Savings.Worth slow = new Savings.Worth(1, Arrays.asList(new Savings.Point(NOW - 2 * DAY, 0), new Savings.Point(NOW, 3_000_000)));
		// 1.5M a day, 59M to go: 39.3 days is 40 days, never an optimistic 39.
		assertEquals(40, Savings.of(o, false, 1_000_000, slow, NOW).getDays());
		Savings.Worth falling = new Savings.Worth(1, Arrays.asList(new Savings.Point(NOW - 2 * DAY, 9), new Savings.Point(NOW, 3)));
		assertEquals(-1, Savings.of(o, false, 1_000_000, falling, NOW).getDays());
	}

	@Test
	public void ledgerSaveFormatReads()
	{
		// The shape Codex Ledger saves: Gear Roadmap reads only the total and history, ignoring the rest.
		String json = "{\"stores\":{\"BANK\":{\"seen\":1,\"items\":{\"995\":5}}},\"prices\":{\"995\":1},"
			+ "\"history\":[{\"t\":100,\"v\":7},{\"t\":200,\"v\":9}],\"days\":[],\"total\":9,\"since\":100,\"exchange\":{}}";
		Savings.Worth worth = new Gson().fromJson(json, Savings.Worth.class);
		assertEquals(9, worth.getTotal());
		assertEquals(2, worth.getHistory().size());
		assertEquals(200, worth.getHistory().get(1).getTime());
		assertEquals(9, worth.getHistory().get(1).getValue());
	}

	@Test
	public void savedGoalRoundTrips()
	{
		Gson gson = new Gson();
		Savings.Goal g = gson.fromJson(gson.toJson(goal("Masori body", "Masori chaps")), Savings.Goal.class);
		assertTrue(g.isValid());
		assertEquals("Masori body + Masori chaps", g.getName());
		assertEquals(2, g.getIds().size());
		assertFalse(gson.fromJson("{\"name\":\"x\"}", Savings.Goal.class).isValid());
	}

	@Test
	public void goalInReachIsSaidOnceNotEachTimeCoinsComeBack()
	{
		Roadmap.Option o = plan(Fixtures.midGame(data), goal("Dragon hunter crossbow")).getGoal();
		Savings.View poor = Savings.of(o, false, 59_000_000, null, NOW);
		Savings.View rich = Savings.of(o, false, 61_000_000, null, NOW);
		assertFalse("the first look after login never announces", Savings.inReach(null, false, rich));
