		assertTrue(SlayerTask.of(SlayerTask.Mode.SMART, "Crabs").covers(data.target("Sand Crab")));
		assertTrue(SlayerTask.of(SlayerTask.Mode.SMART, "Crabs").covers(data.target("Ammonite Crab")));
		assertTrue(SlayerTask.of(SlayerTask.Mode.SMART, "Crabs").covers(data.target("Rock Crab")));
	}

	@Test
	public void modesOverride()
	{
		assertTrue(SlayerTask.ALWAYS.covers(data.target("Vorkath")));
		assertFalse(SlayerTask.NEVER.covers(data.target("Abyssal demon")));
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.Fixtures;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

public class SwapTest
{
	private static RoadmapData data;
	private static Advisor advisor;

	@BeforeClass
	public static void load() throws IOException
	{
		data = RoadmapData.load(new Gson());
		advisor = new Advisor(data);
	}

	private static Set<Integer> ids(Loadout lo)
	{
		Set<Integer> ids = new HashSet<>();
		for (int i = 0; i < Gear.SLOTS; i++)
		{
			if (lo.get(i) != null)
			{
				ids.add(lo.get(i).getId());
			}
		}
		return ids;
	}

	@Test
	public void wearingTheBestOwnedSaysSo()
	{
		Fighter fighter = Fixtures.midGameFighter();
		Target target = data.target("General Graardor");
		Planner.Best best = advisor.planner().optimise(Fixtures.midGame(data), fighter, target);
		Swap swap = Swap.of(ids(best.best().getLoadout()), Collections.emptySet(), data::gear, best.best(), advisor.planner().calc(),
			fighter, target);
		assertTrue(swap.isBest());
		assertEquals(best.dps(), swap.getWornDps(), 1e-9);
	}

	@Test
	public void namesThePiecesToPutOnAndWhereTheyAre()
	{
		Fighter fighter = Fixtures.midGameFighter();
		Target target = data.target("General Graardor");
		Planner.Best best = advisor.planner().optimise(Fixtures.midGame(data), fighter, target);
		Loadout lo = best.best().getLoadout();
		Gear weapon = lo.weapon();
		Gear body = lo.get(Gear.BODY);
		// Wearing the best bar the weapon and body; the body is carried, the weapon is in the bank.
		Set<Integer> worn = ids(lo.without(Gear.WEAPON).without(Gear.BODY));
		Set<Integer> carried = new HashSet<>();
		carried.add(body.getIds()[body.getIds().length - 1]);
		Swap swap = Swap.of(worn, carried, data::gear, best.best(), advisor.planner().calc(), fighter, target);
		assertFalse(swap.isBest());
		assertEquals(2, swap.getChanges().size());
		Swap.Change first = swap.getChanges().get(0);
		assertEquals("the weapon comes first", weapon.key(), first.getWear().key());
		assertEquals(Swap.Where.BANK, first.getWhere());
		assertNull(first.getOff());
		assertEquals(body.key(), swap.getChanges().get(1).getWear().key());
		assertEquals(Swap.Where.INVENTORY, swap.getChanges().get(1).getWhere());
		assertTrue(swap.gain() > 0);
	}

	@Test
	public void piecesItDoesNotKnowAreIgnoredAndAnotherStyleIsNamed()
	{
		Fighter fighter = Fixtures.midGameFighter();
		Target target = data.target("General Graardor");
		Planner.Best best = advisor.planner().optimise(Fixtures.midGame(data), fighter, target);
		Gear trident = data.named("Trident of the Seas");
		Set<Integer> worn = new HashSet<>();
		worn.add(trident.getId());
		// A ring of wealth, say: not combat gear, so not in the roadmap's data.
		worn.add(2572);
		Swap swap = Swap.of(worn, Collections.emptySet(), data::gear, best.best(), advisor.planner().calc(), fighter, target);
		assertEquals(trident.key(), swap.getChanges().get(0).getOff().key());
		assertTrue(swap.getWornDps() < swap.getBestDps());
		assertTrue(swap.getChanges().stream().noneMatch(c -> c.getOff() != null && c.getOff().getId() == 2572));
	}
}

package com.codex.gearroadmap.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The slayer task through logins and world hops, where the client takes its varps afresh. */
public class TaskWatchTest
{
	private static void settle(TaskWatch w, String key)
	{
		for (int i = 0; i < TaskWatch.SETTLE_TICKS - 1; i++)
		{
			assertEquals(TaskWatch.Change.NONE, w.tick(key));
		}
	}

	@Test
	public void aHopsBlinkNeitherEndsTheTaskNorReplans()
	{
		TaskWatch w = new TaskWatch();
		settle(w, "42:0");
		assertEquals(TaskWatch.Change.CHANGED, w.tick("42:0"));
		assertTrue(w.isSettled());

		// The hop: the varps read none while the new world's are sent, then the task again.
		w.arrived();
		assertFalse(w.isSettled());
		assertEquals(TaskWatch.Change.NONE, w.seen(""));
		assertEquals(TaskWatch.Change.NONE, w.tick(""));
		assertEquals(TaskWatch.Change.NONE, w.seen("42:0"));
		settle(w, "42:0");
		assertEquals("same task after the hop: nothing to do", TaskWatch.Change.NONE, w.tick("42:0"));
		assertEquals("42:0", w.getKey());
	}

	@Test
	public void theTaskEndingOnceSettledIsBelieved()
	{
		TaskWatch w = new TaskWatch();
		settle(w, "42:0");
		w.tick("42:0");
		assertEquals(TaskWatch.Change.NONE, w.seen("42:0"));
		assertEquals(TaskWatch.Change.ENDED, w.seen(""));
		assertEquals(TaskWatch.Change.CHANGED, w.seen("98:3"));
	}

	@Test
	public void aTaskChangedWhileAwayIsSeenAtTheSettlingTick()
	{
		TaskWatch w = new TaskWatch();
		settle(w, "42:0");
		w.tick("42:0");
		w.arrived();
		settle(w, "7:0");
		assertEquals(TaskWatch.Change.CHANGED, w.tick("7:0"));
		w.arrived();
		settle(w, "");
		assertEquals("finished on another device: the next task is followed afresh", TaskWatch.Change.ENDED, w.tick(""));
	}

	@Test
	public void afterLoggingOutTheFirstReadingIsNoEnd()
	{
		TaskWatch w = new TaskWatch();
		settle(w, "42:0");
		w.tick("42:0");
		w.forget();
		settle(w, "");
		assertEquals(TaskWatch.Change.CHANGED, w.tick(""));
		assertEquals(TaskWatch.Change.NONE, w.seen(""));
	}
	/**
	 * The plan reads the task straight from the varps, so it is only made once settled: a plan made
	 * during the blink would aim away from the task, and nothing after it would plan again.
	 */
	@Test
	public void aPlanMadeDuringTheBlinkWouldNeverBeRedone()
	{
		TaskWatch w = new TaskWatch();
		settle(w, "42:0");
		w.tick("42:0");
		w.arrived();
		assertFalse("not settled on the first tick after a hop, when the varps may still read none", w.isSettled());
		assertEquals(TaskWatch.Change.NONE, w.tick(""));
		assertFalse(w.isSettled());
		for (int i = 0; i < TaskWatch.SETTLE_TICKS - 2; i++)
		{
			assertEquals(TaskWatch.Change.NONE, w.tick("42:0"));
		}
		assertEquals("the task came back as it was: no new plan is asked for", TaskWatch.Change.NONE, w.tick("42:0"));
		assertTrue(w.isSettled());
	}
}

