package com.codex.gearroadmap.ui;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CardPicturesTest
{
	/** Pictures that arrive only when told to, the way RuneLite's item pictures load. */
	private static final class Late implements ItemIcons
	{
		final Map<Integer, Runnable> callbacks = new HashMap<>();
		final Set<BufferedImage> in = new HashSet<>();
		int asked;

		@Override
		public BufferedImage icon(int itemId, Runnable onLoaded)
		{
			asked++;
			BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
			callbacks.put(itemId, () ->
			{
				in.add(image);
				onLoaded.run();
			});
			return image;
		}

		@Override
		public boolean hasArrived(BufferedImage image)
		{
			return in.contains(image);
		}
	}

	/** A card that is "complete" only when every picture it drew had arrived. */
	private static BufferedImage card(ItemIcons icons, Late late, List<Boolean> complete)
	{
		boolean all = true;
		for (int id : new int[]{995, 4151})
		{
			all &= late.hasArrived(icons.icon(id, null));
		}
		complete.add(all);
		return new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	}

	@Test
	public void aCardWaitsForItsPicturesThenDrawsWithThem()
	{
		Late late = new Late();
		List<Boolean> drawn = new ArrayList<>();
		List<BufferedImage> delivered = new ArrayList<>();
		List<Runnable> waits = new ArrayList<>();
		int[] ended = {0};
		CardPictures.draw(late, icons -> card(icons, late, drawn), delivered::add, Runnable::run, waits::add, () -> ended[0]++);
		// Drawn once to learn what it needs, and nothing handed over yet.
		assertEquals(1, drawn.size());
		assertTrue(delivered.isEmpty());
		assertEquals(0, ended[0]);
		late.callbacks.get(995).run();
		assertTrue(delivered.isEmpty());
		late.callbacks.get(4151).run();
		// The last picture in draws it again, complete, with the same pictures (none asked for twice).
		assertEquals(1, delivered.size());
		assertEquals(Boolean.TRUE, drawn.get(1));
		assertEquals(2, late.asked);
		// The wait running out afterwards hands nothing over a second time, and the card ended once.
		waits.get(0).run();
		assertEquals(1, delivered.size());
		assertEquals(1, ended[0]);
	}

	@Test
	public void aPictureThatNeverComesHoldsTheCardOnlyUntilTheWaitRunsOut()
	{
		Late late = new Late();
		List<Boolean> drawn = new ArrayList<>();
		List<BufferedImage> delivered = new ArrayList<>();
		List<Runnable> waits = new ArrayList<>();
		int[] ended = {0};
		CardPictures.draw(late, icons -> card(icons, late, drawn), delivered::add, Runnable::run, waits::add, () -> ended[0]++);
		late.callbacks.get(995).run();
		waits.get(0).run();
		assertEquals(1, delivered.size());
		// A straggler after that is ignored.
		late.callbacks.get(4151).run();
		assertEquals(1, delivered.size());
	}

	@Test
	public void aCardThatFailsToDrawStillLetsTheNextPressThrough()
	{
		Late late = new Late();
		int[] ended = {0};
		List<Runnable> waits = new ArrayList<>();
		int[] calls = {0};
		CardPictures.draw(late, icons ->
		{
			icons.icon(995, null);
			if (calls[0]++ > 0)
			{
				throw new IllegalStateException("broken");
			}
			return null;
		}, c -> { }, Runnable::run, waits::add, () -> ended[0]++);
		try
		{
			late.callbacks.get(995).run();
		}
		catch (IllegalStateException expected)
		{
			// The failure reaches the caller as before.
		}
		assertEquals(1, ended[0]);
	}

	@Test
	public void picturesAlreadyInAreDrawnAtOnce()
	{
		List<BufferedImage> delivered = new ArrayList<>();
		int[] ended = {0};
		BufferedImage card = new BufferedImage(2, 2, BufferedImage.TYPE_INT_ARGB);
		ItemIcons ready = (id, cb) -> new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		CardPictures.draw(ready, icons ->
		{
			icons.icon(995, null);
			return card;
		}, delivered::add, r -> { throw new AssertionError(); }, r -> { }, () -> ended[0]++);
		assertSame(card, delivered.get(0));
		assertEquals(1, ended[0]);
		CardPictures.draw(null, icons -> card, delivered::add);
		assertEquals(2, delivered.size());
	}

	@Test
	public void aCardStillWaitingWhenThePluginStopsIsNeverHandedOver() throws Exception
	{
		Late late = new Late();
		List<BufferedImage> delivered = new ArrayList<>();
		javax.swing.SwingUtilities.invokeAndWait(() ->
			CardPictures.draw(late, icons -> card(icons, late, new ArrayList<>()), delivered::add));
		// The plugin stops while the card waits; its pictures turn up afterwards.
		javax.swing.SwingUtilities.invokeAndWait(CardPictures::cancel);
		late.callbacks.get(995).run();
		late.callbacks.get(4151).run();
		javax.swing.SwingUtilities.invokeAndWait(() -> { });
		assertTrue(delivered.isEmpty());
		// And the next card, after a restart, is not held back by the dropped one.
		ItemIcons ready = (id, cb) -> new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		javax.swing.SwingUtilities.invokeAndWait(() ->
			CardPictures.draw(ready, icons -> new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), delivered::add));
		assertEquals(1, delivered.size());
	}
}

package com.codex.gearroadmap.ui;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class FormatTest
{
	@Test
	public void amountsFollowTheSuiteRule()
	{
		// In full below 10,000; whole k below a million; M to one decimal; B to two.
		assertEquals("8,240", Format.coins(8_240));
		assertEquals("10k", Format.coins(10_000));
		assertEquals("41k", Format.coins(41_200));
		assertEquals("96k", Format.coins(95_700));
		assertEquals("412k", Format.coins(412_000));
		assertEquals("1.2M", Format.coins(1_240_000));
		assertEquals("2.4M", Format.coins(2_370_000));
		assertEquals("26.0M", Format.coins(26_000_000));
		assertEquals("98.7M", Format.coins(98_700_000));
		assertEquals("812.4M", Format.coins(812_400_000));
		assertEquals("2.10B", Format.coins(2_100_000_000L));
		// Rounding that reaches the next unit is written in it.
		assertEquals("100k", Format.coins(99_960));
		assertEquals("1.0M", Format.coins(999_600));
		assertEquals("999k", Format.coins(999_499));
		assertEquals("1.00B", Format.coins(999_960_000));
		assertEquals("Free", Format.coins(0));
	}

}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.Fixtures;
import com.codex.gearroadmap.core.Advisor;
import com.codex.gearroadmap.core.Roadmap;
import com.codex.gearroadmap.core.Savings;
import com.codex.gearroadmap.data.RoadmapData;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

public class GoalCardTest
{
	private static final long DAY = 24 * 3_600_000L;
	private static final long NOW = 1_800_000_000_000L;
	private static Roadmap.Option dhcb;

	@BeforeClass
	public static void load() throws IOException
	{
		RoadmapData data = RoadmapData.load(new Gson());
		Savings.Goal goal = new Savings.Goal("Dragon hunter crossbow", Collections.singletonList(data.named("Dragon hunter crossbow").getIds()[0]));
		dhcb = new Advisor(data).plan(Fixtures.midGame(data), Fixtures.midGameFighter(), data.target("Vorkath"), Fixtures.prices(data),
			0, goal).getGoal();
	}

	private static Savings.Worth growing(long perDay, long total)
	{
		return new Savings.Worth(total, Arrays.asList(new Savings.Point(NOW - 4 * DAY, total - 4 * perDay), new Savings.Point(NOW, total)));
	}

	@Test
	public void paceLineSaysWhenInPlainWords()
	{
		assertEquals("Your coins cover it. Buy it whenever you like.",
			GoalCard.paceLine(Savings.of(dhcb, false, 60_000_000, null, NOW)));
		assertEquals("You own it now. Clear this to pick your next goal.", GoalCard.paceLine(Savings.of(dhcb, true, 0, null, NOW)));
		assertEquals("50.0M to go. Codex Ledger can tell you when.",
			GoalCard.paceLine(Savings.of(dhcb, false, 10_000_000, null, NOW)));
		assertEquals("50.0M to go, about 17 days at +3.0M a day.",
			GoalCard.paceLine(Savings.of(dhcb, false, 10_000_000, growing(3_000_000, 20_000_000), NOW)));
		assertEquals("50.0M to go, about a day at +60.0M a day. Your 200.0M net worth covers it.",
			GoalCard.paceLine(Savings.of(dhcb, false, 10_000_000, growing(60_000_000, 200_000_000), NOW)));
		assertTrue(GoalCard.paceLine(Savings.of(dhcb, false, 10_000_000, growing(-1_000, 90_000_000), NOW))
			.endsWith("has not grown this week. Your 90.0M net worth covers it."));
		assertEquals("50.0M to go. Codex Ledger needs a day of history to tell when.",
			GoalCard.paceLine(Savings.of(dhcb, false, 10_000_000, new Savings.Worth(12_000_000, null), NOW)));
	}

	@Test
	public void gainLineNamesTheTarget()
	{
		String[] line = GoalCard.gainLine(dhcb, "Vorkath");
		assertTrue(line[0], line[0].startsWith("+") && line[0].contains("DPS against Vorkath"));
	}
}

package com.codex.gearroadmap.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.AsyncBufferedImage;
import org.junit.Test;

public class IconWatchTest
{
	/** Stands in for AsyncBufferedImage: once loaded, every callback given runs again. */
	private static final class Picture
	{
		boolean loaded;
		final List<Runnable> waiting = new ArrayList<>();
		final List<Runnable> later = new ArrayList<>();

		void onLoaded(Runnable r)
		{
			if (loaded)
			{
				later.add(r);
			}
			else
			{
				waiting.add(r);
			}
		}

		void load()
		{
			loaded = true;
			waiting.forEach(Runnable::run);
			waiting.clear();
		}

		void runLater()
		{
			List<Runnable> now = new ArrayList<>(later);
			later.clear();
			now.forEach(Runnable::run);
		}
	}

	@Test
	public void aRepaintOnLoadDoesNotLoopOnceThePictureHasArrived()
	{
		IconWatch watch = new IconWatch();
		Picture picture = new Picture();
		int[] paints = {0};
		// A component that asks for its picture while painting and repaints when it loads.
		Runnable[] paint = new Runnable[1];
		paint[0] = () ->
		{
			paints[0]++;
			watch.watch(picture, () -> picture.later.add(paint[0]), picture::onLoaded);
		};
		paint[0].run();
		paint[0].run();
		picture.load();
		for (int i = 0; i < 20; i++)
		{
			picture.runLater();
		}
		assertTrue(watch.hasArrived(picture));
		// Two paints before it arrived, one repaint each from the arrival, then nothing more.
		assertEquals(4, paints[0]);
		assertTrue(picture.later.isEmpty());
	}

	@Test
	public void aPictureAlreadyLoadedRepaintsOnceAtMost()
	{
		IconWatch watch = new IconWatch();
		Picture picture = new Picture();
		picture.loaded = true;
		int[] runs = {0};
		watch.watch(picture, () -> runs[0]++, picture::onLoaded);
		picture.runLater();
		watch.watch(picture, () -> runs[0]++, picture::onLoaded);
		picture.runLater();
		assertEquals(1, runs[0]);
		assertEquals(1, watch.size());
	}

	@Test
	public void nothingToWatchIsSafe()
	{
		IconWatch watch = new IconWatch();
		watch.watch(null, () -> { }, r -> { throw new AssertionError(); });
		Picture picture = new Picture();
		watch.watch(picture, null, picture::onLoaded);
		picture.load();
		assertTrue(watch.hasArrived(picture));
	}

	/** Holds what RuneLite would run later on the client thread, so a test can run it. */
	private static final class Later extends ClientThread
	{
		final List<Runnable> queued = new ArrayList<>();

		@Override
		public void invokeLater(Runnable r)
		{
			queued.add(r);
		}

		void run()
		{
			List<Runnable> now = new ArrayList<>(queued);
			queued.clear();
			now.forEach(Runnable::run);
		}
	}

	@Test
	public void aFreshPictureForTheSameItemIsWatchedAgain()
	{
		// ItemManager keeps only so many item pictures; after one is dropped, asking for the same item
		// hands out a new blank picture that loads later. It must be watched, not taken as arrived.
		Later clientThread = new Later();
		IconWatch watch = new IconWatch();
		int[] repaints = {0};
		AsyncBufferedImage first = new AsyncBufferedImage(clientThread, 36, 32, java.awt.image.BufferedImage.TYPE_INT_ARGB);
		watch.watch(first, () -> repaints[0]++, first::onLoaded);
		first.loaded();
		assertEquals(1, repaints[0]);
		watch.watch(first, () -> repaints[0]++, first::onLoaded);
		clientThread.run();
		assertEquals(1, repaints[0]);

		AsyncBufferedImage again = new AsyncBufferedImage(clientThread, 36, 32, java.awt.image.BufferedImage.TYPE_INT_ARGB);
		assertFalse(watch.hasArrived(again));
		watch.watch(again, () -> repaints[0]++, again::onLoaded);
		again.loaded();
		assertEquals(2, repaints[0]);
		assertTrue(watch.hasArrived(again));
		assertTrue(watch.hasArrived(first));
	}

	@Test
	public void aDroppedPictureIsNotHeldOn()
	{
		IconWatch watch = new IconWatch();
		Later clientThread = new Later();
		AsyncBufferedImage picture = new AsyncBufferedImage(clientThread, 36, 32, java.awt.image.BufferedImage.TYPE_INT_ARGB);
		watch.watch(picture, null, picture::onLoaded);
		picture.loaded();
		assertEquals(1, watch.size());
		picture = null;
		for (int i = 0; i < 50 && watch.size() > 0; i++)
		{
			System.gc();
			byte[] churn = new byte[1 << 20];
			churn[0] = 1;
		}
		assertEquals(0, watch.size());
	}
}

package com.codex.gearroadmap.ui;

import java.util.Locale;
import static org.junit.Assert.assertEquals;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** Damage figures read the same on a German computer as on an English one, as coins already did. */
public class LocaleFormatTest
{
	private Locale was;

	@Before
	public void german()
	{
		was = Locale.getDefault();
		Locale.setDefault(Locale.GERMANY);
	}

	@After
	public void restore()
	{
		Locale.setDefault(was);
	}

	@Test
	public void dpsUsesAFullStop()
	{
		assertEquals("4.25", Format.dps(4.25));
		assertEquals(Format.dps(1.5).indexOf(','), -1);
		assertEquals(Format.gain(0.37).indexOf(','), -1);
	}

	@Test
	public void pricesSideBySideCarryTheSamePlaces()
	{
		// The road card once priced its stops "1.4M", "12M", "9.9M", "25M".
		assertEquals("12.0M", Format.coins(12_000_000));
		assertEquals("9.9M", Format.coins(9_900_000));
		assertEquals("156.0M", Format.coins(156_000_000));
		// Thousands whole and billions to two places, as Ledger and Session Chronicle write them.
		assertEquals("60k", Format.coins(60_000));
		assertEquals("300k", Format.coins(300_000));
		assertEquals("160k", Format.coins(160_400));
		assertEquals("850", Format.coins(850));
		assertEquals("8,240", Format.coins(8_240));
		assertEquals("999k", Format.coins(999_499));
		assertEquals("1.0M", Format.coins(999_500));
		assertEquals("1.60B", Format.coins(1_600_000_000L));
		assertEquals("Free", Format.coins(0));
	}
}

